#!/usr/bin/env bash
# Стенд корпусных инструментов: tools/sweep.sh, tools/fetch-corpus.sh и
# tools/corpus-list.py (общий дом формата списка).
#
# Зачем. Эти скрипты -- фундамент измерительной базы: свип решает, что и на чём
# мерить, наполнитель решает, какие байты считать эталонными, разбор списка
# решает, что вообще считается версией. Их гарантии держались на разовых ручных
# проверках, то есть на памяти человека; следующая правка снимала бы их
# беззвучно. Здесь они закреплены.
#
# Двери, которые стенд проверяет, срабатывают ДО первой сборки, поэтому корпус
# игрушечный (файлы в десятки байт), а вместо конвейера в копию кита кладётся
# ЗАГЛУШКА -- она печатает те же маркеры, по которым свип выносит вердикт, и
# позволяет задать любой их набор. Весь прогон занимает секунды и не трогает ни
# боевой корпус, ни боевой замок конвейера: дом корпуса, список версий,
# рабочий корень и путь замка берутся из CORPUS_DIR, CORPUS_LIST,
# SWEEP_STATE_DIR и CLAUDE_PATCH_LOCK.
#
# Сеть трогается в одном месте: сценарии наполнителя спрашивают реестр о
# заведомо несуществующей версии и получают отказ. При мёртвой сети они
# проходят так же -- проверено прогоном через закрытый порт как прокси.
#
# КОДЫ ВОЗВРАТА (подмножество общей конвенции кита, README «Exit codes»):
#   0 -- прогон зелёный: расхождений нет, беззубых правок нет
#   1 -- отказ по существу: сценарий разошёлся, мутация прошла молча,
#        прогон оборвался на полпути
#   2 -- прибор не может мерить: неизвестный режим в аргументах, пропавший
#        якорь вырезки, держатель замка не занял его за бюджет ожидания,
#        замена мутации сломала РАЗБОР жертвы -- номер круга аудита, а не
#        счётчик (круг 24, Н-1 docnum:other): покраснение по синтаксической
#        ошибке неотличимо от покраснения по механизму.
#   4 -- объявленное число не сходится с фактическим: длины пяти таблиц
#        мутаций или покрытие сценариев мутациями (тот же класс, что
#        EXPECTED_MUTATIONS у соседних стендов -- раунд 19, A-8)
#   3 -- мерить сейчас нельзя: замок стенда держит другой прогон стенда либо
#        идёт настоящая сборка (повторить позже)
#   6 -- машинерия замка сломана: не открыть файл замка, не работает perl
#        (повтор не поможет)
#
# Смерть по сигналу отдаётся как 128+N (130 INT, 143 TERM -- расщеплённые
# трапы ниже) и вердиктом кита НЕ является (круг 28, F-8).
# 130 приходит, когда INT доставлен ГРУППЕ процессов (так делает терминал по
# Ctrl-C); `kill -INT <pid скрипта>` при живом foreground-ребёнке bash
# отбрасывает -- ребёнок доживает своё, трап НЕ исполняется, прогон доходит
# до конца и отдаёт обычный код. Усечения нет, код честен; но проверка 130
# одиночным kill даёт ложный вывод «трап сломан» (замерено, круг 25, F-6).
#
# Два режима:
#   bash tools/corpus-tools-bench.sh              -- прогон сценариев
#   bash tools/corpus-tools-bench.sh --self-check -- каждая мутация обязана
#                                                    покраснить свой сценарий
#                                                    И НАЗВАННОЙ ПРИЧИНОЙ
#   bash tools/corpus-tools-bench.sh --table-check -- только сверка длин таблиц
#   bash tools/corpus-tools-bench.sh --lock-probe  -- только встать в очередь
#                                                    на замок стенда
# Второй режим -- ответ на вопрос «а стенд вообще может упасть?». Беззубый
# стенд неотличим от рабочего, пока не назовёшь мутацию, которая его краснит.
# Мало и того: сценарий, покрасневший по ПОСТОРОННЕЙ причине (отказ соседней
# двери, упавший инструмент), доказывает чужое правило, а выглядит как зуб.
# Поэтому у каждой мутации записан след, который она обязана оставить в выводе.
set -u
KIT=$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)
EXPECTED_SCENARIOS=207
EXPECTED_MUTATIONS=277

# Предусловие 1: параллельный прогон СТЕНДА.
#
# Заглушка конвейера называется claude-patch-all.sh -- иначе свип её не
# запустит. Значит, второй прогон стенда виден первому как «идёт настоящий
# прогон»: предусловие ниже объявило бы чужую заглушку боевой сборкой и
# отказало по неверно названной причине (а свипы внутри сценариев -- своим
# стражем выживших). Стенды поэтому выстраиваются в очередь на своём замке, и
# ожидание называется своим именем. Замок берётся ДО предусловия: наоборот
# порядок не помогает -- заглушки предыдущего прогона живы, пока он идёт.
__blk="${CORPUS_BENCH_LOCK:-${TMPDIR:-/tmp}/corpus-tools-bench.$(id -u).lock}"
__budget="${CORPUS_BENCH_LOCK_BUDGET:-300}"
# Не открыть файл замка -- сломана машинерия, а не занят замок: повтор через
# минуту даст то же самое, и вызывающий обязан это различать (код 6, не 3).
exec 9>"$__blk" || { echo "corpus-tools-bench: ОТКАЗ -- не открыть замок $__blk" >&2; exit 6; }
BLK_BUDGET="$__budget" perl -e '
  use Fcntl ":flock";
  open(my $fh, ">&=9") or exit 2;
  $SIG{ALRM} = sub { exit 1 };
  alarm($ENV{BLK_BUDGET} || 300);
  flock($fh, LOCK_EX) or exit 2;
  alarm(0); exit 0;'
__blk_rc=$?
if (( __blk_rc != 0 )); then
  if (( __blk_rc == 1 )); then
    echo "corpus-tools-bench: ОТКАЗ -- другой прогон стенда держит замок $__blk" >&2
    echo "  дольше ${__budget} c. Параллельно стенды не гоняются: заглушка второго" >&2
    echo "  прогона зовётся claude-patch-all.sh и выглядела бы боевой сборкой." >&2
    exit 3
  fi
  echo "corpus-tools-bench: ОТКАЗ -- не взять замок стенда (perl rc=$__blk_rc)" >&2
  echo "  Это отказ машинерии замка, а не занятый замок: повтор не поможет." >&2
  exit 6
fi

# Неизвестный режим -- отказ контракта вызова, а не тихий прогон сценариев:
# опечатка в `--self-chek` иначе давала бы зелёный прогон БЕЗ мутаций, и
# отчёт «стенд зелёный» означал бы не то, что читатель прочтёт.
case "${1:-}" in
  ''|--self-check|--table-check|--lock-probe) ;;
  *) echo "corpus-tools-bench: ОТКАЗ -- неизвестный режим «$1»" >&2
     echo "  режимы: (без аргументов) | --self-check | --table-check | --lock-probe" >&2
     exit 2 ;;
esac

# Зонд замка: взять очередь и выйти. Нужен сценарию, который проверяет,
# что второй прогон ЖДЁТ и называет причину: запускать вложенным весь стенд
# нельзя -- он дошёл бы до того же сценария и запустил себя снова.
if [[ "${1:-}" == "--lock-probe" ]]; then
  echo "corpus-tools-bench: замок стенда взят"
  exit 0
fi

# Предусловие 2: живой настоящий прогон.
#
# Свип отказывается стартовать, пока жив чужой claude-patch-all.sh или пишущая
# стадия tweakcc (обе -- и `--apply`, и `adhoc-patch`: вторую страж не видел, а
# пишет она в тот же образ) -- это ГЛОБАЛЬНЫЙ страж общего состояния, и подменять его
# ради стенда нельзя. Но тогда все сценарии свипа получают этот отказ вместо
# своего, и стенд краснеет по причине, не имеющей отношения к его предмету.
# Поэтому условие называется прямо и один раз, отдельным кодом возврата.
# Форма стража -- КАНОН свипа (tools/sweep.sh, «путь засчитывается, только если
# до него в командной строке нет ДРУГОГО скрипта»). Своя, более строгая форма
# здесь уже ловила гейт чисел (`python3 .docnum-gate.py <кит>/claude-patch-all.sh`)
# и отказывала стенду на чужом аргументе. Копия, а не общий файл: стенд обязан
# уметь краснеть от расхождения с каноном, а не наследовать его молча.
# Условие СНИМАЕТСЯ ЗАНОВО перед каждым сценарием, а не один раз на старте.
# Полный прогон идёт минуты, самопроверка -- десятки минут: настоящий прогон,
# начатый в это окно, ломал сценарии по своей причине, и читатель видел
# «стенд красный» вместо «мерить сейчас нельзя» (круг 21, F-3).
real_run_pids() {
  local __snap __alive __mine __p
  __snap=$(ps -eo pid,args)
  __alive=$(printf '%s\n' "$__snap" | awk '
  $2 ~ /^(\/.*\/)?(bash|sh)$/ && $3 ~ /claude-patch-all\.sh$/ { print $1 }
  /catalyst-tweakcc.*index\.mjs.*(--apply|adhoc-patch)/ { print $1 }' || true)
  # Ниже -- НЕ часть стража, а вычитание СВОИХ: сценарий 45 сам поднимает
  # поддельный claude-patch-all.sh, чтобы проверить страж свипа, и канонический
  # страж обязан его увидеть -- а предусловие стенда обязано НЕ увидеть, иначе
  # стенд отказывает себе на собственной декорации (измерено полным прогоном:
  # «ПРОВАЛ 45 настоящий прогон конвейера не пойман» -- отказ шёл из
  # предусловия и подменял собой вывод свипа). Признак своего -- путь под временным
  # корнем стенда: ни один настоящий прогон оператора там не живёт. Вычитание
  # стоит ПОСЛЕ блока стража намеренно: сравнение форм (сценарий 57) режет
  # текст по «| awk '\''» и по «adhoc-patch», и всё, что ниже, в сравнение не
  # входит -- программа стража остаётся байт в байт канонической.
  __mine=$(printf '%s\n' "$__snap" | awk -v r="${ROOT:-}" '
    r != "" && index($0, r) { print $1 }' || true)
  for __p in $__alive; do
    printf '%s\n' "$__mine" | grep -qx "$__p" || printf '%s\n' "$__p"
  done
}

require_no_real_run() {   # $1 -- что шло дальше (для сообщения)
  local alive
  alive=$(real_run_pids)
  [[ -z "$alive" ]] && return 0
  # Отметка на диске, а не только `exit 3`.
  #
  # Предусловие снимается заново перед каждым игрушечным свипом, а свип всегда
  # зовут из подстановки команд (`out=$(run_sweep ...)`). `exit` внутри неё
  # кончает ТОЛЬКО подстановку: сценарий получал текст этого отказа как вывод
  # свипа и краснел своей формулировкой, а стенд ехал дальше -- ровно то, что
  # предусловие обязано было предотвратить. Отметка переживает подстановку, и
  # верхний уровень (ok/bad) прерывает прогон классом 3.
  [[ -n "${ROOT:-}" ]] && printf '%s\n' "$alive" > "$ROOT/.real-run"
  say "corpus-tools-bench: ОТКАЗ -- идёт настоящий прогон (pid: $alive)."
  say "  Стенд гоняет те же скрипты, и их же страж общего состояния tweakcc"
  say "  отказал бы каждому сценарию раньше проверяемой двери. Дождитесь конца."
  [[ -n "${1:-}" ]] && say "  Прервано перед: $1"
  exit 3
}

# Верхний уровень читает отметку и прерывает прогон целиком.
abort_if_real_run() {
  [[ -n "${ROOT:-}" && -e "${ROOT:-}/.real-run" ]] || return 0
  say "corpus-tools-bench: ОТКАЗ -- настоящий прогон начался посреди стенда (pid: $(tr '\n' ' ' < "$ROOT/.real-run"))."
  say "  Сценарии рядом с ним недостоверны: мерить сейчас нельзя, повторить позже."
  exit 3
}

# --- ОДИН дом опознания процессов ------------------------------------------
#
# 5 сценариев (docnum:subset) искали чужие процессы одной и той же формой
#   ps -eo pid,args | awk -v r="<путь>" 'index($0, r) && /<форма>/ { print $1 }'
# и эта форма НАХОДИТ САМУ СЕБЯ: путь приходит в argv через `-v`, а форма стоит
# в тексте программы awk, поэтому командная строка самого awk удовлетворяет
# ОБОИМ предикатам разом. Замер (волна 40a, Linux, сценарий 95):
#   >> 1370556 awk -v r=/tmp/s10c/s95tmp index($0, r) && /sleep 120/ { print ... }
#   orph_seen = [1370607]  -> вердикт стенда: ПРОВАЛ
# при том, что кит отработал правильно: держатель был снят и дождан, его не
# было даже зомби. На маке ошибка НЕВИДИМА: BSD awk (`awk version 20200816`)
# при `-v name=value` корёжит собственный argv, и `ps` показывает
# `awk -v r ZZPATHZZ` БЕЗ текста программы; GNU Awk 5.3.0 показывает всё.
# Перекрёстная проверка: голая регулярка находит себя на ОБЕИХ платформах --
# значит дело именно в `-v`, а не в общем «соседей не видно». Это тот же урок,
# за который кит уже платил («pgrep -f находит себя»), выживший только потому,
# что платформа его прятала.
#
# КОНСТРЕЙНТ: детектор процессов по форме командной строки обязан исключать
# СЕБЯ, и исключение делается ПО PID, а не по тексту строки -- фильтр по тексту
# сам стал бы следующей ловушкой того же класса (он вычёркивал бы и настоящего
# соседа, чья строка похожа на нашу).
#
# Исключение держится ДВУМЯ независимыми способами:
#   1. Снимок ps снимается ОТДЕЛЬНЫМ шагом и фильтруется ИЗ ПАМЯТИ. Процесса-
#      фильтра в снимке нет ПО ПОСТРОЕНИЮ: он ещё не существовал. Это та же
#      форма, что уже стоит в `real_run_pids` выше -- канон кита, а не новая
#      идея.
#   2. Из снимка вычёркиваются pid'ы, названные ПОИМЕННО: свой ($$, а в
#      подоболочке ещё и BASHPID) и любые, которые назвал вызывающий.
#      Построение вызывающему не докажешь -- он видит только список, -- а
#      поимённое вычёркивание он может замерить, и оно замеряется сценарием.
# BASHPID нет в bash 3.2 (мак): под `set -u` голое обращение к нему было бы
# фатальной ошибкой подстановки, поэтому оно взято с умолчанием.
__ps_snapshot() {   # -> «pid ppid argv» по строке на процесс
  ps -eo pid,ppid,args 2>/dev/null
}

# <корень пути> <регексп argv> [pid, которые НЕ возвращать...] -> pid по строке
__ps_matching() {
  local __root="$1" __re="$2"; shift 2
  local __snap __skip=" $$ ${BASHPID:-$$} $* "
  __snap=$(__ps_snapshot) || return 0
  # Членство в списке -- по ОКРУЖЁННОМУ ПРОБЕЛАМИ числу: без окружения «1» из
  # списка вычеркнуло бы и 21, и 100, то есть исключение по pid молча стало бы
  # исключением по подстроке.
  printf '%s\n' "$__snap" | awk -v root="$__root" -v re="$__re" -v skip="$__skip" '
    index(skip, " " $1 " ") { next }
    index($0, root) && $0 ~ re { print $1 }' || true
}

# <ppid> [регексп, которому потомок НЕ должен отвечать] -> pid по строке
__ps_children() {
  local __ppid="$1" __not="${2:-}"
  local __snap __skip=" $$ ${BASHPID:-$$} "
  __snap=$(__ps_snapshot) || return 0
  printf '%s\n' "$__snap" | awk -v p="$__ppid" -v not="$__not" -v skip="$__skip" '
    index(skip, " " $1 " ") { next }
    $2 != p { next }
    not != "" && $0 ~ not { next }
    { print $1 }' || true
}

# Ранний двойник `say`: настоящее определение ниже, а отказ предусловия
# случается раньше него.
say() { printf '%s\n' "$*"; }
require_no_real_run

ROOT=$(mktemp -d "${TMPDIR:-/tmp}/corpus-bench.XXXXXX")
# Часовой оборванного прогона: bash 3.2 отдаёт код 0, когда скрипт с
# EXIT-трапом умирает на фатальной ошибке ПОДСТАНОВКИ (unbound variable под
# `set -u`, `${x:?}`, bad substitution) -- провал невидим вызывающему
# (измерено 2026-08-28). Штатный конец объявляет себя, трап без объявления
# краснит сам.
__DONE=0
cleanup() {
  __rc=$?
  rm -rf "$ROOT"
  if [[ "${__DONE:-0}" != 1 && "$__rc" == 0 ]]; then
    echo "corpus-tools-bench: ОТКАЗ -- прогон оборвался, не дойдя до конца (ошибка оболочки выше)" >&2
    exit 1
  fi
  exit "$__rc"
}
trap cleanup EXIT
# Круг 28, F-3: сценарий 91 требует 143 БЕЗ строки «ошибка оболочки» у свипа,
# наполнителя и зонда пути -- а сам стенд стоял на слитой форме: TERM приходил
# в cleanup как __rc=0, и остановка оператора называлась «ошибкой оболочки».
# Расщеплено той же волной, что и остальные: явный код сигнала, EXIT-трап
# при этом всё равно исполняется (уборка $ROOT происходит).
trap 'exit 130' INT
trap 'exit 143' TERM

FAILED=0
RUN=0
# След последнего сценария: по нему --self-check требует от мутации ЕЁ причину.
LAST_EVID=""

say()  { printf '%s\n' "$*"; }
# Каждый сценарий кончается ok или bad -- это и есть точка, где верхний уровень
# видит отметку, оставленную предусловием внутри подстановки команд.
ok()   { abort_if_real_run; RUN=$((RUN+1)); say "  ok     $*"; }
bad()  { abort_if_real_run; RUN=$((RUN+1)); FAILED=$((FAILED+1)); say "  ПРОВАЛ $*"; }

# --- игрушечный корпус -------------------------------------------------------
# Версии названы заведомо несуществующими в реестре: если сценарий всё же
# дойдёт до сети, он получит отказ, а не чужой образ.
# Содержимое игрушечного образа -- ОДИН дом.
#
# Оно было записано в пяти местах: в наполнении корпуса и в 4 сценариях
# docnum:subset,
# которые портят образ и восстанавливают его литералом. Когда образу добавили
# номер версии (заглушка обязана отвечать про НЕГО), восстановления вернули
# старый текст -- пин перестал сходиться, и 22 сценария docnum:historical подряд
# покраснели по чужой причине. Одна функция: сменить содержимое можно только
# сразу везде.
toy_image() {   # путь, версия
  printf 'образ %s\n' "$2" > "$1"
}

mk_corpus() {   # каталог-назначение
  local dir=$1
  mkdir -p "$dir/corpus"
  # Образ НЕСЁТ свою версию: заглушка конвейера читает её оттуда и печатает
  # строку дыма про НЕЁ. С константой в заглушке поле вердикта, привязанное к
  # номеру версии, проверялось бы на выдуманном номере.
  toy_image "$dir/corpus/0.0.900.pristine" 0.0.900
  toy_image "$dir/corpus/0.0.901.pristine" 0.0.901
  local h900 h901
  h900=$(shasum -a 256 "$dir/corpus/0.0.900.pristine" | awk '{print $1}')
  h901=$(shasum -a 256 "$dir/corpus/0.0.901.pristine" | awk '{print $1}')
  # Платформа называется и здесь: разбор списка её ТРЕБУЕТ, и игрушечный
  # список без неё проверял бы дверь платформы, а не свой предмет.
  local plat
  plat=$(cd "$KIT" && python3 -c 'import claude_patch; print(claude_patch.npm_platform_pkg())')
  { echo "# игрушечный список стенда"
    echo "# platform: $plat"
    echo "900 0.0.900 $h900"
    echo "901 0.0.901 $h901"
  } > "$dir/versions.txt"
  # Производные списки заводятся один раз, рядом с основным.
  grep -v '^# platform:' "$dir/versions.txt" > "$dir/versions.noplat.txt"
  { echo "# platform: $plat"
    echo "900 0.0.900 $h900"
    echo "900b 0.0.900 $h900"
  } > "$dir/versions.dup.txt"
  { echo "# platform: $plat"
    echo "900 0.0.900 $h900 лишнее"
  } > "$dir/versions.extra.txt"
  { echo "# platform: $plat"
    echo "900 0.0.900 $(printf '%s' "$h900" | tr 'a-f' 'A-F')"
  } > "$dir/versions.upper.txt"
  { echo "# platform: @anthropic-ai/claude-code-и-не-эта-машина"
    echo "900 0.0.900 $h900"
  } > "$dir/versions.foreign.txt"
  # Дубль МЕТКИ при РАЗНЫХ версиях: дубль версии ловит соседняя дверь, и список
  # с обоими совпадениями доказывал бы её, а не эту.
  { echo "# platform: $plat"
    echo "900 0.0.900 $h900"
    echo "900 0.0.901 $h901"
  } > "$dir/versions.duplabel.txt"
  # Пин из 63 знаков -- не «-» и не 64 знака.
  { echo "# platform: $plat"
    echo "900 0.0.900 ${h900:0:63}"
  } > "$dir/versions.badpin.txt"
  # Версия с буквой: имя файла из неё считалось бы молча.
  { echo "# platform: $plat"
    echo "900 0.0.900 $h900"
    echo "90x 0.0.90x $h901"
  } > "$dir/versions.badver.txt"
}

# Копия кита под мутации: сценарии всегда гоняют скрипты ИЗ НЕЁ, поэтому режим
# мутаций отличается от обычного ровно одной правкой в копии.
mk_kit() {   # каталог-назначение
  local dir=$1 __sig
  # Круг 24: КИТ ВЫВЕДЕН ИЗ ПУТИ ЗАПУСКА, а строкой ниже копируется ЦЕЛИКОМ.
  # Позванный не из tools/ -- скажем, из копии в /tmp -- стенд получает KIT=/
  # и копирует корень файловой системы: замерено, 3.8 ГБ за секунды, до ручной
  # остановки. Страж стоит ЗДЕСЬ, а не в шапке, по двум причинам: (1) это точка
  # самой опасности, и новый вызывающий не сможет обойти проверку; (2) двери,
  # которые НЕ копируют (--table-check), обязаны работать откуда угодно -- их
  # проверяет сценарий 43, запуская стенд из временного каталога.
  # Подпись кита -- три его файла; нет любого => прибор не может мерить (код 2).
  for __sig in claude-patch-all.sh tools/sweep.sh tools/corpus-versions.txt; do
    if [[ ! -f "$KIT/$__sig" ]]; then
      echo "corpus-tools-bench: КОРЕНЬ НЕ КИТ -- в «${KIT}» нет ${__sig}." >&2
      echo "  Стенд копирует кит целиком; запускать только как" >&2
      echo "  tools/corpus-tools-bench.sh внутри кита." >&2
      exit 2
    fi
  done
  mkdir -p "$dir"
  cp -R "$KIT"/. "$dir"/
  # Конвейер игрушечного кита -- ЗАГЛУШКА.
  #
  # Двери, которые проверяет стенд, срабатывают ДО первой сборки, но мутации,
  # эти двери отключающие, пускали свип дальше -- в НАСТОЯЩИЙ конвейер: он брал
  # боевой замок, лез в сеть за распаковщиком и упирался в игрушечную цель.
  # Безопасность держалась на его раннем отказе, который стенд не пинил.
  #
  # Заглушка печатает РОВНО те маркеры, по которым свип считает поля вердикта,
  # и умеет убрать любой из них (STUB_TWEAK) или вернуть любой код (STUB_RC).
  # Так каждое слагаемое вердикта получает свой сценарий и свою мутацию.
  # Настоящий источник сохраняется без суффикса .sh: сценарий env-ручек обязан
  # читать и мутировать ТОТ ЖЕ код, но перепись shell-потребителей замка не
  # должна принять неисполняемую копию стенда за ещё один самостоятельный дом.
  mv "$dir/claude-patch-all.sh" "$dir/claude-patch-all.real"
  cat > "$dir/claude-patch-all.sh" <<'STUB'
#!/usr/bin/env bash
# Заглушка конвейера для tools/corpus-tools-bench.sh. Печатает маркеры, по
# которым свип считает поля вердикта. STUB_TWEAK убирает один маркер (или
# добавляет [FAIL]/NUL), STUB_RC задаёт код возврата, STUB_TAMPER портит
# названный файл -- так проверяется сверка КОПИИ, сделанной после сверки пинов.
set -u
# Перечисления секций НЕ пишутся здесь руками: строки подставляет сборщик
# игрушечного кита, вырезая их из настоящего конвейера. Свип читает их из
# снимка кита, и вторая, разошедшаяся копия сделала бы стенд измерителем
# расхождения, которого в ките нет.
TW_RESULTS_ANCHOR='@@TW_RESULTS_ANCHOR@@'
__TW_CODE_SECTIONS='@@TW_CODE_SECTIONS@@'
__TW_PROMPT_SECTIONS='@@TW_PROMPT_SECTIONS@@'
# Имя отметки происхождения дома tweakcc: свип достаёт его из конвейера тем же
# якорем, что и перечисления, и без строки здесь отказался бы стартовать.
TWEAKCC_HOME_ORIGIN_NAME='@@TWEAKCC_HOME_ORIGIN_NAME@@'
tweak="${STUB_TWEAK:-none}"
# Цель читается ИЗ АРГУМЕНТОВ: два поля вердикта -- версия и дайджест --
# привязаны к тому, что конвейеру передали, и заглушка обязана отвечать про
# ЭТОТ файл, а не про константу. `--expect-sha` она принимает и молчит: свою
# дверь пина настоящий конвейер закрывает сам (проверено прямым прогоном), а
# стенд здесь меряет ВЕРДИКТ СВИПА.
target=""
while [[ $# -gt 0 ]]; do
  case "$1" in
    --target)     target="${2:-}"; shift 2 ;;
    --expect-sha) shift 2 ;;
    *)            shift ;;
  esac
done
unless() { [[ "$tweak" == "$1" ]] || printf '%s\n' "$2"; }
[[ -z "${STUB_TAMPER:-}" ]] || printf 'подменённые байты\n' > "$STUB_TAMPER"
# STUB_LINGER: оставить за собой ЖИВОЙ процесс, чей путь ведёт в снимок кита.
# Так проверяется, что свип не сносит снимок из-под ещё исполняющегося
# конвейера (круг 21, F-9). Путь снимка попадает в аргументы через $0.
#
# Ожидание -- ВСТРОЕННЫЙ read -t, а не ребёнок sleep: голый `sleep 25` не
# несёт пути снимка в argv, невидим для ловца жильцов и доживает сиротой
# (сценарий 84 убирал только носителя пути). Читается из /dev/zero: EOF на
# унаследованном stdin обрывал бы ожидание мгновенно.
[[ -z "${STUB_LINGER:-}" ]] || { bash -c 'read -t 25 x; true' "$0" < /dev/zero >/dev/null 2>&1 & }
# STUB_SLEEP: держать сам прогон заглушки N секунд -- окно для сигналов,
# адресованных СВИПУ, пока идёт версия (сценарий 91).
[[ -z "${STUB_SLEEP:-}" ]] || sleep "$STUB_SLEEP"
ver=$(awk '{print $2; exit}' "$target" 2>/dev/null)
[[ "$tweak" != otherver ]] || ver=0.0.999
sha=$(shasum -a 256 "$target" 2>/dev/null | awk '{print $1}')
# Баннер прогона tweakcc: полный, либо частичный (режимы parttw*); NOTE
# конвейера об объявленных непроходах печатает только parttw, а
# parttw_undeclared оставляет частичный баннер без неё.
case "$tweak" in
  notw) ;;
  parttw|parttw_undeclared) printf 'Customizations applied with some failures.\n' ;;
  *) printf 'Customizations applied successfully\n' ;;
esac
[[ "$tweak" != parttw ]] || printf 'NOTE: объявленные непроходы tweakcc на %s (гейт держится на остальных):\n' "$ver"
# Лог печатается СЕКЦИЯМИ: так его печатает форк, и по секции свип относит
# строку правки к слою. Лог АСИММЕТРИЧЕН намеренно -- при раскладе 1/1
# перестановка двух счётчиков свипа ролями оставляет расклад неизменным, и пин
# сценария 116 теряет зуб.
# Имена правок выбраны ВРАЗРЕЗ с секцией: правки кода названы типами накладок
# («Data: model list», «Skill: rename»), а накладка -- незнакомым типом
# («Custom Kind: my overlay»). Счёт по секции даёт 3/1, счёт по префиксу имени
# дал бы 2/2 -- подмена разбора видна ЧИСЛОМ, а не только на глаз.
# Разделитель перечисления -- ТАБУЛЯЦИЯ (см. claude-patch-all.sh): он подставлен
# сюда вместе со строкой из настоящего конвейера, и разбор обязан быть тем же.
__tw_tab=$'\t'
__tw_c1="${__TW_CODE_SECTIONS%%"$__tw_tab"*}"
__tw_crest="${__TW_CODE_SECTIONS#*"$__tw_tab"}"
__tw_c2="${__tw_crest%%"$__tw_tab"*}"
__tw_p1="${__TW_PROMPT_SECTIONS%%"$__tw_tab"*}"
# ЯКОРЬ блока результатов: читатели слоя ограничены областью ПОСЛЕ него (форк
# печатает те же заголовки секций и в предапплайном списке плана). Заглушка без
# якоря отдала бы свипу ПУСТУЮ область -- расклад слоёв стал бы нулевым при
# исправном разборе, и сценарии мерили бы не тот вход. Строка берётся из
# носителя разбора, а не вписана здесь второй копией.
# Предапплайный СПИСОК ПЛАНА форка: те же заголовки секций, но ДО якоря. Его
# строки читателям слоя не принадлежат, и режим planticks кладёт туда ГАЛОЧКУ --
# так проверяется, что поле суммы больше не считает её своим образцом.
[[ "$tweak" != planticks ]] || { printf '  %s:\n' "$__tw_c1"; printf '    ✓ plan only\n'; }
# Якорь: ноль и два -- две разные поломки читателя, и обе тихие. Двойной якорь
# моделирует ЧИСЛО якорей (предмет двери), а не удвоенный блок.
# Режим nopatches якорь ПЕЧАТАЕТ: его предмет -- пустой блок результатов, а не
# пропавший блок. Сняв там якорь, стенд смешал бы две разные поломки в одном
# сценарии, и мутация, отменившая дверь «ни одного патча», осталась бы
# незамеченной -- красным вердикт держала бы соседняя дверь якоря.
case "$tweak" in
  noanchor) ;;
  twoanchors) printf '%s\n' "$TW_RESULTS_ANCHOR"; printf '%s\n' "$TW_RESULTS_ANCHOR" ;;
  *) printf '%s\n' "$TW_RESULTS_ANCHOR" ;;
esac
unless nopatches  "  ${__tw_c1}:"
unless nopatches  '    ✓ site'
unless nopatches  '    ✓ Data: model list'
unless nopatches  "  ${__tw_c2}:"
unless nopatches  '    ✓ Skill: rename'
unless nopatches  "  ${__tw_p1}:"
unless nopatches  '    ✓ Custom Kind: my overlay'
# Промах слоя накладок печатает сам tweakcc -- с НАЧАЛА строки; перечень
# конвейера ниже пересказывает тот же промах с отступом. Обе строки здесь,
# потому что неякоренный счёт свипа считал бы их за два промаха.
unless nomiss 'Could not find system prompt "stub" in cli.js'
unless nomiss '  не найдена накладка: stub'
unless nomiss 'Could not find system prompt for stub in cli.js'
unless nomiss '  не найдена накладка (строка не разобрана, не-ASCII снят): Could not find system prompt for stub in cli.js'
unless noours  'Script patch applied'
unless nook    '  [OK] stub check'
[[ "$tweak" != fail ]] || printf '  [FAIL] stub check\n'
unless nodigest "Source digest: $sha  $target"
unless nosmoke "Version: $ver (Claude Code)"
unless noiface 'Interface: stub'
unless nobench 'Probes: 1 scenarios behaved as specified'
unless noforms 'ФОРМЫ ОБОЛОЧКИ ЧИСТЫ: разобрано файлов 1'
unless nofloor 'ПОЛ ПРОВЕРОК СОШЁЛСЯ: на пристинном образе зелёных 1 из 1, все объявлены'
case "$tweak" in
  notwlevel) ;;
  blindtwlevel|blindtwboth) printf 'NOTE: CLAUDE_PATCH_ALLOW_TWEAKCC_FAILURES=1 -- дверь уровня tweakcc погашена (попыток 3, легло 3, промтов 1)\n' ;;
  *) printf 'NOTE: уровень tweakcc на %s сошёлся: код 3 попыток (объявлено 3), промты 1 (пол 1)\n' "$ver" ;;
esac
# Дверь МНОЖЕСТВА выключенных правок -- СОСЕДНЯЯ, и у неё ТРИ терминальных
# ответа. Слепой ответ печатается с тем же именем ручки, что у двери уровня:
# режим blindtwboth печатает оба сразу, и им проверяется, что поле свипа сужено
# по имени ДВЕРИ -- иначе одна ручка дала бы двойку в обоих полях.
case "$tweak" in
  notwoff) ;;
  blindtwboth) printf 'NOTE: CLAUDE_PATCH_ALLOW_TWEAKCC_FAILURES=1 -- дверь выключенных правок tweakcc погашена (выключено 0)\n' ;;
  emptyoff) printf 'NOTE: объявления выключенных правок tweakcc для дома /toy/tweakcc нет, и выключенных правок не измерено (0) -- сходится\n' ;;
  originoff) printf 'NOTE: дом tweakcc /toy/tweakcc создан прогоном, а не оператором (sweep-created 2026-01-01T00:00:00Z abc1234): объявления выключенных правок у него нет, выключено конфигурацией 30 -- это дефолты форка, дрейфовать в таком доме нечему\n' ;;
  *) printf 'NOTE: выключенные конфигурацией правки tweakcc на %s сошлись с объявлением дома: 0\n' "$ver" ;;
esac
# Дверь ИНЕРТНЫХ правок -- ТРЕТЬЯ соседка, и у неё тоже три терминальных
# ответа. Слепой ответ печатается тем же именем ручки, что у двух соседних:
# режим blindtwboth печатает все три, и ими проверяется, что каждое поле свипа
# сужено по имени СВОЕЙ двери -- иначе одна ручка дала бы тройку в каждом.
case "$tweak" in
  notwinert) ;;
  blindtwboth) printf 'NOTE: CLAUDE_PATCH_ALLOW_TWEAKCC_FAILURES=1 -- дверь инертных правок tweakcc погашена (пропущено по версии 0, вхолостую 0)\n' ;;
  emptyinert) printf 'NOTE: инертных правок tweakcc на %s не объявлено и не измерено -- сходится.\n' "$ver" ;;
  *) printf 'NOTE: инертные правки tweakcc на %s сошлись с объявлением: пропущено по версии 0, вхолостую 0 (из /toy/kit/tools/tweakcc-expected-inert.txt)\n' "$ver" ;;
esac
# Часовой ФОРМЫ вывода -- ЧЕТВЁРТАЯ соседка, и с волны 39d его голос безусловен:
# на здоровом прогоне он называет измеренное число нарушителей (ноль). Условный
# голос делал бы поле свипа нулём на законном прогоне, то есть неотличимым от
# снятого часового.
case "$tweak" in
  notwform) ;;
  blindtwboth) printf 'NOTE: CLAUDE_PATCH_ALLOW_TWEAKCC_FAILURES=1 -- часовой формы вывода tweakcc погашен (строк вне известных секций либо с незнакомым знаком: 0)\n' ;;
  *) printf 'NOTE: часовой формы строк tweakcc на %s: строк вне известных секций 0\n' "$ver" ;;
esac
# Дверь НЕПРОШЕДШИХ НАКЛАДОК -- ПЯТАЯ, и её голос безусловен по той же причине.
# Слепой ответ начинается с того же имени ручки, что у трёх «дверей» и у
# «часового»: режим blindtwboth печатает все пять, и ими проверяется, что каждое
# поле свипа сужено по имени СВОЕЙ двери.
case "$tweak" in
  notwpfail) ;;
  blindtwboth) printf 'NOTE: CLAUDE_PATCH_ALLOW_TWEAKCC_FAILURES=1 -- дверь непрошедших накладок tweakcc погашена (не легло накладок 0)\n' ;;
  *) printf 'NOTE: накладки промтов tweakcc на %s: объявленных не легшими 0\n' "$ver" ;;
esac
# Строки формы правки ПОСЛЕ блока результатов: область, которую читает только
# свип -- захват конвейера кончается на выводе форка. Секция незнакомая, значит
# строка не попадает ни в один счёт и обязана быть названа часовым СВИПА, а не
# растворяться в тишине.
[[ "$tweak" != postform ]] || { printf '  Post Block Group:\n'; printf '    ✓ post-block edit\n'; }
[[ "$tweak" != nul ]] || printf 'второй писатель\000\n'
# Литерал маршрутной правки. Сторож зубной стадии свипа удостоверяет продукт
# СОБСТВЕННЫМ замером байтов собранного образа (grep -F по этой игле), а не
# свидетелем вызова в логе: настоящий конвейер вписывает эту строку в образ,
# и заглушка, не пишущая её, расходилась бы с оригиналом ровно здесь --
# сторож видел бы ноль вхождений и уводил каждый зелёный сценарий в отказ.
# Пишется ТОЛЬКО при нулевом коде возврата и непустой существующей цели:
# отказ конвейера означает, что продукта нет, и образ обязан остаться
# нетронутым. Ручка STUB_NO_MARKER снимает дописывание, не трогая код
# возврата, -- она существует ровно для отрицательного плеча сценария
# «успех объявлен, а правки в образе нет».
if [[ "${STUB_RC:-0}" == 0 && -z "${STUB_NO_MARKER:-}" && -n "$target" && -f "$target" ]]; then
  printf '%s\n' 'baseURL:/^claude/i.test(' >> "$target"
fi
exit "${STUB_RC:-0}"
STUB
  # Перечисления секций вырезаются из НАСТОЯЩЕГО конвейера (он лежит рядом как
  # claude-patch-all.real) и подставляются в заглушку. Отсутствие строки в
  # источнике -- отказ ПРИБОРА (код 2), а не заглушка без перечисления: свип на
  # такой снимок отказывается стартовать, и вина легла бы на свип.
  # Оба перечисления идут ОДНОЙ лестницей: разные требования к ним развели бы
  # строгость стенда со строгостью свипа, который читает их одним носителем.
  # Якорь блока результатов вырезается из НОСИТЕЛЯ РАЗБОРА (tools/tw-layer.sh),
  # а перечисления секций -- из конвейера: у каждой константы один дом, и
  # заглушка повторяет ровно ту строку, которую исполняет читатель. Вторая копия
  # якоря здесь разошлась бы с ним ровно так же, как когда-то разошёлся разбор.
  __anchor_hits=$(grep -a -c '^TW_RESULTS_ANCHOR=' "$dir/tools/tw-layer.sh" 2>/dev/null || echo 0)
  if [[ "$__anchor_hits" != 1 ]]; then
    echo "corpus-tools-bench: в носителе разбора присваиваний TW_RESULTS_ANCHOR $__anchor_hits, а нужно ровно одно --" >&2
    echo "  заглушка не смогла бы повторить якорь, и свип мерил бы пустую область." >&2
    exit 2
  fi
  __anchor_line=$(sed -n "/^TW_RESULTS_ANCHOR='/p" "$dir/tools/tw-layer.sh")
  if ! python3 - "$dir/claude-patch-all.sh" TW_RESULTS_ANCHOR "$__anchor_line" <<'INJECT'
import io, sys
path, name, line = sys.argv[1], sys.argv[2], sys.argv[3]
text = io.open(path, encoding='utf-8').read()
mark = "%s='@@%s@@'" % (name, name)
if text.count(mark) != 1:
    sys.stderr.write('corpus-tools-bench: место под якорь в заглушке не одно\n')
    raise SystemExit(2)
io.open(path, 'w', encoding='utf-8').write(text.replace(mark, line))
INJECT
  then
    echo "corpus-tools-bench: подстановка якоря в заглушку не удалась." >&2
    exit 2
  fi
  # Константы кита, которые заглушка обязана повторить ДОСЛОВНО: перечисления
  # секций и имя отметки происхождения дома. Все три свип читает из снимка
  # ЯКОРЕМ, поэтому лестница у них одна -- разные требования развели бы
  # строгость стенда со строгостью свипа.
  for __sec_name in __TW_CODE_SECTIONS __TW_PROMPT_SECTIONS TWEAKCC_HOME_ORIGIN_NAME; do
    __sec_hits=$(grep -a -c "^${__sec_name}=" "$dir/claude-patch-all.real")
    if [[ "$__sec_hits" != 1 ]]; then
      echo "corpus-tools-bench: в ките присваиваний $__sec_name $__sec_hits, а нужно ровно одно --" >&2
      echo "  заглушка повторила бы не ту строку, которую исполняет конвейер." >&2
      exit 2
    fi
    __sec_line=$(sed -n "/^${__sec_name}='/p" "$dir/claude-patch-all.real")
    if [[ -z "$__sec_line" ]]; then
      echo "corpus-tools-bench: в ките нет присваивания $__sec_name --" >&2
      echo "  заглушке нечем повторить константу кита, мерить нечем." >&2
      exit 2
    fi
    if ! python3 - "$dir/claude-patch-all.sh" "$__sec_name" "$__sec_line" <<'INJECT'
import io, sys
path, name, line = sys.argv[1], sys.argv[2], sys.argv[3]
text = io.open(path, encoding='utf-8').read()
# Метка -- имя БЕЗ ведущих подчёркиваний: внутренние константы конвейера
# зовутся `__TW_...`, а место под них в заглушке помечено `@@TW_...@@`.
# Правило записано ОДНО на все константы: прежняя редакция резала ровно два
# первых символа, и константа без такой приставки получала метку из середины
# собственного имени -- подстановка не находила места и винила заглушку.
mark = "%s='@@%s@@'" % (name, name.lstrip('_'))
if text.count(mark) != 1:
    sys.stderr.write('corpus-tools-bench: место под константу %s в заглушке не одно\n' % name)
    raise SystemExit(2)
io.open(path, 'w', encoding='utf-8').write(text.replace(mark, line))
INJECT
    then
      echo "corpus-tools-bench: подстановка константы $__sec_name в заглушку не удалась --" >&2
      echo "  метка осталась бы на месте, и отказ свипа не сработал бы: вина легла бы на свип." >&2
      exit 2
    fi
  done
  chmod +x "$dir/claude-patch-all.sh"
  # НАСТОЯЩИЙ зонд остаётся в копии под именем `.real.sh`: сценарий формы имени
  # замка считает ДОМА этой формы по игрушечному дереву, и заглушка, вставшая
  # на место файла, унесла бы один дом вместе с его мутацией -- то есть стенд
  # перестал бы проверять правило, о котором рапортует.
  mv "$dir/tools/build-path-probe.sh" "$dir/tools/build-path-probe.real.sh"
  # Зонд пути сборки -- тоже ЗАГЛУШКА. Настоящий гонит полные сборки минутами,
  # берёт боевой замок и одалживает живой ~/.tweakcc; стенд меряет не его, а
  # предполётную ДВЕРЬ свипа: позвали ли, как прочли код, объявлен ли пропуск.
  # Отметка «позвали» кладётся на диск: строку в логе печатает и сам свип.
  cat > "$dir/tools/build-path-probe.sh" <<'PROBESTUB'
#!/usr/bin/env bash
set -u
[[ -z "${STUB_PROBE_MARK:-}" ]] || printf 'зонд звался\n' > "$STUB_PROBE_MARK"
echo "stub build-path-probe rc=${STUB_PROBE_RC:-0}"
exit "${STUB_PROBE_RC:-0}"
PROBESTUB
  chmod +x "$dir/tools/build-path-probe.sh"
  mv "$dir/tools/checks-teeth.py" "$dir/tools/checks-teeth.real.py"
  # Прибор зубов реестра -- тоже ЗАГЛУШКА: настоящему нужен СОБРАННЫЙ образ и
  # минуты на мутации, а стенд меряет предполётную ДВЕРЬ свипа -- позвали ли,
  # как прочли КЛАСС ответа, объявлен ли пропуск. Отметка «позвали» кладётся на
  # диск, как у зонда пути сборки.
  cat > "$dir/tools/checks-teeth.py" <<'TEETHSTUB'
#!/usr/bin/env python3
import os
import sys

mark = os.environ.get('STUB_TEETH_MARK', '')
if mark:
    with open(mark, 'w', encoding='utf-8') as fh:
        fh.write('прибор зубов звался\n')
        fh.write('argv=%s\n' % ' '.join(sys.argv))
if os.environ.get('STUB_TEETH_CONTROL_FAIL', ''):
    print('checks-teeth: КОНТРОЛЬ ПРОВАЛЕН -- образ красен ещё до мутаций:',
          file=sys.stderr)
    sys.exit(2)
rc = int(os.environ.get('STUB_TEETH_RC', '0') or 0)
print('stub checks-teeth rc=%d' % rc)
sys.exit(rc)
TEETHSTUB
  chmod +x "$dir/tools/checks-teeth.py"
  # И САМ СТЕНД -- заглушка, по той же причине. Предполёт свипа зовёт стенд
  # корпусных инструментов; свип здесь запускается ИЗ стенда, то есть настоящий
  # стенд позвал бы сам себя, упёрся в собственный замок и встал на бюджете
  # ожидания (измерено: прогон замирал на девятом сценарии). Настоящий остаётся
  # под именем `.real.sh` -- его гоняют сценарии таблиц и очереди, его же правят
  # мутации. Заглушка отвечает мгновенно и умеет вернуть любой код.
  mv "$dir/tools/corpus-tools-bench.sh" "$dir/tools/corpus-tools-bench.real.sh"
  # Перепись замков в КОПИИ описывает и переименованные инструменты: census
  # прибора замка сканирует *.sh дерева копии, где настоящие файлы лежат под
  # именами .real.sh и открывают те же замки. Живой README этих строк не
  # носит: в живом дереве таких путей нет.
  cat >> "$dir/README.md" <<'CENSUS'

| `tools/build-path-probe.real.sh` | 9 | ТОТ ЖЕ файл | копия зонда внутри снимка кита: та же очередь |
| `tools/corpus-tools-bench.real.sh` | 9 | CORPUS_BENCH_LOCK | копия стенда внутри снимка кита: та же очередь |
CENSUS
  cat > "$dir/tools/corpus-tools-bench.sh" <<'BENCHSTUB'
#!/usr/bin/env bash
set -u
[[ -z "${STUB_BENCH_MARK:-}" ]] || printf 'стенд звался: %s\n' "${1:-прогон}" >> "$STUB_BENCH_MARK"
echo "stub corpus-tools-bench ${1:-прогон} rc=${STUB_BENCH_RC:-0}"
exit "${STUB_BENCH_RC:-0}"
BENCHSTUB
  chmod +x "$dir/tools/corpus-tools-bench.sh"
}

# --- сценарии ----------------------------------------------------------------
# Каждый: подготовить состояние, запустить, потребовать код возврата и текст.

# Свой рабочий корень: иначе стенд бьётся о замок ЖИВОГО прогона и пишет в его
# сводку. Каталог создаётся рядом с игрушечным корпусом и уходит вместе с ним.
# Бухгалтерия внешнего свипа СНИМАЕТСЯ, а не наследуется.
#
# С волны 21 стенд зовётся ИЗ свипа (предполёт), а свип экспортирует
# SWEEP_LEADER=1, SWEEP_KIT и SWEEP_SELF. Унаследовав их, игрушечный свип
# пропускал блок лидера: не делал своей копии, не уходил в свою сессию и брал
# ЧУЖОЙ SWEEP_KIT -- то есть настоящий кит вместо игрушечного. Измерено
# 2026-08-28: сценарии 9/16/18/19 покраснели ложно, «80-секундный» предполёт
# сорок минут гонял НАСТОЯЩИЕ сборки с настоящим tweakcc и зондом пути сборки
# по ЖИВОМУ ~/.tweakcc, и диск ушёл в ноль -- восстановление живого состояния
# не дописалось. Инструмент обязан мерить одно и то же, откуда бы его ни
# позвали.
SWEEP_ENV_SCRUB=(env -u SWEEP_LEADER -u SWEEP_KIT -u SWEEP_SELF -u SWEEP_LAST_N)

# Второй слой, и он ГЛАВНЫЙ. Скруббер выше защищает КАЖДЫЙ пусковой по
# отдельности -- то есть держится на памяти автора СЛЕДУЮЩЕГО пускового.
# 2026-08-30 эта память подвела: волна 25 добавила шестой пусковой (сценарий
# 87, S13) без скруббера, игрушечный свип унаследовал SWEEP_LEADER=1 настоящего
# свипа, пропустил блок лидера, перехватчик не был позван вовсе -- «прибор не
# мерит», -- и ПЕРВЫЙ настоящий предполёт после той волны отказал. Пин формы
# этого не видел ПО УСТРОЙСТВУ: он считает ИСПОЛЬЗОВАНИЯ скруббера, а
# пусковой, который скруббер ЗАБЫЛ, использований не добавляет.
#
# Снятие у СЕБЯ закрывает класс целиком: наследовать нечего, что бы ни забыл
# будущий пусковой. Скрубберы пусковых остаются вторым слоем -- они держат
# другой случай: переменную ставит сам сценарий (поведенческая половина
# сценария 66). Свои SWEEP_* стенд для собственной логики не читает.
unset SWEEP_LEADER SWEEP_KIT SWEEP_SELF SWEEP_LAST_N

# Ручки ПРОПУСКА у сценариев свои (BENCH_SKIP_PROBE/BENCH_SKIP_TOOLS): прежде
# пусковой пробрасывал операторские SWEEP_SKIP_* «как есть», и человек, честно
# выключивший предполётный зонд для своего свипа, ронял сценарий 53 внутри
# стенда -- документированная ручка валила несвязанный гейт, а диагноз указывал
# на стенд (раунд 19, В-6).
# Игрушечный дом tweakcc для прогонов стенда.
#
# Свип теперь СЕМЕНИТ свой дом из живого, и без этой подмены каждый игрушечный
# прогон клонировал бы живой дом (у него 116 МБ кэша промтов) -- десятки раз за
# прогон стенда, и живой дом читался бы там, где стенд не должен его знать
# вовсе. Пусковой инструмента снимает бухгалтерию вызывающего; здесь он ещё и
# ПОДСТАВЛЯЕТ свою: крошечный дом с одним файлом настроек.
TW_FIXTURE="$ROOT/tweakcc-fixture"
mkdir -p "$TW_FIXTURE"
printf '{}\n' > "$TW_FIXTURE/config.json"

run_sweep() {   # kit, corpus-dir, list, аргументы...
  local kit=$1 cdir=$2 list=$3; shift 3
  # Стенд всегда называет значение: 5 имитирует боевое умолчание, а явно
  # заданная пустая строка остаётся пустой и доходит до валидатора как негодность.
  local __bench_last_n="${BENCH_LAST_N-5}"
  # Условие пересматривается ПЕРЕД КАЖДЫМ игрушечным свипом: настоящий прогон,
  # начатый после старта стенда, отказал бы этому свипу своим стражем общего
  # состояния -- и сценарий покраснел бы по чужой причине (круг 21, F-3).
  require_no_real_run "игрушечный свип ($*)"
  # Замок конвейера -- СВОЙ: сценарий занятого замка прежде держал боевой файл,
  # и законный прогон оператора в это окно получал FATAL от стенда.
  "${SWEEP_ENV_SCRUB[@]}" \
    CORPUS_DIR="$cdir" CORPUS_LIST="$list" SWEEP_STATE_DIR="$cdir/state" \
    CLAUDE_PATCH_LOCK="$PLOCK" \
    STUB_TWEAK="${STUB_TWEAK:-none}" STUB_RC="${STUB_RC:-0}" \
    STUB_NO_MARKER="${STUB_NO_MARKER:-}" \
    STUB_TAMPER="${STUB_TAMPER:-}" STUB_LINGER="${STUB_LINGER:-}" \
    STUB_SLEEP="${STUB_SLEEP:-}" \
    SWEEP_KIT_DRAIN="${BENCH_KIT_DRAIN:-}" \
    STUB_PROBE_RC="${STUB_PROBE_RC:-0}" STUB_PROBE_MARK="${STUB_PROBE_MARK:-}" \
    STUB_BENCH_RC="${STUB_BENCH_RC:-0}" STUB_BENCH_MARK="${STUB_BENCH_MARK:-}" \
    SWEEP_SKIP_TOOLS_BENCH="${BENCH_SKIP_TOOLS:-}" \
    SWEEP_SKIP_BUILD_PROBE="${BENCH_SKIP_PROBE:-}" \
    SWEEP_LAST_N="$__bench_last_n" \
    STUB_TEETH_RC="${STUB_TEETH_RC:-0}" STUB_TEETH_MARK="${STUB_TEETH_MARK:-}" \
    STUB_TEETH_CONTROL_FAIL="${STUB_TEETH_CONTROL_FAIL:-}" \
    SWEEP_SKIP_CHECKS_TEETH="${BENCH_SKIP_TEETH:-}" \
    TWEAKCC_CONFIG_DIR="${BENCH_TW_HOME:-$TW_FIXTURE}" \
    bash "$kit/tools/sweep.sh" "$@" 2>&1 9>&-
}

run_fetch() {   # kit, corpus-dir, list
  local kit=$1 cdir=$2 list=$3
  "${SWEEP_ENV_SCRUB[@]}" \
    CORPUS_DIR="$cdir" CORPUS_LIST="$list" bash "$kit/tools/fetch-corpus.sh" 2>&1 9>&-
}

expect_refusal() {   # имя, ожидаемая подстрока, вывод, код
  local name=$1 want=$2 out=$3 rc=$4
  LAST_EVID="rc=$rc :: $out"
  if [[ $rc -eq 0 ]]; then
    bad "$name: код возврата 0, ждали отказ"; return
  fi
  if [[ "$out" != *"$want"* ]]; then
    bad "$name: в выводе нет «${want}»; было: $(printf '%s' "$out" | head -2 | tr '\n' ' ')"
    return
  fi
  ok "$name"
}

# Красная строка вердикта: прогон обязан назвать ИМЕННО эту причину и вернуть
# ненулевой код. Заглушка задаёт лог, сценарий -- ожидаемое слагаемое.
expect_red() {   # имя, режим заглушки, ожидаемая причина, [код заглушки]
  local name=$1 tweak=$2 want=$3 stub_rc=${4:-0} out rc
  out=$(STUB_TWEAK="$tweak" STUB_RC="$stub_rc" \
        run_sweep "$K" "$C/corpus" "$C/versions.txt" 900); rc=$?
  LAST_EVID="rc=$rc :: $out"
  if (( rc == 0 )); then
    bad "$name: код возврата 0 -- вердикт принял такой лог"; return
  fi
  if [[ "$out" != *"КРАСНАЯ: "*"$want"* ]]; then
    bad "$name: в вердикте нет причины «${want}»; было: $(printf '%s' "$out" | grep -a 'SWEEP 900' | head -1)"
    return
  fi
  ok "$name"
}

# Держатель считается готовым, когда замок ДЕЙСТВИТЕЛЬНО занят -- проба той же
# лестницей, а не истечение фиксированной паузы: под load 30-40 испытуемый
# доходил до замка уже после смерти держателя, и сценарий краснел по чужой
# причине -- «замок не занят», а не «дверь не работает».
LOCK_HOLD_BUDGET=15
wait_holder_ready() {   # файл замка; 0 -- держатель занял, 1 -- бюджет исчерпан
  local left=$LOCK_HOLD_BUDGET __hrc
  while (( left > 0 )); do
    perl -e 'use Fcntl ":flock"; open(my $fh, ">>", $ARGV[0]) or exit 2;
             exit(flock($fh, LOCK_EX|LOCK_NB) ? 0 : 1);' "$1" 2>/dev/null
    __hrc=$?
    (( __hrc == 1 )) && return 0
    sleep 1
    left=$(( left - 1 ))
  done
  say "corpus-tools-bench: ОТКАЗ -- держатель не занял замок $1 за ${LOCK_HOLD_BUDGET} c -- прибор не мерил" >&2
  return 1
}

# Мёртвый pid для сценариев-прополок: случайно ВЫБРАННЫЙ номер может оказаться
# живым, и проверка превратится в гонку с машиной.
dead_pid() {
  sh -c 'exit 0' &
  local pid=$!
  wait "$pid"
  printf '%s' "$pid"
}

scenario_1() {   # неизвестное имя версии
  local out rc
  out=$(run_sweep "$K" "$C/corpus" "$C/versions.txt" 999); rc=$?
  expect_refusal "1 неизвестная версия -- отказ" "не в списке" "$out" $rc
}

scenario_2() {   # образа нет
  rm -f "$C/corpus/0.0.901.pristine"
  local out rc
  out=$(run_sweep "$K" "$C/corpus" "$C/versions.txt" 901); rc=$?
  toy_image "$C/corpus/0.0.901.pristine" 0.0.901
  expect_refusal "2 образа нет -- отказ до сборки" "нет пристинных образов" "$out" $rc
}

scenario_3() {   # байты не сходятся с пином
  printf 'подменённые байты\n' > "$C/corpus/0.0.901.pristine"
  local out rc
  out=$(run_sweep "$K" "$C/corpus" "$C/versions.txt" 901); rc=$?
  toy_image "$C/corpus/0.0.901.pristine" 0.0.901
  # Текст двери назван ПОЛНОСТЬЮ: «не сходится с пином» пишет и вторая дверь --
  # сверка КОПИИ перед подачей конвейеру. Сценарий про первую, дособорочную;
  # на коротком образце он зеленел и с выключенной первой дверью.
  expect_refusal "3 подменённый образ -- отказ по пину" "корпус не сходится с пином" "$out" $rc
}

scenario_4() {   # пин не записан
  sed 's/^901 0.0.901 .*/901 0.0.901 -/' "$C/versions.txt" > "$C/versions.nopin.txt"
  local out rc
  out=$(run_sweep "$K" "$C/corpus" "$C/versions.nopin.txt" 901); rc=$?
  expect_refusal "4 пин не записан -- отказ" "пин не записан" "$out" $rc
}

scenario_5() {   # список пуст
  { echo "# только комментарий"
    grep '^# platform:' "$C/versions.txt"
  } > "$C/versions.empty.txt"
  local out rc
  out=$(run_sweep "$K" "$C/corpus" "$C/versions.empty.txt"); rc=$?
  expect_refusal "5 пустой список -- отказ" "нет ни одной версии" "$out" $rc
}

scenario_6() {   # списка нет -- разбирать нечего, класс 2
  local out rc
  out=$(run_sweep "$K" "$C/corpus" "$C/нет-такого.txt"); rc=$?
  expect_refusal "6 нет списка версий -- отказ" "нет списка версий" "$out" $rc
  # Класс ответа: названного списка нет -- прибор НЕ МЕРИЛ, а не «список не
  # проходит разбор» (раунд 19, A-7).
  if (( rc != 2 )); then
    LAST_EVID="КЛАСС_НЕ_ТОТ rc=$rc :: $out"
    bad "6 нет списка версий: код возврата $rc, ждали 2"
  fi
}

scenario_7() {   # замок свипа занят
  # Держателям закрывается дескриптор 9 -- на нём висит замок САМОГО стенда.
  # Держатель, переживший стенд (прерывание между запуском и `kill`), держал бы
  # вместе с проверяемым замком ещё и замок стенда, и следующий прогон ждал бы
  # призрака: ровно тот класс, из-за которого замок конвейера закрывают детям.
  local holder out rc
  mkdir -p "$S"
  perl -e 'use Fcntl ":flock"; open(my $fh, ">>", $ARGV[0]) or die $!;
           flock($fh, LOCK_EX) or die $!; sleep 20;' "$S/sweep.lock" 9>&- &
  holder=$!
  wait_holder_ready "$S/sweep.lock" || exit 2
  out=$(run_sweep "$K" "$C/corpus" "$C/versions.txt" 900); rc=$?
  kill "$holder" 2>/dev/null; wait "$holder" 2>/dev/null
  expect_refusal "7 замок свипа занят -- отказ с именем причины" "другой свип уже идёт" "$out" $rc
}

scenario_8() {   # метка происхождения видит неотслеживаемое
  # Проверяется ФУНКЦИЯ из самого свипа, вырезанная по якорю, а не переписанное
  # здесь выражение: копия разошлась бы с оригиналом молча. Первая редакция
  # вырезала ОДНУ СТРОКУ и держала имя переменной результата у себя -- правка,
  # свернувшая те же две строки в функцию с локальным именем, сделала сценарий
  # вечно красным, хотя проверяемое свойство не менялось.
  local repo fn out
  fn=$(awk '/^kit_state\(\) \{/{f=1} f{print} f && /^\}/{exit}' "$K/tools/sweep.sh")
  # Проверка вырезки идёт по имени ВХОДА функции, а не по её содержимому:
  # опора на конкретное выражение внутри делала мутацию этого выражения
  # неотличимой от «якорь не найден», то есть съедала собственный зуб.
  if [[ -z "$fn" || "$fn" != *"SRC_KIT"* ]]; then
    LAST_EVID="ЯКОРЬ_НЕ_НАЙДЕН"
    bad "8 метка происхождения: kit_state в sweep.sh не вырезан по якорю"; return
  fi
  repo=$(mktemp -d "$ROOT/gitrepo.XXXXXX")
  ( cd "$repo" && git init -q . && echo a > a.txt && git add a.txt \
      && git -c user.email=b@b -c user.name=b commit -qm init ) >/dev/null 2>&1
  echo untracked > "$repo/b.txt"
  out=$(SRC_KIT="$repo" bash -c "$fn
kit_state")
  if [[ "$out" == *"+dirty"* ]]; then
    LAST_EVID="метка=[$out]"
    ok "8 метка происхождения видит неотслеживаемый файл"
  else
    LAST_EVID="БЕЗ_ПОМЕТКИ_ГРЯЗИ метка=[$out]"
    bad "8 метка происхождения: неотслеживаемый файл не сделал дерево грязным (метка «${out}»)"
  fi
}

scenario_9() {   # конвейер вернул 3 -- версия НЕ ИЗМЕРЕНА, а не зелена
  # Держатель настоящий: свип обязан НАЗВАТЬ его в момент отказа, и проверяется
  # именно это -- pid держателя в записи lsof, а не наличие слова «lsof».
  local holder out rc
  perl -e 'use Fcntl ":flock"; open(my $fh, ">>", $ARGV[0]) or die $!;
           flock($fh, LOCK_EX) or die $!; sleep 30;' "$PLOCK" 9>&- &
  holder=$!
  wait_holder_ready "$PLOCK" || exit 2
  out=$(SWEEP_LOCK_BUDGET=0 STUB_RC=3 \
        run_sweep "$K" "$C/corpus" "$C/versions.txt" 900); rc=$?
  kill "$holder" 2>/dev/null; wait "$holder" 2>/dev/null
  LAST_EVID="rc=$rc :: $out"
  if [[ $rc -eq 0 ]]; then
    bad "9 конвейер вернул 3: код возврата свипа 0"; return
  fi
  if [[ "$out" != *"НЕ ИЗМЕРЕНО(замок"* || "$out" != *"НЕПОЛНЫЙ"* ]]; then
    bad "9 конвейер вернул 3: нет пометки НЕ ИЗМЕРЕНО или хвоста НЕПОЛНЫЙ"
    return
  fi
  if ! grep -q "[^0-9]$holder[^0-9]" "$S/log/sweep-900.lock.log" 2>/dev/null; then
    bad "9 конвейер вернул 3: держатель замка (pid $holder) не записан"
    return
  fi
  # Класс кода: версия не измерена ТОЛЬКО из-за занятого замка и красных нет,
  # значит «повторить позже» -- 3, а не отказ по существу (раунд 19, A-6).
  if (( rc != 3 )); then
    LAST_EVID="КЛАСС_НЕ_ТОТ rc=$rc :: $out"
    bad "9 конвейер вернул 3: свип вышел $rc, ждали 3"; return
  fi
  ok "9 конвейер вернул 3 -- НЕ ИЗМЕРЕНО, держатель назван, код свипа 3"
}

scenario_10() {   # наполнитель: байты на диске не сходятся с пином
  printf 'подменённые байты\n' > "$C/corpus/0.0.901.pristine"
  local out rc
  out=$(run_fetch "$K" "$C/corpus" "$C/versions.txt"); rc=$?
  toy_image "$C/corpus/0.0.901.pristine" 0.0.901
  expect_refusal "10 наполнитель: диск против пина -- отказ" "на диске не сходится с пином" "$out" $rc
}

scenario_11() {   # наполнитель НЕ пинит то, что лежит на диске
  cp "$C/versions.txt" "$C/versions.diskpin.txt"
  sed -i.bak 's/^901 0.0.901 .*/901 0.0.901 -/' "$C/versions.diskpin.txt"; rm -f "$C/versions.diskpin.txt.bak"
  local out rc pin
  out=$(run_fetch "$K" "$C/corpus" "$C/versions.diskpin.txt"); rc=$?
  pin=$(awk '$1=="901"{print $3}' "$C/versions.diskpin.txt")
  LAST_EVID="pin=[$pin] rc=$rc :: $out"
  if [[ "$pin" != "-" ]]; then
    LAST_EVID="ПИН_ЗАПИСАН_С_ДИСКА pin=[$pin]"
    bad "11 наполнитель записал пин по байтам диска (стало «${pin}»)"; return
  fi
  if [[ $rc -eq 0 ]]; then
    bad "11 наполнитель не отказал, хотя реестр не подтвердил файл"; return
  fi
  ok "11 лежащий образ без пина не становится эталоном без реестра"
}

scenario_12() {   # обход списка не обрывается на первой версии
  # Регрессия: пин писался ПРЯМО В ЦИКЛЕ, в файл, который цикл читал по
  # открытому дескриптору. Первая запись усекала файл, и хвост списка молча
  # не обходился. Обе версии обязаны появиться в выводе.
  rm -f "$C/corpus/0.0.900.pristine" "$C/corpus/0.0.901.pristine"
  cp "$C/versions.txt" "$C/versions.both.txt"
  sed -i.bak -e 's/^900 0.0.900 .*/900 0.0.900 -/' -e 's/^901 0.0.901 .*/901 0.0.901 -/' \
    "$C/versions.both.txt"; rm -f "$C/versions.both.txt.bak"
  local out
  out=$(run_fetch "$K" "$C/corpus" "$C/versions.both.txt")
  toy_image "$C/corpus/0.0.900.pristine" 0.0.900
  toy_image "$C/corpus/0.0.901.pristine" 0.0.901
  LAST_EVID="$out"
  if [[ "$out" == *"0.0.900"* && "$out" == *"0.0.901"* ]]; then
    ok "12 обход списка доходит до последней версии"
  else
    # Метка в следе -- требование --self-check: без неё мутация «оборви обход»
    # неотличима от любого другого отказа наполнителя.
    LAST_EVID="ОБХОД_ОБОРВАН :: $out"
    bad "12 обход списка оборвался: в выводе нет обеих версий"
  fi
}

scenario_13() {   # список не называет платформу
  local out rc
  out=$(run_sweep "$K" "$C/corpus" "$C/versions.noplat.txt" 900); rc=$?
  expect_refusal "13 платформа не названа -- отказ" "не названа платформа" "$out" $rc
}

scenario_14() {   # одна версия под двумя метками
  local out rc
  out=$(run_sweep "$K" "$C/corpus" "$C/versions.dup.txt"); rc=$?
