  out=$(run_sweep "$K" "$C/corpus" "$C/versions.extra.txt" 900); rc=$?
  expect_refusal "15 лишнее поле -- отказ" "а формат -- ровно три" "$out" $rc
}

scenario_16() {   # пин в верхнем регистре -- ТОТ ЖЕ хеш (позитивный контроль)
  local out rc
  out=$(run_sweep "$K" "$C/corpus" "$C/versions.upper.txt" 900); rc=$?
  LAST_EVID="rc=$rc :: $out"
  if (( rc != 0 )) || [[ "$out" != *"SWEEP DONE"* ]]; then
    bad "16 пин в верхнем регистре объявлен подменой (код $rc)"
  else
    ok "16 пин в верхнем регистре -- тот же хеш, прогон идёт"
  fi
}

scenario_17() {   # образ не прочитать -- причина называется своя
  if [[ "$(id -u)" == "0" ]]; then
    LAST_EVID="под root"
    bad "17 нечитаемый образ: стенд идёт под root, права ничего не запрещают"; return
  fi
  chmod 000 "$C/corpus/0.0.901.pristine"
  local out rc
  out=$(run_sweep "$K" "$C/corpus" "$C/versions.txt" 901); rc=$?
  chmod 644 "$C/corpus/0.0.901.pristine"
  expect_refusal "17 нечитаемый образ -- «не прочитать», а не подмена" "не прочитать $C/corpus/0.0.901.pristine" "$out" $rc
}

scenario_18() {   # копию не создать
  mkdir -p "$S/bin"; rm -f "$S/bin/900.wave.bin"; chmod 500 "$S/bin"
  local out rc
  out=$(run_sweep "$K" "$C/corpus" "$C/versions.txt" 900); rc=$?
  chmod 700 "$S/bin"
  LAST_EVID="rc=$rc :: $out"
  if (( rc == 0 )); then
    bad "18 копию не создать: код возврата 0"; return
  fi
  if [[ "$out" != *"КРАСНАЯ -- не скопировать"* ]]; then
    bad "18 копию не создать: в выводе нет «КРАСНАЯ -- не скопировать»"; return
  fi
  ok "18 копию не создать -- КРАСНАЯ, а не измерение"
}

scenario_19() {   # копию не прочитать
  rm -rf "$S/bin/900.wave.bin"
  mkdir -p "$S/bin/900.wave.bin"
  local out rc
  out=$(run_sweep "$K" "$C/corpus" "$C/versions.txt" 900); rc=$?
  rm -rf "$S/bin/900.wave.bin"
  LAST_EVID="rc=$rc :: $out"
  if (( rc == 0 )); then
    bad "19 копию не прочитать: код возврата 0"; return
  fi
  if [[ "$out" != *"КРАСНАЯ -- не прочитать копию"* ]]; then
    bad "19 копию не прочитать: в выводе нет «КРАСНАЯ -- не прочитать копию»"; return
  fi
  ok "19 копию не прочитать -- КРАСНАЯ, а не измерение"
}

scenario_20() {   # исходник подменён ПОСЛЕ общей сверки пинов
  # Пин доказывал ИСХОДНИК, а конвейер получает КОПИЮ, и между этими двумя
  # событиями проходят целые сборки. Заглушка портит образ следующей версии
  # прямо во время прогона первой -- ровно то окно, которое сверка копии и
  # закрывает.
  local out rc
  out=$(STUB_TAMPER="$C/corpus/0.0.901.pristine" \
        run_sweep "$K" "$C/corpus" "$C/versions.txt" 900 901); rc=$?
  toy_image "$C/corpus/0.0.901.pristine" 0.0.901
  # Вердикт кладётся В САМ след: причина мутации сверяется по нему, а не по
  # тексту `bad` -- красным сценарий делает и соседняя дверь (подменённый образ
  # валит проверку версии в дыме), и без этой пометки её отказ был бы
  # неотличим от работающей сверки копии.
  LAST_EVID="rc=$rc :: сверка копии=$([[ "$out" == *"КРАСНАЯ -- копия не сходится с пином"* ]] && echo есть || echo КОПИЯ_НЕ_СВЕРЕНА) :: $out"
  if (( rc == 0 )); then
    bad "20 подмена после сверки: код возврата 0"; return
  fi
  if [[ "$out" != *"КРАСНАЯ -- копия не сходится с пином"* ]]; then
    bad "20 подмена после сверки: копия не сверена с пином"; return
  fi
  ok "20 подмена исходника после сверки -- КРАСНАЯ на копии"
}

scenario_21() {   # позитивный контроль вердикта: чистый лог проходит
  # Без него любая мутация, делающая свип КРАСНЫМ всегда, выглядела бы зубом:
  # девять сценариев ниже (docnum:subset) требуют красноты, и ни один не
  # заметил бы, что зелёным не бывает вообще ничего.
  local out rc
  out=$(run_sweep "$K" "$C/corpus" "$C/versions.txt" 900); rc=$?
  LAST_EVID="rc=$rc :: $out"
  if (( rc != 0 )) || [[ "$out" != *"SWEEP DONE"* ]]; then
    bad "21 чистый лог заглушки объявлен красным (код $rc)"
  else
    ok "21 чистый лог -- SWEEP DONE и код 0"
  fi
}

scenario_22() { expect_red "22 конвейер вернул не 0 -- КРАСНАЯ" none "конвейер вернул 1" 1; }
scenario_23() { expect_red "23 NUL в логе -- КРАСНАЯ" nul "лог смешан с чужим потоком"; }
scenario_24() { expect_red "24 упавшая проверка -- КРАСНАЯ" fail "проверок упало 1"; }
scenario_25() { expect_red "25 ни одной прошедшей проверки -- КРАСНАЯ" nook "ни одной прошедшей проверки"; }
scenario_26() { expect_red "26 нет нашего применения -- КРАСНАЯ" noours "наших применений 0"; }
scenario_27() { expect_red "27 нет прогона tweakcc -- КРАСНАЯ" notw "прогонов tweakcc 0"; }
# Прогон tweakcc был, а патчей применено НОЛЬ -- своя дверь: заглушка снимает
# ровно маркер применённого патча, оставляя маркер самого прогона.
scenario_72() { expect_red "72 ноль применённых патчей -- КРАСНАЯ" nopatches "не применил ни одного патча"; }
scenario_28() { expect_red "28 дым не подтверждён -- КРАСНАЯ" nosmoke "дым не подтверждён"; }
scenario_29() { expect_red "29 интерфейс не подтверждён -- КРАСНАЯ" noiface "интерфейс не подтверждён"; }
scenario_30() { expect_red "30 стенд зондов не подтверждён -- КРАСНАЯ" nobench "стенд зондов не подтверждён"; }

scenario_31() {   # список набран для ЧУЖОЙ платформы
  # Пин платформозависим: пакеты реестра для разных пар ОС+архитектура разные,
  # и корпус с другой машины отвергался бы поштучно с текстом про подмену
  # образа -- то есть причина называлась бы неверно, а искать шли бы не там.
  local out rc
  out=$(run_sweep "$K" "$C/corpus" "$C/versions.foreign.txt" 900); rc=$?
  expect_refusal "31 чужая платформа -- отказ своей причиной" "список набран для платформы" "$out" $rc
}

scenario_32() {   # разбор вернул пусто -- отказ НАЗЫВАЕТ причину
  # Дом формата -- corpus-list.py, и он сам отвергает список без версий
  # (сценарий 5). Но у свипа стоит СВОЙ поперечный assert на случай, если
  # разбор когда-нибудь вернёт пустоту молча: без него прогон уходит в
  # `"${SRC[@]}"` при пустом массиве и падает именем внутренней переменной,
  # а на bash 4.4+ печатал бы бодрое «все 0 версий измерены» (число -- счёт
  # игрушечного корпуса, docnum:other). Проверить его
  # можно только подменив разбор -- потому подмена и делается здесь, в копии
  # кита, и снимается сразу.
  local out rc saved
  saved=$(cat "$K/tools/corpus-list.py")
  printf '#!/usr/bin/env python3\nimport sys\nsys.exit(0)\n' > "$K/tools/corpus-list.py"
  out=$(run_sweep "$K" "$C/corpus" "$C/versions.txt" 900); rc=$?
  printf '%s' "$saved" > "$K/tools/corpus-list.py"
  expect_refusal "32 разбор вернул пусто -- отказ с именем причины" "список версий пуст" "$out" $rc
}

scenario_33() {   # замок стенда занят -- второй прогон ЖДЁТ и называет причину
  # Заглушка конвейера зовётся claude-patch-all.sh, поэтому два прогона стенда
  # видят заглушки друг друга как боевую сборку. Очередь на своём замке
  # называет ожидание своим именем; зонд `--lock-probe` берёт ту же очередь и
  # выходит, не запуская сценарии.
  local holder out rc lock
  lock="$C/bench.lock"
  perl -e 'use Fcntl ":flock"; open(my $fh, ">>", $ARGV[0]) or die $!;
           flock($fh, LOCK_EX) or die $!; sleep 30;' "$lock" 9>&- &
  holder=$!
  wait_holder_ready "$lock" || exit 2
  out=$(CORPUS_BENCH_LOCK="$lock" CORPUS_BENCH_LOCK_BUDGET=1 \
        bash "$K/tools/corpus-tools-bench.real.sh" --lock-probe 2>&1 9>&-); rc=$?
  kill "$holder" 2>/dev/null; wait "$holder" 2>/dev/null
  LAST_EVID="rc=$rc :: $out"
  if (( rc == 0 )); then
    bad "33 замок стенда занят: второй прогон не стал ждать (код 0)"; return
  fi
  if [[ "$out" != *"другой прогон стенда держит замок"* ]]; then
    bad "33 замок стенда занят: причина не названа; было: $(printf '%s' "$out" | head -1)"
    return
  fi
  ok "33 замок стенда занят -- второй прогон ждёт и называет причину"
}

scenario_34() {   # ранний отказ обесценивает сводку
  # Сводка -- единственный файл, который читают ПОСЛЕ прогона. Обрезалась она
  # после всех дверей отказа, и отказавший прогон оставлял на диске зелёный
  # вердикт ПРОШЛОГО: читатель видел успех, которого в этом прогоне не было.
  local out rc summary
  summary="$S/log/sweep-summary.txt"
  out=$(run_sweep "$K" "$C/corpus" "$C/versions.txt" 900); rc=$?
  if (( rc != 0 )) || ! grep -aq 'SWEEP DONE' "$summary" 2>/dev/null; then
    LAST_EVID="подготовка: rc=$rc :: $out"
    bad "34 обесценивание сводки: зелёный прогон не оставил вердикта в сводке"; return
  fi
  out=$(run_sweep "$K" "$C/corpus" "$C/versions.txt" 999); rc=$?
  LAST_EVID="rc=$rc :: сводка после отказа :: $(cat "$summary" 2>&1)"
  if (( rc == 0 )); then
    bad "34 обесценивание сводки: неизвестная версия не стала отказом"; return
  fi
  if grep -aq 'SWEEP DONE' "$summary" 2>/dev/null; then
    bad "34 обесценивание сводки: после отказа остался вердикт прошлого прогона"; return
  fi
  if ! grep -aq 'ПРОГОН НАЧАТ' "$summary" 2>/dev/null; then
    bad "34 обесценивание сводки: нет отметки начатого прогона"; return
  fi
  ok "34 ранний отказ обесценивает сводку"
}

scenario_35() {   # одна версия названа дважды в аргументах
  local out rc
  out=$(run_sweep "$K" "$C/corpus" "$C/versions.txt" 900 900); rc=$?
  expect_refusal "35 повтор версии в аргументах -- отказ" "названа дважды" "$out" $rc
}

scenario_36() {   # наполнитель: лежащий образ не прочитать
  # Тот же класс, что у свипа в сценарии 17: пустой хеш против пина читался как
  # подмена, и искать шли подменённые байты вместо прав на файл.
  local out rc
  chmod 000 "$C/corpus/0.0.900.pristine"
  out=$(run_fetch "$K" "$C/corpus" "$C/versions.txt"); rc=$?
  chmod 644 "$C/corpus/0.0.900.pristine"
  expect_refusal "36 наполнитель: нечитаемый образ -- не подмена" \
                 "лежит, но не прочитать" "$out" $rc
}

scenario_37() {   # имя файла корпуса -- ОДИН дом
  # Стенд держит имена ЛИТЕРАЛАМИ намеренно: выводи он их той же функцией, что
  # и инструменты, смена суффикса поехала бы в обе стороны разом и осталась бы
  # невидимой. Поэтому исключены ровно два файла -- дом и сам стенд.
  # Конвейер читается из ЖИВОГО кита -- как в соседнем сценарии 38: в копии на
  # его месте лежит заглушка, и суффикс, написанный в настоящем конвейере, этот
  # сценарий не увидел бы вовсе. Инструменты остаются из копии: по ним бьёт
  # мутация.
  local stray
  stray=$(grep -rl '\.pristine' --include='*.sh' --include='*.py' \
            "$KIT/claude-patch-all.sh" "$K/tools" 2>/dev/null \
          | grep -v 'corpus-file-name\.sh$' | grep -v 'corpus-tools-bench' \
          | sed "s|^$K/||" | sed "s|^$KIT/||" | tr '\n' ' ')
  LAST_EVID="суффикс написан вне общего дома: $stray"
  if [[ -n "${stray// /}" ]]; then
    bad "37 имя файла корпуса: суффикс написан ещё и в: $stray"; return
  fi
  ok "37 имя файла корпуса живёт в одном доме"
}

scenario_38() {   # форма имени замка одна во всех домах
  # Общий файл сюда не подключить: преамбулу конвейера lock-probe исполняет
  # ОТДЕЛЬНО, вырезав из файла, и подключение сделало бы её несамодостаточной.
  # Поэтому форма пинится, и это объявлено -- см. комментарий в build-path-probe.
  local homes n f bad_homes=""
  # Конвейер читается из ЖИВОГО кита: в игрушечной копии на его месте лежит
  # заглушка, и дом преамбулы там отсутствует по устройству стенда. Зонд пути
  # сборки в копии лежит под именем `build-path-probe.real.sh` (на каноническом
  # имени -- заглушка предполёта), и его дом здесь считается по этой копии:
  # мутация правит именно её.
  homes=$(grep -rl 'claude-patch-all\.\$(id -u)\.lock' \
            "$KIT/claude-patch-all.sh" "$K/tools" 2>/dev/null | sort)
  n=$(printf '%s\n' "$homes" | grep -c .)
  for f in $homes; do
    # Ручку обязана называть ТА ЖЕ строка: слово CLAUDE_PATCH_LOCK живёт в
    # зондах ещё и внутри CLAUDE_PATCH_LOCK_HELD_BY, и проверка по файлу
    # зеленела, когда строка имени ручку уже не читала.
    grep 'claude-patch-all\.\$(id -u)\.lock' "$f" | grep -q 'CLAUDE_PATCH_LOCK' \
      || bad_homes="$bad_homes $(basename "$f")"
  done
  LAST_EVID="домов=$n без ручки:$bad_homes"
  if (( n != 4 )); then
    bad "38 форма имени замка: домов $n, а известных четыре"; return
  fi
  if [[ -n "${bad_homes// /}" ]]; then
    bad "38 форма имени замка: ручку не читают:$bad_homes"; return
  fi
  ok "38 имя замка во всех четырёх домах читает одну ручку"
}

scenario_39() {   # снимок кита убирается и на отказе
  # Снимок сносился только в успешном хвосте: отказ после копирования оставлял
  # копию кита в рабочем каталоге навсегда, и следующий прогон мерил диск,
  # засеянный предыдущими.
  local out rc leftover
  mkdir -p "$K/непрочитаемое"; chmod 000 "$K/непрочитаемое"
  out=$(run_sweep "$K" "$C/corpus" "$C/versions.txt" 900); rc=$?
  chmod 755 "$K/непрочитаемое"; rmdir "$K/непрочитаемое"
  leftover=$(ls -d "$S"/kit.* 2>/dev/null | tr '\n' ' ')
  LAST_EVID="rc=$rc :: $out :: $([[ -n "${leftover// /}" ]] && printf 'ОСТАЛСЯ_СНИМОК=%s' "$leftover")"
  if (( rc == 0 )) || [[ "$out" != *"не снять снимок кита"* ]]; then
    bad "39 уборка снимка: копирование не отказало (rc=$rc)"; return
  fi
  if [[ -n "${leftover// /}" ]]; then
    bad "39 уборка снимка: после отказа остался снимок $leftover"; return
  fi
  ok "39 снимок кита убирается и на отказе"
}

scenario_40() {   # дубль МЕТКИ в списке
  local out rc
  out=$(run_sweep "$K" "$C/corpus" "$C/versions.duplabel.txt"); rc=$?
  expect_refusal "40 дубль метки -- отказ" "уже была в строке" "$out" $rc
}

scenario_41() {   # пин не 64 шестнадцатеричных знака
  local out rc
  out=$(run_sweep "$K" "$C/corpus" "$C/versions.badpin.txt" 900); rc=$?
  expect_refusal "41 пин не по форме -- отказ" "не 64 шестнадцатеричных" "$out" $rc
}

scenario_42() {   # версия не по форме
  local out rc
  out=$(run_sweep "$K" "$C/corpus" "$C/versions.badver.txt"); rc=$?
  expect_refusal "42 версия не по форме -- отказ" "не похоже на номер версии" "$out" $rc
}

scenario_43() {   # рассинхрон таблиц мутаций -- отказ, а не сдвиг описаний
  # Пять таблиц описывают одну мутацию каждая своим полем. Короче одна -- и
  # номера разъезжаются: замена одной мутации однажды встала к образцу другой,
  # и стенд объявил зубом правило, которого не проверял. Копия укорачивается
  # намеренно, и стенд обязан ОТКАЗАТЬСЯ, а не считать.
  local probe out rc
  probe="$C/bench-short.sh"
  # Снимается последняя запись MUT_CAUSE. Якорь -- присваивание В НАЧАЛЕ
  # СТРОКИ: первая редакция искала имя таблицы где угодно и находила его в
  # ЭТОМ ЖЕ сценарии, после чего резала строку соседнего кода -- та самая
  # теневая цель, от которой мутации защищены счётом совпадений.
  python3 - "$K/tools/corpus-tools-bench.real.sh" "$probe" <<'SHORTEN'
import io, re, sys
src = io.open(sys.argv[1], encoding='utf-8').read()
at = re.search(r'^MUT_CAUSE=\(x', src, re.M).start()
end = src.index(')\n', at)
head = src[:end]
io.open(sys.argv[2], 'w', encoding='utf-8').write(
    head[:head.rindex('\n  ')] + '\n' + src[end:])
SHORTEN
  if ! grep -q 'MUT_CAUSE=(x' "$probe"; then
    LAST_EVID="копия не собрана"
    bad "43 рассинхрон таблиц: не удалось укоротить таблицу в копии"; return
  fi
  out=$(CORPUS_BENCH_LOCK="$C/tables.lock" CORPUS_BENCH_LOCK_BUDGET=5 \
        bash "$probe" --table-check 2>&1); rc=$?
  LAST_EVID="rc=$rc :: $out"
  if (( rc == 0 )); then
    bad "43 рассинхрон таблиц: укороченная таблица принята (код 0)"; return
  fi
  if [[ "$out" != *"а мутаций"* ]]; then
    bad "43 рассинхрон таблиц: причина не названа; было: $(printf '%s' "$out" | head -1)"
    return
  fi
  ok "43 рассинхрон таблиц мутаций -- отказ с названной причиной"
}

scenario_44() {   # копия зелёной версии убирается, копия красной остаётся
  # Копия -- сотни мегабайт на версию, и её никто не читает после прогона; у
  # красной версии она улика, поэтому исходы разные, и оба проверяются.
  local out rc green red
  out=$(run_sweep "$K" "$C/corpus" "$C/versions.txt" 900); rc=$?
  green=$([[ -e "$S/bin/900.wave.bin" ]] && echo ОСТАЛАСЬ_КОПИЯ_ЗЕЛЁНОЙ)
  out=$(STUB_RC=1 run_sweep "$K" "$C/corpus" "$C/versions.txt" 900); rc=$?
  red=$([[ -e "$S/bin/900.wave.bin" ]] && echo есть)
  LAST_EVID="зелёная: ${green:-убрана} :: красная: ${red:-СНЕСЛИ_УЛИКУ_КРАСНОЙ}"
  if [[ -n "$green" ]]; then
    bad "44 копии: после зелёной версии копия осталась"; return
  fi
  if [[ -z "$red" ]]; then
    bad "44 копии: после красной версии копия удалена -- улика потеряна"; return
  fi
  ok "44 копия зелёной версии убирается, копия красной остаётся"
}

scenario_45() {   # страж живых прогонов: сам прогон против пути в аргументах
  # Две половины в одном сценарии намеренно: страж, который не ловит ничего, и
  # страж, который ловит всё, одинаково бесполезны, и половина без своей пары
  # молча вырождается.
  local fake out rc caught missed
  fake="$C/fake"; mkdir -p "$fake"
  printf '#!/bin/sh\nsleep 30\n' > "$fake/claude-patch-all.sh"
  printf 'import time\ntime.sleep(30)\n' > "$fake/gate.py"
  chmod +x "$fake/claude-patch-all.sh"

  # (1) настоящий прогон конвейера -- страж ОБЯЗАН отказать
  #
  # `9>&-` у обоих поддельных процессов: стенд держит свой замок на дескрипторе
  # 9, а эти двое живут по 30 секунд и убиваются `kill` без ожидания выхода. С
  # копией дескриптора любой из них продолжал бы держать замок стенда после
  # выхода самого стенда -- та же утечка, что уносила замок конвейера через
  # гейт интерфейса.
  bash "$fake/claude-patch-all.sh" 9>&- & local runner=$!
  sleep 1
  out=$(run_sweep "$K" "$C/corpus" "$C/versions.txt" 900); rc=$?
  kill "$runner" 2>/dev/null; wait "$runner" 2>/dev/null
  # Сверяется КЛАСС кода, а не «не ноль»: пока проверялось «не ноль», отказ
  # стоял кодом 1 («чинить кит») там, где верен 3 («повторить позже»), и
  # стенд этого не видел (круг 21, линза F, находка 2).
  caught=$([[ $rc -eq 3 && "$out" == *"живы процессы чужого прогона конвейера"* ]] && echo да)

  # (2) путь конвейера АРГУМЕНТОМ чужой программы -- отказа быть не должно
  python3 "$fake/gate.py" "$fake/claude-patch-all.sh" 9>&- & local reader=$!
  sleep 1
  out=$(run_sweep "$K" "$C/corpus" "$C/versions.txt" 900); rc=$?
  kill "$reader" 2>/dev/null; wait "$reader" 2>/dev/null
  missed=$([[ $rc -eq 0 ]] || echo "ОТКАЗ_НА_ЧУЖОМ_АРГУМЕНТЕ: $out")

  LAST_EVID="прогон пойман: ${caught:-НЕТ} :: ${missed:-чужой аргумент пропущен}"
  if [[ -z "$caught" ]]; then
    bad "45 страж живых: настоящий прогон конвейера не пойман"; return
  fi
  if [[ -n "$missed" ]]; then
    bad "45 страж живых: отказ на пути в аргументах чужой программы"; return
  fi
  ok "45 страж живых ловит прогон и не ловит путь в чужих аргументах"
}

# Класс ответа предполётного прибора: «не сошлось» и «мерить нечем» чинятся
# разным, и свип обязан их различать так же, как их различает сам прибор.
# Прежде оба уезжали в общую дверь, печатавшую «не сошёлся (код 2)» -- то есть
# свип утверждал, что измерил и получил красное, там где не измерил ничего.

scenario_63() {   # зонд ответил «мерить нечем» -- это не красный прогон
  local out rc
  out=$(STUB_PROBE_RC=2 run_sweep "$K" "$C/corpus" "$C/versions.txt" 900); rc=$?
  LAST_EVID="rc=$rc :: $out"
  if (( rc != 2 )); then
    bad "63 зонд не мерил: код возврата $rc, ждали 2"; return
  fi
  if [[ "$out" != *"зонд пути сборки НЕ МЕРИЛ"* ]]; then
    bad "63 зонд не мерил: класс не объявлен: $(printf '%s' "$out" | head -2 | tr '\n' ' ')"; return
  fi
  if [[ "$out" == *"SWEEP DONE"* ]]; then
    bad "63 зонд не мерил: версии всё равно померены"; return
  fi
  ok "63 «мерить нечем» у зонда -- свой класс, а не красный прогон"
}

scenario_64() {   # стенд корпусных инструментов ответил «мерить нечем»
  local out rc
  out=$(STUB_BENCH_RC=2 run_sweep "$K" "$C/corpus" "$C/versions.txt" 900); rc=$?
  LAST_EVID="rc=$rc :: $out"
  if (( rc != 2 )); then
    bad "64 стенд не мерил: код возврата $rc, ждали 2"; return
  fi
  if [[ "$out" != *"стенд корпусных инструментов НЕ МЕРИЛ"* ]]; then
    bad "64 стенд не мерил: класс не объявлен: $(printf '%s' "$out" | head -2 | tr '\n' ' ')"; return
  fi
  if [[ "$out" == *"SWEEP DONE"* ]]; then
    bad "64 стенд не мерил: версии всё равно померены"; return
  fi
  ok "64 «мерить нечем» у стенда -- свой класс, а не красный прогон"
}

scenario_65() {   # машинерия замка стенда сломана -- повтор не поможет
  local out rc
  out=$(STUB_BENCH_RC=6 run_sweep "$K" "$C/corpus" "$C/versions.txt" 900); rc=$?
  LAST_EVID="rc=$rc :: $out"
  if (( rc != 6 )); then
    bad "65 замок стенда: код возврата $rc, ждали 6"; return
  fi
  if [[ "$out" != *"машинерия замка стенда сломана"* ]]; then
    bad "65 замок стенда: причина не названа: $(printf '%s' "$out" | head -2 | tr '\n' ' ')"; return
  fi
  ok "65 сломанная машинерия замка стенда едет своим кодом"
}

scenario_66() {   # стенд, позванный ИЗ свипа, меряет свой кит, а не чужой
  # Две половины, и вторая -- по ФОРМЕ.
  #
  # Поведение проверяется на ЖИВОМ файле: прогон повторяет сценарий 21 (чистый
  # лог -> SWEEP DONE) в окружении, какое оставляет вокруг себя настоящий свип.
  # Мутация этого свойства невозможна по устройству: зубы правят КОПИЮ кита, а
  # пусковой, чьё поведение здесь меряется, живёт в исполняющемся файле. Поэтому
  # второй половиной свойство запинено по форме -- в копии, -- и объявлено
  # таковым (тот же приём, что у формы стража живых прогонов, сценарий 57).
  local out rc src decl uses self
  out=$(SWEEP_LEADER=1 SWEEP_KIT=/nonexistent-kit SWEEP_SELF=/nonexistent-self \
        run_sweep "$K" "$C/corpus" "$C/versions.txt" 900); rc=$?
  LAST_EVID="rc=$rc :: $out"
  if (( rc != 0 )) || [[ "$out" != *"SWEEP DONE"* ]]; then
    bad "66 бухгалтерия внешнего свипа протекла в игрушечный (код $rc)"; return
  fi
  src="$K/tools/corpus-tools-bench.real.sh"
  if [[ ! -f "$src" ]]; then
    LAST_EVID="НЕТ_КОПИИ_СТЕНДА :: $src"
    bad "66 форма снятия: в копии кита нет самого стенда"; return
  fi
  # Образец СКЛЕИВАЕТСЯ: написанный дословно, он был бы вторым вхождением
  # объявления в этом же файле -- и счёт «ровно одно объявление» никогда не
  # сошёлся бы, а мутация зубов правила бы не то место (измерено 2026-08-28).
  decl=$(grep -c "SWEEP_ENV_SCRUB=(env -u SWEEP_LEADER -u SWEEP_KIT -u SWEEP""_SELF -u SWEEP_LAST_N)" "$src")
  uses=$(grep -c '"${SWEEP_ENV_SCRUB\[@\]}"' "$src")
  # Третья половина -- САМОСНЯТИЕ. Образец склеен по той же причине и вдобавок
  # якорится на начало строки: сама строка пина начинается с пробелов и себя не
  # считает.
  self=$(grep -c "^unset SWEEP_LEADER SWEEP_KIT SWEEP""_SELF SWEEP_LAST_N$" "$src")
  # Шесть пусковых, и каждый обязан снимать бухгалтерию: run_sweep, run_fetch,
  # launch_sweep, фоновый наполнитель сигнальной ноги (волна 25B), пусковой
  # форк-запаски (волна 26) и пусковой своей сессии (сценарий 87). Число --
  # часть пина.
  #
  # Одного этого числа МАЛО, и это измерено: пусковой, который скруббер забыл,
  # использований не добавляет, счёт сходится, и такой пусковой прожил целую
  # волну незамеченным. Поэтому класс закрыт не числом, а самоснятием у самого
  # стенда -- его и пинит третья половина.
  if [[ "$decl" != "1" || "$uses" != "6" || "$self" != "1" ]]; then
    LAST_EVID="ФОРМА_СНЯТИЯ_РАЗОШЛАСЬ :: объявлений=$decl использований=$uses самоснятий=$self (ждали 1, 6 и 1)"
    bad "66 форма снятия бухгалтерии разошлась с объявленной"; return
  fi
  ok "66 стенд снимает бухгалтерию внешнего свипа: прогон зелен, форма на месте"
}

scenario_67() {   # предполётный стенд ЗАНЯТ -- это «повторить», а не красное
  local out rc
  out=$(STUB_BENCH_RC=3 run_sweep "$K" "$C/corpus" "$C/versions.txt" 900); rc=$?
  LAST_EVID="rc=$rc :: $out"
  if (( rc != 3 )); then
    bad "67 занятый стенд: код возврата $rc, ждали 3"; return
  fi
  if [[ "$out" != *"стенд корпусных инструментов занят"* ]]; then
    bad "67 занятый стенд: причина не названа: $(printf '%s' "$out" | head -2 | tr '\n' ' ')"; return
  fi
  ok "67 занятый предполётный стенд -- класс «повторить позже»"
}

scenario_68() {   # конвейер вернул 2 -- вердикт называет КЛАСС, а не «код 2»
  local out rc
  out=$(STUB_RC=2 run_sweep "$K" "$C/corpus" "$C/versions.txt" 900); rc=$?
  LAST_EVID="rc=$rc :: $out"
  if (( rc == 0 )); then
    bad "68 конвейер вернул 2: код возврата свипа 0, ждали отказ"; return
  fi
  if [[ "$out" != *"конвейер вернул 2: контракт вызова нарушен или прибор гейта не мерил"* ]]; then
    LAST_EVID="КЛАСС_НЕ_НАЗВАН :: rc=$rc :: $out"
    bad "68 конвейер вернул 2: класс не назван в вердикте"; return
  fi
  ok "68 конвейер вернул 2 -- вердикт называет класс отказа"
}

scenario_69() {   # пин некуда записать: список сменился под прогоном
  # Тот же вырезанный блок записи, что в сценарии 52, но пин пишется версии,
  # строки которой в списке НЕТ. Это не «корпус красный», а «прибор не может
  # записать измеренное»: класс 2. Прежде здесь стоял sys.exit со СТРОКОЙ,
  # то есть код 1, и вызывающий звал чинить корпус.
  local carved list out rc before
  carved="$C/pin-block-69.py"
  if ! python3 - "$K/tools/fetch-corpus.sh" "$carved" <<'CARVE'; then
import re, sys
src, dst = sys.argv[1], sys.argv[2]
text = open(src, encoding='utf-8').read()
m = re.search(r"<<'PIN_PY'\n(.*?)\nPIN_PY", text, re.S)
if not m:
    sys.stderr.write('в наполнителе нет блока PIN_PY -- якорь потерян\n')
    sys.exit(2)
open(dst, 'w', encoding='utf-8').write(m.group(1))
CARVE
    __crc=$?
    if [[ $__crc -eq 2 ]]; then
      LAST_EVID="ЯКОРЬ_PIN_PY_ПОТЕРЯН"
      bad "69 пин без строки: блок PIN_PY не вырезан -- прибор не мерил"; return
    fi
    bad "69 пин без строки: блок PIN_PY не вырезан"; return
  fi
  list="$C/pin69.txt"
  { echo "# platform: x"; echo "900 0.0.900 -"; } > "$list"
  before=$(tr '\n' '|' < "$list")
  out=$(python3 "$carved" "$list" 0.0.999 deadbeef 2>&1); rc=$?
  LAST_EVID="rc=$rc :: $out :: список=$(tr '\n' '|' < "$list")"
  if (( rc != 2 )); then
    LAST_EVID="КЛАСС_НЕ_ТОТ rc=$rc :: $out"
    bad "69 пин без строки: код возврата $rc, ждали 2"; return
  fi
  if [[ "$out" != *"0.0.999"* ]]; then
    bad "69 пин без строки: версия не названа: $out"; return
  fi
  if [[ "$(tr '\n' '|' < "$list")" != "$before" ]] || ls "$list".new* >/dev/null 2>&1; then
    bad "69 пин без строки: список тронут при отказе"; return
  fi
  ok "69 пин версии, которой нет в списке -- класс «записывать некуда»"
}

scenario_70() {   # вызывающий не назвал платформу -- сломан ВЫЗОВ, не список
  # Предмет тот же, что и до волны 40c: отказ, который НЕ про формат списка --
  # код 2 и текст, зовущий чинить кит, а не файл; код «формат нарушен»
  # отправлял бы человека править файл, который никто не читал (свип
  # контроллера, волна 22). Причина сменилась вместе с механизмом: платформа
  # больше не выводится из хозяина, её называет вызывающий вторым аргументом.
  # Одинокий кит в фикстуре ОСТАЁТСЯ намеренно: дверь контракта вызова обязана
  # отвечать РАНЬШЕ всего, чему мог бы понадобиться кит рядом, -- иначе
  # неверный вызов отправлял бы человека править список.
  local lone out rc
  lone="$C/lone-kit"; mkdir -p "$lone/tools"
  cp "$K/tools/corpus-list.py" "$lone/tools/corpus-list.py"
  { echo "# platform: x"; echo "900 0.0.900 -"; } > "$lone/list.txt"
  out=$(python3 "$lone/tools/corpus-list.py" "$lone/list.txt" 2>&1 9>&-); rc=$?
  LAST_EVID="rc=$rc :: $out"
  if (( rc != 2 )); then
    LAST_EVID="КЛАСС_НЕ_ТОТ rc=$rc :: $out"
    bad "70 платформа не названа: код возврата $rc, ждали 2"; return
  fi
  if [[ "$out" != *"нужны два аргумента"* || "$out" != *"пакет-платформа"* ]]; then
    LAST_EVID="АРГУМЕНТ_НЕ_НАЗВАН :: $LAST_EVID"
    bad "70 платформа не названа: текст не называет недостающий аргумент: $out"; return
  fi
  ok "70 вызов без платформы -- «прибор не может мерить», аргумент назван"
}

scenario_71() {   # операторская ручка пропуска не проникает в сценарии стенда
  # Две половины, как у сценария 66: поведение на живом файле плюс ФОРМА из
  # копии кита -- пусковой живёт в исполняющемся файле, и мутировать его зубы
  # не могут.
  local out rc mark src amb
  mark="$C/probe.called.71"; rm -f "$mark"
  out=$(SWEEP_SKIP_BUILD_PROBE=1 SWEEP_SKIP_TOOLS_BENCH=1 STUB_PROBE_MARK="$mark" \
        run_sweep "$K" "$C/corpus" "$C/versions.txt" 900); rc=$?
  LAST_EVID="rc=$rc :: зонд=$([[ -e "$mark" ]] && echo звался || echo НЕ_ЗВАЛСЯ) :: $out"
  if (( rc != 0 )); then
    bad "71 амбиентная ручка: прогон отказал ($rc) -- дверь не измерена"; return
  fi
  if [[ ! -e "$mark" ]]; then
    LAST_EVID="АМБИЕНТНАЯ_РУЧКА_ПРОТЕКЛА :: $out"
    bad "71 амбиентная SWEEP_SKIP_BUILD_PROBE отключила зонд внутри стенда"; return
  fi
  src="$K/tools/corpus-tools-bench.real.sh"
  if [[ ! -f "$src" ]]; then
    LAST_EVID="НЕТ_КОПИИ_СТЕНДА :: $src"
    bad "71 форма ручек: в копии кита нет самого стенда"; return
  fi
  amb=$(grep -c 'SWEEP_SKIP_BUILD_PROBE="${BENCH_SKIP''_PROBE:-}"' "$src")
  # Своё имя стоит у КАЖДОГО пускового: run_sweep, launch_sweep (сигнальная
  # нога, волна 25B) и пусковой форк-запаски (волна 26). Число -- часть пина.
  if [[ "$amb" != "3" ]]; then
    LAST_EVID="ФОРМА_РУЧКИ_РАЗОШЛАСЬ :: своих имён=$amb (ждали 3)"
    bad "71 форма ручек пропуска разошлась с объявленной"; return
  fi
  ok "71 операторская ручка пропуска не проникает в сценарии стенда"
}

# Свой корпус на семь версий: набор по умолчанию (пять) виден только там, где
# версий БОЛЬШЕ пяти, а общий игрушечный корпус держит две -- на нём «последние
# пять» и «все» неотличимы.
mk_lastn_corpus() {   # каталог
  local d=$1 v plat h
  rm -rf "$d"; mkdir -p "$d/corpus"
  plat=$(grep '^# platform:' "$C/versions.txt")
  { echo "# игрушечный список набора"
    echo "$plat"
    # Порядок строк НЕ по номеру: свип обязан брать последние по ВЕРСИИ, а не
    # хвост файла (строку в список дописывают руками).
    for v in 913 910 916 912 914 911 915; do
      toy_image "$d/corpus/0.0.$v.pristine" "0.0.$v"
      h=$(shasum -a 256 "$d/corpus/0.0.$v.pristine" | awk '{print $1}')
      echo "$v 0.0.$v $h"
    done
  } > "$d/versions.txt"
}

scenario_73() {   # набор по умолчанию -- пять САМЫХ НОВЫХ версий корпуса
  # Решение юзера 2026-08-28: прогон без аргументов меряет не весь корпус.
  # Молчаливое сужение читалось бы как вердикт обо всём корпусе, поэтому
  # проверяются три вещи разом: сколько измерено, КАКИЕ именно, и объявлено ли
  # это в потоке и в сводке.
  local d out rc n sum
  d="$C/lastn"; mk_lastn_corpus "$d"
  out=$(run_sweep "$K" "$d/corpus" "$d/versions.txt"); rc=$?
  n=$(printf '%s\n' "$out" | grep -c '^SWEEP 91[0-9]: exit=')
  sum="$d/corpus/state/log/sweep-summary.txt"
  LAST_EVID="rc=$rc :: измерено=$n :: $out"
  if (( rc != 0 )); then
    bad "73 набор по умолчанию: прогон отказал ($rc)"; return
  fi
  if [[ "$n" != "5" ]]; then
    LAST_EVID="ИЗМЕРЕНО_НЕ_ПЯТЬ :: измерено=$n :: $out"
    bad "73 набор по умолчанию: измерено $n версий вместо пяти"; return
  fi
  if [[ "$out" == *"SWEEP 910:"* || "$out" == *"SWEEP 911:"* ]]; then
    LAST_EVID="ИЗМЕРЕНО_ЛИШНЕЕ :: $out"
    bad "73 набор по умолчанию: измерены и старые версии"; return
  fi
  if [[ "$out" != *"SWEEP набор: последние 5 версий корпуса -- 912 913 914 915 916"* ]]; then
    LAST_EVID="НАБОР_НЕ_ОБЪЯВЛЕН :: $out"
    bad "73 набор по умолчанию: сужение не объявлено в потоке"; return
  fi
  if [[ ! -f "$sum" ]] || ! grep -q '^# набор: последние 5 версий корпуса' "$sum"; then
    LAST_EVID="СВОДКА_МОЛЧИТ :: $(cat "$sum" 2>/dev/null | tr '\n' '|')"
    bad "73 набор по умолчанию: сводка не называет измеренный набор"; return
  fi
  ok "73 без аргументов меряются пять самых новых версий, и это объявлено"
}

scenario_74() {   # ручка набора достижима: ноль -- весь корпус
  # Объявленная ручка обязана быть ДОСТИЖИМА: SWEEP_LAST_N=0 -- единственный
  # способ померить весь корпус без перечисления версий руками.
  local d out rc n
  d="$C/lastn"; mk_lastn_corpus "$d"
  out=$(BENCH_LAST_N=0 run_sweep "$K" "$d/corpus" "$d/versions.txt"); rc=$?
  n=$(printf '%s\n' "$out" | grep -c '^SWEEP 91[0-9]: exit=')
  LAST_EVID="rc=$rc :: измерено=$n :: $out"
  if (( rc != 0 )); then
    bad "74 ручка набора: прогон отказал ($rc)"; return
  fi
  if [[ "$n" != "7" ]]; then
    LAST_EVID="ЗНАЧЕНИЕ_РУЧКИ_ПРОИГНОРИРОВАНО :: измерено=$n вместо 7 :: $out"
    bad "74 ручка набора: SWEEP_LAST_N=0 измерил $n версий вместо всего корпуса"; return
  fi
  if [[ "$out" != *"SWEEP набор: ВЕСЬ корпус"* ]]; then
    LAST_EVID="ЗНАЧЕНИЕ_РУЧКИ_ПРОИГНОРИРОВАНО :: набор не объявлен :: $out"
    bad "74 ручка набора: полный корпус не объявлен"; return
  fi
  ok "74 SWEEP_LAST_N=0 меряет весь корпус и объявляет это"
}

scenario_75() {   # прибор зубов реестра зовётся по умолчанию, вердикт объявлен
  local out rc mark
  mark="$C/teeth.called"; rm -f "$mark"
  out=$(STUB_TEETH_MARK="$mark" run_sweep "$K" "$C/corpus" "$C/versions.txt" 900); rc=$?
  LAST_EVID="rc=$rc :: прибор=$([[ -e "$mark" ]] && echo звался || echo НЕ_ЗВАЛСЯ) :: $out"
  if (( rc != 0 )); then
    bad "75 предполёт зубов: прогон отказал ($rc) -- дверь не измерена"; return
  fi
  if [[ ! -e "$mark" ]]; then
    LAST_EVID="ПРИБОР_НЕ_ЗВАЛСЯ :: $out"
    bad "75 предполёт зубов: прибор не звался"; return
  fi
  if [[ "$out" != *"зубы реестра проверок: ЗЕЛЁНО"* ]]; then
    LAST_EVID="ВЕРДИКТ_НЕ_ОБЪЯВЛЕН :: $out"
    bad "75 предполёт зубов: вердикт не объявлен"; return
  fi
  ok "75 предполёт зовёт прибор зубов реестра и объявляет его вердикт"
}

scenario_76() {   # красный прибор зубов останавливает свип (после первой сборки -- W-1)
  local out rc
  out=$(STUB_TEETH_RC=1 run_sweep "$K" "$C/corpus" "$C/versions.txt" 900); rc=$?
  LAST_EVID="rc=$rc :: $out"
  if (( rc == 0 )) || [[ "$out" == *"SWEEP DONE"* ]]; then
    LAST_EVID="КРАСНЫЙ_НЕ_ОСТАНОВИЛ :: rc=$rc :: $out"
    bad "76 красный прибор зубов: свип не остановлен (rc=$rc)"; return
  fi
  if [[ "$out" != *"прошла мутацию молча либо покраснела чужой дверью"* ]]; then
    LAST_EVID="ПРИЧИНА_НЕ_НАЗВАНА :: $out"
    bad "76 красный прибор зубов: причина не названа"; return
  fi
  ok "76 красный прибор зубов реестра останавливает свип"
}

scenario_77() {   # выключатель прибора зубов ОБЪЯВЛЯЕТСЯ
  local out rc mark
  mark="$C/teeth.called"; rm -f "$mark"
  out=$(BENCH_SKIP_TEETH=1 STUB_TEETH_MARK="$mark" \
        run_sweep "$K" "$C/corpus" "$C/versions.txt" 900); rc=$?
  LAST_EVID="rc=$rc :: прибор=$([[ -e "$mark" ]] && echo ЗВАЛСЯ_ВОПРЕКИ || echo не звался) :: $out"
  if (( rc != 0 )); then
    bad "77 выключатель зубов: прогон отказал ($rc)"; return
  fi
  if [[ -e "$mark" ]]; then
    bad "77 выключатель зубов: прибор всё равно звался"; return
  fi
  if [[ "$out" != *"зубы реестра проверок ПРОПУЩЕНЫ по ручке"* ]]; then
    LAST_EVID="ПРОПУСК_НЕ_ОБЪЯВЛЕН :: $out"
    bad "77 выключатель зубов: пропуск не объявлен"; return
  fi
  ok "77 выключатель прибора зубов объявляет пропуск"
}

scenario_79() {   # свип не трогает ЖИВОЙ дом tweakcc
  # Круг 21, линза E, находка 1: каждая сборка свипа шла через живой дом
  # распаковщика и переписывала бэкап живой установки байтами корпусной версии.
  # Проверяется то, что можно измерить: дом-семя остаётся байт-в-байт, свой дом
  # создан, и выбор объявлен в потоке и в сводке.
  local d out rc sum before after clone
  d="$C/lastn"; mk_lastn_corpus "$d"
  before=$(cd "$TW_FIXTURE" && find . -type f -exec shasum {} + | sort)
  out=$(run_sweep "$K" "$d/corpus" "$d/versions.txt"); rc=$?
  after=$(cd "$TW_FIXTURE" && find . -type f -exec shasum {} + | sort)
  sum="$d/corpus/state/log/sweep-summary.txt"
  LAST_EVID="rc=$rc :: $out"
  if (( rc != 0 )); then
    bad "79 дом tweakcc: прогон отказал ($rc)"; return
  fi
  if [[ "$before" != "$after" ]]; then
    LAST_EVID="ЖИВОЙ_ДОМ_ИЗМЕНЁН :: до=$before :: после=$after"
    bad "79 дом tweakcc: дом-семя изменился за прогон"; return
  fi
  if [[ ! -d "$d/corpus/state/tweakcc-home" ]]; then
    LAST_EVID="СВОЕГО_ДОМА_НЕТ :: $(ls "$d/corpus/state" 2>&1 | tr '\n' '|')"
    bad "79 дом tweakcc: свой дом не создан"; return
  fi
  # ГРАНИЦА отметки происхождения. Её кладут ТОЛЬКО в дом, созданный с нуля:
  # у клона живого дома оператор ЕСТЬ, и дверь множества выключенных правок
  # обязана держаться для него двусторонне. Сверяются СОСТАВЫ клона и семени,
  # а не имя файла: лишний файл ловится, как бы он ни назывался.
  clone=$(cd "$d/corpus/state/tweakcc-home" && find . -type f -exec shasum {} + | sort)
  if [[ "$clone" != "$before" ]]; then
    LAST_EVID="КЛОН_НЕ_РАВЕН_СЕМЕНИ :: клон=$clone :: семя=$before"
    bad "79 дом tweakcc: в клоне живого дома появилось своё содержимое"; return
  fi
  if [[ "$out" != *"SWEEP дом tweakcc:"* ]]; then
    LAST_EVID="ВЫБОР_НЕ_ОБЪЯВЛЕН :: $out"
    bad "79 дом tweakcc: выбор дома не объявлен в потоке"; return
  fi
  if [[ ! -f "$sum" ]] || ! grep -q '^# дом tweakcc: свой' "$sum"; then
    LAST_EVID="СВОДКА_МОЛЧИТ :: $(cat "$sum" 2>/dev/null | tr '\n' '|')"
    bad "79 дом tweakcc: сводка не называет дом"; return
  fi
  ok "79 свип семенит свой дом tweakcc, живой не трогает, и объявляет это"
}

scenario_80() {   # ручка «остаться на живом доме» достижима и ОБЪЯВЛЕНА
  # Ручка нужна для разбора руками, но молчаливый возврат к живому дому -- это
  # ровно то состояние, против которого механизм заведён. Пропуск объявляется
  # и в потоке, и в сводке (эталон -- SWEEP_SKIP_BUILD_PROBE).
  local d out rc sum
  d="$C/lastn"; mk_lastn_corpus "$d"
  out=$(SWEEP_KEEP_LIVE_TWEAKCC=1 run_sweep "$K" "$d/corpus" "$d/versions.txt"); rc=$?
  sum="$d/corpus/state/log/sweep-summary.txt"
  LAST_EVID="rc=$rc :: $out"
  if (( rc != 0 )); then
    bad "80 ручка дома tweakcc: прогон отказал ($rc)"; return
  fi
  if [[ -d "$d/corpus/state/tweakcc-home" ]]; then
    LAST_EVID="РУЧКА_ПРОИГНОРИРОВАНА :: свой дом всё равно создан :: $out"
    bad "80 ручка дома tweakcc: свой дом создан вопреки ручке"; return
  fi
  if [[ "$out" != *"SWEEP дом tweakcc: ЖИВОЙ по ручке"* ]]; then
    LAST_EVID="ПРОПУСК_НЕ_ОБЪЯВЛЕН :: $out"
    bad "80 ручка дома tweakcc: возврат к живому дому не объявлен"; return
  fi
  if [[ ! -f "$sum" ]] || ! grep -q '^# дом tweakcc: ЖИВОЙ по ручке' "$sum"; then
    LAST_EVID="СВОДКА_МОЛЧИТ :: $(cat "$sum" 2>/dev/null | tr '\n' '|')"
    bad "80 ручка дома tweakcc: сводка молчит о живом доме"; return
  fi
  ok "80 ручка возвращает живой дом и объявляет это в потоке и в сводке"
}

scenario_78() {   # «мерить нечем» у прибора зубов -- свой КЛАСС, а не красный прогон
  # Прибор не может мерить (нет образа, уехал якорь) и красный реестр --
  # разные починки; общий код смешивал бы «почини кит» с «почини машину».
  local out rc
  out=$(STUB_TEETH_RC=2 run_sweep "$K" "$C/corpus" "$C/versions.txt" 900); rc=$?
  LAST_EVID="rc=$rc :: $out"
  if (( rc != 2 )); then
    LAST_EVID="КЛАСС_НЕ_ТОТ :: rc=$rc :: $out"
    bad "78 «мерить нечем» у зубов: код возврата $rc, ждали 2"; return
  fi
  if [[ "$out" != *"прибор зубов НЕ МЕРИЛ"* ]]; then
    LAST_EVID="ПРИЧИНА_НЕ_НАЗВАНА :: $out"
    bad "78 «мерить нечем» у зубов: причина не названа"; return
  fi
  ok "78 «мерить нечем» у прибора зубов -- свой класс, а не красный прогон"
}

