scenario_57() {   # страж живых прогонов -- одна форма в свипе и в стенде
  # У стенда была СВОЯ, более строгая копия стража: она засчитывала путь
  # конвейера, стоявший аргументом ЧУЖОЙ программы (гейт чисел запускает
  # `python3 .docnum-gate.py <кит>/claude-patch-all.sh`), и отказывала стенду
  # на ровном месте. Общий файл сюда не подключить -- преамбулу стенда
  # исполняет и lock-probe, вырезая её отдельно; поэтому форма пинится
  # сравнением, и расхождение двух домов -- находка, а не стиль.
  local a b
  a=$(guard_form "$K/tools/sweep.sh")
  b=$(guard_form "$K/tools/corpus-tools-bench.real.sh")
  if [[ -z "$a" || -z "$b" ]]; then
    LAST_EVID="ФОРМА_СТРАЖА_РАЗОШЛАСЬ: блок не вырезан (свип=${#a} симв., стенд=${#b} симв.)"
    bad "57 страж живых: блок не найден в одном из домов"; return
  fi
  if [[ "$a" != "$b" ]]; then
    LAST_EVID="ФОРМА_СТРАЖА_РАЗОШЛАСЬ :: свип=[$a] стенд=[$b]"
    bad "57 страж живых прогонов: формы в свипе и в стенде разошлись"; return
  fi
  LAST_EVID="форма стража одна на оба дома: $a"
  ok "57 страж живых прогонов -- одна форма в свипе и в стенде"
}

scenario_83() {   # занятый замок конвейера -- НЕ ИЗМЕРЕНО, а не красный прогон
  # Прибор зубов меряет ЖИВОЙ образ и копирует его дюжину раз. Сборка вносит
  # новый образ переименованием, и копия попадала на файл, который уже не тот:
  # прибор объявлял КРАСНОЕ там, где дефекта нет. Класс ответа обязан быть
  # своим -- «повтор поможет», а не «проверка прошла мутацию молча».
  local out rc
  out=$(STUB_TEETH_RC=3 run_sweep "$K" "$C/corpus" "$C/versions.txt" 900); rc=$?
  LAST_EVID="rc=$rc :: $out"
  if (( rc != 3 )); then
    LAST_EVID="КЛАСС_НЕ_ТОТ rc=$rc :: $out"
    bad "83 занятый замок при зубах: код возврата $rc, ждали 3"; return
  fi
  if [[ "$out" != *"НЕ ИЗМЕРЕНЫ -- замок конвейера держит живая сборка"* ]]; then
    LAST_EVID="ПРИЧИНА_НЕ_НАЗВАНА :: $out"
    bad "83 занятый замок при зубах: причина не названа"; return
  fi
  ok "83 занятый замок конвейера при зубах -- свой класс, а не красный прогон"
}

scenario_84() {   # снимок кита не сносится из-под живого конвейера
  local out rc left users
  out=$(STUB_LINGER=1 BENCH_KIT_DRAIN=2 \
        run_sweep "$K" "$C/corpus" "$C/versions.txt" 900); rc=$?
  left=$(ls -d "$C/corpus/state"/kit.?????? 2>/dev/null | head -1)
  # Жилец -- ОДИН процесс с путём снимка в argv (read -t встроен, ребёнка
  # sleep нет): раньше убивался только носитель пути, а голый sleep доживал
  # сиротой. Жильцы -- не дети сценария, wait недоступен: смерть
  # подтверждается поллингом с бюджетом.
  users=$(__ps_matching "$C/corpus/state" 'read -t 25')
  local __u __still __n
  if [[ -n "$users" ]]; then
    kill $users 2>/dev/null
    __n=0
    while (( __n < 100 )); do
      __still=''
      for __u in $users; do kill -0 "$__u" 2>/dev/null && __still="$__still $__u"; done
      [[ -z "$__still" ]] && break
      sleep 0.1; __n=$(( __n + 1 ))
    done
  fi
  LAST_EVID="rc=$rc :: снимок=${left:-СНИМОК_СНЕСЁН} :: $out"
  if [[ -z "$left" ]]; then
    bad "84 снимок кита снесён из-под живого процесса, поднятого из него"; return
  fi
  if [[ "$out" != *"снимок кита НЕ убран"* ]]; then
    LAST_EVID="ПРИЧИНА_НЕ_НАЗВАНА :: $out"
    bad "84 снимок кита: пропуск уборки не объявлен"; return
  fi
  rm -rf "$left"
  ok "84 снимок кита переживает уборку, пока из него исполняются процессы"
}

scenario_85() {   # предусловие: чужой прогон -- да, своя декорация -- нет
  # Две половины, и вторая объявлена намеренно.
  #
  # ЖИВАЯ половина доказывает поведение прямо здесь: поддельный конвейер ПОД
  # временным корнем стенда (такой поднимает сценарий 45, чтобы проверить страж
  # свипа) в ответ попасть не должен, а поддельный ВНЕ корня -- обязан. Мутации
  # до этой половины не достают: правка ложится в КОПИЮ кита, а предусловие
  # исполняется из ЖИВОГО файла стенда (тот же класс, что у сценария 66).
  # Поэтому зуб -- на ФОРМЕ в копии: вычитание своих обязано вычитать по
  # временному корню. Без этого вычитания стенд отказывал сам себе на
  # собственной декорации, и сценарий 45 краснел чужой причиной (измерено).
  local inside outside mine_pid other_pid got form
  inside="$C/fake85"; mkdir -p "$inside"
  printf '#!/bin/sh\nsleep 30\n' > "$inside/claude-patch-all.sh"
  outside=$(mktemp -d "${TMPDIR:-/tmp}/cb-outside85.XXXXXX")
  printf '#!/bin/sh\nsleep 30\n' > "$outside/claude-patch-all.sh"
  # `9>&-`: оба живут по 30 секунд и убиваются без ожидания выхода -- с копией
  # дескриптора они держали бы замок стенда после его выхода.
  bash "$inside/claude-patch-all.sh" 9>&- & mine_pid=$!
  bash "$outside/claude-patch-all.sh" 9>&- & other_pid=$!
  sleep 1
  got=$(real_run_pids)
  kill "$mine_pid" "$other_pid" 2>/dev/null
  wait "$mine_pid" 2>/dev/null; wait "$other_pid" 2>/dev/null
  rm -rf "$outside"
  # Считается ТОЛЬКО внутри real_run_pids: строка этого же сценария содержит тот
  # же литерал (иначе grep считал бы сам себя, и счёт зависел бы от правок
  # сценария, а не от предмета).
  form=$(sed -n '/^real_run_pids() {/,/^}/p' "$K/tools/corpus-tools-bench.real.sh" \
         | grep -cF 'index($0, r) { print $1 }')
  LAST_EVID="ответ=[$(printf '%s' "$got" | tr '\n' ' ')] свой=$mine_pid чужой=$other_pid форма=$form"
  if printf '%s\n' "$got" | grep -qx "$mine_pid"; then
    LAST_EVID="СВОЙ_НЕ_ВЫЧТЕН :: $LAST_EVID"
    bad "85 предусловие: своя декорация засчитана настоящим прогоном"; return
  fi
  if ! printf '%s\n' "$got" | grep -qx "$other_pid"; then
    LAST_EVID="ЧУЖОЙ_ПРОПУЩЕН :: $LAST_EVID"
    bad "85 предусловие: чужой прогон вне корня стенда не замечен"; return
  fi
  if [[ "$form" != "1" ]]; then
    LAST_EVID="СВОЙ_НЕ_ВЫЧТЕН :: в копии нет вычитания по корню :: $LAST_EVID"
    bad "85 предусловие: в копии стенда нет вычитания своих по временному корню"; return
  fi
  ok "85 предусловие видит чужой прогон и не видит свою декорацию"
}

scenario_86() {   # отметка настоящего прогона переживает подстановку команд
  # Свип зовут только из подстановки (`out=$(run_sweep ...)`), а `exit` внутри
  # неё кончает ТОЛЬКО подстановку: отказ предусловия приезжал сценарию как
  # вывод свипа, сценарий краснел своей формулировкой, и стенд ехал дальше.
  # Отметка на диске переживает подстановку, верхний уровень (ok/bad) её
  # читает и прерывает прогон классом 3. Форма в копии -- зуб к этой половине:
  # живой abort_if_real_run исполняется из живого файла и мутации недоступен.
  local outside pid out rc marker sub_rc form
  outside=$(mktemp -d "${TMPDIR:-/tmp}/cb-outside86.XXXXXX")
  printf '#!/bin/sh\nsleep 30\n' > "$outside/claude-patch-all.sh"
  bash "$outside/claude-patch-all.sh" 9>&- & pid=$!
  sleep 1
  out=$(require_no_real_run "проба сценария 86"); rc=$?
  marker=НЕТ
  [[ -e "$ROOT/.real-run" ]] && marker=$(tr '\n' ' ' < "$ROOT/.real-run")
  ( abort_if_real_run ) >/dev/null 2>&1; sub_rc=$?
  # Отметка снимается ДО ok/bad: иначе они прервут прогон на этом сценарии.
  rm -f "$ROOT/.real-run"
  kill "$pid" 2>/dev/null; wait "$pid" 2>/dev/null
  rm -rf "$outside"
  # Якорь на начало строки: определения ok/bad стоят с нулевой колонки, а
  # строка этого сценария -- с отступом, и сама в счёт не попадает.
  form=$(grep -cE '^(ok|bad)\(\) +\{ abort_if_real_run;' "$K/tools/corpus-tools-bench.real.sh")
  LAST_EVID="rc=$rc отметка=$marker чтение=$sub_rc форма=$form :: $out"
  if (( rc != 3 )); then
    LAST_EVID="КЛАСС_НЕ_ТОТ :: $LAST_EVID"
    bad "86 отметка прогона: предусловие вернуло $rc, ждали 3"; return
  fi
  if [[ "$marker" == НЕТ || "$marker" != *"$pid"* ]]; then
    LAST_EVID="ОТМЕТКИ_НЕТ :: $LAST_EVID"
    bad "86 отметка прогона: подстановка кончилась, следа не осталось"; return
  fi
  if (( sub_rc != 3 )); then
    LAST_EVID="ОТМЕТКА_НЕ_ЧИТАЕТСЯ :: $LAST_EVID"
    bad "86 отметка прогона: верхний уровень её не читает ($sub_rc)"; return
  fi
  if [[ "$form" != "2" ]]; then
    LAST_EVID="ОТМЕТКА_НЕ_ЧИТАЕТСЯ :: чтений в копии $form, ждали 2 :: $LAST_EVID"
    bad "86 отметка прогона: в копии стенда её читают не оба исхода сценария"; return
  fi
  ok "86 отметка настоящего прогона переживает подстановку и прерывает стенд"
}

scenario_87() {   # S13: лидер группы получает свою сессию через ребёнка
  local root record out pid sess
  root=$(mktemp -d "$ROOT/session87.XXXXXX"); mkdir -p "$root/bin" "$root/state"
  record="$root/record"
  # Сессию читает `os.getsid`, а не `ps`: на этом Darwin `ps -o sess=` печатает
  # 0 и обычному процессу, и отделённому через setsid, а ключевого слова `sid`
  # у него нет вовсе. Прибор, не различающий сессии, держал бы сценарий
  # красным по устройству -- при любом состоянии проверяемой гарантии.
  cat > "$root/bin/bash" <<'SH87'
#!/bin/sh
sid=$(python3 -c 'import os; print(os.getsid(0))' 2>/dev/null) || sid=''
printf '%s %s\n' "$$" "${sid:-НЕТ_ПРИБОРА}" > "$SESSION_RECORD"
exit 0
SH87
  chmod +x "$root/bin/bash"
  "${SWEEP_ENV_SCRUB[@]}" \
    SESSION_RECORD="$record" PATH="$root/bin:$PATH" \
    perl -e 'use POSIX (); POSIX::setpgid(0,0); exec "/bin/bash", $ARGV[0], "999"' "$K/tools/sweep.sh" >/dev/null 2>&1 9>&-
  out=$(cat "$record" 2>/dev/null); pid=${out%% *}; sess=${out##* }
  rm -rf "$root"
  # «Не смог измерить» отделено от «измерил и разошлось»: без разделения
  # отсутствие python3 или отказ свипа до перехватчика читались бы как
  # доказанная потеря сессии.
  if [[ -z "$pid" || "$sess" == "НЕТ_ПРИБОРА" ]]; then
    LAST_EVID="ПРИБОР_НЕ_МЕРИТ pid=$pid sess=$sess"
    bad '87 S13 сессия прогона не измерена'; return
  fi
  if [[ "$pid" == "$sess" ]]; then
    LAST_EVID="СВОЯ_СЕССИЯ pid=$pid sess=$sess"
    ok '87 S13 отказ setsid у лидера исправлен форком в собственную сессию'
  else
    LAST_EVID="ЧУЖАЯ_СЕССИЯ pid=$pid sess=$sess"
    bad '87 S13 прогон остался в чужой сессии'
  fi
}

# Фоновый свип: то же окружение, что и run_sweep, но процесс остаётся жив --
# так сценарии сигнальных зубов доставляют адресный TERM самому свипу.
launch_sweep() {   # логфайл, аргументы свипа...
  local log=$1; shift
  require_no_real_run "фоновый свип ($*)"
  "${SWEEP_ENV_SCRUB[@]}" \
    CORPUS_DIR="$C/corpus" CORPUS_LIST="$C/versions.txt" SWEEP_STATE_DIR="$C/corpus/state" \
    CLAUDE_PATCH_LOCK="$PLOCK" \
    STUB_TWEAK="${STUB_TWEAK:-none}" STUB_RC="${STUB_RC:-0}" \
    STUB_TAMPER="${STUB_TAMPER:-}" STUB_LINGER="${STUB_LINGER:-}" \
    STUB_SLEEP="${STUB_SLEEP:-}" \
    SWEEP_KIT_DRAIN="${BENCH_KIT_DRAIN:-}" \
    SWEEP_SKIP_TOOLS_BENCH="${BENCH_SKIP_TOOLS:-}" \
    STUB_PROBE_RC="${STUB_PROBE_RC:-0}" STUB_PROBE_MARK="${STUB_PROBE_MARK:-}" \
    STUB_BENCH_RC="${STUB_BENCH_RC:-0}" STUB_BENCH_MARK="${STUB_BENCH_MARK:-}" \
    SWEEP_SKIP_BUILD_PROBE="${BENCH_SKIP_PROBE:-}" \
    SWEEP_LAST_N="${BENCH_LAST_N:-}" \
    STUB_TEETH_RC="${STUB_TEETH_RC:-0}" STUB_TEETH_MARK="${STUB_TEETH_MARK:-}" \
    STUB_TEETH_CONTROL_FAIL="${STUB_TEETH_CONTROL_FAIL:-}" \
    SWEEP_SKIP_CHECKS_TEETH="${BENCH_SKIP_TEETH:-}" \
    TWEAKCC_CONFIG_DIR="${BENCH_TW_HOME:-$TW_FIXTURE}" \
    bash "$K/tools/sweep.sh" "$@" > "$log" 2>&1 9>&- &
}

scenario_88() {   # S1: --stop не сигналит по записи с чужим временем старта
  # Приманка -- ЖИВАЯ группа в своей сессии, каждый доставшийся ей TERM она
  # записывает в файл. В sweep.pgid -- её номер и ЧУЖАЯ метка старта: дверь
  # обязана отказать, не послав ни одного сигнала.
  local st mark decoy out rc
  st="$C/s88"; mkdir -p "$st"
  mark="$st/decoy.hit"
  MARK="$mark" perl -e 'use POSIX (); POSIX::setpgid(0,0); exec @ARGV' \
    bash -c 'trap "printf hit >> \"\$MARK\"; exit 143" TERM; while :; do sleep 1; done' 9>&- & decoy=$!
  sleep 1
  printf '%s\t%s\n' "$decoy" 'Thu Jan  1 00:00:00 1970' > "$st/sweep.pgid"
  out=$(SWEEP_STATE_DIR="$st" bash "$K/tools/sweep.sh" --stop 2>&1 9>&-); rc=$?
  local hit=есть; [[ -e "$mark" ]] || hit=НЕТ
  kill "$decoy" 2>/dev/null; wait "$decoy" 2>/dev/null; rm -f "$mark"
  if (( rc == 0 )); then
    LAST_EVID="СИГНАЛ_УШЁЛ rc=$rc сигнал_приманке=$hit :: $out"
    bad "88 S1 --stop послал сигнал по протухшей записи"; return
  fi
  LAST_EVID="rc=$rc сигнал_приманке=$hit :: $out"
  if (( rc != 1 )); then
    bad "88 S1 --stop по чужой метке: код $rc, ждали 1"; return
  fi
  if [[ "$out" != *"переиспользован"* ]]; then
    bad "88 S1 --stop по чужой метке: причина не названа"; return
  fi
  if [[ "$hit" == есть ]]; then
    LAST_EVID="СИГНАЛ_УШЁЛ rc=$rc сигнал_приманке=$hit :: $out"
    bad "88 S1 --stop отказал, но сигнал приманке ушёл"; return
  fi
  ok "88 S1 --stop отказывает по переиспользованному номеру и не сигналит"
}

scenario_89() {   # S2: протухший sweep.pgid убирается прополкой под замком
  local out rc
  # В self-check сценарий исполняется ОДИН на свежем корпусе: каталог состояния
  # ещё не создан никаким более ранним сценарием.
  mkdir -p "$S"
  printf '999999\tThu Jan  1 00:00:00 1970\n' > "$S/sweep.pgid"
  touch -t 202601010000 "$S/sweep.pgid"
  out=$(run_sweep "$K" "$C/corpus" "$C/versions.txt" 900); rc=$?
  if (( rc != 0 )); then
    LAST_EVID="rc=$rc :: $out"
    bad "89 S2 прополка sweep.pgid: прогон отказал ($rc) -- прополка не измерена"; return
  fi
  if printf '%s' "$out" | grep -q 'убрал обломок прошлого прогона: .*sweep\.pgid'; then
    LAST_EVID="обломок назван в прополке :: $out"
    ok "89 S2 протухший sweep.pgid снимается прополкой под замком"
  else
    LAST_EVID="ПРОТАХЛЫЙ_PGID_ОСТАЛСЯ :: $out"
    bad "89 S2 протухший sweep.pgid остался: прополка его не знает"
  fi
}

scenario_90() {   # S3: сигнал в дренаже не стартует его со свежим бюджетом
  local log pid rc n t0 t1 linger
  log="$C/s90.log"; rm -f "$log"
  BENCH_KIT_DRAIN=6 STUB_LINGER=1 launch_sweep "$log" 900
  pid=$!
  n=0
  while (( n < 250 )); do
    grep -aq 'SWEEP 900: exit=' "$log" 2>/dev/null && break
    sleep 0.2; n=$(( n + 1 ))
  done
  if ! grep -aq 'SWEEP 900: exit=' "$log" 2>/dev/null; then
    kill "$pid" 2>/dev/null; wait "$pid" 2>/dev/null
    LAST_EVID="ПРИБОР_НЕ_МЕРИТ :: $(tail -3 "$log" 2>/dev/null | tr '\n' '|')"
    bad "90 S3 прогон не дошёл до дренажа -- сценарий не измерен"; return
  fi
  sleep 1
  t0=$(date +%s)
  kill -TERM "$pid" 2>/dev/null
  wait "$pid"; rc=$?
  t1=$(date +%s)
  linger=$(__ps_matching "$C/corpus/state" 'read -t 25')
  [[ -n "$linger" ]] && { kill $linger 2>/dev/null; sleep 0.3; }
  rm -rf "$C/corpus/state"/kit.?????? 2>/dev/null
  if (( rc != 143 )); then
    LAST_EVID="КЛАСС_НЕ_ТОТ rc=$rc drainer=$((t1 - t0)) c :: $(tail -3 "$log" | tr '\n' '|')"
    bad "90 S3 сигнал в дренаже: код $rc, ждали 143"; return
  fi
  if (( t1 - t0 > 3 )); then
    LAST_EVID="СВЕЖИЙ_БЮДЖЕТ drainer=$((t1 - t0)) c при бюджете 6 c :: $(tail -2 "$log" | tr '\n' '|')"
    bad "90 S3 дренаж перезапустился со свежим бюджетом ($((t1 - t0)) c)"; return
  fi
  LAST_EVID="rc=$rc drainer=$((t1 - t0)) c :: $log"
  ok "90 S3 сигнал в дренаже не перезапускает бюджет (выход за $((t1 - t0)) c)"
}

scenario_91() {   # S4: точечный TERM отчитывается кодом сигнала, а не «ошибкой оболочки»
  local leg log pid rc n out fdir flist plat fpid c t fh stub_save mutkit
  # --- нога 1: свип, окно держит заглушка версии ---
  log="$C/s91-sweep.log"; rm -f "$log" "$C/corpus/state/log/sweep-900.log"
  STUB_SLEEP=4 launch_sweep "$log" 900
  pid=$!
  n=0
  while (( n < 250 )); do
    [[ -e "$C/corpus/state/log/sweep-900.log" ]] && break
    sleep 0.2; n=$(( n + 1 ))
  done
  if [[ -e "$C/corpus/state/log/sweep-900.log" ]]; then
    sleep 1
    kill -TERM "$pid" 2>/dev/null
    wait "$pid"; rc=$?
    out=$(cat "$log")
    if (( rc != 143 )); then
      LAST_EVID="СВИП_НЕ_143 rc=$rc оболочка=$([[ "$out" == *"ошибка оболочки выше"* ]] && echo НАЗВАНА || echo нет) :: $(tail -3 "$log" | tr '\n' '|')"
      bad "91 S4 свип: точечный TERM дал код $rc, ждали 143"; return
    fi
    if [[ "$out" == *"ошибка оболочки выше"* ]]; then
      LAST_EVID="СВИП_НЕ_143 rc=$rc оболочка=НАЗВАНА :: $out"
      bad "91 S4 свип: остановка оператора названа «ошибкой оболочки»"; return
    fi
  else
    kill "$pid" 2>/dev/null; wait "$pid" 2>/dev/null
    say "corpus-tools-bench: ОТКАЗ -- нога «свип» сценария 91 не измерена (версия не дошла до лога)" >&2
    exit 2
  fi
  # --- нога 2: наполнитель, окно -- длинный список уже-лежащих версий ---
  fdir="$C/s91fetch"; rm -rf "$fdir"; mkdir -p "$fdir/corpus"
  python3 - "$fdir" <<'PY91'
import hashlib, os, sys
d = sys.argv[1] + '/corpus'
os.makedirs(d, exist_ok=True)
rows = []
for i in range(150):
    v = '0.1.%03d' % i
    b = ('v%s\n' % v).encode()
    with open(os.path.join(d, '%s.pristine' % v), 'wb') as fh:
        fh.write(b)
    rows.append('%03d %s %s' % (i, v, hashlib.sha256(b).hexdigest()))
with open(sys.argv[1] + '/rows.txt', 'w') as fh:
    fh.write('\n'.join(rows) + '\n')
PY91
  plat=$(sed -n 's/^# platform: //p' "$C/versions.txt")
  { echo "# platform: $plat"; cat "$fdir/rows.txt"; } > "$fdir/versions.txt"
  rm -f "$fdir/rows.txt"
  log="$C/s91-fetch.log"
  "${SWEEP_ENV_SCRUB[@]}" CORPUS_DIR="$fdir/corpus" CORPUS_LIST="$fdir/versions.txt" \
    bash "$K/tools/fetch-corpus.sh" > "$log" 2>&1 9>&- &
  fpid=$!
  n=0; c=0
  while (( n < 300 )); do
    c=$(grep -ac '^уже есть' "$log" 2>/dev/null); c=${c:-0}
    (( c >= 30 )) && break
    sleep 0.1; n=$(( n + 1 ))
  done
  if ! kill -0 "$fpid" 2>/dev/null; then
    LAST_EVID="ПРИБОР_НЕ_МЕРИТ цикл=$c :: $(tail -3 "$log" | tr '\n' '|')"
    bad "91 S4 наполнитель: прогон кончился раньше сигнала -- нога не измерена"; return
  fi
  kill -TERM "$fpid" 2>/dev/null
  wait "$fpid"; rc=$?
  out=$(cat "$log")
  if (( rc != 143 )); then
    LAST_EVID="НАПОЛНИТЕЛЬ_НЕ_143 rc=$rc оболочка=$([[ "$out" == *"ошибка оболочки выше"* ]] && echo НАЗВАНА || echo нет) :: $(tail -3 "$log" | tr '\n' '|')"
    bad "91 S4 наполнитель: точечный TERM дал код $rc, ждали 143"; return
  fi
  if [[ "$out" == *"ошибка оболочки выше"* ]]; then
    LAST_EVID="НАПОЛНИТЕЛЬ_НЕ_143 rc=$rc оболочка=НАЗВАНА :: $out"
    bad "91 S4 наполнитель: остановка оператора названа «ошибкой оболочки»"; return
  fi
  # --- нога 3: зонд пути сборки, случай (x) без сборок ---
  # Настоящий конвейер подставляется в копию кита НА ВРЕМЯ ноги: заглушка не
  # проходит прибор замка (нет строки трапа), а мутации бьют по копии.
  stub_save="$C/s91-stub-pipeline"
  cp "$K/claude-patch-all.sh" "$stub_save"
  cp "$KIT/claude-patch-all.sh" "$K/claude-patch-all.sh"
  fh="$C/s91home"; rm -rf "$fh"; mkdir -p "$fh/.local/share/claude/versions"
  printf 'baseURL:/^claude/i.test(x)\n' > "$fh/.local/share/claude/versions/9.9.9"
  printf 'pristine\n' > "$fh/.local/share/claude/versions/9.9.9.orig"
  log="$C/s91-probe.log"; rm -f "$log"
  mkdir -p "$C/s91tmp"
  env -u CLAUDE_PATCH_LOCK_HELD_BY HOME="$fh" TMPDIR="$C/s91tmp" \
    CLAUDE_PATCH_LOCK="$PLOCK" \
    bash "$K/tools/build-path-probe.real.sh" --case x --version 9.9.9 > "$log" 2>&1 9>&- &
  pid=$!
  n=0
  while (( n < 450 )); do
    grep -aq 'case x:' "$log" 2>/dev/null && break
    sleep 0.2; n=$(( n + 1 ))
  done
  if grep -aq 'case x:' "$log" 2>/dev/null; then
    sleep 0.5
    kill -TERM "$pid" 2>/dev/null
    wait "$pid"; rc=$?
    out=$(cat "$log")
    local orph=$(__ps_matching "$C/s91tmp" 'sleep 120')
    [[ -n "$orph" ]] && kill $orph 2>/dev/null
  else
    kill "$pid" 2>/dev/null; wait "$pid" 2>/dev/null
    mv "$stub_save" "$K/claude-patch-all.sh"
    say "corpus-tools-bench: ОТКАЗ -- нога «зонд» сценария 91 не измерена: $(tail -2 "$log" | tr '\n' '|')" >&2
    exit 2
  fi
  mv "$stub_save" "$K/claude-patch-all.sh"
  rm -rf "$C/s91tmp"/cc-build-path-probe.* 2>/dev/null
  if (( rc != 143 )); then
    LAST_EVID="ЗОНД_НЕ_143 rc=$rc оболочка=$([[ "$out" == *"ошибка оболочки выше"* ]] && echo НАЗВАНА || echo нет) :: $(tail -3 "$log" | tr '\n' '|')"
    bad "91 S4 зонд пути: точечный TERM дал код $rc, ждали 143"; return
  fi
  if [[ "$out" == *"ошибка оболочки выше"* ]]; then
    LAST_EVID="ЗОНД_НЕ_143 rc=$rc оболочка=НАЗВАНА :: $out"
    bad "91 S4 зонд пути: остановка оператора названа «ошибкой оболочки»"; return
  fi
  LAST_EVID="свип=143 наполнитель=143 зонд=143"
  ok "91 S4 точечный TERM отчитывается кодом 143 во всех трёх домах"
}

scenario_92() {   # S5: путь конвейера в argv ЧУЖОЙ программы -- не живой прогон
  # Просмотрщик -- класс vi/less: путь стоит аргументом чужой ДОЛГОЖИВУЩЕЙ
  # программы. Настоящий less без терминала не живёт (измерено), носитель
  # класса в безголовом прогоне -- tail -f.
  local fake vpid runner out rc out2 rc2
  fake="$C/fake92"; mkdir -p "$fake"
  printf '#!/bin/sh\nsleep 30\n' > "$fake/claude-patch-all.sh"
  chmod +x "$fake/claude-patch-all.sh"
  tail -f "$fake/claude-patch-all.sh" 9>&- >/dev/null 2>&1 & vpid=$!
  sleep 1
  out=$(run_sweep "$K" "$C/corpus" "$C/versions.txt" 900); rc=$?
  kill "$vpid" 2>/dev/null; wait "$vpid" 2>/dev/null
  if (( rc != 0 )); then
    LAST_EVID="ЧУЖАЯ_ПРОГРАММА_ЗАСЧИТАНА rc=$rc :: $out"
    bad "92 S5 страж: путь в argv чужой программы засчитан живым прогоном"; return
  fi
  # Контроль: тот же путь ВТОРЫМ полем за интерпретатором -- прогон, страж
  # обязан отказать. Декорация под корнем стенда: предусловие её вычитает,
  # а страж свипа -- нет.
  bash "$fake/claude-patch-all.sh" 9>&- & runner=$!
  sleep 1
  out2=$(run_sweep "$K" "$C/corpus" "$C/versions.txt" 900); rc2=$?
  kill "$runner" 2>/dev/null; wait "$runner" 2>/dev/null
  if (( rc2 != 3 )) || [[ "$out2" != *"живы процессы чужого прогона конвейера"* ]]; then
    LAST_EVID="НАСТОЯЩИЙ_НЕ_ПОЙМАН rc=$rc2 :: $out2"
    bad "92 S5 контроль: настоящий запуск конвейера стражем не пойман"; return
  fi
  LAST_EVID="чужая программа пропущена (rc=0), настоящий запуск пойман (rc=3)"
  ok "92 S5 страж различает чужую программу и настоящий запуск"
}

scenario_93() {   # S6: смерть воркера зубов -- код 2, а не 1
  # Заглушка раннера: контролю нужен мгновенный зелёный ответ, воркеру --
  # время жить; различие по пути образа. Без этой подмены убить воркер ВНУТРИ
  # его работы невозможно: копия игрушечного образа делается мгновенно.
  local tdir rid anchor img cpid wpid n rc out wk
  tdir="$C/s93tmp"; rm -rf "$tdir"; mkdir -p "$tdir"
  rid=$(awk -F'\t' '$3=="literal"{print $1; exit}' "$K/tools/checks-mutations.tsv")
  anchor=$(awk -F'\t' -v id="$rid" '$1==id{print $4}' "$K/tools/checks-mutations.tsv")
  if [[ -z "$anchor" ]]; then
    LAST_EVID="ЯКОРЬ_ТАБЛИЦЫ_ПОТЕРЯН"
    bad "93 S6: в таблице мутаций нет literal-строки -- прибор не мерил"; return
  fi
  # ФОРМА опознания, прочитанная ИЗ КОПИИ КИТА, и по той же причине, что в
  # сценарии 149: воркера ищет ЖИВОЙ __ps_children, мутации доступна только
  # копия. Проверка стоит ПЕРВОЙ -- снятый механизм отвечает раньше и дешевле,
  # чем поднятый пул.
  local kinform
  kinform=$(sed -n '/^__ps_children() {$/,/^}$/p' "$K/tools/corpus-tools-bench.real.sh" \
            | grep -cF '$2 != p { next }')
  if [[ "$kinform" != "1" ]]; then
    LAST_EVID="ОПОЗНАНИЕ_НЕ_ПО_РОДСТВУ форма=$kinform"
    bad "93 S6: в копии стенда воркер пула опознаётся не по родству"; return
  fi
  img="$C/s93-image"
  printf '%s' "$anchor" > "$img"
  cp "$K/tools/checks-on-image.sh" "$C/s93-runner-orig"
  cat > "$K/tools/checks-on-image.sh" <<'S93R'
#!/usr/bin/env bash
echo "  [OK] stub check"
case "$1" in
  *s93-image) exit 0 ;;
esac
sleep 30
S93R
  # --id называет ЕДИНСТВЕННУЮ строку: игрушечный образ несёт якорь только
  # первой literal-строки, а отказ «якорь не найден» у любой другой случился
  # бы ДО пула -- воркер не поднялся бы вовсе.
  TMPDIR="$tdir" CLAUDE_PATCH_LOCK="$PLOCK" \
    python3 "$K/tools/checks-teeth.real.py" --image "$img" --jobs 1 --id "$rid" \
    > "$C/s93.log" 2>&1 9>&- &
  cpid=$!
  # Ребёнок у python НЕ один: resource_tracker тоже ребёнок, и его смерть
  # пул переживает (перезапускает), получался ЗЕЛЁНЫЙ «прошла молча».
  #
  # Воркер опознаётся по РОДСТВУ (ppid), а не по форме argv. Форма argv --
  # свойство УМОЛЧАНИЯ CPython, а не пула: `spawn_main` попадает в argv только
  # при методе старта `spawn`, а кит метод старта нигде не пинит (ценз по
  # `set_start_method|get_context|forkserver` дал ноль при положительном
  # контроле -- ProcessPoolExecutor стоит в tools/checks-teeth.py). Значит
  # решает платформа, и это замерено:
  #   macOS  python3 3.14.7: spawn -> ... spawn_main(tracker_fd=9, ...) --multiprocessing-fork
  #   LINUX  python3 3.12.14: fork  -> python3 <путь>   (argv РОДИТЕЛЯ)
  # Половина `$2==p` того же awk ребёнка НАХОДИЛА -- ложен был только предикат
  # `/spawn_main/`, и цикл выжигал весь бюджет (300 x 0.1 c), после чего
  # сценарий объявлял «воркер не поднялся» на здоровом ките. На Python 3.14
  # умолчание Linux становится `forkserver`, и опознание по argv осталось бы
  # слепым и там; родство устойчиво ко всем трём методам старта.
  #
  # ОБЪЯВЛЕННОЕ ПРАВИЛО отбора, когда потомков больше одного: из потомков
  # вычёркивается resource_tracker, и остаться обязан РОВНО ОДИН -- иначе
  # прибор не мерит и говорит это, а не берёт «первого попавшегося». Трекер
  # опознаётся по argv намеренно: его argv -- инвариант CPython при ЛЮБОМ
  # методе старта (он всегда запускается как `python -c 'from
  # multiprocessing.resource_tracker import main;main(fd)'` и никогда не
  # форкается), тогда как argv ВОРКЕРА меняется от метода старта. Замер:
  # на маке потомков два (трекер + воркер), на Linux один (только воркер).
  wpid=''; n=0
  while (( n < 300 )); do
    wpid=$(__ps_children "$cpid" 'resource_tracker')
    if [[ "$wpid" == *$'\n'* ]]; then
      kill "$cpid" 2>/dev/null; wait "$cpid" 2>/dev/null
      mv "$C/s93-runner-orig" "$K/tools/checks-on-image.sh"
      LAST_EVID="ПРИБОР_НЕ_МЕРИТ ПОТОМКОВ_БОЛЬШЕ_ОДНОГО :: $(printf '%s' "$wpid" | tr '\n' ' ')"
      bad "93 S6: у пула больше одного потомка -- воркер не назван однозначно"; return
    fi
    [[ -n "$wpid" ]] && break
    sleep 0.1; n=$(( n + 1 ))
  done
  if [[ -z "$wpid" ]]; then
    kill "$cpid" 2>/dev/null; wait "$cpid" 2>/dev/null
    mv "$C/s93-runner-orig" "$K/tools/checks-on-image.sh"
    LAST_EVID="ПРИБОР_НЕ_МЕРИТ :: $(tail -3 "$C/s93.log" | tr '\n' '|')"
    bad "93 S6: воркер не поднялся -- сценарий не измерен"; return
  fi
  wk=$(__ps_children "$wpid")
  kill -9 "$wpid" 2>/dev/null
  wait "$cpid"; rc=$?
  [[ -n "$wk" ]] && kill -9 $wk 2>/dev/null
  mv "$C/s93-runner-orig" "$K/tools/checks-on-image.sh"
  out=$(cat "$C/s93.log")
  if (( rc == 1 )); then
    LAST_EVID="КОД_НЕ_2 rc=1 (мутация прошла молча) :: $(tail -4 "$C/s93.log" | tr '\n' '|')"
    bad "93 S6 смерть воркера: код 1 -- «мутация прошла молча» вместо «не мерил»"; return
  fi
  if (( rc != 2 )); then
    LAST_EVID="КЛАСС_НЕ_ТОТ rc=$rc :: $(tail -4 "$C/s93.log" | tr '\n' '|')"
    bad "93 S6 смерть воркера: код $rc, ждали 2"; return
  fi
  if [[ "$out" != *"воркер умер"* ]]; then
    LAST_EVID="ПРИЧИНА_НЕ_НАЗВАНА :: $out"
    bad "93 S6 смерть воркера: причина не названа"; return
  fi
  LAST_EVID="rc=2 :: $out"
  ok "93 S6 смерть воркера зубов -- класс 2 с названной причиной"
}

scenario_94() {   # S7: обломки checks-teeth.<мёртвый pid> убираются на старте
  local tdir dead out rc
  tdir="$C/s94tmp"; rm -rf "$tdir"; mkdir -p "$tdir"
  dead=$(dead_pid)
  printf 'debris' > "$tdir/checks-teeth.$dead.abc.bin"
  printf 'live'   > "$tdir/checks-teeth.$$.def.bin"
  out=$(TMPDIR="$tdir" CLAUDE_PATCH_LOCK="$PLOCK" \
        python3 "$K/tools/checks-teeth.real.py" --image "$C/corpus/0.0.900.pristine" 2>&1 9>&-); rc=$?
  local dstat=ОСТАЛСЯ lstat=СНЁСЛИ_ЖИВОЙ
  [[ -e "$tdir/checks-teeth.$dead.abc.bin" ]] || dstat=убран
  [[ -e "$tdir/checks-teeth.$$.def.bin" ]] && lstat=цел
  LAST_EVID="rc=$rc мёртвый=$dstat живой=$lstat :: $out"
  if [[ "$dstat" == ОСТАЛСЯ ]]; then
    LAST_EVID="ОСТАЛСЯ_ОБЛОМОК_МЁРТВОГО_PID rc=$rc :: $out"
    bad "94 S7 обломок мёртвого воркера не убирается на старте"; return
  fi
  if [[ "$lstat" != цел ]]; then
    bad "94 S7 снят обломок ЖИВОГО pid -- рядом может идти второй экземпляр"; return
  fi
  ok "94 S7 старт убирает обломки мёртвых pid и не трогает живые"
}

scenario_95() {   # S10: сигнал зонду в case_x -- боевой замок свободен, сироты нет
  # Две половины: SIGKILL меряет ЗАМОК (трап не исполняется -- держатель жив
  # ровно потому, что унаследовал дескриптор), TERM меряет СИРОТУ (траУ
  # принадлежит уборка держателя).
  local fh stub_save log pid rc n out lrc orph
  stub_save="$C/s95-stub-pipeline"
  fh="$C/s95home"
  run_probe_x() {   # $1 -- лог
    cp "$K/claude-patch-all.sh" "$stub_save"
    cp "$KIT/claude-patch-all.sh" "$K/claude-patch-all.sh"
    rm -rf "$fh" "$C/s95tmp"; mkdir -p "$fh/.local/share/claude/versions" "$C/s95tmp"
    printf 'baseURL:/^claude/i.test(x)\n' > "$fh/.local/share/claude/versions/9.9.9"
    printf 'pristine\n' > "$fh/.local/share/claude/versions/9.9.9.orig"
    env -u CLAUDE_PATCH_LOCK_HELD_BY HOME="$fh" TMPDIR="$C/s95tmp" \
      CLAUDE_PATCH_LOCK="$PLOCK" \
      bash "$K/tools/build-path-probe.real.sh" --case x --version 9.9.9 > "$1" 2>&1 9>&- &
    PROBE_PID=$!
    n=0
    while (( n < 450 )); do
      grep -aq 'case x:' "$1" 2>/dev/null && break
      sleep 0.2; n=$(( n + 1 ))
    done
    if ! grep -aq 'case x:' "$1" 2>/dev/null; then
      kill "$PROBE_PID" 2>/dev/null; wait "$PROBE_PID" 2>/dev/null
      mv "$stub_save" "$K/claude-patch-all.sh"
      say "corpus-tools-bench: ОТКАЗ -- зонд не дошёл до case x: $(tail -2 "$1" | tr '\n' '|')" >&2
      exit 2
    fi
    sleep 0.5
  }
  cleanup_probe_x() {
    orph=$(__ps_matching "$C/s95tmp" 'sleep 120')
    [[ -n "$orph" ]] && kill $orph 2>/dev/null
    mv "$stub_save" "$K/claude-patch-all.sh"
    rm -rf "$C/s95tmp"/cc-build-path-probe.* 2>/dev/null
  }
  # --- половина 1: SIGKILL, меряется ПРОБА ЗАМКА, а не отсутствие процесса ---
  run_probe_x "$C/s95-kill.log"
  kill -9 "$PROBE_PID" 2>/dev/null
  wait "$PROBE_PID" 2>/dev/null; rc=$?
  sleep 0.5
  perl -e 'use Fcntl ":flock"; open(my $fh, ">>", $ARGV[0]) or exit 2;
           exit(flock($fh, LOCK_EX|LOCK_NB) ? 0 : 1);' "$PLOCK" 2>/dev/null
  lrc=$?
  orph=''; cleanup_probe_x
  if (( lrc != 0 )); then
    LAST_EVID="ЗАМОК_ЗАНЯТ проба_rc=$lrc :: $(tail -2 "$C/s95-kill.log" | tr '\n' '|')"
    bad "95 S10: боевой замок занят после гибели зонда -- держатель унаследовал дескриптор"; return
  fi
  # --- половина 2: TERM, меряется СИРОТА-держатель ---
  run_probe_x "$C/s95-term.log"
  kill -TERM "$PROBE_PID" 2>/dev/null
  wait "$PROBE_PID"; rc=$?
  orph=$(__ps_matching "$C/s95tmp" 'sleep 120')
  # Снимок ДО cleanup_probe_x: та вложенная функция ПЕРЕЗАПИСЫВАЕТ orph своим
  # замером уборки, и проверка ниже читала бы уже пусто -- сирота, убитая
  # строкой выше, выглядела бы отсутствующей на любой мутации.
  local orph_seen="${orph:-НЕТ}"
  [[ -n "$orph" ]] && kill $orph 2>/dev/null
  cleanup_probe_x
  if [[ -n "${orph_seen:-}" && "$orph_seen" != "НЕТ" ]]; then
    LAST_EVID="СИРОТА_ЖИВА pid=$orph_seen :: $(tail -2 "$C/s95-term.log" | tr '\n' '|')"
    bad "95 S10: держатель case_x пережил сигнал зонду и жив сиротой"; return
  fi
  LAST_EVID="замок_свободен=да сирота=нет (rc TERM-ноги=$rc)"
  ok "95 S10 сигнал зонду в case_x: боевой замок свободен, держателя нет"
}

scenario_96() {   # S11: обломки .part.<мёртвый pid> убираются на старте наполнителя
  local dead out rc
  dead=$(dead_pid)
  printf 'debris' > "$C/corpus/0.0.900.pristine.part.$dead"
  printf 'live'   > "$C/corpus/0.0.900.pristine.part.$$"
  out=$(run_fetch "$K" "$C/corpus" "$C/versions.txt"); rc=$?
  local dstat=ОСТАЛСЯ lstat=СНЁСЛИ_ЖИВОЙ
  [[ -e "$C/corpus/0.0.900.pristine.part.$dead" ]] || dstat=убран
  [[ -e "$C/corpus/0.0.900.pristine.part.$$" ]] && lstat=цел
  rm -f "$C/corpus/0.0.900.pristine.part.$$" 2>/dev/null
  LAST_EVID="rc=$rc мёртвый=$dstat живой=$lstat :: $out"
  if (( rc != 0 )); then
    bad "96 S11 прополка .part: прогон отказал ($rc) -- прополка не измерена"; return
  fi
  if [[ "$dstat" == ОСТАЛСЯ ]]; then
    LAST_EVID="ОСТАЛСЯ_ОБЛОМОК_PART rc=$rc :: $out"
    bad "96 S11 обломок закачки мёртвого прогона не убирается на старте"; return
  fi
  if [[ "$lstat" != цел ]]; then
    bad "96 S11 снят .part ЖИВОГО pid -- рядом может идти второй наполнитель"; return
  fi
  ok "96 S11 старт наполнителя убирает .part мёртвых и не трогает живые"
}

scenario_97() {   # S12: обломок с меткой на СУТКИ ВПЕРЁД убирается прополкой
  local out rc future fresh
  mkdir -p "$S"
  future=$(mktemp -d "$S/kit.XXXXXX")
  fresh=$(mktemp -d "$S/kit.XXXXXX")
  python3 - "$future" <<'PY97'
import os, sys, time
p = sys.argv[1]
t = time.time() + 24 * 3600
os.utime(p, (t, t))
PY97
  out=$(run_sweep "$K" "$C/corpus" "$C/versions.txt" 900); rc=$?
  local fstat=ОСТАЛСЯ cstat=СНЕСЛИ_ЧУЖОЙ
  [[ -e "$future" ]] || fstat=убран
  [[ -e "$fresh" ]] && cstat=цел
  rm -rf "$future" "$fresh" 2>/dev/null
  LAST_EVID="rc=$rc будущий=$fstat свежий=$cstat :: $out"
  if (( rc != 0 )); then
    bad "97 S12 будущая метка: прогон отказал ($rc) -- прополка не измерена"; return
  fi
  if [[ "$fstat" == ОСТАЛСЯ ]]; then
    LAST_EVID="БУДУЩАЯ_МЕТКА_ОСТАЛАСЬ rc=$rc :: $out"
    bad "97 S12 обломок с меткой из будущего не убирается прополкой"; return
  fi
  if [[ "$cstat" != цел ]]; then
    bad "97 S12 снесён СВЕЖИЙ обломок -- это может быть живой прогон"; return
  fi
  ok "97 S12 метка из будущего считается протухшей, минутной давности -- нет"
}

scenario_98() {   # волна 26, D-2: ребёнок форк-запаски, убитый сигналом -- код 128+N
  # Обёртка сама становится лидером группы (setsid): тогда setsid() у лидера
  # свипа откажет, и прогон уходит в форк-запаску -- путь, который исполняется
  # при интерактивном запуске из терминала. Ребёнок запаски -- сам свип;
  # SIGKILL по его группе обязан выйти из обёртки кодом 137, а не нулём.
  local log pid rc n rec pgid pg out
  log="$C/s98.log"; rm -f "$log" "$S/sweep.pgid"
  require_no_real_run "форк-запаска (900)"
  "${SWEEP_ENV_SCRUB[@]}" \
    CORPUS_DIR="$C/corpus" CORPUS_LIST="$C/versions.txt" SWEEP_STATE_DIR="$C/corpus/state" \
    CLAUDE_PATCH_LOCK="$PLOCK" \
    STUB_SLEEP=10 \
    SWEEP_KIT_DRAIN="${BENCH_KIT_DRAIN:-}" \
    SWEEP_SKIP_TOOLS_BENCH="${BENCH_SKIP_TOOLS:-}" SWEEP_SKIP_BUILD_PROBE="${BENCH_SKIP_PROBE:-}" \
    STUB_TEETH_RC="${STUB_TEETH_RC:-0}" STUB_TEETH_MARK="${STUB_TEETH_MARK:-}" \
    STUB_TEETH_CONTROL_FAIL="${STUB_TEETH_CONTROL_FAIL:-}" \
    SWEEP_SKIP_CHECKS_TEETH="${BENCH_SKIP_TEETH:-}" \
    TWEAKCC_CONFIG_DIR="${BENCH_TW_HOME:-$TW_FIXTURE}" \
    perl -e 'use POSIX (); my $sid = POSIX::setsid();
             defined($sid) && $sid >= 0 or do { print STDERR "s98: обёртке не стать лидером группы\n"; exit 9 };
             exec @ARGV' \
      bash "$K/tools/sweep.sh" 900 > "$log" 2>&1 9>&- &
  pid=$!
  n=0; rec=""
  while (( n < 300 )); do
    [[ -s "$S/sweep.pgid" ]] && { rec=$(cat "$S/sweep.pgid" 2>/dev/null); break; }
    sleep 0.2; n=$(( n + 1 ))
  done
  pgid="${rec%%$'\t'*}"
  case "$pgid" in ''|*[!0-9]*)
    kill "$pid" 2>/dev/null; wait "$pid" 2>/dev/null
    LAST_EVID="ЗАПАСКА_НЕ_ДОШЛА rec=[$rec] :: $(tail -3 "$log" | tr '\n' '|')"
    bad "98 D2 прогон не записал номер группы -- форк-запаска не измерена"; return ;; esac
  # Обёртка обязана оставаться лидером СВОЕЙ группы: иначе setsid внутри свипа
  # прошёл бы без форка, и мерилась бы смерть свипа напрямую, а не запаска.
  pg=$(ps -o pgid= -p "$pid" 2>/dev/null | tr -d ' ')
  sleep 1
  kill -9 -- -"$pgid" 2>/dev/null
  wait "$pid" 2>/dev/null; rc=$?
  rm -f "$S/sweep.self.??????" 2>/dev/null
  rm -rf "$S"/kit.?????? 2>/dev/null
  rm -f "$S/sweep.pgid" 2>/dev/null
  if [[ "$pg" != "$pid" ]]; then
    LAST_EVID="ЗАПАСКА_НЕ_ТА pgid_обёртки=$pg pid=$pid :: $(tail -3 "$log" | tr '\n' '|')"
    bad "98 D2 обёртка не лидер своей группы -- форк-запаска не исполнялась"; return
  fi
  if (( rc != 137 )); then
    LAST_EVID="ФОРК_ЗАПАСКА_НЕ_137 rc=$rc :: $(tail -3 "$log" | tr '\n' '|')"
    bad "98 D2 ребёнок форк-запаски, убитый сигналом, дал код $rc, ждали 137"; return
  fi
  LAST_EVID="rc=$rc лидер_обёртки=$pg :: $log"
  ok "98 D2 убитый сигналом ребёнок форк-запаски поднимается в код 137"
}

scenario_99() {   # волна 26, D-4: пустая метка lstart -- файл не пишется, прогон жив
  # Подмена ps: отказывает ТОЛЬКО на форме lstart, остальное пропускает к
  # настоящему. Отказ ps обязан оставить прогон зелёным, объявить недоступность
  # двери --stop и НЕ создавать запись с пустой меткой (дверь прочла бы её и
  # отказала бы весь прогон с диагнозом «номер группы переиспользован»).
  local stubdir realps log pid rc n out saw
  stubdir="$C/s99ps"; rm -rf "$stubdir"; mkdir -p "$stubdir"
  realps=$(command -v ps)
  cat > "$stubdir/ps" <<PS99
#!/bin/sh
case " \$* " in
  *" -o lstart= -p "*) exit 1 ;;
  *) exec $realps "\$@" ;;
esac
PS99
  chmod +x "$stubdir/ps"
  log="$C/s99.log"; rm -f "$log" "$S/sweep.pgid"
  PATH="$stubdir:$PATH" STUB_SLEEP=3 launch_sweep "$log" 900
  pid=$!
  n=0; saw=0
  while (( n < 300 )); do
    [[ -e "$S/sweep.pgid" ]] && { saw=1; break; }
    grep -aq 'SWEEP 900: exit=' "$log" 2>/dev/null && break
    sleep 0.2; n=$(( n + 1 ))
  done
  wait "$pid"; rc=$?
  out=$(cat "$log")
  rm -rf "$stubdir"
  if (( rc != 0 )); then
    LAST_EVID="ПРОГОН_УБИТ_ПУСТОЙ_МЕТКОЙ rc=$rc saw=$saw :: $(tail -3 "$log" | tr '\n' '|')"
    bad "99 D4 отказ ps завалил прогон -- отсутствие двери --stop не повод валить его"; return
  fi
  if [[ "$out" != *"SWEEP NOTE"*"--stop"*"недоступна"* ]]; then
    LAST_EVID="МЕТКА_ПУСТА_ЗАПИСАНА saw_файл=$saw note=НЕТ :: $(grep -a 'SWEEP 900' "$log" | head -1)"
    bad "99 D4 недоступность двери --stop не объявлена (NOTE нет)"; return
  fi
  if (( saw )); then
    LAST_EVID="МЕТКА_ПУСТА_ЗАПИСАНА saw_файл=1 :: $(grep -a 'SWEEP 900' "$log" | head -1)"
    bad "99 D4 sweep.pgid записан с пустой меткой -- дверь прочла бы его"; return
  fi
  LAST_EVID="rc=$rc файл=не_создан note=есть :: $(grep -a 'SWEEP 900' "$log" | head -1)"
  ok "99 D4 пустая метка: файла нет, NOTE объявлен, прогон зелёный"
}

scenario_100() {   # волна 26, D-5: лидер группы мёртв, группа жива -- свой диагноз
  # Приманка: лидер умирает, его ребёнок остаётся в группе. kill -0 по группе
  # проходит, ps по лидеру пуст -- прежний диагноз «номер группы
  # переиспользован» для этого случая ложен; дверь обязана назвать его своим
  # именем, вернуть 1 и не послать ни одного сигнала.
  local st mark out rc pgid leader kid
  st="$C/s100"; mkdir -p "$st"; mark="$st/orphan.hit"; rm -f "$mark"
  MARK="$mark" perl -e 'use POSIX ();
    my $rc = POSIX::setpgid(0, 0); defined($rc) && $rc == 0 or exit 9;
    my $kid = fork(); defined($kid) or exit 9;
    exit 0 if $kid;
    exec @ARGV;' \
    bash -c 'trap "printf hit >> \"$MARK\"; exit 143" TERM; while :; do sleep 1; done' 9>&- & leader=$!
  wait "$leader"
  pgid=$leader
  printf '%s\t%s\n' "$pgid" 'Thu Jan  1 00:00:00 1970' > "$st/sweep.pgid"
  sleep 0.3
  out=$(SWEEP_STATE_DIR="$st" bash "$K/tools/sweep.sh" --stop 2>&1 9>&-); rc=$?
  local hit=есть; [[ -e "$mark" ]] || hit=НЕТ
  for kid in $(ps -eo pid,pgid | awk -v g="$pgid" '$2 == g { print $1 }'); do
    kill -9 "$kid" 2>/dev/null
  done
  rm -f "$mark" "$st/sweep.pgid"
  if [[ "$out" == *переиспользован* ]]; then
    LAST_EVID="ПЕРЕИСПОЛЬЗОВАН_НА_МЁРТВОМ_ЛИДЕРЕ rc=$rc :: $out"
    bad "100 D5 мёртвый лидер живой группы назван переиспользованным номером"; return
  fi
  if [[ "$out" != *"лидер группы"*"мёртв"* ]]; then
    LAST_EVID="ДИАГНОЗ_НЕ_НАЗВАН rc=$rc :: $out"
    bad "100 D5 случай «лидер мёртв, группа жива» не назван своим именем"; return
  fi
  if (( rc != 1 )); then
    bad "100 D5 мёртвый лидер: код $rc, ждали 1"; return
  fi
  if [[ "$hit" == есть ]]; then
    LAST_EVID="СИГНАЛ_УШЁЛ rc=$rc :: $out"
    bad "100 D5 по мёртвому лидеру ушли сигналы"; return
  fi
  ok "100 D5 мёртвый лидер живой группы: свой диагноз, код 1, сигнала нет"
}

scenario_101() {   # волна 26, D-6: наследный .part без числового суффикса убирается
  # Обломок прежней формы (.part.XXXXXX) не проходит числовой фильтр прополки
  # и лежит вечно. Под замком наполнителя он сирота по построению: замок
  # сериализует писателей на весь прогон, живого писателя с такой формой нет.
  local out rc dead
  printf 'orphan' > "$C/corpus/0.0.900.pristine.part.Xk9Zz"
  printf 'live'   > "$C/corpus/0.0.900.pristine.part.$$"
  out=$(run_fetch "$K" "$C/corpus" "$C/versions.txt"); rc=$?
  local xstat=ОСТАЛСЯ lstat=СНЯЛИ_ЖИВОЙ
  [[ -e "$C/corpus/0.0.900.pristine.part.Xk9Zz" ]] || xstat=убран
  [[ -e "$C/corpus/0.0.900.pristine.part.$$" ]] && lstat=цел
  rm -f "$C/corpus/0.0.900.pristine.part.$$" 2>/dev/null
  LAST_EVID="rc=$rc mktemp-обломок=$xstat живой=$lstat :: $out"
  if (( rc != 0 )); then
    bad "101 D6 прополка mktemp-обломков: прогон отказал ($rc) -- прополка не измерена"; return
  fi
  if [[ "$xstat" == ОСТАЛСЯ ]]; then
    LAST_EVID="ОСТАЛСЯ_ОБЛОМОК_МКТЕМП rc=$rc :: $out"
    bad "101 D6 обломок .part без числового суффикса не убирается никогда"; return
  fi
  if [[ "$out" != *"убрал обломок закачки мёртвого прогона"* ]]; then
    bad "101 D6 обломок убран, но сообщение прополки не названо"; return
  fi
  if [[ "$lstat" != цел ]]; then
    bad "101 D6 снят .part ЖИВОГО pid -- рядом может идти второй наполнитель"; return
  fi
  ok "101 D6 наследный .part.XXXXXX убирается прополкой, живой pid не тронут"
}

scenario_102() {   # волна 26, D-7: перепись замков видит открытие в одежде данных
  # Вычитание строк-данных из переписи обязано быть привязано к файлу таблиц
  # мутаций (corpus-tools-bench), а не к форме строки во всём ките: настоящее
  # открытие замка, отформатированное двумя пробелами и кавычкой (строка-
  # инициализация в чужом инструменте), выпадало из переписи молча. Перепись
  # вырезается из зонда по якорю и исполняется на копии кита с подсаженной
  # приманкой: обязана назвать её, и ТОЛЬКО её.
  local planted carved out rc rest
  planted="$K/tools/pgid-door-probe.sh"
  carved="$C/s102-census.sh"
  cat > "$planted" <<'PLANT102'
#!/usr/bin/env bash
# Приманка переписи замков: НАСТОЯЩЕЕ открытие, отформатированное в одежде
# строки данных (два пробела и кавычка) -- ровно та форма, которую вычитание
# из переписи имеет право трогать ТОЛЬКО в файле таблиц мутаций.
  'exec 3>"$STATE/door.lock"'
echo дверь
PLANT102
  python3 - "$K/tools/lock-probe.sh" "$carved" <<'CARVE102'
import re, sys
src, dst = sys.argv[1], sys.argv[2]
text = open(src, encoding='utf-8').read()
m = re.search(r'CENSUS_MISSED=""\n(?:[^\n]*\n)*?done < <\(grep -rn .exec \[0-9\]>.[^\n]*\n[^\n]*\n', text)
if not m:
    sys.stderr.write('блок переписи не найден в зонде\n')
    sys.exit(2)
open(dst, 'w', encoding='utf-8').write(m.group(0) + 'printf "MISSED=[%s]\\n" "$CENSUS_MISSED"\n')
CARVE102
  if (( $? != 0 )); then
    rm -f "$planted"
    LAST_EVID="ЯКОРЬ_ПЕРЕПИСИ_ПОТЕРЯН"
    bad "102 D7 блок переписи замков не вырезан из зонда"; return
  fi
  out=$(HERE="$K" bash "$carved" 2>&1); rc=$?
  rm -f "$planted" "$carved"
  rest=${out//tools\/pgid-door-probe.sh(fd 3)/}
  if [[ "$out" != *"tools/pgid-door-probe.sh(fd 3)"* ]]; then
    LAST_EVID="ПЕРЕПИСЬ_ОСЛЕПЛА rc=$rc :: $out"
    bad "102 D7 перепись не увидела открытие замка в одежде данных"; return
  fi
  if [[ "$rest" == *"(fd "* ]]; then
    LAST_EVID="ПЕРЕПИСЬ_ШУМИТ :: $out"
    bad "102 D7 перепись назвала лишние открытия -- измерение замусорено"; return
  fi
  if (( rc != 0 )); then
    bad "102 D7 вырезанная перепись упала (rc=$rc)"; return
  fi
  ok "102 D7 открытие в одежде данных входит в перепись и называется по имени"
}

carve_pin_py() {   # $1 -- куда положить блок; возвращает 2, если якорь потерян
  python3 - "$K/tools/fetch-corpus.sh" "$1" <<'CARVE'
import re, sys
src, dst = sys.argv[1], sys.argv[2]
text = open(src, encoding='utf-8').read()
m = re.search(r"<<'PIN_PY'\n(.*?)\nPIN_PY", text, re.S)
if not m:
    sys.stderr.write('в наполнителе нет блока PIN_PY -- якорь потерян\n')
    sys.exit(2)
open(dst, 'w', encoding='utf-8').write(m.group(1))
CARVE
}

scenario_81() {   # стадия чужого прогона не уносится нашей записью
  # Замок наполнителя стоит на КОРПУСЕ, а список живёт в ките: два прогона с
  # разными корпусами и одним списком берут каждый свой замок. С фиксированным
  # `<список>.new` один переименовывал ЧУЖУЮ половину поверх списка.
  local carved list out rc h900 stray
  carved="$C/pin-block81.py"
  if ! carve_pin_py "$carved"; then
    LAST_EVID="ЯКОРЬ_PIN_PY_ПОТЕРЯН"
    bad "81 стадия чужого прогона: блок PIN_PY не вырезан -- прибор не мерил"; return
  fi
  list="$C/pin81.txt"
  { echo "# platform: x"; echo "900 0.0.900 -"; } > "$list"
  stray="$list.new"
  echo "стадия чужого прогона" > "$stray"
  h900=$(shasum -a 256 "$C/corpus/0.0.900.pristine" | awk '{print $1}')
  out=$(python3 "$carved" "$list" 0.0.900 "$h900" 2>&1); rc=$?
  LAST_EVID="rc=$rc :: $out :: чужая стадия=$(cat "$stray" 2>/dev/null || echo СНЕСЕНА)"
  if (( rc != 0 )); then
    bad "81 стадия чужого прогона: блок отказал ($rc): $out"; return
  fi
  if [[ ! -f "$stray" || "$(cat "$stray")" != "стадия чужого прогона" ]]; then
    LAST_EVID="ЧУЖАЯ_СТАДИЯ_СНЕСЕНА"
    bad "81 стадия чужого прогона снесена -- имя стадии не несёт pid"; return
  fi
  if ! grep -q "^900 0.0.900 $h900$" "$list"; then
    bad "81 стадия чужого прогона: пин не записан: $(tr '\n' '|' < "$list")"; return
  fi
  rm -f "$stray"
  ok "81 запись списка не сталкивается со стадией чужого прогона"
}

scenario_82() {   # сорванное переименование не оставляет обломка стадии
  local carved list out rc h900 leftover
  carved="$C/pin-block82.py"
  if ! carve_pin_py "$carved"; then
    LAST_EVID="ЯКОРЬ_PIN_PY_ПОТЕРЯН"
    bad "82 обломок стадии: блок PIN_PY не вырезан -- прибор не мерил"; return
  fi
  list="$C/pin82.txt"
  { echo "# platform: x"; echo "900 0.0.900 -"; } > "$list"
  h900=$(shasum -a 256 "$C/corpus/0.0.900.pristine" | awk '{print $1}')
  # Переименование подменяется падающим: другого способа попасть в окно
  # «стадия записана, ввод не удался» у стенда нет.
  out=$(python3 - "$carved" "$list" 0.0.900 "$h900" 2>&1 <<'WRAP'
import os, sys
carved = sys.argv[1]
sys.argv = sys.argv[1:]
def boom(_a, _b):
    raise OSError('переименование сорвано (стенд)')
os.replace = boom
try:
    exec(compile(open(carved).read(), carved, 'exec'), {'__name__': '__main__'})
except OSError as error:
    sys.stderr.write('ожидаемый сбой: %s\n' % error)
    sys.exit(7)
sys.stderr.write('переименование НЕ сорвалось -- прибор не мерил\n')
sys.exit(2)
WRAP
); rc=$?
  leftover=$(ls "$list".new* 2>/dev/null | head -1)
  LAST_EVID="rc=$rc :: $out :: обломок=${leftover:-убран}"
  if (( rc == 2 )); then
    LAST_EVID="ПОДМЕНА_НЕ_СРАБОТАЛА"
    bad "82 обломок стадии: переименование не сорвалось -- прибор не мерил"; return
  fi
  if (( rc != 7 )); then
    bad "82 обломок стадии: ждали код 7 от обёртки, получили $rc: $out"; return
  fi
  if [[ -n "$leftover" ]]; then
    LAST_EVID="ОСТАЛСЯ_ОБЛОМОК $leftover"
    bad "82 обломок стадии: $leftover остался после сорванного переименования"; return
  fi
  ok "82 сорванное переименование не оставляет обломка стадии"
}


scenario_103() {   # SWEEP_LAST_N=08 -- десятичные восемь
  local d out rc n
  d="$C/lastn-08"; mk_decimal_corpus "$d"
  out=$(BENCH_LAST_N=08 run_sweep "$K" "$d/corpus" "$d/versions.txt"); rc=$?
  n=$(printf '%s\n' "$out" | grep -c '^SWEEP 9[0-9][0-9]: exit=')
  LAST_EVID="rc=$rc :: измерено=$n :: $out"
  if (( rc != 0 )) || [[ "$n" != 8 ]]; then
    LAST_EVID="НЕ_ДЕСЯТИЧНЫЕ_ВОСЕМЬ rc=$rc измерено=$n :: $out"
    bad "103 SWEEP_LAST_N=08: измерено $n версий вместо 8"; return
  fi
  ok "103 SWEEP_LAST_N=08 -- ровно 8 версий"
}

scenario_104() {   # любой будущий путь к пустому SRC обязан отказать кодом 5
  local k out rc changed
  k=$(mktemp -d "$ROOT/kit.empty.XXXXXX")
  # В self-check $K уже несёт мутацию жертвы; повторный mk_kit скопировал бы
  # живое дерево и незаметно выбросил именно ту правку, зубы которой меряются.
  cp -R "$K/." "$k/"
  changed=$(python3 - "$k/tools/sweep.sh" <<'PY_EMPTY'
from pathlib import Path
import sys
p = Path(sys.argv[1])
s = p.read_text()
old = '    SRC=("${__sorted[@]: -__n}")'
if s.count(old) != 1:
    print(0)
else:
    p.write_text(s.replace(old, '    SRC=() # test fixture: force the generic empty-set guard', 1))
    print(1)
PY_EMPTY
)
  if [[ "$changed" != 1 ]]; then
    LAST_EVID="УСЛОВИЕ_НЕ_ДОСТИГНУТО: не удалось заставить SRC опустеть"
    bad "104 пустой набор: прибор не подготовил путь"; return
  fi
  out=$(BENCH_LAST_N=1 run_sweep "$k" "$C/corpus" "$C/versions.txt"); rc=$?
  LAST_EVID="rc=$rc :: $out"
  if (( rc != 5 )) || [[ "$out" != *"набор версий пуст -- мерить нечего"* ]] \
     || [[ "$out" == *"все 0 версий измерены"* ]]; then
    LAST_EVID="ПУСТОЙ_НАБОР_ЗЕЛЁНЫЙ rc=$rc :: $out"
    bad "104 пустой набор: ждали код 5 без зелёного хвоста"; return
  fi
  ok "104 пустой набор версий -- код 5, не зелёный хвост"
}

mk_decimal_corpus() {   # каталог; двенадцать версий для отличия 10 от восьмеричных 8
  local d=$1 v plat h
  rm -rf "$d"; mkdir -p "$d/corpus"
  plat=$(grep '^# platform:' "$C/versions.txt")
  { echo "# игрушечный десятичный список"
    echo "$plat"
    for v in 920 921 922 923 924 925 926 927 928 929 930 931; do
      toy_image "$d/corpus/0.0.$v.pristine" "0.0.$v"
      h=$(shasum -a 256 "$d/corpus/0.0.$v.pristine" | awk '{print $1}')
      echo "$v 0.0.$v $h"
    done
  } > "$d/versions.txt"
}

scenario_105() {   # ведущие нули не меняют десятичное значение
  local d out rc n
  d="$C/lastn-0010"; mk_decimal_corpus "$d"
  out=$(BENCH_LAST_N=0010 run_sweep "$K" "$d/corpus" "$d/versions.txt"); rc=$?
  n=$(printf '%s\n' "$out" | grep -c '^SWEEP 9[0-9][0-9]: exit=')
  LAST_EVID="rc=$rc :: измерено=$n :: $out"
  if (( rc != 0 )) || [[ "$n" != 10 ]]; then
    LAST_EVID="ВОСЬМЕРИЧНЫЕ_ВОСЕМЬ rc=$rc :: измерено=$n :: $out"
    bad "105 SWEEP_LAST_N=0010: измерено $n версий вместо 10"; return
  fi
  ok "105 SWEEP_LAST_N=0010 -- ровно 10 версий"
}

scenario_106() {   # суточный снимок с живым жильцом не сносится прополкой
  local state stale holder out rc left alive
  state="$C/corpus/state"; mkdir -p "$state"
  stale=$(mktemp -d "$state/kit.XXXXXX")
  cat > "$stale/hold.sh" <<'HOLD'
#!/usr/bin/env bash
while :; do sleep 1; done
HOLD
  chmod +x "$stale/hold.sh"
  bash "$stale/hold.sh" 9>&- & holder=$!
  sleep 0.2
  touch -t 202601010000 "$stale"
  out=$(run_sweep "$K" "$C/corpus" "$C/versions.txt" 900); rc=$?
  left=$([[ -d "$stale" ]] && echo 1 || echo 0)
  alive=$(kill -0 "$holder" 2>/dev/null && echo 1 || echo 0)
  LAST_EVID="rc=$rc :: каталог=$left процесс=$alive :: $out"
  kill "$holder" 2>/dev/null; wait "$holder" 2>/dev/null
  rm -rf "$stale"
  if (( rc != 0 )) || [[ "$left" != 1 || "$alive" != 1 ]] \
     || [[ "$out" != *"снимок кита НЕ убран"* ]]; then
    LAST_EVID="СНЕСЁН_ЖИВОЙ_ОБЛОМОК rc=$rc каталог=$left процесс=$alive :: $out"
    bad "106 прополка: живой суточный снимок обязан остаться"; return
  fi
  ok "106 живой суточный обломок кита остаётся и объявляется"
}

scenario_107() {   # автоцель патчера -- только полное имя версии
  local d out rc
  d=$(mktemp -d "$ROOT/patch-target.XXXXXX")
  out=$(python3 - "$K/claude_patch.py" "$d" <<'PY_TARGET'
import importlib.util
import os
from pathlib import Path
import sys

modpath, raw = sys.argv[1:]
spec = importlib.util.spec_from_file_location('ccpatch_target_test', modpath)
mod = importlib.util.module_from_spec(spec)
spec.loader.exec_module(mod)
d = Path(raw)
mod.shutil.which = lambda _: None
mod.versions_dir = lambda: d
mod.is_windows = lambda: False
for name in ('2.1.250', '2.1.251', '.claude-patched-leftover'):
    (d / name).write_bytes(name.encode())
os.utime(d / '2.1.250', (10, 10)); os.utime(d / '2.1.251', (20, 20)); os.utime(d / '.claude-patched-leftover', (30, 30))
chosen = mod.resolve_active_binary()
if chosen.name != '2.1.251':
    print('ОБЛОМОК_ВЫБРАН=' + chosen.name)
    raise SystemExit(1)
(d / '2.1.250').unlink(); (d / '2.1.251').unlink()
try:
    mod.resolve_active_binary()
except SystemExit as exc:
    if exc.code != 2:
        print('НЕВЕРНЫЙ_КОД=' + str(exc.code)); raise SystemExit(1)
else:
    print('ОБЛОМОК_ПРИНЯТ_ЦЕЛЬЮ'); raise SystemExit(1)
for child in list(d.iterdir()): child.unlink()
mod.is_windows = lambda: True
(d / '2.1.251.exe').write_bytes(b'win')
if mod.resolve_active_binary().name != '2.1.251.exe':
    print('EXE_НЕ_ВЫБРАН'); raise SystemExit(1)
print('ИМЯ_ВЕРСИИ_ВЫБРАНО')
PY_TARGET
); rc=$?
  LAST_EVID="rc=$rc :: $out"
  rm -rf "$d"
  if (( rc != 0 )) || [[ "$out" != *"ИМЯ_ВЕРСИИ_ВЫБРАНО"* ]]; then
    LAST_EVID="НЕВЕРНАЯ_АВТОЦЕЛЬ rc=$rc :: $out"
    bad "107 автоцель патчера: обломок не должен быть кандидатом"; return
  fi
  ok "107 патчер выбирает только имя версии, а каталог обломков даёт 2"
}

scenario_108() {   # промежуточный backup принадлежит процессу-писателю
  local d driver p1 p2 r1 r2 t1 t2 final out
  d=$(mktemp -d "$ROOT/backup-race.XXXXXX")
  printf 'AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\n' > "$d/A"
  printf 'BBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBB\n' > "$d/B"
  driver="$d/driver.py"
  cat > "$driver" <<'PY_BACKUP'
import importlib.util
import os
from pathlib import Path
import sys
import time
modpath, srcraw, backupraw, rootraw = sys.argv[1:]
spec = importlib.util.spec_from_file_location('ccpatch_backup_test', modpath)
mod = importlib.util.module_from_spec(spec); spec.loader.exec_module(mod)
src, backup, root = Path(srcraw), Path(backupraw), Path(rootraw)
def controlled_copy(source, tmp):
    data = Path(source).read_bytes()
    with open(tmp, 'wb') as fh:
        fh.write(data[:len(data)//2]); fh.flush(); os.fsync(fh.fileno())
        (root / ('ready.' + str(os.getpid()))).write_text(str(tmp))
        until = time.time() + 10
        while len(list(root.glob('ready.*'))) < 2 and time.time() < until: time.sleep(.01)
        if len(list(root.glob('ready.*'))) < 2: raise RuntimeError('barrier timeout')
        fh.write(data[len(data)//2:]); fh.flush(); os.fsync(fh.fileno())
mod.shutil.copy2 = controlled_copy
mod._replace_backup(src, backup)
PY_BACKUP
  python3 "$driver" "$K/claude_patch.py" "$d/A" "$d/backup" "$d" >"$d/one.log" 2>&1 & p1=$!
  python3 "$driver" "$K/claude_patch.py" "$d/B" "$d/backup" "$d" >"$d/two.log" 2>&1 & p2=$!
  wait "$p1"; r1=$?; wait "$p2"; r2=$?
  t1=$(cat "$d/ready.$p1" 2>/dev/null); t2=$(cat "$d/ready.$p2" 2>/dev/null)
  final=bad
  cmp -s "$d/backup" "$d/A" 2>/dev/null && final=A
  cmp -s "$d/backup" "$d/B" 2>/dev/null && final=B
  out="r1=$r1 r2=$r2 tmp1=$t1 tmp2=$t2 final=$final :: $(cat "$d/one.log" "$d/two.log")"
  LAST_EVID="$out"
  rm -rf "$d"
  if (( r1 != 0 || r2 != 0 )) || [[ -z "$t1" || "$t1" == "$t2" || "$final" == bad ]]; then
    LAST_EVID="ОБЩАЯ_СТАДИЯ :: $out"
    bad "108 два backup-писателя: стадии должны различаться, итог -- один источник"; return
  fi
  ok "108 два backup-писателя имеют разные .new.<pid>, итог целиком из одного источника"
}

scenario_109() {   # env-ручки читаются одной строгой истинностью
  local mark out rc helper phelper lhelper bhelper hrc survived pout lout bout
  local pair sfile sknob site shelper sout found
  mark="$C/probe-zero.called"; rm -f "$mark"
  out=$(BENCH_SKIP_PROBE=0 STUB_PROBE_MARK="$mark" run_sweep "$K" "$C/corpus" "$C/versions.txt" 900); rc=$?
  if (( rc != 0 )) || [[ ! -e "$mark" ]]; then
    LAST_EVID="ZERO_ПРОПУСТИЛ_ЗОНД rc=$rc mark=$([[ -e "$mark" ]] && echo есть || echo нет) :: $out"
    bad "109 env-ручки: SWEEP_SKIP_BUILD_PROBE=0 обязан запускать зонд"; return
  fi
  helper=$(awk '/^__envon\(\) \{/{on=1} on{print} on && /^\}/{exit}' "$K/tools/sweep.sh")
  out=$(bash -c "$helper"$'\n''TEST_FLAG=true; __envon TEST_FLAG; a=$?; TEST_FLAG=false; __envon TEST_FLAG; b=$?; TEST_FLAG=ага; __envon TEST_FLAG >/dev/null 2>&1; c=$?; printf "%s/%s/%s\n" "$a" "$b" "$c"'); hrc=$?
  phelper=$(awk '/^__envon\(\) \{/{on=1} on{print} on && /^\}/{exit}' "$K/claude-patch-all.real")
  pout=$(bash -c "$phelper"$'\n''CLAUDE_PATCH_SKIP_MODELS=true; __envon CLAUDE_PATCH_SKIP_MODELS; printf "%s\n" "$?"')
  lhelper=$(awk '/^__envon\(\) \{/{on=1} on{print} on && /^\}/{exit}' "$K/tools/lock-probe.sh")
  lout=$(bash -c "$lhelper"$'\n''KEEP_ROOT=0; __envon KEEP_ROOT; a=$?; KEEP_ROOT=ага; __envon KEEP_ROOT >/dev/null 2>&1; b=$?; printf "%s/%s\n" "$a" "$b"')
  bhelper=$(awk '/^__envon\(\) \{/{on=1} on{print} on && /^\}/{exit}' "$K/tools/build-path-probe.real.sh")
  bout=$(bash -c "$bhelper"$'\n''KEEP_ROOT=0; __envon KEEP_ROOT; a=$?; KEEP_ROOT=ага; __envon KEEP_ROOT >/dev/null 2>&1; b=$?; printf "%s/%s\n" "$a" "$b"')
  # Раньше здесь стоял греп ФОРМЫ вызова -- и он запинил форму `__envon ИМЯ; rc=$?`,
  # которая под `set -e` обрывает скрипт молча на невыставленной ручке (измерено на
  # приёмке волны 31: установка проходила, конвейер объявлял отказ 1 сразу после
  # свапа). Греп формы был доволен: он проверял НАПИСАНИЕ, а не то, переживает ли
  # сайт свою же самую частую входную ситуацию. Теперь для каждого потребителя
  # берутся ЕГО байты (читатель + строки вызова из файла) и исполняются под
  # `set -euo pipefail` с СНЯТОЙ ручкой: выжил -- значит дошли до следующей строки.
  # Два разных дефекта -- два разных следа. «Читателя на сайте не стало» и
  # «сайт есть, но обрывается на снятой ручке» ловятся разными мутациями и
  # обязаны называться по-разному: слитый след объявил бы удалённый читатель
  # обрывом, то есть доказал бы чужое правило. Поэтому сайт ищется формой,
  # ДОПУСКАЮЩЕЙ обе записи (`|| rc=$?` и `; rc=$?`) -- иначе возврат сломанной
  # формы читался бы как исчезновение сайта.
  found=0; survived=0
  for pair in "tools/sweep.sh SWEEP_SKIP_BUILD_PROBE" \
              "tools/sweep.sh SWEEP_SKIP_TOOLS_BENCH" \
              "tools/sweep.sh SWEEP_SKIP_CHECKS_TEETH" \
              "claude-patch-all.real CLAUDE_PATCH_SKIP_MODELS" \
              "tools/lock-probe.sh KEEP_ROOT" \
              "tools/build-path-probe.real.sh KEEP_ROOT"; do
    sfile="${pair%% *}"; sknob="${pair##* }"
    site=$(grep -B1 -E "^__envon $sknob(;| \|\|) " "$K/$sfile" | grep -v '^--$')
    [[ "$site" == *"__envon $sknob"* ]] || continue
    found=$((found+1))
    shelper=$(awk '/^__envon\(\) \{/{on=1} on{print} on && /^\}/{exit}' "$K/$sfile")
    sout=$(env -u "$sknob" bash -c "set -euo pipefail
$shelper
$site
printf ДОШЛИ" 2>&1)
    [[ "$sout" == *ДОШЛИ* ]] && survived=$((survived+1))
  done
  LAST_EVID="helper_rc=$hrc sweep=$out patch=$pout lock=$lout build=$bout найдено=$found выжили=$survived"
  if (( hrc != 0 )) || [[ "$out" != "0/1/2" || "$pout" != 0 \
       || "$lout" != "1/2" || "$bout" != "1/2" ]]; then
    LAST_EVID="ИСТИННОСТЬ_РАЗОШЛАСЬ helper_rc=$hrc sweep=$out patch=$pout lock=$lout build=$bout выжили=$survived"
    bad "109 env-ручки: true/false/неизвестное у читателей не сошлись"; return
  fi
  if [[ "$found" != 6 ]]; then
    LAST_EVID="САЙТ_ЧИТАТЕЛЯ_ПРОПАЛ найдено=$found из 6 :: sweep=$out patch=$pout lock=$lout build=$bout"
    bad "109 env-ручки: у потребителя не стало сайта чтения ручки"; return
  fi
  if [[ "$survived" != 6 ]]; then
    LAST_EVID="ОБРЫВ_НА_СНЯТОЙ_РУЧКЕ выжили=$survived из 6 :: sweep=$out patch=$pout lock=$lout build=$bout"
    bad "109 env-ручки: сайт вызова обрывается под set -e, когда ручка не выставлена"; return
  fi
  ok "109 env-ручки: true/false/invalid едины; все 6 сайтов переживают снятую ручку под set -e"
}


scenario_110() {   # настоящая негодность числовой ручки -- код 2 с именем
  local d value out rc
  d="$C/lastn-invalid"; mk_decimal_corpus "$d"
  for value in abc -1 1.5 '' 99999999999999999999; do
    out=$(BENCH_LAST_N="$value" run_sweep "$K" "$d/corpus" "$d/versions.txt"); rc=$?
    if (( rc != 2 )) || [[ "$out" != *"SWEEP_LAST_N"* ]]; then
      LAST_EVID="НЕГОДНОСТЬ_ПРИНЯТА value=[$value] rc=$rc :: $out"
      bad "110 SWEEP_LAST_N=[$value]: ждали код 2 с именем ручки"; return
    fi
  done
  LAST_EVID='все пять негодных форм отвергнуты кодом 2 с именем SWEEP_LAST_N'
  ok "110 SWEEP_LAST_N: abc/-1/1.5/пусто/переполнение -- отказ 2"
}

scenario_111() {   # зубы меряют образ прогона, а не установленный
  # W-1: стадия зубов прежде звала прибор без --image, и умолчание прибора --
  # установленный ~/.local/bin/claude. После любой волны, меняющей пины,
  # контроль «образ зелен до мутаций» проверял чужой артефакт.
  local out rc mark
  mark="$C/teeth.called"; rm -f "$mark"
  out=$(STUB_TEETH_MARK="$mark" run_sweep "$K" "$C/corpus" "$C/versions.txt" 900); rc=$?
  LAST_EVID="rc=$rc :: mark=$(cat "$mark" 2>/dev/null | tr '\n' '|') :: $out"
  if (( rc != 0 )); then
    bad "111 зубы по образу прогона: прогон отказал ($rc)"; return
  fi
  if [[ ! -e "$mark" ]]; then
    LAST_EVID="ПРИБОР_НЕ_ЗВАЛСЯ :: $out"
    bad "111 зубы по образу прогона: прибор не звался"; return
  fi
  if ! grep -q -- '--image' "$mark"; then
    LAST_EVID="НЕТ_--image :: $(cat "$mark" | tr '\n' '|') :: $out"
    bad "111 зубы по образу прогона: нет --image"; return
  fi
  if ! grep -q 'bin/900.wave.bin' "$mark"; then
    LAST_EVID="НЕ_ОБРАЗ_ПРОГОНА :: $(cat "$mark" | tr '\n' '|') :: $out"
    bad "111 зубы по образу прогона: --image не на 900.wave.bin"; return
  fi
  if grep -q '/.local/bin/claude' "$mark"; then
    LAST_EVID="УСТАНОВЛЕННЫЙ_ОБРАЗ :: $(cat "$mark" | tr '\n' '|') :: $out"
    bad "111 зубы по образу прогона: измерялся установленный образ"; return
  fi
  ok "111 зубы реестра зовутся с --image на образ прогона"
}

scenario_112() {   # ни одна версия не собралась -- зубы названы, а не тишина
  # Молчание здесь неотличимо от зелёного: стадия просто не дошла, а сводка
  # не говорила, что зубы не мерили.
  mkdir -p "$S/bin"; rm -f "$S/bin/900.wave.bin"; chmod 500 "$S/bin"
  local out rc sum
  out=$(run_sweep "$K" "$C/corpus" "$C/versions.txt" 900); rc=$?
  chmod 700 "$S/bin"
  sum="$C/corpus/state/log/sweep-summary.txt"
  LAST_EVID="rc=$rc :: $out"
  if [[ "$out" != *"зубы реестра: НЕ ИЗМЕРЕНЫ -- ни одна версия не собралась"* ]]; then
    LAST_EVID="ЗУБЫ_МОЛЧАТ :: rc=$rc :: $out"
    bad "112 нет сборки: зубы не названы отдельной строкой"; return
  fi
  if [[ ! -f "$sum" ]] || ! grep -q 'зубы реестра проверок: НЕ ИЗМЕРЕНЫ -- ни одна версия не собралась' "$sum"; then
    LAST_EVID="СВОДКА_МОЛЧИТ :: $(cat "$sum" 2>/dev/null | tr '\n' '|')"
    bad "112 нет сборки: сводка молчит о зубах"; return
  fi
  ok "112 нет сборки -- зубы названы в потоке и в сводке, а не тишина"
}

scenario_113() {   # провал контроля зубов назван своим именем, а не дизъюнкцией
  # Класс «прибор не может мерить» с провалом контроля прежде печатал
  # «якорь мутации, длина замены или контроль» -- из дизъюнкции не видно,
  # какая из трёх сработала. docnum:other
  local out rc
  out=$(STUB_TEETH_CONTROL_FAIL=1 run_sweep "$K" "$C/corpus" "$C/versions.txt" 900); rc=$?
  LAST_EVID="rc=$rc :: $out"
  if (( rc != 2 )); then
    LAST_EVID="КЛАСС_НЕ_ТОТ :: rc=$rc :: $out"
    bad "113 контроль зубов: код $rc, ждали 2"; return
  fi
  if [[ "$out" != *"образ прогона красен ещё до мутаций"* ]]; then
    LAST_EVID="ДИСЪЮНКЦИЯ :: $out"
    bad "113 контроль зубов: причина не своим именем"; return
  fi
  if [[ "$out" == *"якорь мутации, длина замены или контроль"* ]]; then
    LAST_EVID="ДИСЪЮНКЦИЯ :: $out"
    bad "113 контроль зубов: осталась дизъюнкция трёх"; return
  fi
  ok "113 провал контроля зубов назван своим именем"
}

scenario_168() {   # конвейер отказал -- зубы не звались и слот не съеден
  # Сторож зубной стадии пускает прибор только по СОБРАННОМУ продукту:
  # конвейер вернул 0 И образ несёт правку. Прежнее условие (rc != 3)
  # пускало прибор по одному НАЛИЧИЮ копии, которую кладёт сам свип ДО
  # конвейера, -- у отказавшей версии прибор мерял ПРИСТИННЫЙ образ.
  # Здесь конвейер отказывает, и главное утверждение -- прибор НЕ ЗВАЛСЯ
  # вовсе; строка «ни одна версия не собралась» в сводке -- это и есть
  # «слот не съеден»: TEETH_DONE остался нулём, и отказ версии не присвоил
  # себе стадию зубов.
  # STUB_TEETH_RC=1 ставится СОЗНАТЕЛЬНО: зелёный ответ прибора свип в
  # свой вывод не печатает (уходит в лог прибора), и без красного ответа
  # первое утверждение было бы неопровержимо-истинным. Мутация условия
  # пускает отказавшую версию к проверке метки, и та отказывает раньше
  # прибора -- тогда зуб держит строка сводки; первое утверждение ловит
  # мир, где снята и проверка метки: прибор идёт по пристинному образу, и
  # красный ответ выносит его строку в вывод свипа.
  local out rc sum
  out=$(STUB_RC=1 STUB_TEETH_RC=1 run_sweep "$K" "$C/corpus" "$C/versions.txt" 900); rc=$?
  sum="$C/corpus/state/log/sweep-summary.txt"
  LAST_EVID="rc=$rc :: $out"
  if [[ "$out" == *"stub checks-teeth rc="* ]]; then
    LAST_EVID="ПРИБОР_ЗВАЛСЯ :: $out"
    bad "168 отказ конвейера: прибор зубов всё равно звался"; return
  fi
  if [[ ! -f "$sum" ]] || ! grep -q 'зубы реестра проверок: НЕ ИЗМЕРЕНЫ -- ни одна версия не собралась' "$sum"; then
    LAST_EVID="СВОДКА_МОЛЧИТ :: $(cat "$sum" 2>/dev/null | tr '\n' '|')"
    bad "168 отказ конвейера: сводка молчит о зубах"; return
  fi
  ok "168 отказ конвейера -- зубы не мерили, слот не съеден"
}

scenario_169() {   # успех объявлен, а правки в образе нет -- отказ своей причиной
  # Два утверждения об ОДНОМ образе разошлись: конвейер вернул 0, а иглы
  # маршрутной правки в образе нет. Молчание здесь неотличимо от зелёного,
  # поэтому свип отказывает САМОЙ ПРИЧИНОЙ -- и в потоке, и в сводке.
  # STUB_NO_MARKER снимает у заглушки ДОПИСЫВАНИЕ метки, не трогая код
  # возврата: имитируется конвейер, который объявил успех и не оставил
  # продукта.
  local out rc sum
  out=$(STUB_RC=0 STUB_NO_MARKER=1 run_sweep "$K" "$C/corpus" "$C/versions.txt" 900); rc=$?
  sum="$C/corpus/state/log/sweep-summary.txt"
  LAST_EVID="rc=$rc :: $out"
  if (( rc == 0 )); then
    LAST_EVID="ОТКАЗА_НЕТ rc=0 :: $out"
    bad "169 успех без правки: свип не отказал"; return
  fi
  if [[ "$out" != *"не несёт нашей правки"* ]]; then
    LAST_EVID="ПРИЧИНА_НЕ_НАЗВАНА :: $out"
    bad "169 успех без правки: причина не названа"; return
  fi
  if [[ ! -f "$sum" ]] || ! grep -Eq '^# зубы реестра проверок: НЕ ИЗМЕРЕНЫ -- образ версии .*без нашей правки при exit=0$' "$sum"; then
    LAST_EVID="СВОДКА_МОЛЧИТ :: $(cat "$sum" 2>/dev/null | tr '\n' '|')"
    bad "169 успех без правки: сводка молчит о зубах"; return
  fi
  ok "169 успех без правки в образе -- отказ своей причиной"
}

scenario_170() {   # положительный контроль: заглушка несёт метку, зубы идут
  # Без этого плеча сценарии 168 и 169 не доказывают ничего: «прибор не
  # звался» на сломанном конвейере ничего не стоит, если на исправном он
  # тоже не зовётся. Заглушка при нулевом коде возврата дописывает литерал
  # маршрутной правки в образ, сторож пропускает образ к прибору, стадия
  # зелёная.
  # Игла читается из ЛОГА прибора: свип маршрутизирует stdout прибора в его
  # лог, и ЗЕЛЁНЫЙ ответ в вывод свипа не попадает -- в вывод его выносят
  # только хвосты отказных веток, чем и живёт отрицательное плечо 168.
  local out rc sum tlog
  # Лог прибора сносится ДО прогона, как соседи сносят свои метки: файл
  # переживает сценарии, и без уборки игла читалась бы из ЧУЖОГО прогона.
  tlog="$C/corpus/state/log/checks-teeth.log"
  rm -f "$tlog"
  out=$(run_sweep "$K" "$C/corpus" "$C/versions.txt" 900); rc=$?
  sum="$C/corpus/state/log/sweep-summary.txt"
  LAST_EVID="rc=$rc :: прибор=$(cat "$tlog" 2>/dev/null | tr '\n' '|') :: $out"
  if [[ ! -f "$tlog" ]] || ! grep -q 'stub checks-teeth rc=' "$tlog"; then
    LAST_EVID="ПРИБОР_НЕ_ЗВАЛСЯ :: $out"
    bad "170 положительный контроль: прибор зубов не звался"; return
  fi
  if [[ ! -f "$sum" ]] || ! grep -q '^# зубы реестра проверок: ЗЕЛЁНО$' "$sum"; then
    LAST_EVID="СТАДИЯ_НЕ_ЗЕЛЕНАЯ :: $(cat "$sum" 2>/dev/null | tr '\n' '|')"
    bad "170 положительный контроль: стадия не объявлена зелёной"; return
  fi
  if (( rc != 0 )); then
    LAST_EVID="ПРОГОН_ОТКАЗАЛ rc=$rc :: $out"
    bad "170 положительный контроль: прогон отказал ($rc)"; return
  fi
  ok "170 положительный контроль -- метка в образе, зубы зелёные"
}

scenario_114() {   # частичный прогон tweakcc с ОБЪЯВЛЕННЫМИ непроходами -- зелёный
  # Волна 33 научила конвейер принимать объявленный непроход правки tweakcc
  # (tools/tweakcc-known-misses.txt), а вердикт свипа считал прогоном только
  # полный баннер -- законный прогон 257 читался как «прогонов tweakcc 0».
  local out rc
  out=$(STUB_TWEAK=parttw run_sweep "$K" "$C/corpus" "$C/versions.txt" 900); rc=$?
  LAST_EVID="rc=$rc :: $out"
  if (( rc != 0 )) || [[ "$out" != *"SWEEP DONE"* ]]; then
    bad "114 частичный прогон tweakcc с объявленными непроходами объявлен красным (код $rc)"
  else
    ok "114 частичный прогон tweakcc с объявленными непроходами -- SWEEP DONE"
  fi
}
scenario_115() { expect_red "115 частичный прогон tweakcc БЕЗ объявленных непроходов -- КРАСНАЯ" parttw_undeclared "частичный прогон tweakcc без объявленных непроходов"; }

scenario_116() {   # расклад крестиков ПО СЕКЦИЯМ и ЯКОРНЫЙ счёт промахов
  # Волна 34b дала сводке три новых поля (twcode/twprompt/twmiss), и ни одно не
  # пинилось: сумма крестиков сходится при ЛЮБОМ расколе на слои, а неякоренный
  # счёт промахов удваивается на ЖИВОМ образе (2.1.259: 24 -> 48). На игрушечном
  # логе он даёт 3 при 2 якорных: образец сидит внутри строки пересказа только
  # у неразобранной ветки.
  # Волна 39b: слой опознаётся СЕКЦИЕЙ вывода, а не префиксом имени. Имена в
  # игрушечном логе идут ВРАЗРЕЗ с секциями -- «Data: model list» и «Skill:
  # rename» лежат в секциях кода, «Custom Kind: my overlay» -- в секции
  # промтов, -- поэтому счёт по секции даёт 3/1, а счёт по префиксу имени дал
  # бы 2/2: подмена разбора видна числом.
  local out rc line summary
  summary="$S/log/sweep-summary.txt"
  out=$(run_sweep "$K" "$C/corpus" "$C/versions.txt" 900); rc=$?
  LAST_EVID="rc=$rc :: $out"
  if (( rc != 0 )); then
    bad "116 расклад крестиков: зелёный прогон не состоялся (код $rc)"; return
  fi
  line=$(grep -a 'twcode=' "$summary" 2>/dev/null | head -1)
  LAST_EVID="РАСКЛАД :: $line"
  if [[ "$line" != *"tweakcc=4 twcode=3 twprompt=1 twmiss=2"* ]]; then
    bad "116 расклад крестиков: в сводке не «tweakcc=4 twcode=3 twprompt=1 twmiss=2»; было: $line"
    return
  fi
  ok "116 крестики разделены по секциям, промахи считаются якорно"
}

scenario_117() { expect_red "117 дверь уровня tweakcc не отработала -- КРАСНАЯ" notwlevel "дверь уровня tweakcc не отработала"; }

scenario_118() {   # объявленное гашение двери уровня -- законный зелёный
  # У двери ДВА объявленных выхода: «сошёлся» и погашение слепой ручкой.
  # Вердикт обязан принимать оба, иначе объявленное гашение читалось бы как
  # «дверь не отработала» -- красное на законном прогоне.
  local out rc
  out=$(STUB_TWEAK=blindtwlevel run_sweep "$K" "$C/corpus" "$C/versions.txt" 900); rc=$?
  LAST_EVID="rc=$rc :: $out"
  if (( rc != 0 )) || [[ "$out" != *"SWEEP DONE"* ]]; then
    bad "118 объявленное гашение двери уровня объявлено красным (код $rc)"
  else
    ok "118 объявленное гашение двери уровня -- SWEEP DONE"
  fi
}

scenario_119() {   # снимок кита без перечисления секций -- отказ ДО первой сборки
  # Перечисления секций принадлежат конвейеру, свип читает их из СНИМКА.
  # Пустое перечисление молча обнулило бы слой в каждой строке сводки, и
  # расклад противоречил бы двери конвейера -- поэтому отсутствие присваивания
  # обязано быть отказом, а не нулём. Отказ называется ИМЕНЕМ константы:
  # перечисления два, и отказ по соседней -- отказ по чужой причине.
  local lone out rc
  lone="$C/nosections-kit"
  rm -rf "$lone"; cp -R "$K" "$lone"
  perl -0pi -e "s/^__TW_CODE_SECTIONS=.*\n//m" "$lone/claude-patch-all.sh"
  out=$(run_sweep "$lone" "$C/corpus" "$C/versions.txt" 900); rc=$?
  LAST_EVID="rc=$rc :: $out"
  if (( rc == 0 )); then
    bad "119 снимок без перечисления секций: прогон не отказал"; return
  fi
  if [[ "$out" != *"не найдено присваивание __TW_CODE_SECTIONS"* ]]; then
    bad "119 снимок без перечисления секций: причина не названа: $(printf '%s' "$out" | head -3 | tr '\n' ' ')"
    return
  fi
  if [[ "$out" == *"SWEEP 900"* ]]; then
    LAST_EVID="ОТКАЗ_ПОСЛЕ_СБОРКИ :: $out"
    bad "119 снимок без перечисления секций: отказ пришёл ПОСЛЕ сборки версии"; return
  fi
  ok "119 снимок без перечисления секций -- отказ до первой сборки"
}

scenario_120() {   # два присваивания перечисления -- отказ ДО первой сборки
  # Читатели берут первое присваивание, bash -- последнее. Расхождение молчит,
  # пока единственность не проверена, поэтому она проверяется.
  local dup out rc
  dup="$C/dupsections-kit"
  rm -rf "$dup"; cp -R "$K" "$dup"
  printf "__TW_CODE_SECTIONS='Data'\n" >> "$dup/claude-patch-all.sh"
  out=$(run_sweep "$dup" "$C/corpus" "$C/versions.txt" 900); rc=$?
  LAST_EVID="rc=$rc :: $out"
  if (( rc == 0 )); then
    bad "120 два присваивания перечисления: прогон не отказал"; return
  fi
  if [[ "$out" != *"присваиваний __TW_CODE_SECTIONS несколько"* ]]; then
    bad "120 два присваивания перечисления: причина не названа: $(printf '%s' "$out" | head -3 | tr '\n' ' ')"
    return
  fi
  if [[ "$out" == *"SWEEP 900"* ]]; then
    LAST_EVID="ОТКАЗ_ПОСЛЕ_СБОРКИ :: $out"
    bad "120 два присваивания перечисления: отказ пришёл ПОСЛЕ сборки версии"; return
  fi
  ok "120 два присваивания перечисления -- отказ до первой сборки"
}

scenario_121() {   # промахов накладок нет -- поле обязано быть НУЛЁМ
  # Единственное пиненное значение поля переживает подмену счётчика константой
  # этого же значения. Нулевой случай -- вторая точка, через которую константа
  # уже не проходит.
  local out rc line summary
  summary="$S/log/sweep-summary.txt"
  out=$(STUB_TWEAK=nomiss run_sweep "$K" "$C/corpus" "$C/versions.txt" 900); rc=$?
  LAST_EVID="rc=$rc :: $out"
  if (( rc != 0 )); then
    bad "121 лог без промахов накладок: зелёный прогон не состоялся (код $rc)"; return
  fi
  line=$(grep -a 'twmiss=' "$summary" 2>/dev/null | head -1)
  LAST_EVID="РАСКЛАД :: $line"
  if [[ "$line" != *"twmiss=0"* ]]; then
    bad "121 лог без промахов накладок: в сводке не «twmiss=0»; было: $line"; return
  fi
  ok "121 отсутствие промахов накладок читается нулём"
}

scenario_122() {   # присваивание есть, но не разобрано -- отказ, а не пустое перечисление
  # Счёт сходится (строка одна), а форма чужая: пустое перечисление молча
  # обнулило бы слой в каждой строке сводки. Отказ обязан назвать ТУ константу,
  # которая не разобрана: носитель разбора один на две, и отказ по здоровой
  # соседке -- отказ по чужой причине.
  local odd out rc
  odd="$C/oddsections-kit"
  rm -rf "$odd"; cp -R "$K" "$odd"
  perl -0pi -e 's/^__TW_CODE_SECTIONS=.*\n/__TW_CODE_SECTIONS="Always Applied"\n/m' "$odd/claude-patch-all.sh"
  out=$(run_sweep "$odd" "$C/corpus" "$C/versions.txt" 900); rc=$?
  LAST_EVID="rc=$rc :: $out"
  if (( rc == 0 )); then
    bad "122 неразобранное присваивание: прогон не отказал"; return
  fi
  if [[ "$out" != *"присваивание __TW_CODE_SECTIONS в снимке кита не разобрано"* ]]; then
    bad "122 неразобранное присваивание: причина не названа: $(printf '%s' "$out" | head -3 | tr '\n' ' ')"
    return
  fi
  if [[ "$out" == *"SWEEP 900"* ]]; then
    LAST_EVID="ОТКАЗ_ПОСЛЕ_СБОРКИ :: $out"
    bad "122 неразобранное присваивание: отказ пришёл ПОСЛЕ сборки версии"; return
  fi
  ok "122 неразобранное присваивание -- отказ до первой сборки"
}

# Дверь МНОЖЕСТВА выключенных правок tweakcc: её вызова не пинило НИЧТО.
# Оснастка зонда пути сборки берёт из исходника ТЕЛО функции и зовёт его сама,
# поэтому снятый из конвейера боевой вызов ей невидим ПО ПОСТРОЕНИЮ -- измерено
# на копии конвейера без вызова: случай (n) остался зелёным (23 ok, 25 RED).
# Свидетель вызова живёт там же, где свидетель двери уровня, -- в вердикте
# свипа, и его считают сценарии ниже.
scenario_123() {   # ответ «сошлись» засчитан полем twoff
  local out rc line summary
  summary="$S/log/sweep-summary.txt"
  out=$(run_sweep "$K" "$C/corpus" "$C/versions.txt" 900); rc=$?
  line=$(grep -a 'twoff=' "$summary" 2>/dev/null | head -1)
  LAST_EVID="РАСКЛАД(rc=$rc) :: $line"
  if [[ "$line" != *"twoff=1"* ]]; then
    bad "123 дверь выключенных правок: в сводке не «twoff=1»; было: $line"; return
  fi
  if (( rc != 0 )) || [[ "$out" != *"SWEEP DONE"* ]]; then
    LAST_EVID="rc=$rc :: $out"
    bad "123 дверь выключенных правок: зелёный прогон не состоялся (код $rc)"; return
  fi
  ok "123 ответ «сошлись» двери выключенных правок засчитан"
}

scenario_124() {   # слепая ручка: считается СВОЯ дверь, соседняя -- нет
  # Одна ручка гасит обе двери, и оба объявления начинаются одинаково
  # («... -- дверь »). Образец, суженный по имени РУЧКИ, дал бы двойку в обоих
  # полях, а вердикт сравнивает каждое с единицей -- то есть объявил бы
  # неотработавшими двери, которые отработали обе.
  local out rc line summary
  summary="$S/log/sweep-summary.txt"
  out=$(STUB_TWEAK=blindtwboth run_sweep "$K" "$C/corpus" "$C/versions.txt" 900); rc=$?
  line=$(grep -a 'twoff=' "$summary" 2>/dev/null | head -1)
  LAST_EVID="РАСКЛАД(rc=$rc) :: $line"
  if [[ "$line" != *"twlevel=1 twoff=1"* ]]; then
    bad "124 слепая ручка: в сводке не «twlevel=1 twoff=1»; было: $line"; return
  fi
  if (( rc != 0 )) || [[ "$out" != *"SWEEP DONE"* ]]; then
    LAST_EVID="rc=$rc :: $out"
    bad "124 слепая ручка: объявленное гашение обеих дверей объявлено красным (код $rc)"; return
  fi
  ok "124 слепая ручка: каждая дверь засчитана своим полем"
}

scenario_125() {   # ответ «объявления нет, выключенных нет» засчитан
  # Третий терминальный ответ двери: дома без файла объявления и с пустым
  # измеренным множеством сходятся обеими сторонами. Так отвечает клон-пустышка
  # дома, который свип создаёт сам, когда живого дома на машине нет, -- и не
  # засчитать этот ответ значило бы красить законный прогон.
  local out rc line summary
  summary="$S/log/sweep-summary.txt"
  out=$(STUB_TWEAK=emptyoff run_sweep "$K" "$C/corpus" "$C/versions.txt" 900); rc=$?
  line=$(grep -a 'twoff=' "$summary" 2>/dev/null | head -1)
  LAST_EVID="РАСКЛАД(rc=$rc) :: $line"
  if [[ "$line" != *"twoff=1"* ]]; then
    bad "125 пустое объявление: в сводке не «twoff=1»; было: $line"; return
  fi
  if (( rc != 0 )) || [[ "$out" != *"SWEEP DONE"* ]]; then
    LAST_EVID="rc=$rc :: $out"
    bad "125 пустое объявление: зелёный прогон не состоялся (код $rc)"; return
  fi
  ok "125 ответ «объявления нет, выключенных нет» засчитан"
}

scenario_126() { expect_red "126 дверь выключенных правок tweakcc не отработала -- КРАСНАЯ" notwoff "дверь выключенных правок tweakcc не отработала"; }

scenario_127() {   # снимок кита без дома разбора -- отказ ДО первой сборки
  # Разбор вывода форка живёт в ОДНОМ подключаемом файле, и свип берёт его из
  # снимка, как берёт оттуда перечисления секций. Снимок без этого файла оставил
  # бы свипу неопределённую функцию: под `set -u` расклад слоёв стал бы «БИТО»
  # в каждой строке сводки, а вердикт молчал бы о причине. Отказ обязан прийти
  # ДО первой сборки и назвать файл.
  local lone out rc
  lone="$C/nolayer-kit"
  rm -rf "$lone"; cp -R "$K" "$lone"
  rm -f "$lone/tools/tw-layer.sh"
  out=$(run_sweep "$lone" "$C/corpus" "$C/versions.txt" 900); rc=$?
  LAST_EVID="rc=$rc :: $out"
  if (( rc == 0 )); then
    bad "127 снимок без дома разбора: прогон не отказал"; return
  fi
  if [[ "$out" != *"нет tools/tw-layer.sh"* ]]; then
    bad "127 снимок без дома разбора: причина не названа: $(printf '%s' "$out" | head -3 | tr '\n' ' ')"
    return
  fi
  if [[ "$out" == *"SWEEP 900"* ]]; then
    LAST_EVID="ОТКАЗ_ПОСЛЕ_СБОРКИ :: $out"
    bad "127 снимок без дома разбора: отказ пришёл ПОСЛЕ сборки версии"; return
  fi
  ok "127 снимок без дома разбора -- отказ до первой сборки"
}

scenario_128() {   # ноль якорей в логе -- свип обязан покраснеть СВОИМ текстом
  # У носителя разбора два потребителя: конвейер и свип. Дверь единственности
  # якоря досталась только конвейеру, и она меряет ЕГО захват вывода tweakcc, а
  # свип читает весь лог сборки -- разные входы. Лог без якоря оставляет
  # читателям слоя ПУСТУЮ область: расклад честно нулевой при исправном
  # разборе, и без своей двери свип объявил бы причиной «не применил ни одного
  # патча» -- диагноз мимо поломки.
  local out rc
  out=$(STUB_TWEAK=noanchor run_sweep "$K" "$C/corpus" "$C/versions.txt" 900); rc=$?
  LAST_EVID="rc=$rc :: $out"
  if (( rc == 0 )); then
    LAST_EVID="ЛОГ_БЕЗ_ЯКОРЯ_ПРИНЯТ :: $out"
    bad "128 лог без якоря блока результатов принят зелёным"; return
  fi
  if [[ "$out" != *"КРАСНАЯ: "*"якоря блока результатов tweakcc нет в логе"* ]]; then
    LAST_EVID="БЕЗ_ДВЕРИ_ЯКОРЯ :: $out"
    bad "128 лог без якоря: в вердикте нет причины про якорь; было: $(printf '%s' "$out" | grep -a 'SWEEP 900' | head -1)"
    return
  fi
  # Текст обязан называть НАЙДЕННОЕ ЧИСЛО: без него ноль и два сливаются в одну
  # жалобу, и читающий вердикт не знает, чинить пустую область или разъезд
  # двух прогонов.
  if [[ "$out" != *"(найдено 0)"* ]]; then
    LAST_EVID="ЧИСЛО_НЕ_НАЗВАНО :: $out"
    bad "128 лог без якоря: число найденных якорей не названо; было: $(printf '%s' "$out" | grep -a 'SWEEP 900' | head -1)"
    return
  fi
  ok "128 ноль якорей -- КРАСНАЯ со своим текстом и числом"
}

scenario_129() {   # два якоря -- ДРУГАЯ поломка и другой текст
  # При двух якорях расклад слоёв считается исправно и сходится: зелёным
  # остаётся всё, кроме самой двери. Поэтому односторонняя дверь (только ноль)
  # пропустила бы сложение двух прогонов tweakcc в один счёт МОЛЧА.
  local out rc
  out=$(STUB_TWEAK=twoanchors run_sweep "$K" "$C/corpus" "$C/versions.txt" 900); rc=$?
  LAST_EVID="rc=$rc :: $out"
  if (( rc == 0 )); then
    LAST_EVID="ДВА_ЯКОРЯ_ПРИНЯТЫ :: $out"
    bad "129 лог с двумя якорями принят зелёным"; return
  fi
  if [[ "$out" != *"КРАСНАЯ: "*"якорей блока результатов tweakcc в логе 2"* ]]; then
    LAST_EVID="ТЕКСТЫ_НЕ_РАЗЛИЧЕНЫ :: $out"
    bad "129 два якоря: нет своего текста с числом 2; было: $(printf '%s' "$out" | grep -a 'SWEEP 900' | head -1)"
    return
  fi
  ok "129 два якоря -- КРАСНАЯ отдельным текстом с числом"
}

scenario_130() {   # сумма крестиков ПРОИЗВОДНА от расклада, а не своим образцом
  # Форк печатает строки правок ДВАЖДЫ под одинаковыми заголовками секций:
  # предапплайный список плана и блок результатов. Поле суммы читало их сырым
  # `grep '^    ✓ '` по всему логу -- мимо носителя разбора и мимо области
  # блока результатов. Режим planticks кладёт галочку в область ПЛАНА: сырой
  # счёт даёт 5 при раскладе 3+1, производная сумма -- 4.
  local out rc line summary
  summary="$S/log/sweep-summary.txt"
  out=$(STUB_TWEAK=planticks run_sweep "$K" "$C/corpus" "$C/versions.txt" 900); rc=$?
  LAST_EVID="rc=$rc :: $out"
  if (( rc != 0 )); then
    bad "130 галочка в списке плана: зелёный прогон не состоялся (код $rc)"; return
  fi
  line=$(grep -a 'twcode=' "$summary" 2>/dev/null | head -1)
  LAST_EVID="СУММА :: $line"
  if [[ "$line" != *"tweakcc=4 twcode=3 twprompt=1"* ]]; then
    bad "130 сумма не производна от расклада; было: $line"
    return
  fi
  ok "130 галочка в списке плана в сумму не попала"
}

# Дверь ИНЕРТНЫХ правок tweakcc (⊘ и ≡): до волны 39c у неё не было свидетеля
# НИГДЕ. На успешной двусторонней сходимости она молчала, то есть снятие обеих
# сверок не меняло ни лога прогона, ни строки вердикта ни на байт -- ровно тот
# класс «дверь, сходящаяся молча», который волна закрывает у соседей. Сценарии
# ниже считают три её законных ответа и требуют красноты, когда ответа нет.
scenario_131() {   # ответ «сошлись с объявлением» засчитан полем twinert
  local out rc line summary
  summary="$S/log/sweep-summary.txt"
  out=$(run_sweep "$K" "$C/corpus" "$C/versions.txt" 900); rc=$?
  line=$(grep -a 'twinert=' "$summary" 2>/dev/null | head -1)
  LAST_EVID="РАСКЛАД(rc=$rc) :: $line"
  if [[ "$line" != *"twinert=1"* ]]; then
    bad "131 дверь инертных правок: в сводке не «twinert=1»; было: $line"; return
  fi
  if (( rc != 0 )) || [[ "$out" != *"SWEEP DONE"* ]]; then
    LAST_EVID="rc=$rc :: $out"
    bad "131 дверь инертных правок: зелёный прогон не состоялся (код $rc)"; return
  fi
  ok "131 ответ «сошлись с объявлением» двери инертных правок засчитан"
}

scenario_132() {   # ответ «не объявлено и не измерено» засчитан
  # Второй терминальный ответ: строк под версию нет и инертных не измерено --
  # обе стороны согласны. Не засчитать его значило бы красить версию, на
  # которой ничего не сломано.
  local out rc line summary
  summary="$S/log/sweep-summary.txt"
  out=$(STUB_TWEAK=emptyinert run_sweep "$K" "$C/corpus" "$C/versions.txt" 900); rc=$?
  line=$(grep -a 'twinert=' "$summary" 2>/dev/null | head -1)
  LAST_EVID="РАСКЛАД(rc=$rc) :: $line"
  if [[ "$line" != *"twinert=1"* ]]; then
    bad "132 пустая сходимость инертных: в сводке не «twinert=1»; было: $line"; return
  fi
  if (( rc != 0 )) || [[ "$out" != *"SWEEP DONE"* ]]; then
    LAST_EVID="rc=$rc :: $out"
    bad "132 пустая сходимость инертных: зелёный прогон не состоялся (код $rc)"; return
  fi
  ok "132 ответ «не объявлено и не измерено» засчитан"
}

scenario_133() {   # слепая ручка: ТРИ двери, три поля, ни одного двойного счёта
  # Одна ручка гасит три двери, и все три объявления начинаются одинаково
  # («... -- дверь »). Образец, суженный по имени РУЧКИ, дал бы тройку в каждом
  # поле, а вердикт сравнивает каждое с единицей -- то есть объявил бы
  # неотработавшей каждую дверь, которая на этом прогоне отработала.
  local out rc line summary
  summary="$S/log/sweep-summary.txt"
  out=$(STUB_TWEAK=blindtwboth run_sweep "$K" "$C/corpus" "$C/versions.txt" 900); rc=$?
  line=$(grep -a 'twinert=' "$summary" 2>/dev/null | head -1)
  LAST_EVID="РАСКЛАД(rc=$rc) :: $line"
  if [[ "$line" != *"twlevel=1 twoff=1 twinert=1"* ]]; then
    bad "133 слепая ручка: в сводке не «twlevel=1 twoff=1 twinert=1»; было: $line"; return
  fi
  if (( rc != 0 )) || [[ "$out" != *"SWEEP DONE"* ]]; then
    LAST_EVID="rc=$rc :: $out"
    bad "133 слепая ручка: объявленное гашение трёх дверей объявлено красным (код $rc)"; return
  fi
  ok "133 слепая ручка: каждая из трёх дверей засчитана своим полем"
}

scenario_134() { expect_red "134 дверь инертных правок tweakcc не отработала -- КРАСНАЯ" notwinert "дверь инертных правок tweakcc не отработала"; }

# Волна 39d. Свидетелей в вердикте не было у трёх величин сразу: собственный
# счёт якорей читался только в ветке «почему» (на здоровом прогоне его удаление
# не меняло вердикт ни на байт), а у часового формы и у двери непрошедших
# накладок поля не было вовсе. Плюс у свипа не было СВОЕГО часового формы, хотя
# он читает не тот вход, что конвейер.
#
# Поле снимается ОДНОЙ строкой сборки группы -- потому и группа отдельная: в
# общей строке формата снятие поля сдвинуло бы разбор соседних, и мутация
# доказывала бы сдвиг вместо пропажи.
scenario_135() {   # собственный счёт якорей назван в сводке
  local out rc line summary
  summary="$S/log/sweep-summary.txt"
  out=$(run_sweep "$K" "$C/corpus" "$C/versions.txt" 900); rc=$?
  line=$(grep -a '^900 ' "$summary" 2>/dev/null | head -1)
  LAST_EVID="РАСКЛАД(rc=$rc) :: $line"
  if [[ "$line" != *"twanchor="* ]]; then
    LAST_EVID="ПОЛЕ_TWANCHOR_НЕТ :: $line"
    bad "135 счёт якорей: в сводке нет поля twanchor; было: $line"; return
  fi
  if [[ "$line" != *"twanchor=1"* ]]; then
    bad "135 счёт якорей: в сводке не «twanchor=1»; было: $line"; return
  fi
  if (( rc != 0 )) || [[ "$out" != *"SWEEP DONE"* ]]; then
    LAST_EVID="rc=$rc :: $out"
    bad "135 счёт якорей: зелёный прогон не состоялся (код $rc)"; return
  fi
  ok "135 собственный счёт якорей засчитан полем twanchor"
}

scenario_136() {   # ответ часового формы засчитан полем twform
  local out rc line summary
  summary="$S/log/sweep-summary.txt"
  out=$(run_sweep "$K" "$C/corpus" "$C/versions.txt" 900); rc=$?
  line=$(grep -a '^900 ' "$summary" 2>/dev/null | head -1)
  LAST_EVID="РАСКЛАД(rc=$rc) :: $line"
  if [[ "$line" != *"twform="* ]]; then
    LAST_EVID="ПОЛЕ_TWFORM_НЕТ :: $line"
    bad "136 часовой формы: в сводке нет поля twform; было: $line"; return
  fi
  if [[ "$line" != *"twform=1"* ]]; then
    bad "136 часовой формы: в сводке не «twform=1»; было: $line"; return
  fi
  if (( rc != 0 )) || [[ "$out" != *"SWEEP DONE"* ]]; then
    LAST_EVID="rc=$rc :: $out"
    bad "136 часовой формы: зелёный прогон не состоялся (код $rc)"; return
  fi
  ok "136 безусловный ответ часового формы засчитан полем twform"
}

scenario_137() {   # ответ двери непрошедших накладок засчитан полем twpfail
  local out rc line summary
  summary="$S/log/sweep-summary.txt"
  out=$(run_sweep "$K" "$C/corpus" "$C/versions.txt" 900); rc=$?
  line=$(grep -a '^900 ' "$summary" 2>/dev/null | head -1)
  LAST_EVID="РАСКЛАД(rc=$rc) :: $line"
  if [[ "$line" != *"twpfail="* ]]; then
    LAST_EVID="ПОЛЕ_TWPFAIL_НЕТ :: $line"
    bad "137 дверь непрошедших накладок: в сводке нет поля twpfail; было: $line"; return
  fi
  if [[ "$line" != *"twpfail=1"* ]]; then
    bad "137 дверь непрошедших накладок: в сводке не «twpfail=1»; было: $line"; return
  fi
  if (( rc != 0 )) || [[ "$out" != *"SWEEP DONE"* ]]; then
    LAST_EVID="rc=$rc :: $out"
    bad "137 дверь непрошедших накладок: зелёный прогон не состоялся (код $rc)"; return
  fi
  ok "137 безусловный ответ двери непрошедших накладок засчитан полем twpfail"
}

scenario_138() {   # слепая ручка: каждой двери -- своё поле, ни одного двойного счёта
  # Ручка гасит ВСЕ двери слоя разом; в этом прогоне СТЕНД печатает пять
  # объявлений, и все они начинаются одинаково
  # («CLAUDE_PATCH_ALLOW_TWEAKCC_FAILURES=1 -- »). Образец, суженный по имени
  # РУЧКИ, дал бы пятёрку в каждом поле, а вердикт сравнивает каждое с единицей.
  local out rc line summary
  summary="$S/log/sweep-summary.txt"
  out=$(STUB_TWEAK=blindtwboth run_sweep "$K" "$C/corpus" "$C/versions.txt" 900); rc=$?
  line=$(grep -a '^900 ' "$summary" 2>/dev/null | head -1)
  LAST_EVID="РАСКЛАД(rc=$rc) :: $line"
  if [[ "$line" != *"twlevel=1 twoff=1 twinert=1 twanchor=1 twform=1 twpfail=1"* ]]; then
    bad "138 слепая ручка: в сводке не «twlevel=1 twoff=1 twinert=1 twanchor=1 twform=1 twpfail=1»; было: $line"; return
  fi
  if (( rc != 0 )) || [[ "$out" != *"SWEEP DONE"* ]]; then
    LAST_EVID="rc=$rc :: $out"
    bad "138 слепая ручка: объявленное гашение пяти дверей объявлено красным (код $rc)"; return
  fi
  ok "138 слепая ручка: каждая из пяти дверей засчитана своим полем"
}

scenario_139() {   # СВОЙ часовой формы у свипа: строка правки ПОСЛЕ блока
  # Конвейер спрашивает часового о своём захвате, свип читает весь лог сборки:
  # область от якоря до конца включает то, что печатается после блока. Свидетель
  # чужой двери (twform) этот вход не покрывает по построению.
  local out rc line summary
  summary="$S/log/sweep-summary.txt"
  out=$(STUB_TWEAK=postform run_sweep "$K" "$C/corpus" "$C/versions.txt" 900); rc=$?
  LAST_EVID="rc=$rc :: $out"
  if (( rc == 0 )); then
    LAST_EVID="ЛОГ_С_НАРУШИТЕЛЕМ_ПРИНЯТ :: $out"
    bad "139 строка правки под незнакомой секцией после блока принята зелёной"; return
  fi
  if [[ "$out" != *"КРАСНАЯ: "*"часовой формы свипа"* ]]; then
    LAST_EVID="БЕЗ_ЧАСОВОГО_СВИПА :: $out"
    bad "139 нарушитель формы: в вердикте нет причины часового свипа; было: $(printf '%s' "$out" | grep -a 'SWEEP 900' | head -1)"
    return
  fi
  line=$(grep -a '^900 ' "$summary" 2>/dev/null | head -1)
  if [[ "$line" != *"twunsect=1"* ]]; then
    LAST_EVID="ПОЛЕ_TWUNSECT_НЕТ :: $line"
    bad "139 нарушитель формы: в сводке не «twunsect=1»; было: $line"; return
  fi
  ok "139 нарушитель формы после блока -- КРАСНАЯ своим часовым, число в сводке"
}

scenario_140() { expect_red "140 часовой формы вывода tweakcc не отработал -- КРАСНАЯ" notwform "часовой формы вывода tweakcc не отработал"; }
scenario_141() { expect_red "141 дверь непрошедших накладок tweakcc не отработала -- КРАСНАЯ" notwpfail "дверь непрошедших накладок tweakcc не отработала"; }

# Волна 39d, довесок: дом, созданный САМИМ свипом, и один набор дверей на обе
# сводки.
scenario_142() {   # ЧЕТВЁРТЫЙ терминальный ответ двери выключенных правок
  # Живого дома tweakcc на машине может не быть вовсе -- тогда свип создаёт
  # пустой дом сам. Объявления выключенных правок у такого дома нет, а дефолты
  # форка гасят три десятка правок кода, и дверь отвечает «дом создан прогоном,
  # а не оператором». Не засчитать этот ответ -- значит красить свежую машину
  # вердиктом «дверь не отработала» при исправной двери.
  local out rc line summary
  summary="$S/log/sweep-summary.txt"
  out=$(STUB_TWEAK=originoff run_sweep "$K" "$C/corpus" "$C/versions.txt" 900); rc=$?
  line=$(grep -a 'twoff=' "$summary" 2>/dev/null | head -1)
  LAST_EVID="РАСКЛАД(rc=$rc) :: $line"
  if [[ "$line" != *"twoff=1"* ]]; then
    bad "142 дом создан прогоном: в сводке не «twoff=1»; было: $line"; return
  fi
  if (( rc != 0 )) || [[ "$out" != *"SWEEP DONE"* ]]; then
    LAST_EVID="rc=$rc :: $out"
    bad "142 дом создан прогоном: зелёный прогон не состоялся (код $rc)"; return
  fi
  ok "142 ответ «дом создан прогоном, а не оператором» засчитан полем twoff"
}

scenario_143() {   # третья ветка выбора дома: свип КЛАДЁТ отметку происхождения
  # Ветка «живого дома нет, создаём пустой» до этой волны оставляла дом без
  # единого свидетельства о происхождении, и конвейер требовал от него
  # объявления, которого никто не делал. Имя отметки берётся ИЗ КОНВЕЙЕРА --
  # он её единственный читатель; вписанное сюда третьей копией, оно скрыло бы
  # расхождение писателя с читателем ровно на той машине, ради которой отметка
  # и заведена.
  local out rc name origin home
  name=$(LC_ALL=C sed -n "s/^TWEAKCC_HOME_ORIGIN_NAME='\(.*\)'\$/\1/p" "$K/claude-patch-all.real")
  if [[ -z "$name" ]]; then
    LAST_EVID="ИМЯ_ОТМЕТКИ_НЕ_ПРОЧИТАНО :: $K/claude-patch-all.real"
    bad "143 отметка происхождения: имя не прочитано из конвейера"; return
  fi
  out=$(BENCH_TW_HOME="$C/no-such-tweakcc-home" run_sweep "$K" "$C/corpus" "$C/versions.txt" 900); rc=$?
  home="$S/tweakcc-home"
  LAST_EVID="rc=$rc :: $out"
  if (( rc != 0 )); then
    bad "143 отметка происхождения: прогон отказал ($rc)"; return
  fi
  if [[ "$out" != *"живого дома нет, создан пустой"* ]]; then
    LAST_EVID="НЕ_ТА_ВЕТКА :: $out"
    bad "143 отметка происхождения: свип пошёл не третьей веткой выбора дома"; return
  fi
  if [[ ! -f "$home/$name" ]]; then
    LAST_EVID="ОТМЕТКИ_НЕТ :: $(ls -a "$home" 2>&1 | tr '\n' '|')"
    bad "143 отметка происхождения: файла «${name}» в созданном доме нет"; return
  fi
  origin=$(head -1 "$home/$name")
  if [[ "$origin" != "sweep-created "* ]]; then
    LAST_EVID="ОТМЕТКА_БЕЗ_ФОРМЫ :: $origin"
    bad "143 отметка происхождения: первая строка не называет происхождение: $origin"; return
  fi
  if [[ "$out" != *"отметка происхождения"* ]]; then
    LAST_EVID="ОТМЕТКА_НЕ_ОБЪЯВЛЕНА :: $out"
    bad "143 отметка происхождения: запись отметки не объявлена в потоке"; return
  fi
  ok "143 свип кладёт отметку происхождения в дом, который создал сам"
}

scenario_144() {   # обе сводки называют ОДИН набор дверей
  # Человек читал три двери, машина несла семь полей. Две редакции одного
  # набора расходятся на первой же новой двери -- и уже расходились. Группа
  # вырезается из машинной строки СОСЕДЯМИ ПО ФОРМАТУ, а не перечнем имён:
  # перечень здесь стал бы третьим домом набора.
  local out rc human machine group summary
  summary="$S/log/sweep-summary.txt"
  out=$(run_sweep "$K" "$C/corpus" "$C/versions.txt" 900); rc=$?
  LAST_EVID="rc=$rc :: $out"
  if (( rc != 0 )); then
    bad "144 две сводки: зелёный прогон не состоялся (код $rc)"; return
  fi
  machine=$(grep -a '^900 ' "$summary" 2>/dev/null | head -1)
  human=$(printf '%s\n' "$out" | grep -a '^SWEEP 900: ' | head -1)
  group=$(printf '%s\n' "$machine" | LC_ALL=C sed -n 's/.* twmiss=[0-9]* \(.*\) ours=.*/\1/p')
  if [[ -z "$group" || "$group" != *"="* ]]; then
    LAST_EVID="ГРУППА_НЕ_ВЫРЕЗАНА :: $machine"
    bad "144 две сводки: группа дверей не вырезана из машинной строки"; return
  fi
  if [[ "$human" != *"$group"* ]]; then
    LAST_EVID="СТРОКА_БЕЗ_ГРУППЫ :: человек «${human}» :: группа «${group}»"
    bad "144 две сводки: человеческая строка называет не те двери, что машинная"; return
  fi
  ok "144 обе сводки называют один и тот же набор дверей слоя tweakcc"
}

scenario_145() {   # дом метаданных: одна строка цифр или ЧЕСТНЫЙ ОТКАЗ
  # Носитель подключается в ПОДОБОЛОЧКЕ: его функции не должны протечь в стенд,
  # а PATH с подставным stat не должен пережить сценарий.
  local home live m i junk absent shim
  home="$K/tools/fs-meta.sh"
  if [[ ! -f "$home" ]]; then
    LAST_EVID="ДОМА_НЕТ"
    bad "145 дом метаданных: в копии кита нет tools/fs-meta.sh"; return
  fi
  live="$C/s145.file"; : > "$live"
  # `9>&-` на КАЖДОМ вызове: стенд держит замок на дескрипторе 9, и внук,
  # унаследовавший его, продолжал бы держать замок после конца прогона. Это
  # правило кита, и его сторожит гейт наследования замка в конвейере.
  m=$(bash -c 'source "$1"; fs_mtime "$2"' _ "$home" "$live" 2>/dev/null 9>&- || echo НЕТ)
  i=$(bash -c 'source "$1"; fs_inode "$2"' _ "$home" "$live" 2>/dev/null 9>&- || echo НЕТ)
  # Подставной stat печатает МНОГОСТРОЧНЫЙ ответ с цифрой в конце и выходит
  # УСПЕШНО. Это модель отравления в чистом виде: у настоящей отравляющей формы
  # мусор попадает в stdout ДО ненулевого кода, поэтому вердикт обязан выносить
  # ФОРМА ответа, а не код возврата. Подстановка идёт через PATH подоболочки --
  # ни один настоящий stat машины при этом не трогается.
  shim="$C/s145bin"; rm -rf "$shim"; mkdir -p "$shim"
  cat > "$shim/stat" <<'S145STAT'
#!/bin/sh
printf '  File: "kitd"\n'
printf 'Block size: 4096       Fundamental block size: 4096\n'
printf '1788824969\n'
exit 0
S145STAT
  chmod +x "$shim/stat"
  junk=$(PATH="$shim:$PATH" bash -c 'source "$1"; fs_mtime "$2"' _ "$home" "$live" 2>/dev/null 9>&- || echo ОТКАЗ)
  absent=$(bash -c 'source "$1"; fs_mtime "$2"' _ "$home" "$C/s145.nope" 2>/dev/null 9>&- || echo ОТКАЗ)
  rm -rf "$shim" "$live"
  LAST_EVID="метка=$m инод=$i мусор=[$(printf '%s' "$junk" | tr '\n' '|')] отсутствие=[$absent]"
  case "$m" in
    ''|*[!0-9]*)
      LAST_EVID="ЖИВОЙ_ФАЙЛ_БЕЗ_МЕТКИ :: $LAST_EVID"
      bad "145 дом метаданных: живой файл не дал метки времени"; return ;;
  esac
  case "$i" in
    ''|*[!0-9]*)
      LAST_EVID="ЖИВОЙ_ФАЙЛ_БЕЗ_ИНОДА :: $LAST_EVID"
      bad "145 дом метаданных: живой файл не дал инода"; return ;;
  esac
  if [[ "$junk" != "ОТКАЗ" ]]; then
    LAST_EVID="МУСОР_ПРИНЯТ_ЗА_ЧИСЛО :: $LAST_EVID"
    bad "145 дом метаданных: многострочный ответ отдан вызывающему как число"; return
  fi
  if [[ "$absent" != "ОТКАЗ" ]]; then
    LAST_EVID="ОТСУТСТВИЕ_ПРИНЯТО_ЗА_ЧИСЛО :: $LAST_EVID"
    bad "145 дом метаданных: пропавший файл не дал честного отказа"; return
  fi
  ok "145 дом метаданных отвечает цифрами либо отказывает, но не отравляет"
}

scenario_146() {   # отравляющая форма чтения stat не вернулась ни в один дом
  # Ценз ФОРМЫ, а не поведения: на маке отравляющая форма ПРАВИЛЬНА (BSD stat
  # берёт формат следующим словом), поэтому поведенческий сценарий не может
  # покраснеть там ни при каком возврате этой формы. Ценз краснеет одинаково на
  # обеих платформах -- это единственный симметричный зуб на «форма вернулась».
  #
  # Ценз считает СТРОКИ дома и не разбирает код против прозы: поэтому домам
  # ЗАПРЕЩЕНО писать форму дословно даже в комментарии, а единственное место,
  # где её позволено назвать буквально, -- сам носитель. Правило объявлено в
  # комментариях обоих домов рядом с подключением.
  local __h n carrier_hits plant plant_hits offenders=""
  for __h in claude-patch-all.real tools/sweep.sh tools/build-path-probe.real.sh; do
    if [[ ! -f "$K/$__h" ]]; then
      LAST_EVID="ДОМА_НЕТ :: $__h"
      bad "146 ценз чтения метаданных: в копии кита нет $__h -- ценз без знаменателя"; return
    fi
    n=$(LC_ALL=C grep -a -c -E 'stat +-[fc]' "$K/$__h" 2>/dev/null || true)
    (( n > 0 )) && offenders="$offenders $__h=$n"
  done
  # ДВА положительных контроля: пустой результат без них недействителен --
  # «нарушителей нет» неотличимо от «ценз ничего не смотрел». Первый -- сам
  # носитель (игла обязана находиться там, где форма законна), второй --
  # подсадка формы в копию настоящего дома (игла обязана находиться и в файле
  # ТОЙ ЖЕ природы, что и цензурируемые).
  carrier_hits=$(LC_ALL=C grep -a -c -E 'stat +-[fc]' "$K/tools/fs-meta.sh" 2>/dev/null || true)
  plant="$C/s146.plant"
  cp "$K/tools/sweep.sh" "$plant"
  printf 'm=$(stat -f %%m "$1" 2>/dev/null || stat -c %%Y "$1" 2>/dev/null)\n' >> "$plant"
  plant_hits=$(LC_ALL=C grep -a -c -E 'stat +-[fc]' "$plant" 2>/dev/null || true)
  rm -f "$plant"
  LAST_EVID="домов=3 нарушители=[${offenders# }] носитель=$carrier_hits подсадка=$plant_hits"
  if (( carrier_hits < 1 )); then
    LAST_EVID="ЦЕНЗ_НЕ_ВИДИТ_ИГЛЫ носитель :: $LAST_EVID"
    bad "146 ценз чтения метаданных: игла не найдена даже в носителе"; return
  fi
  if (( plant_hits < 1 )); then
    LAST_EVID="ЦЕНЗ_НЕ_ВИДИТ_ИГЛЫ подсадка :: $LAST_EVID"
    bad "146 ценз чтения метаданных: подсаженная форма не найдена"; return
  fi
  if [[ -n "$offenders" ]]; then
    LAST_EVID="ОТРАВА_В_ДОМЕ:${offenders# } :: $LAST_EVID"
    bad "146 ценз чтения метаданных: дом читает stat мимо носителя:${offenders}"; return
  fi
  ok "146 ни один дом не читает метаданные мимо общего носителя"
}

scenario_147() {   # конвейер удаляет старые сборки распаковщика по МЕТКЕ ВРЕМЕНИ
  # Стадия «Cleaning old unpacker builds» -- ПУТЬ УДАЛЕНИЯ, и её ключ сортировки
  # брался своей копией чтения stat: на Linux в ключ попадала четырёхстрочная
  # каша плюс число, то есть неверно упорядочивалось то, ЧТО УДАЛЯЕТСЯ. Своего
  # сценария у стадии не было вовсе.
  #
  # Функция вырезается ИЗ КОНВЕЙЕРА по якорю, а не переписывается здесь: вторая
  # копия правила стала бы третьим его домом и разошлась бы с обоими.
  local frag drv cache out rc anchors pin newest mid oldest
  anchors=$(LC_ALL=C grep -a -c '^prune_tweakcc_cache() {$' "$K/claude-patch-all.real" 2>/dev/null || true)
  frag="$C/s147.prune.sh"
  sed -n '/^prune_tweakcc_cache() {$/,/^}$/p' "$K/claude-patch-all.real" > "$frag"
  if [[ "$anchors" != "1" || ! -s "$frag" ]]; then
    LAST_EVID="ЯКОРЬ_ПОТЕРЯН якорей=$anchors"
    bad "147 порядок удаления: функция не вырезана из конвейера -- прибор не мерит"; return
  fi
  # Имена -- сорок шестнадцатеричных знаков: только такие конвейер и трогает.
  # Порядок ИМЁН намеренно ОБРАТЕН порядку меток, иначе сортировка по имени
  # дала бы тот же ответ, что и по метке, и зуб растворился бы.
  pin='aaaa000000000000000000000000000000000000'
  newest='bbbb000000000000000000000000000000000000'
  mid='cccc000000000000000000000000000000000000'
  oldest='dddd000000000000000000000000000000000000'
  cache="$C/s147cache"; rm -rf "$cache"
  mkdir -p "$cache/$pin" "$cache/$newest" "$cache/$mid" "$cache/$oldest"
  python3 - "$cache/$newest" "$cache/$mid" "$cache/$oldest" <<'PY147'
import os, sys, time
now = time.time()
for path, back in zip(sys.argv[1:], (100, 200, 300)):
    os.utime(path, (now - back, now - back))
PY147
  drv="$C/s147.drv.sh"
  cat > "$drv" <<'DRV147'
# Оболочка та же, под какой функция живёт в конвейере: `set -euo pipefail`.
set -euo pipefail
source "$1"
source "$2"
CATALYST_TWEAKCC_CACHE="$3"
CATALYST_TWEAKCC_SHA="$4"
prune_tweakcc_cache "$5"
DRV147
  out=$(bash "$drv" "$K/tools/fs-meta.sh" "$frag" "$cache" "$pin" 1 2>&1 9>&-); rc=$?
  local left
  left=$(cd "$cache" && ls -d [0-9a-f]* 2>/dev/null | tr '\n' ' ')
  rm -rf "$cache" "$frag" "$drv"
  LAST_EVID="rc=$rc осталось=[$left] :: $out"
  if (( rc != 0 )); then
    bad "147 порядок удаления: прогон вырезанной функции отказал ($rc)"; return
  fi
  if [[ "$left" != *"$pin"* ]]; then
    LAST_EVID="УДАЛЁН_ПИН :: $LAST_EVID"
    bad "147 порядок удаления: снесён пин, которым прогон пользуется"; return
  fi
  if [[ "$left" != *"$newest"* ]]; then
    LAST_EVID="УДАЛЁН_СВЕЖИЙ :: $LAST_EVID"
    bad "147 порядок удаления: снесена самая свежая сборка вместо старых"; return
  fi
  if [[ "$left" == *"$mid"* || "$left" == *"$oldest"* ]]; then
    LAST_EVID="ПОРЯДОК_НЕ_ПО_МЕТКЕ :: $LAST_EVID"
    bad "147 порядок удаления: старые сборки остались -- ключ сортировки не метка"; return
  fi
  ok "147 удаляются самые старые сборки распаковщика, пин и свежая целы"
}

scenario_148() {   # самопроверка не засчитывает зуб БЕЗ КОНТРОЛЯ
  # Зуб на саму дисциплину контроля: мутация, чей сценарий красен И БЕЗ неё,
  # обязана уходить в «НЕ ИЗМЕРЕНО», а не в «покраснела своей причиной».
  #
  # Настоящая самопроверка гоняется здесь ВЫРЕЗАННОЙ по якорю и на заглушках:
  # вложенный полный `--self-check` -- это все 277 мутаций corpus-tools-bench
  # по два прогона каждая, то есть минуты внутри одного сценария, а измерить
  # надо ровно код
  # самопроверки, а не её нагрузку. Заглушки дают ДВА зуба с известным ответом:
  # один красен всегда (и тем же следом, что объявлен его причиной), второй --
  # нормальный.
  local frag drv out rc anchors
  anchors=$(LC_ALL=C grep -a -c '^self_check() {$' "$K/tools/corpus-tools-bench.real.sh" 2>/dev/null || true)
  frag="$C/s148.selfcheck.sh"
  sed -n '/^self_check() {$/,/^}$/p' "$K/tools/corpus-tools-bench.real.sh" > "$frag"
  if [[ "$anchors" != "1" || ! -s "$frag" ]]; then
    LAST_EVID="ЯКОРЬ_ПОТЕРЯН якорей=$anchors"
    bad "148 контроль самопроверки: self_check не вырезан -- прибор не мерит"; return
  fi
  drv="$C/s148.drv.sh"
  cat > "$drv" <<'DRV148'
set -u
ROOT="$1"
# Объявления заглушки записаны С ОТСТУПОМ намеренно: КАЖДЫЙ читатель этого
# файла ищет их якорем «присваивание В НАЧАЛЕ СТРОКИ», и объявление с нулевой
# колонки стало бы для него ТЕНЕВОЙ ЦЕЛЬЮ. Замерено на обоих читателях:
#   -- сценарий 43 берёт настоящую таблицу якорем `^MUT_CAUSE=(x` и укоротил
#      бы ЭТУ заглушку вместо таблицы стенда, объявив зубом правило, которого
#      не проверял;
#   -- гейт чисел берёт величину владельца якорем `^EXPECTED_MUTATIONS=(\d+)$`
#      и читал бы двойку заглушки как объявленный счёт мутаций стенда (его
#      собственный зуб D7 на этом и покраснел не по своей причине).
# Отступ оболочке безразличен, якорю -- нет.
  EXPECTED_MUTATIONS=2
  MUT_FILE=(x жертва.sh жертва.sh)
  MUT_SCENARIO=(x 900 901)
  MUT_CAUSE=(x СЛЕД_A СЛЕД_B)
FAILED=0
LAST_EVID=""
MUTATED=0
say() { printf '%s\n' "$*"; }
# Признак «мутация применена» сбрасывается ПРИ СБОРКЕ КИТА: самопроверка
# собирает кит и для контрольного прогона, и для измерительного, поэтому
# сброс здесь -- это и есть проверка того, что контроль идёт ПЕРВЫМ.
mk_kit() { mkdir -p "$1"; MUTATED=0; }
mk_corpus() { mkdir -p "$1"; }
use_corpus() { C="$1"; }
mutate() { MUTATED=1; return 0; }
# Зуб 1: сценарий красен ВСЕГДА, ровно тем следом, что объявлен причиной его
# мутации. Без контроля он получал бы зачёт ни за что.
scenario_900() { FAILED=$((FAILED+1)); LAST_EVID="СЛЕД_A"; }
# Зуб 2: зелен без мутации, красен под ней -- нормальный зуб.
scenario_901() {
  if (( MUTATED )); then FAILED=$((FAILED+1)); LAST_EVID="СЛЕД_B"; else LAST_EVID="ЗЕЛЁНО"; fi
}
source "$2"
__rc=0; self_check || __rc=$?
echo "RC=$__rc"
DRV148
  out=$(bash "$drv" "$C" "$frag" 2>&1 9>&-); rc=$?
  rm -f "$frag" "$drv"
  LAST_EVID="rc=$rc :: $(printf '%s' "$out" | tr '\n' '|')"
  if [[ "$out" != *"RC="* ]]; then
    LAST_EVID="ПРИБОР_НЕ_МЕРИТ :: $LAST_EVID"
    bad "148 контроль самопроверки: вырезанный self_check не доехал до вердикта"; return
  fi
  if [[ "$out" == *"ok     мутация 1 "* || "$out" != *"НЕ ИЗМЕРЕН зуб мутации 1"* ]]; then
    LAST_EVID="ЗАЧЁТ_БЕЗ_КОНТРОЛЯ :: $LAST_EVID"
    bad "148 контроль самопроверки: зуб сценария, красного в базе, засчитан покрасневшим"; return
  fi
  if [[ "$out" != *"НЕ_ИЗМЕРЕНО=1"* ]]; then
    LAST_EVID="ТРЁХ_ВЕЛИЧИН_НЕТ :: $LAST_EVID"
    bad "148 контроль самопроверки: итог не называет числа НЕ ИЗМЕРЕННЫХ зубов"; return
  fi
  if [[ "$out" != *"ok     мутация 2 "* ]]; then
    LAST_EVID="ЗДОРОВЫЙ_ЗУБ_ПОТЕРЯН :: $LAST_EVID"
    bad "148 контроль самопроверки: нормальный зуб перестал засчитываться"; return
  fi
  if [[ "$out" != *"RC=1"* ]]; then
    LAST_EVID="ВЕРДИКТ_НЕ_КРАСЕН :: $LAST_EVID"
    bad "148 контроль самопроверки: не измеренный зуб не сделал вердикт красным"; return
  fi
  ok "148 самопроверка требует зелёного контроля и называет НЕ ИЗМЕРЕННЫЕ зубы"
}

scenario_149() {   # детектор процессов не возвращает исключённый pid
  # Положительный контроль и исключение -- в одном сценарии: детектор, который
  # не находит ничего, и детектор, который возвращает всё, одинаково бесполезны,
  # и половина без своей пары молча вырождается.
  #
  # Держатель ждёт ВСТРОЕННЫМ read, а не ребёнком sleep: голый sleep не несёт
  # пути в argv и детектору невидим (тот же урок, что у заглушки конвейера).
  #
  # ТРЕТЬЯ половина -- ФОРМА исключения, прочитанная ИЗ КОПИИ КИТА. Обе
  # половины выше исполняются ЖИВЫМ файлом стенда, а мутации доступна только
  # копия (тот же предел, что у сценариев 85 и 86: живой код стенда мутации
  # недоступен). Без формы у механизма не было бы зуба вовсе -- измерено:
  # мутация, снявшая исключение в копии, прошла МОЛЧА, потому что сценарий
  # исполнял неизменённый живой файл.
  local dir holder seen excl form
  dir="$C/s149"; rm -rf "$dir"; mkdir -p "$dir"
  bash -c 'read -t 20 x; true' "$dir/holder" < /dev/zero > /dev/null 2>&1 9>&- &
  holder=$!
  # Появления держателя ЖДЁМ с бюджетом, а не фиксированной паузой. Между
  # fork и exec argv ребёнка -- ещё argv РОДИТЕЛЯ, и пути в нём нет: на
  # загруженной машине фиксированная пауза давала бы «детектор слеп» без
  # единого дефекта в детекторе. Бюджет тот же, что у соседних ожиданий.
  local n=0
  while (( n < 300 )); do
    seen=$(__ps_matching "$dir" 'read -t 20')
    [[ -n "$seen" ]] && break
    sleep 0.1; n=$(( n + 1 ))
  done
  excl=$(__ps_matching "$dir" 'read -t 20' "$holder")
  kill "$holder" 2>/dev/null; wait "$holder" 2>/dev/null
  rm -rf "$dir"
  # Считается ТОЛЬКО внутри __ps_matching: строка этого же сценария содержит
  # тот же литерал, и счёт по всему файлу зависел бы от правок сценария, а не
  # от предмета (тот же приём, что в сценарии 85).
  form=$(sed -n '/^__ps_matching() {$/,/^}$/p' "$K/tools/corpus-tools-bench.real.sh" \
         | grep -cF 'index(skip, " " $1 " ") { next }')
  LAST_EVID="держатель=$holder найден=[$(printf '%s' "$seen" | tr '\n' ' ')] с_исключением=[$(printf '%s' "$excl" | tr '\n' ' ')] форма=$form"
  if ! printf '%s\n' "$seen" | grep -qx "$holder"; then
    LAST_EVID="ДЕТЕКТОР_СЛЕП :: $LAST_EVID"
    bad "149 детектор процессов: держатель не найден -- положительного контроля нет"; return
  fi
  if printf '%s\n' "$excl" | grep -qx "$holder"; then
    LAST_EVID="ИСКЛЮЧЁННЫЙ_PID_ВЕРНУЛСЯ :: $LAST_EVID"
    bad "149 детектор процессов: названный исключённым pid вернулся в ответе"; return
  fi
  if [[ "$form" != "1" ]]; then
    LAST_EVID="ИСКЛЮЧЕНИЕ_PID_СНЯТО :: $LAST_EVID"
    bad "149 детектор процессов: в копии стенда нет вычёркивания названных pid"; return
  fi
  ok "149 детектор процессов видит соседа и не возвращает исключённый pid"
}

# --- волна 41: гейт интерфейса (#92) -----------------------------------------
# Стадия «запуск -> опрос -> вердикт» вырезается ИЗ КОНВЕЙЕРА по якорям и
# гоняется на поддельных $BIN и `script`: настоящий интерфейс здесь не нужен,
# нужен ВЕРДИКТ стадии на каждом её пути. Копия стадии в стенде стала бы вторым
# домом правила и разошлась бы с конвейером молча.
#
# До волны 41 стадия жила без имени и без зуба, и три её ветки были
# НЕДОСТИЖИМЫ: `wait $GATE_PID` под `set -euo pipefail` убивал оболочку ДО
# присвоения кода (прогон отдавал голый код ребёнка и молчал), а форма `script`
# была зашита BSD-синтаксисом и на util-linux не запускала вообще ничего.
gate_carve() {   # каталог фрагментов -> печатает число вырезанных кусков
  local dir="$1" n=0 name
  for name in __host_os_arch __gate_script_form gate_state __interface_gate; do
    # Голова функции опознаётся ПОДСТРОКОЙ С НАЧАЛА строки, а не регуляркой:
    # у голов есть хвостовой комментарий, и экранирование скобок в шаблоне было
    # бы вторым источником истины о форме объявления.
    awk -v h="${name}() {" 'index($0, h) == 1 {on=1} on {print} on && $0 == "}" {exit}' \
      "$K/claude-patch-all.real" > "$dir/$name.sh"
    [[ -s "$dir/$name.sh" ]] && n=$((n+1))
  done
  printf '%s\n' "$n"
}

# Подставной `script`: принимает РОВНО те формы, что названы в GATE_STUB_TAKE,
# а на чужой отвечает как настоящий -- ненулевым кодом с диагностикой. Так
# различитель меряется на ОБЕИХ сторонах с одной машины: замер настоящих
# бинарей (util-linux 2.40.2 и BSD) снят волной 41 и записан в её бриф.
gate_stub_script() {   # каталог
  mkdir -p "$1"
  cat > "$1/script" <<'STUB41'
#!/usr/bin/env bash
# util-linux: script -q -c КОМАНДА ФАЙЛ (команду разбирает sh)
# BSD:        script -q ФАЙЛ КОМАНДА    (команда -- хвост argv)
[[ -n "${GATE_STUB_LOG:-}" ]] && printf '%s\n' "$*" >> "$GATE_STUB_LOG"
# СВИДЕТЕЛЬ ВХОДА (волна 44, #100). Подставной -- bash-скрипт и tcgetattr не
# зовёт, поэтому СОКЕТ на входе сам по себе его не валит: настоящий отказ
# воспроизвёл бы только настоящий BSD-`script`. Значит зуб мерит МЕХАНИЗМ --
# чем закреплён вход проб, -- и для этого подставной сообщает КЛАСС своего
# stdin. Журнал ОТДЕЛЬНЫЙ: строку argv соседние сценарии читают по префиксу,
# и дописывание в неё сделало бы их скрытыми потребителями этого зуба.
if [[ -n "${GATE_STUB_STDIN_LOG:-}" ]]; then
  __sin=прочее
  [[ -S /dev/fd/0 ]] && __sin=сокет
  [[ -c /dev/fd/0 ]] && __sin=символьное
  printf '%s\t%s\n' "$__sin" "$*" >> "$GATE_STUB_STDIN_LOG"
fi
if [[ "${1:-}" == "-q" && "${2:-}" == "-c" && $# -eq 4 ]]; then
  case "${GATE_STUB_TAKE:-}" in
    ul|both) exec sh -c "$3" ;;
  esac
  echo "script: unrecognized option '--strict-mcp-config'" >&2
  exit 1
fi
if [[ "${1:-}" == "-q" && $# -ge 3 ]]; then
  case "${GATE_STUB_TAKE:-}" in
    bsd|both) shift 2; exec "$@" ;;
  esac
  echo "script: unexpected number of arguments" >&2
  exit 1
fi
echo "script: подставной не понял форму: $*" >&2
exit 1
STUB41
  chmod +x "$1/script"
}

# Поддельный интерфейс: ведёт себя ровно тем способом, что назван в
# GATE_FAKE_MODE. Приглашение печатается ТЕМ ЖЕ текстом, что пришло в argv --
# разбор захвата сверяет именно его, и выдуманная строка проверяла бы другое.
gate_fake_bin() {   # путь
  cat > "$1" <<'FAKE41'
#!/usr/bin/env bash
prompt="${2:-}"
case "${GATE_FAKE_MODE:-}" in
  a) exit 1 ;;
  b) printf '%s\n' "$prompt"; sleep 4; exit 1 ;;
  c) sleep 20 ;;
  d) printf '%s\n' "$prompt"; sleep 20 ;;
  e) printf '%s\n' "$prompt"; exit 0 ;;
  *) echo "поддельный интерфейс: неизвестный режим «${GATE_FAKE_MODE:-}»" >&2; exit 9 ;;
esac
FAKE41
  chmod +x "$1"
}

# Запускатель стадии повторяет ВЫЗОВ конвейера, а не его тело: те же три
# фрагмента, та же оболочка `set -euo pipefail`, та же связка «замер формы ->
# стадия». Иначе зуб доказывал бы стадию, вызванную не так, как её зовёт кит.
gate_drv_file() {   # путь
  # Драйвер НЕ считает форму `script` и не печатает её сам: с волны 40c замер
  # живёт ВНУТРИ стадии, и вторая копия правила в стенде разошлась бы с
  # конвейером молча -- ровно то, от чего предостерегает комментарий карвинга.
  # Сценарии читают СОБСТВЕННУЮ строку стадии.
  # GATE_TARGET задаёт драйвер: пару ЦЕЛИ стадия читает из окружения
  # вызывающего, и это единственный способ прогнать её ветки на поддельном
  # $BIN, который остаётся обычным скриптом.
  cat > "$1" <<'DRV41'
set -euo pipefail
source "$1"; source "$2"; source "$3"; source "$4"
BIN="$5"; GATE_HOME="$6"; GATE_BUDGET="$7"; GATE_TARGET="$8"
GATE_LOG="$GATE_HOME/capture.log"
GATE_PROMPT="tweakcc interface gate"
: > "$GATE_LOG"
# Голым именем -- как в конвейере: под `||` `set -e` не действует во всём теле
# стадии, и зуб мерил бы стадию под ДРУГОЙ оболочкой, чем её гоняет кит.
__interface_gate
DRV41
}

# Драйвер под СОКЕТОМ на дескрипторе 0 -- ровно тот вид входа, что приносят
# агентский, launchd- и cron-контексты. Отдельным ФАЙЛОМ, а не строкой в
# командной строке: строка уехала бы в argv и в журналы, которые соседние
# сценарии читают по префиксу.
gate_sock_py() {   # путь файла
  cat > "$1" <<'SOCKPY'
import socket, os, sys
a, b = socket.socketpair()
os.dup2(a.fileno(), 0)
os.execvp(sys.argv[1], sys.argv[1:])
SOCKPY
}

gate_prepare() {   # имя каталога сценария
  GATE_D="$C/$1"; rm -rf "$GATE_D"; mkdir -p "$GATE_D/frag" "$GATE_D/stub"
  GATE_CARVED=$(gate_carve "$GATE_D/frag")
  GATE_BIN="$GATE_D/fake-bin"; gate_fake_bin "$GATE_BIN"
  gate_stub_script "$GATE_D/stub"
  GATE_DRV="$GATE_D/drv.sh"; gate_drv_file "$GATE_DRV"
  GATE_STUB_LOG_F="$GATE_D/stub.log"; : > "$GATE_STUB_LOG_F"
  GATE_STUB_SIN_F="$GATE_D/stub-stdin.log"; : > "$GATE_STUB_SIN_F"
  GATE_SOCK_PY="$GATE_D/sockexec.py"; gate_sock_py "$GATE_SOCK_PY"
}

# Пара ХОЗЯИНА, посчитанная ТЕМ ЖЕ домом, что и в конвейере: сценарию нужна
# «своя» цель, а зашитая строка привязала бы зуб к машине, на которой он писан.
gate_host_pair() { ( source "$GATE_D/frag/__host_os_arch.sh"; __host_os_arch ); }

gate_call() {   # режим бина, что принимает подставной script, бюджет, [цель]
  GATE_H=$(mktemp -d "$GATE_D/home.XXXXXX")
  mkdir -p "$GATE_H/cfg" "$GATE_H/proj"
  local target="${4:-$(gate_host_pair)}"
  # Запускатель отделён от аргументов: под ручкой GATE_STDIN_SOCK драйвер
  # получает СОКЕТ на дескрипторе 0 (сценарий 171, #100). По умолчанию ручка
  # снята, и прочие сценарии идут прежним запуском -- иначе зуб одного
  # сценария молча менял бы условия замера у всех соседей.
  local -a __run=(bash "$GATE_DRV")
  if [[ "${GATE_STDIN_SOCK:-0}" == 1 ]]; then
    __run=(python3 "$GATE_SOCK_PY" bash "$GATE_DRV")
  fi
  GATE_OUT=$(PATH="$GATE_D/stub:$PATH" GATE_STUB_TAKE="$2" \
             GATE_STUB_LOG="$GATE_STUB_LOG_F" GATE_FAKE_MODE="$1" \
             GATE_STUB_STDIN_LOG="$GATE_STUB_SIN_F" \
             "${__run[@]}" \
               "$GATE_D/frag/__host_os_arch.sh" \
               "$GATE_D/frag/__gate_script_form.sh" \
               "$GATE_D/frag/gate_state.sh" \
               "$GATE_D/frag/__interface_gate.sh" \
               "$GATE_BIN" "$GATE_H" "$3" "$target" 2>&1 9>&-)
  GATE_RC=$?
}

# Строка ЗАПУСКА, а не строка пробы: обе идут в один журнал подставного, и
# отличает их путь запускателя.
gate_launch_line() { grep -F 'run.sh' "$GATE_STUB_LOG_F" | tail -1; }

gate_carved_or_bad() {   # номер сценария -- общий отказ прибора
  # ЧЕТЫРЕ, а не три: с волны 40c стадия сама берёт пару ХОЗЯИНА (__host_os_arch)
  # -- из окружения ей приходит только пара ЦЕЛИ.
  [[ "$GATE_CARVED" == "4" ]] && return 0
  LAST_EVID="ЯКОРЬ_ПОТЕРЯН вырезано=$GATE_CARVED из 4"
  bad "$1 гейт интерфейса: стадия не вырезана из конвейера -- прибор не мерит"
  return 1
}

scenario_150() {   # форма script ЗАМЕРЕНА: util-linux-подставной
  local launch
  gate_prepare s150
  gate_carved_or_bad 150 || return
  gate_call e ul 5
  launch=$(gate_launch_line)
  LAST_EVID="rc=$GATE_RC запуск=[$launch] дом=$([[ -d "$GATE_H" ]] && echo есть || echo снят) :: $(printf '%s' "$GATE_OUT" | tr '\n' '|')"
  if [[ "$GATE_OUT" != *"script form utillinux"* ]]; then
    LAST_EVID="ФОРМА_НЕ_UTILLINUX :: $LAST_EVID"
    bad "150 форма script: util-linux-подставной, а выбрана не его форма"; return
  fi
  if [[ "$launch" != "-q -c "* ]]; then
    LAST_EVID="ЗАПУСК_НЕ_ТОЙ_ФОРМЫ :: $LAST_EVID"
    bad "150 форма script: стадия позвала script НЕ в выбранной форме"; return
  fi
  if (( GATE_RC != 0 )) || [[ "$GATE_OUT" != *"came up in a throwaway home"* ]]; then
    LAST_EVID="ВЕРДИКТ_НЕ_УСПЕХ :: $LAST_EVID"
    bad "150 форма script: util-linux-форма не довела стадию до успеха"; return
  fi
  if [[ -d "$GATE_H" ]]; then
    LAST_EVID="ДОМ_НЕ_СНЯТ :: $LAST_EVID"
    bad "150 форма script: успех оставил временный дом гейта"; return
  fi
  ok "150 util-linux-подставной: форма замерена, ею же и позвали"
}

scenario_151() {   # форма script ЗАМЕРЕНА: BSD-подставной
  local launch
  gate_prepare s151
  gate_carved_or_bad 151 || return
  gate_call e bsd 5
  launch=$(gate_launch_line)
  LAST_EVID="rc=$GATE_RC запуск=[$launch] :: $(printf '%s' "$GATE_OUT" | tr '\n' '|')"
  if [[ "$GATE_OUT" != *"script form bsd"* ]]; then
    LAST_EVID="ФОРМА_НЕ_BSD :: $LAST_EVID"
    bad "151 форма script: BSD-подставной, а выбрана не его форма"; return
  fi
  if [[ "$launch" != "-q /dev/null "* ]]; then
    LAST_EVID="ЗАПУСК_НЕ_ТОЙ_ФОРМЫ :: $LAST_EVID"
    bad "151 форма script: стадия позвала script НЕ в выбранной форме"; return
  fi
  if (( GATE_RC != 0 )) || [[ "$GATE_OUT" != *"came up in a throwaway home"* ]]; then
    LAST_EVID="ВЕРДИКТ_НЕ_УСПЕХ :: $LAST_EVID"
    bad "151 форма script: BSD-форма не довела стадию до успеха"; return
  fi
  ok "151 BSD-подставной: форма замерена, ею же и позвали"
}

scenario_152() {   # положительный контроль различителя: обе и ни одной
  # Без этих двух случаев «проба выбрала форму» не доказывает ничего: молчаливый
  # выбор одной из форм даёт ровно тот немой отказ, из которого выросла волна.
  local out_both rc_both out_none rc_none
  gate_prepare s152
  gate_carved_or_bad 152 || return
  gate_call e both 5; out_both="$GATE_OUT"; rc_both=$GATE_RC
  gate_call e none 5; out_none="$GATE_OUT"; rc_none=$GATE_RC
  LAST_EVID="обе rc=$rc_both [$(printf '%s' "$out_both" | tr '\n' '|')] ни_одной rc=$rc_none [$(printf '%s' "$out_none" | tr '\n' '|')]"
  if (( rc_both != 2 )) || [[ "$out_both" != *"принял ОБЕ известные формы"* ]]; then
    LAST_EVID="ОБЕ_ФОРМЫ_НЕ_ОТКАЗ :: $LAST_EVID"
    bad "152 различитель: принявший ОБЕ формы script не дал отказа кода 2"; return
  fi
  if (( rc_none != 2 )) || [[ "$out_none" != *"не принял НИ ОДНОЙ известной формы"* ]]; then
    LAST_EVID="НИ_ОДНОЙ_НЕ_ОТКАЗ :: $LAST_EVID"
    bad "152 различитель: не принявший НИ ОДНОЙ формы script не дал отказа кода 2"; return
  fi
  ok "152 различитель формы: обе и ни одной -- отказ кода 2 с названной причиной"
}

scenario_171() {   # вход проб различителя не наследуется: под СОКЕТОМ форма замерена
  # Корень #100. BSD-`script` зовёт tcgetattr по СВОЕМУ стандартному вводу;
  # когда вызывающий отдаёт сокет (агентский контекст, launchd, cron), проба
  # падает с `Operation not supported on socket`, различитель объявляет «ни
  # одной известной формы», и конвейер умирает кодом 2 ТАМ, ГДЕ ОБЕ ФОРМЫ НА
  # МЕСТЕ. Замер 09.09 на настоящем `script`: под сокетом rc=1, с `</dev/null`
  # rc=0 -- различает ИМЕННО вход, а не машина.
  #
  # Подставной `script` -- bash-скрипт, tcgetattr он не зовёт, и сокет сам по
  # себе его не валит. Поэтому сценарий мерит МЕХАНИЗМ (чем закреплён вход
  # проб), а не симптом: подставной сообщает КЛАСС входа, который ему дали, а
  # драйвер запускается с сокетом на дескрипторе 0.
  #
  # Предмет -- ТОЛЬКО различитель. Реальный запуск отцеплен через `( … ) &`, и
  # оболочка подставляет ему /dev/null сама -- замерено, что даже под `bash -m`,
  # потому что без управляющего терминала управление заданиями не включается.
  # Утверждение о нём было бы ВАКУУМНЫМ: зеленело бы и без правки.
  local calls seen_sock
  local GATE_STDIN_SOCK=1        # видна gate_call по динамической области bash
  gate_prepare s171
  gate_carved_or_bad 171 || return
  gate_call e bsd 5
  calls=$(awk 'END{print NR+0}' "$GATE_STUB_SIN_F")
  seen_sock=$(awk -F'\t' '$1=="сокет"{n++} END{print n+0}' "$GATE_STUB_SIN_F")
  LAST_EVID="rc=$GATE_RC вызовов_подставного=$calls из_них_сокетом=$seen_sock :: $(printf '%s' "$GATE_OUT" | tr '\n' '|')"
  # Положительный контроль ПРИБОРА идёт первым: пустой журнал свидетеля сделал
  # бы проверку «сокетов ноль» истинной впустую. Вызовов обязано быть не меньше
  # трёх -- две пробы различителя и запуск.
  if (( calls < 3 )); then
    LAST_EVID="СВИДЕТЕЛЬ_НЕ_ПИСАЛ вызовов=$calls :: $LAST_EVID"
    bad "171 вход проб: подставной не засвидетельствовал свой stdin -- прибор не мерит"; return
  fi
  if (( seen_sock != 0 )); then
    LAST_EVID="ВХОД_НАСЛЕДОВАН сокетом=$seen_sock :: $LAST_EVID"
    bad "171 вход проб: подставной получил СОКЕТ -- вход наследуется от вызывающего"; return
  fi
  if [[ "$GATE_OUT" != *"script form bsd"* ]]; then
    LAST_EVID="ФОРМА_НЕ_ЗАМЕРЕНА :: $LAST_EVID"
    bad "171 вход проб: под сокетом форма script не замерена"; return
  fi
  if (( GATE_RC != 0 )) || [[ "$GATE_OUT" != *"came up in a throwaway home"* ]]; then
    LAST_EVID="ВЕРДИКТ_НЕ_УСПЕХ :: $LAST_EVID"
    bad "171 вход проб: под сокетом стадия не дошла до успеха"; return
  fi
  ok "171 вход проб различителя закреплён: сокет вызывающего до script не доходит"
}

# --- дверь обвала слоя промтов (#101) ---------------------------------------
# Дверь живёт в КОНВЕЙЕРЕ, а сценарии свипа гоняют его ЗАГЛУШКУ -- до волны 45 (docnum:other)
# у неё не было ни одного сценария, и оба её решения (сработать и НАЗВАТЬ
# ПРИЧИНУ) держались только на замере живого образа. Меряется она тем же
# приёмом, что и стадия интерфейса: ВЫРЕЗАННЫМ фрагментом настоящего
# конвейера, чтобы сценарий проверял ТОТ ЖЕ код, а не его пересказ в стенде.
#
# Сеть стенду запрещена: `curl` подставной, код ответа называет сценарий.
# Иначе зуб мерил бы доступность чужого сервера -- то есть краснел бы от
# погоды, а не от правки.
DOOR_FUNCS=(__tw_prompt_outage __tw_prompt_dl_error __tw_snapshot_probe __tw_prompt_outage_door)

door_carve() {   # каталог фрагментов -> печатает число вырезанных кусков
  local dir="$1" n=0 name
  for name in "${DOOR_FUNCS[@]}"; do
    awk -v h="${name}() {" 'index($0, h) == 1 {on=1} on {print} on && $0 == "}" {exit}' \
      "$K/claude-patch-all.real" > "$dir/$name.sh"
    [[ -s "$dir/$name.sh" ]] && n=$((n+1))
  done
  printf '%s\n' "$n"
}

door_carved_or_bad() {   # номер сценария
  (( DOOR_CARVED == ${#DOOR_FUNCS[@]} )) && return 0
  LAST_EVID="ФРАГМЕНТЫ_НЕ_ВЫРЕЗАНЫ вырезано=$DOOR_CARVED из ${#DOOR_FUNCS[@]}"
  bad "$1 дверь обвала: фрагменты не вырезаны -- прибор смотрит не туда"
  return 1
}

door_prepare() {   # имя каталога сценария
  DOOR_D="$C/$1"; rm -rf "$DOOR_D"; mkdir -p "$DOOR_D/frag" "$DOOR_D/stub" "$DOOR_D/bare"
  DOOR_CARVED=$(door_carve "$DOOR_D/frag")
  cat > "$DOOR_D/stub/curl" <<'CURL45'
#!/usr/bin/env bash
# Подставной `curl` двери: печатает КОД, названный сценарием, и ничего не качает.
printf '%s' "${DOOR_HTTP:-200}"
exit "${DOOR_CURL_RC:-0}"
CURL45
  chmod +x "$DOOR_D/stub/curl"
  # Каталог БЕЗ `curl`: ОТСУТСТВИЕ инструмента заглушкой не подделать -- его
  # можно только не положить. Кладётся ровно то, что зовут дверь и её пробы;
  # `bash` в том числе, иначе подмена PATH не найдёт сам запускатель.
  local __t
  for __t in bash grep; do ln -sf "$(type -P "$__t")" "$DOOR_D/bare/$__t"; done
  cat > "$DOOR_D/drv.sh" <<'DOORDRV'
set -euo pipefail
source "$1"; source "$2"; source "$3"; source "$4"
__tw_prompt_outage_door "$5" "$6" 0 0 0
DOORDRV
  # Две фикстуры вывода форка: с ОБВАЛОМ (обе иглы двери) и чистая.
  printf 'Applying patches...\nSystem prompts not available for version 2.1.263\nError downloading system prompts: fetch failed\nDone\n' > "$DOOR_D/out-outage.txt"
  printf 'Applying patches...\nCustomizations applied successfully!\n' > "$DOOR_D/out-clean.txt"
}

door_call() {   # фикстура (outage|clean), код ответа адреса, [переменные окружения...]
  local fix="$1" http="$2"; shift 2
  DOOR_OUT=$(env "$@" DOOR_HTTP="$http" PATH="${DOOR_PATH:-$DOOR_D/stub:$PATH}" \
             bash "$DOOR_D/drv.sh" \
               "$DOOR_D/frag/__tw_prompt_outage.sh" \
               "$DOOR_D/frag/__tw_prompt_dl_error.sh" \
               "$DOOR_D/frag/__tw_snapshot_probe.sh" \
               "$DOOR_D/frag/__tw_prompt_outage_door.sh" \
               2.1.263 "$DOOR_D/out-$fix.txt" 2>&1 9>&-)
  DOOR_RC=$?
}

door_evid() { LAST_EVID="rc=$DOOR_RC :: $(printf '%s' "$DOOR_OUT" | tr '\n' '|')"; }

door_code_is() {   # <ожидаемый код> <номер сценария>; 0 -- сошлось
  # Проверяется ДВОЕ, и это одна гарантия: код выбирает ДЕЙСТВИЕ, и потребитель
  # у кода не один -- машина читает число, человек читает лог. Дверь, вернувшая
  # верный код молча, оставляет человека без причины; дверь, назвавшая код
  # только словом, оставляет без причины свип. Волна 47.
  local __want="$1" __n="$2"
  if (( DOOR_RC != __want )); then
    LAST_EVID="КОД_НЕ_ТОТ(ждали $__want) :: $LAST_EVID"
    bad "$__n дверь обвала: код $DOOR_RC, а по этой ветке действие требует $__want"
    return 1
  fi
  if [[ "$DOOR_OUT" != *"КОД ВОЗВРАТА $__want"* ]]; then
    LAST_EVID="КОД_НЕ_НАЗВАН(ждали $__want) :: $LAST_EVID"
    bad "$__n дверь обвала: код $__want верен, но вслух не назван -- человек читает лог, а не \$?"
    return 1
  fi
  return 0
}

scenario_172() {   # обвал, адрес отвечает 404 -- апстрим не опубликовал
  door_prepare s172; door_carved_or_bad 172 || return
  door_call outage 404; door_evid
  # ПОРЯДОК ПРОВЕРОК -- КОНСТРЕЙНТ, а не стиль. Сперва спрашивается НАЗВАННАЯ
  # ПРИЧИНА, и только потом КОД. Мутация, убивающая метку ветки в `case`,
  # уносит с собой И печать причины, И присвоение кода: ветка проваливается
  # в `*)`. Спроси код первым -- такая мутация покраснела бы следом
  # «КОД_НЕ_ТОТ», то есть ЧУЖОЙ причиной, и зуб на называние причины остался
  # бы недоказанным. Обратный порядок делит предметы начисто: метку ветки
  # ловит зуб причины, присвоение кода -- зуб кода. Измерено самопроверкой
  # волны 47: мутации 201/202/204 краснели чужой причиной (docnum:other -- это
  # НОМЕРА мутаций, а не счёт чего-либо).
  if [[ "$DOOR_OUT" != *"НЕ ОПУБЛИКОВАЛ"* ]]; then
    LAST_EVID="ПУБЛИКАЦИЯ_НЕ_НАЗВАНА :: $LAST_EVID"
    bad "172 дверь обвала: при 404 не названа непубликация апстрима"; return
  fi
  door_code_is 7 172 || return
  ok "172 обвал при 404 -- непубликация апстрима названа, код 7 (ждать)"
}

scenario_173() {   # обвал, адрес отвечает 200 -- скачать не смог ЭТОТ хозяин
  # Корень #101 целиком: снимок ЛЕЖИТ, а форк его не взял. Прежняя дверь звала
  # ждать публикации -- то есть отправляла чинить не то. Сценарий требует не
  # только правильной ветки, но и НАЗВАННОЙ переменной прокси с ручкой node:
  # причина без имени не отличается от догадки.
  door_prepare s173; door_carved_or_bad 173 || return
  door_call outage 200 https_proxy=http://127.0.0.1:3128; door_evid
  # Порядок «причина раньше кода» -- констрейнт, объяснён в сценарии 172.
  if [[ "$DOOR_OUT" != *"ЭТОТ хозяин"* ]]; then
    LAST_EVID="ХОЗЯИН_НЕ_НАЗВАН :: $LAST_EVID"
    bad "173 дверь обвала: при 200 причиной назван не хозяин"; return
  fi
  if [[ "$DOOR_OUT" != *"https_proxy"* || "$DOOR_OUT" != *"NODE_USE_ENV_PROXY=1"* ]]; then
    LAST_EVID="ПРОКСИ_НЕ_НАЗВАН :: $LAST_EVID"
    bad "173 дверь обвала: заданный прокси и ручка node не названы"; return
  fi
  door_code_is 6 173 || return
  ok "173 обвал при 200 -- хозяин, прокси и ручка node названы, код 6 (чинить окружение)"
}

scenario_174() {   # обвал, соединения не было -- третий класс, не «нет снимка»
  door_prepare s174; door_carved_or_bad 174 || return
  door_call outage 000 DOOR_CURL_RC=7; door_evid
  # Порядок «причина раньше кода» -- констрейнт, объяснён в сценарии 172.
  if [[ "$DOOR_OUT" != *"не вышел НИ ОДИН запрос"* ]]; then
    LAST_EVID="СЕТЬ_НЕ_НАЗВАНА :: $LAST_EVID"
    bad "174 дверь обвала: отсутствие соединения не отделено от отсутствия снимка"; return
  fi
  door_code_is 6 174 || return
  ok "174 обвал без соединения -- отдельный класс, код 6 (чинить окружение)"
}

scenario_175() {   # различителя нет на хозяине -- дверь не гадает
  local DOOR_PATH
  door_prepare s175; door_carved_or_bad 175 || return
  DOOR_PATH="$DOOR_D/bare"
  door_call outage 200; door_evid
  # Порядок «причина раньше кода» -- констрейнт, объяснён в сценарии 172.
  if [[ "$DOOR_OUT" != *"нет «curl»"* ]]; then
    LAST_EVID="НЕТ_CURL_НЕ_НАЗВАН :: $LAST_EVID"
    bad "175 дверь обвала: без curl дверь не называет отсутствие различителя"; return
  fi
  door_code_is 2 175 || return
  ok "175 без curl дверь называет отсутствие различителя, а не причину обвала"
}

scenario_176() {   # обвала НЕТ -- дверь обязана молчать и пропустить
  # Отрицательный контроль двери. Без него все 4 сценария выше (docnum:subset)
  # прошли бы у двери, которая срабатывает ВСЕГДА: «код 2 и правильный текст»
  # она давала бы и на чистом выводе форка, обрушив каждую здоровую сборку.
  door_prepare s176; door_carved_or_bad 176 || return
  door_call clean 200; door_evid
  if (( DOOR_RC != 0 )); then
    LAST_EVID="ДВЕРЬ_ВХОЛОСТУЮ :: $LAST_EVID"
    bad "176 дверь обвала: на чистом выводе форка код $DOOR_RC, а обвала нет"; return
  fi
  if [[ -n "$DOOR_OUT" ]]; then
    LAST_EVID="ДВЕРЬ_НЕ_МОЛЧИТ :: $LAST_EVID"
    bad "176 дверь обвала: на чистом выводе форка дверь что-то печатает"; return
  fi
  ok "176 без обвала дверь молчит и пропускает -- отрицательный контроль"
}

scenario_177() {   # неожиданный ответ адреса: назван числом и НЕ РОНЯЕТ дверь
  # Ловушка измерена 10.09 на этой самой правке: кавычка-ёлочка многобайтовая,
  # и bash 3.2 затягивает её первый байт в ИМЯ переменной -- «$__snap» под
  # `set -u` даёт «unbound variable» ровно в этой ветке, до единого полезного
  # слова. Сценарий требует ОБОИХ: оболочка не упала И код назван.
  #
  # ВЛАДЕЛЕЦ ЭТОЙ ГАРАНТИИ -- НЕ ЗДЕСЬ. Форму `${имя}` по всему киту держит
  # ГЕЙТ ИМЁН ПЕРЕМЕННЫХ конвейера (claude-patch-all.sh, «ФОРМЫ ОБОЛОЧКИ»):
  # он обходит все `*.sh`, пропускает строки-комментарии и несёт свои
  # положительный и отрицательный контроли. Проверка ЗДЕСЬ -- о поведении
  # ветки, и она host-зависима: bash 5.2 склеенное имя исполняет верно
  # (замер 10.09 на linux), так что зубом формы она быть НЕ МОЖЕТ. Ценз
  # исходника в этом файле НЕ ЗАВОДИТЬ: вторая копия правила разойдётся с
  # гейтом молча -- волна 45 такую копию завела и сняла.
  door_prepare s177; door_carved_or_bad 177 || return
  door_call outage 500; door_evid
  if [[ "$DOOR_OUT" == *"unbound variable"* ]]; then
    LAST_EVID="ИМЯ_СЪЕЛО_КАВЫЧКУ :: $LAST_EVID"
    bad "177 дверь обвала: ветка неожиданного ответа падает по unbound variable"; return
  fi
  # Порядок «причина раньше кода» -- констрейнт, объяснён в сценарии 172.
  if [[ "$DOOR_OUT" != *"неясно-500"* ]]; then
    LAST_EVID="ОТВЕТ_НЕ_НАЗВАН :: $LAST_EVID"
    bad "177 дверь обвала: неожиданный ответ адреса не назван числом"; return
  fi
  door_code_is 2 177 || return
  ok "177 неожиданный ответ адреса назван числом, ветка не падает"
}


scenario_185() {   # конвейер вернул 7 -- ждать апстрим, а не красить версию
  # ЗАМЕРЕННЫЙ ПОВОД (10.09, linux, версия 2.1.266, снимок промтов апстримом не
  # опубликован): дверь возвращала 2 на все пять своих причин, свип относил
  # версию к КРАСНЫМ и печатал в одной строке ДЕВЯТЬ причин -- «контракт вызова
  # нарушен или прибор гейта не мерил; ни одной прошедшей проверки; наших
  # применений 0; дым не подтверждён; ...» -- и ни одной верной. Итог при этом
  # заявлял «версий не измерено 0», хотя не измерено было ничего.
  #
  # Порядок проверок -- механизм, а не оформление: каждая мутация волны 47
  # обязана краснить СВОЮ проверку, и проверка «покрашена красной» стоит первой
  # именно потому, что пропуск версии мимо блока вердикта даёт И красноту, И
  # чужой код возврата -- по коду эти две поломки не различить.
  local out rc
  out=$(STUB_RC=7 run_sweep "$K" "$C/corpus" "$C/versions.txt" 900); rc=$?
  LAST_EVID="rc=$rc :: $out"
  if [[ "$out" == *КРАСНАЯ* ]]; then
    LAST_EVID="КРАСНАЯ_ВМЕСТО_ОЖИДАНИЯ :: $LAST_EVID"
    bad "185 конвейер вернул 7: версия покрашена КРАСНОЙ, а чинить нечего -- ждать апстрим"; return
  fi
  if (( rc != 3 )); then
    LAST_EVID="КЛАСС_НЕ_ТОТ(ждали 3) :: $LAST_EVID"
    bad "185 конвейер вернул 7: код свипа $rc, а это класс «измерить сейчас нельзя, повтор поможет» (3)"; return
  fi
  if [[ "$out" != *"НЕ ИЗМЕРЕНО(апстрим не опубликовал"* ]]; then
    LAST_EVID="НЕ_ИЗМЕРЕНО_НЕ_НАЗВАНО :: $LAST_EVID"
    bad "185 конвейер вернул 7: версия не отмечена неизмеренной по вине апстрима"; return
  fi
  if [[ "$out" != *"Апстрим не опубликовал снимок промтов"* ]]; then
    LAST_EVID="АПСТРИМ_НЕ_НАЗВАН :: $LAST_EVID"
    bad "185 конвейер вернул 7: итоговая строка не называет повод неполноты"; return
  fi
  ok "185 конвейер вернул 7 -- версия НЕ ИЗМЕРЕНА по вине апстрима, а не красная"
}

# --- волна 48: почему образ не назвался (#94) --------------------------------
# Пять дверей конвейера просят образ назвать себя (`--version`) и, не получив
# ответа, печатают отказ. Причин у молчания ДВЕ разной природы -- негодные
# байты и чужая платформа, -- и до этой волны каждая дверь называла первую из
# СВОЕГО списка, то есть тот же дефект, что закрыт под #105.
#
# Диагност вырезается из конвейера ПО ИМЕНИ и гоняется на СИНТЕТИЧЕСКИХ
# заголовках (те же, что у волны 40c): корпус несёт две формы из шести, а
# отвечать диагност берётся за все. Сеть и настоящие образы тут не нужны --
# предмет замера чисто текстовый.
NOTE_FUNCS=(__host_os_arch __image_os_arch __image_run_note)
WHY_FUNCS=(__emit_check_why)

w48_carve() {   # каталог, имена функций... -> печатает число вырезанных кусков
  local dir="$1"; shift
  local n=0 name
  for name in "$@"; do
    awk -v h="${name}() {" 'index($0, h) == 1 {on=1} on {print} on && $0 == "}" {exit}' \
      "$K/claude-patch-all.real" > "$dir/$name.sh"
    [[ -s "$dir/$name.sh" ]] && n=$((n+1))
  done
  printf '%s\n' "$n"
}

note_prepare() {   # имя каталога сценария
  NOTE_D="$C/$1"; rm -rf "$NOTE_D"; mkdir -p "$NOTE_D/f"
  NOTE_CARVED=$(w48_carve "$NOTE_D/f" "${NOTE_FUNCS[@]}")
  cat > "$NOTE_D/drv.sh" <<'NOTEDRV'
set -euo pipefail
source "$1"; source "$2"; source "$3"
__image_run_note "$4"
NOTEDRV
}

note_carved_or_bad() {   # номер сценария
  (( NOTE_CARVED == ${#NOTE_FUNCS[@]} )) && return 0
  LAST_EVID="ФРАГМЕНТЫ_НЕ_ВЫРЕЗАНЫ вырезано=$NOTE_CARVED из ${#NOTE_FUNCS[@]}"
  bad "$1 диагност платформы: фрагменты не вырезаны -- прибор смотрит не туда"
  return 1
}

# Пара ХОЗЯИНА спрашивается у той же вырезанной функции, которой пользуется
# конвейер, а не считается стендом заново: вторая копия отображения имён
# разошлась бы молча -- ровно тот силуэт, который волна и разбирает. Эта волна
# `__host_os_arch` не мутирует, так что выбор фикстуры на ней стоять может.
note_host_pair() {
  bash -c 'set -euo pipefail; source "$1"; __host_os_arch' _ "$NOTE_D/f/__host_os_arch.sh"
}

note_host_form() {   # форма заголовка, СОВПАДАЮЩАЯ с хозяином, либо «НЕТ»
  case "$(note_host_pair)" in
    darwin-arm64) printf 'macho-arm64\n' ;;
    darwin-x64)   printf 'macho-x64\n' ;;
    linux-x64)    printf 'elf-x64\n' ;;
    linux-arm64)  printf 'elf-arm64\n' ;;
    win32-x64)    printf 'pe-x64\n' ;;
    win32-arm64)  printf 'pe-arm64\n' ;;
    *)            printf 'НЕТ\n' ;;
  esac
}

note_foreign_form() {   # «форма пара», ЗАВЕДОМО чужая этому хозяину
  # Форма выбирается ОТ хозяина, а не прибивается: зуб, прибитый к win32,
  # зеленел бы на маке и краснел бы на windows-хозяине по причине прибора.
  if [[ "$(note_host_pair)" == win32-arm64 ]]; then
    printf 'elf-x64 linux-x64\n'
  else
    printf 'pe-arm64 win32-arm64\n'
  fi
}

note_call() {   # форма заголовка -> NOTE_OUT/NOTE_RC
  local form="$1"
  cp_mkhead "$NOTE_D/$form.img" "$form"
  NOTE_OUT=$(HERE="$K" bash "$NOTE_D/drv.sh" \
               "$NOTE_D/f/__host_os_arch.sh" "$NOTE_D/f/__image_os_arch.sh" \
               "$NOTE_D/f/__image_run_note.sh" "$NOTE_D/$form.img" 2>&1)
  NOTE_RC=$?
  LAST_EVID="rc=$NOTE_RC :: $(printf '%s' "$NOTE_OUT" | tr '\n' '|')"
}

scenario_186() {   # чужая платформа: причина НАЗВАНА, и это не приговор байтам
  local ff fp hp
  note_prepare s186; note_carved_or_bad 186 || return
  ff=$(note_foreign_form); fp="${ff#* }"; ff="${ff%% *}"
  hp=$(note_host_pair)
  note_call "$ff"
  # Порядок «причина раньше кода» -- констрейнт волны 47, объяснён в сценарии 172.
  if [[ "$NOTE_OUT" != *"ПРИЧИНА: образ собран под $fp, а хозяин $hp"* ]]; then
    LAST_EVID="ПРИЧИНА_НЕ_НАЗВАНА :: $LAST_EVID"
    bad "186 диагност платформы: образ под $fp на хозяине $hp, а причина не названа"; return
  fi
  if [[ "$NOTE_OUT" == *СОВПАДАЕТ* ]]; then
    LAST_EVID="ПАРЫ_СПУТАНЫ :: $LAST_EVID"
    bad "186 диагност платформы: чужая пара объявлена совпавшей -- ветка не завершилась"; return
  fi
  if (( NOTE_RC != 0 )); then
    LAST_EVID="КОД_НЕ_НОЛЬ :: $LAST_EVID"
    bad "186 диагност платформы: вернул $NOTE_RC -- диагност не выбирает код за дверь"; return
  fi
  ok "186 диагност платформы: чужая пара названа причиной, прогон не уронен"
}

scenario_187() {   # своя платформа: причина НЕ в платформе, и это сказано вслух
  local hf hp
  note_prepare s187; note_carved_or_bad 187 || return
  hf=$(note_host_form); hp=$(note_host_pair)
  if [[ "$hf" == "НЕТ" ]]; then
    LAST_EVID="ХОЗЯИН_НЕ_НАЗВАН пара=[$hp]"
    bad "187 диагност платформы: пара хозяина «${hp}» не разобрана -- фикстуру не выбрать"; return
  fi
  note_call "$hf"
  if [[ "$NOTE_OUT" != *"Пара платформ СОВПАДАЕТ ($hp)"* ]]; then
    LAST_EVID="СОВПАДЕНИЕ_НЕ_НАЗВАНО :: $LAST_EVID"
    bad "187 диагност платформы: пара совпала, но вслух это не сказано -- человек уйдёт чинить платформу"; return
  fi
  if (( NOTE_RC != 0 )); then
    LAST_EVID="КОД_НЕ_НОЛЬ :: $LAST_EVID"
    bad "187 диагност платформы: вернул $NOTE_RC -- диагност не выбирает код за дверь"; return
  fi
  ok "187 диагност платформы: своя пара названа совпавшей, разбирательство уходит к байтам"
}

scenario_188() {   # детектор ОТКАЗАЛ: диагност сознаётся, а не гадает
  note_prepare s188; note_carved_or_bad 188 || return
  # Универсальный образ -- отказ САМОГО детектора, а не поломка стенда: у него
  # нет одной целевой платформы, и угадывать её нечем.
  note_call fat-magic
  if [[ "$NOTE_OUT" != *"ПАРА ПЛАТФОРМ НЕ УСТАНОВЛЕНА"* ]]; then
    LAST_EVID="НЕУСТАНОВЛЕННОСТЬ_НЕ_НАЗВАНА :: $LAST_EVID"
    bad "188 диагност платформы: детектор отказал, а диагност этого не сказал"; return
  fi
  if [[ "$NOTE_OUT" != *"universal (fat)"* ]]; then
    LAST_EVID="СЛОВА_ДЕТЕКТОРА_ПОТЕРЯНЫ :: $LAST_EVID"
    bad "188 диагност платформы: причина отказа детектора не донесена -- её погасили"; return
  fi
  if [[ "$NOTE_OUT" == *СОВПАДАЕТ* || "$NOTE_OUT" == *"ПРИЧИНА: образ собран под"* ]]; then
    LAST_EVID="ДОГАДКА_ПОСЛЕ_ОТКАЗА :: $LAST_EVID"
    bad "188 диагност платформы: пара не установлена, а вердикт о ней всё равно вынесен"; return
  fi
  if (( NOTE_RC != 0 )); then
    LAST_EVID="КОД_НЕ_НОЛЬ :: $LAST_EVID"
    bad "188 диагност платформы: вернул $NOTE_RC -- диагност не выбирает код за дверь"; return
  fi
  ok "188 диагност платформы: отказ детектора донесён его же словами, догадки нет"
}

why_prepare() {   # имя каталога сценария
  WHY_D="$C/$1"; rm -rf "$WHY_D"; mkdir -p "$WHY_D/f"
  WHY_CARVED=$(w48_carve "$WHY_D/f" "${WHY_FUNCS[@]}")
  cat > "$WHY_D/drv.sh" <<'WHYDRV'
set -euo pipefail
source "$1"
__emit_check_why "$2"
WHYDRV
}

why_carved_or_bad() {   # номер сценария
  (( WHY_CARVED == ${#WHY_FUNCS[@]} )) && return 0
  LAST_EVID="ФРАГМЕНТ_НЕ_ВЫРЕЗАН вырезано=$WHY_CARVED из ${#WHY_FUNCS[@]}"
  bad "$1 классификатор разбора: фрагмент не вырезан -- прибор смотрит не туда"
  return 1
}

why_call() {   # <текст вывода разбора> -> WHY_OUT
  WHY_OUT=$(bash "$WHY_D/drv.sh" "$WHY_D/f/__emit_check_why.sh" "$1" 2>&1)
  WHY_RC=$?
  LAST_EVID="rc=$WHY_RC :: [$WHY_OUT]"
}

scenario_189() {   # каждый из ЧЕТЫРЁХ поводов кода 2 назван СВОИМ именем
  # Замер, породивший сценарий: на usbox не было `tsc` в неинтерактивном PATH,
  # и конвейер печатал «якорь/строка пропали» -- ЧУЖУЮ причину. Расследование
  # волны 45 ушло искать пропавший якорь, которого никто не терял.
  local pair inp want mark
  why_prepare s189; why_carved_or_bad 189 || return
  for pair in "ЯКОРЬ НЕ НАЙДЕН: X|якорь вклейки|якорь" \
              "НЕ СТРОКА: X|НЕ строкой|не-строка" \
              "ПРОВЕРКА ИМЁН НЕ ВЫПОЛНЕНА: tsc не запустился (ENOENT)|НЕ ЗАПУСТИЛСЯ|tsc" \
              "ПРОВЕРКА ИМЁН НЕ ВЫПОЛНЕНА: tsc вышел с кодом 2, не выдав|ни одной диагностики|без диагностик"; do
    inp="${pair%%|*}"; mark="${pair##*|}"; want="${pair#*|}"; want="${want%|*}"
    why_call "$inp"
    if [[ "$WHY_OUT" != *"$want"* ]]; then
      LAST_EVID="КЛАСС_НЕ_НАЗВАН($mark) :: $LAST_EVID"
      bad "189 классификатор разбора: повод «${mark}» не назван своим именем"; return
    fi
  done
  ok "189 классификатор разбора: все четыре повода кода 2 названы своими именами"
}

scenario_190() {   # неизвестный вывод -> НИЧЕГО, а не первый повод из списка
  why_prepare s190; why_carved_or_bad 190 || return
  why_call "нечто, чего классификатор не знает"
  if [[ -n "$WHY_OUT" ]]; then
    LAST_EVID="КЛАСС_ПОДСТАВЛЕН :: $LAST_EVID"
    bad "190 классификатор разбора: на незнакомый вывод подставлен повод «${WHY_OUT}»"; return
  fi
  ok "190 классификатор разбора: незнакомый вывод оставлен БЕЗ класса, а не назван первым"
}

scenario_191() {   # поводов ДВА -- названы ОБА, а не первый совпавший
  why_prepare s191; why_carved_or_bad 191 || return
  why_call "ЯКОРЬ НЕ НАЙДЕН: X
ПРОВЕРКА ИМЁН НЕ ВЫПОЛНЕНА: tsc не запустился (ENOENT)"
  if [[ "$WHY_OUT" != *"якорь вклейки"* || "$WHY_OUT" != *"НЕ ЗАПУСТИЛСЯ"* ]]; then
    LAST_EVID="ПОВОД_ПОТЕРЯН :: $LAST_EVID"
    bad "191 классификатор разбора: поводов было два, названо «${WHY_OUT}»"; return
  fi
  ok "191 классификатор разбора: два повода названы оба, выбора «первый совпавший» нет"
}

scenario_192() {   # САЙТЫ ВЫЗОВА: диагност и классификатор действительно позваны
  # Механизм, который никто не зовёт, проходит все свои сценарии и не работает
  # ни разу. Счёт идёт по САЙТАМ ВЫЗОВА, а не по вхождениям имени: объявление
  # функции тоже содержит её имя, и ценз вхождений считал бы его за работу.
  local src note_n why_n word_n bytes_n
  src="$K/claude-patch-all.real"
  note_n=$(grep -c '^ *__image_run_note "' "$src" || true)
  why_n=$(grep -c '__emit_check_why "\$__ec_out"' "$src" || true)
  LAST_EVID="сайтов диагноста=$note_n сайтов классификатора=$why_n"
  # Дверей, где образ молчит, ШЕСТЬ, а сайтов вызова СЕМЬ: подписант; сравнение
  # близнеца `.orig` (заметка); отказ близнеца `.orig` -- у него ДВА сайта,
  # потому что молчать может любая из двух сторон сравнения; бэкап tweakcc;
  # версия цели; дым патченного образа. Седьмая дверь -- разбор вклейки --
  # молчит не образом, у неё свой классификатор.
  if (( note_n != 7 )); then
    LAST_EVID="САЙТ_ДЫМА_ПРОПАЛ :: $LAST_EVID"
    bad "192 сайты вызова: диагност платформы позван $note_n раз, а сайтов семь"; return
  fi
  if (( why_n != 1 )); then
    LAST_EVID="САЙТ_РАЗБОРА_ПРОПАЛ :: $LAST_EVID"
    bad "192 сайты вызова: классификатор разбора позван $why_n раз, а дверь одна"; return
  fi
  # Два ЕДИНСТВЕННЫХ ДОМА волны 48 считаются здесь же и по той же причине: дом
  # без сайтов -- это копия трубы, вернувшаяся в текст соседа, и все зубы дома
  # при этом остаются зелёными. Первое слово читают четверо (img_ver и три
  # сравнения версий), версию из байтов -- четыре двери tweakcc: уровень,
  # сверка непроходов, множество выключенных и (волна t106) конфликты накладок.
  word_n=$(grep -c '__first_word "' "$src" || true)
  bytes_n=$(grep -c '__ver_from_bytes "' "$src" || true)
  LAST_EVID="$LAST_EVID сайтов первого слова=$word_n сайтов версии-из-байтов=$bytes_n"
  if (( word_n != 4 )); then
    LAST_EVID="САЙТ_ПЕРВОГО_СЛОВА_ПРОПАЛ :: $LAST_EVID"
    bad "192 сайты вызова: дом первого слова позван $word_n раз, а сайтов четыре"; return
  fi
  if (( bytes_n != 4 )); then
    LAST_EVID="САЙТ_ВЕРСИИ_ИЗ_БАЙТОВ_ПРОПАЛ :: $LAST_EVID"
    bad "192 сайты вызова: дом версии из байтов позван $bytes_n раз, а дверей четыре"; return
  fi
  ok "192 сайты вызова: диагност, классификатор и оба дома позваны своими дверями"
}

scenario_194() {   # __ver_from_bytes: образ без отметки версии не уносит прогон
  # ЗАМЕР волны 48 (обе машины). Три двери tweakcc читали версию из байтов
  # каждая своей копией одной трубы: `grep -m1 ... | head -1 | sed ...`. На
  # образе БЕЗ отметки `grep` отдаёт 1, под `set -o pipefail` это код всей
  # подстановки, и на ПЛОСКОМ вызове прогон умирает прямо на присваивании --
  # вместе с веткой «в байтах нет отметки версии», написанной ровно для этого
  # случая. Измеренная разница: плоский вызов rc=1 без единого слова, вызов из
  # условия (`if ! дверь ...`) ветку достигает. То есть достижимость
  # ОБЪЯВЛЕННОЙ ветки принадлежала форме вызова, а не двери; дом с поясом
  # делает её свойством самой двери.
  local d out rc carved
  d="$C/s194"; rm -rf "$d"; mkdir -p "$d/f"
  carved=$(w48_carve "$d/f" __ver_from_bytes)
  if [[ "$carved" != 1 ]]; then
    LAST_EVID="ФРАГМЕНТ_НЕ_ВЫРЕЗАН(вырезано $carved из 1)"
    bad "194 версия из байтов: фрагмент не вырезан -- прибор смотрит не туда"; return
  fi
  printf 'какие-то байты без отметки\n' > "$d/plain"
  printf 'мусор\n// Version: 2.1.999\nещё мусор\n' > "$d/marked"
  cat > "$d/flat.sh" <<'VBFLAT'
set -euo pipefail
source "$1"
__ver_from_bytes "$2" >/dev/null
printf 'ЖИВ\n'
VBFLAT
  cat > "$d/drv.sh" <<'VBDRV'
set -euo pipefail
source "$1"
V="$(__ver_from_bytes "$2")"
printf 'ВЕРСИЯ=[%s]\n' "$V"
printf 'ЖИВ\n'
VBDRV
  out=$(bash "$d/flat.sh" "$d/f/__ver_from_bytes.sh" "$d/plain" 2>&1); rc=$?
  LAST_EVID="плоский без отметки rc=$rc :: $(printf '%s' "$out" | tr '\n' '|')"
  if [[ "$out" != *"ЖИВ"* ]]; then
    LAST_EVID="ПРОГОН_УБИТ(нет отметки) :: $LAST_EVID"
    bad "194 версия из байтов: образ без отметки унёс прогон кодом $rc, не сказав ни слова"; return
  fi
  out=$(bash "$d/drv.sh" "$d/f/__ver_from_bytes.sh" "$d/plain" 2>&1); rc=$?
  LAST_EVID="без отметки rc=$rc :: $(printf '%s' "$out" | tr '\n' '|') :: $LAST_EVID"
  if [[ "$out" != *"ВЕРСИЯ=[]"* ]]; then
    LAST_EVID="ВЕРСИЯ_ИЗ_НИОТКУДА :: $LAST_EVID"
    bad "194 версия из байтов: образ без отметки всё равно назвал версию"; return
  fi
  # Положительный контроль: дом, всегда отдающий пустоту, доказал бы только
  # собственную немоту, а не умение прочитать отметку.
  out=$(bash "$d/drv.sh" "$d/f/__ver_from_bytes.sh" "$d/marked" 2>&1); rc=$?
  LAST_EVID="с отметкой rc=$rc :: $(printf '%s' "$out" | tr '\n' '|') :: $LAST_EVID"
  if [[ "$out" != *"ВЕРСИЯ=[2.1.999]"* ]]; then
    LAST_EVID="ОТМЕТКА_НЕ_ПРОЧТЕНА :: $LAST_EVID"
    bad "194 версия из байтов: отметка в байтах не прочитана -- прибор нем сам по себе"; return
  fi
  ok "194 версия из байтов: образ без отметки не уносит прогон, отметка читается"
}
scenario_193() {   # img_ver: ни отказ образа, ни его болтливость не уносят прогон
  # ДВА ЗАМЕРА волны 48, оба на ОБЕИХ машинах (bash 3.2.57 и 5.2.26).
  # (1) Дверь читалась одной трубой `"$1" --version | awk ...`: под
  #     `set -o pipefail` код неисполнимого образа (126) становился кодом
  #     ФУНКЦИИ, а вызывающий читает её присваиванием -- и умирал прямо на
  #     нём, не напечатав ни слова; обе ветки «unreadable» ниже по конвейеру
  #     писались ровно для этого случая и были недостижимы.
  # (2) `awk` выходит на первой строке, и образ, наливший в stdout больше
  #     буфера трубы, даёт `printf` EPIPE -- код 141 у функции и та же смерть
  #     вызывающего, уже безо всякого отказа образа (200 000 строк -> rc=141).
  # Поясов поэтому ДВА, и наблюдаемы они в РАЗНЫХ формах вызова -- обе ниже.
  local d out rc carved
  d="$C/s193"; rm -rf "$d"; mkdir -p "$d/f"
  # Вырезаются ОБЕ функции: значение img_ver теперь достаёт единственный дом
  # первого слова, и фрагмент без него был бы прибором, меряющим свою же дыру.
  carved=$(w48_carve "$d/f" __first_word img_ver)
  if [[ "$carved" != 2 ]]; then
    LAST_EVID="ФРАГМЕНТ_НЕ_ВЫРЕЗАН(вырезано $carved из 2)"
    bad "193 img_ver: фрагменты не вырезаны -- прибор смотрит не туда"; return
  fi
  # Молчащий образ на самом деле ГОВОРИТ -- в stderr: ровно те слова, ради
  # которых с двери снят `2>/dev/null`.
  cat > "$d/silent" <<'SILENT'
#!/bin/sh
printf 'образ не запускается: неверный формат\n' >&2
exit 126
SILENT
  # Болтливый образ льёт в stdout больше буфера трубы. Он же -- положительный
  # контроль чтения: функция, всегда отдающая пустоту, доказала бы только
  # собственную немоту, а не умение прочитать версию.
  cat > "$d/chatty" <<'CHATTY'
#!/bin/sh
case "$1" in
  --version) awk 'BEGIN { for (i = 0; i < 200000; i++) print "2.1.999 строка" i }' ;;
esac
CHATTY
  chmod +x "$d/silent" "$d/chatty"
  # Драйверы повторяют ДВЕ формы вызова. Они не взаимозаменяемы: под
  # `V="$(img_ver X)"` bash гасит errexit ВНУТРИ функции (замер обеих машин),
  # и пояс присваивания там не наблюдаем -- его видно только на плоском вызове.
  cat > "$d/drv.sh" <<'IMGDRV'
set -euo pipefail
source "$1"; source "$2"
V="$(img_ver "$3")"
printf 'ВЕРСИЯ=[%s]\n' "$V"
printf 'ЖИВ\n'
IMGDRV
  cat > "$d/flat.sh" <<'IMGFLAT'
set -euo pipefail
source "$1"; source "$2"
img_ver "$3" >/dev/null
printf 'ЖИВ\n'
IMGFLAT
  out=$(bash "$d/drv.sh" "$d/f/__first_word.sh" "$d/f/img_ver.sh" "$d/silent" 2>&1); rc=$?
  LAST_EVID="молчащий rc=$rc :: $(printf '%s' "$out" | tr '\n' '|')"
  if [[ "$out" != *"ЖИВ"* ]]; then
    LAST_EVID="ПРОГОН_УБИТ(отказ образа) :: $LAST_EVID"
    bad "193 img_ver: образ отказал -- и прогон умер кодом $rc, не сказав ни слова"; return
  fi
  if [[ "$out" != *"ВЕРСИЯ=[]"* ]]; then
    LAST_EVID="ВЕРСИЯ_НЕ_ПУСТА :: $LAST_EVID"
    bad "193 img_ver: молчащий образ дал версию вместо пустоты"; return
  fi
  if [[ "$out" != *"образ не запускается"* ]]; then
    LAST_EVID="СЛОВА_ОБРАЗА_ПОТЕРЯНЫ :: $LAST_EVID"
    bad "193 img_ver: единственные слова образа о причине не дошли до лога"; return
  fi
  out=$(bash "$d/flat.sh" "$d/f/__first_word.sh" "$d/f/img_ver.sh" "$d/silent" 2>&1); rc=$?
  LAST_EVID="плоский rc=$rc :: $(printf '%s' "$out" | tr '\n' '|') :: $LAST_EVID"
  if [[ "$out" != *"ЖИВ"* ]]; then
    LAST_EVID="ПРОГОН_УБИТ(плоский вызов) :: $LAST_EVID"
    bad "193 img_ver: на плоском вызове отказ образа унёс прогон кодом $rc"; return
  fi
  out=$(bash "$d/drv.sh" "$d/f/__first_word.sh" "$d/f/img_ver.sh" "$d/chatty" 2>&1); rc=$?
  LAST_EVID="болтливый rc=$rc :: $(printf '%s' "$out" | tr '\n' '|') :: $LAST_EVID"
  if [[ "$out" != *"ЖИВ"* ]]; then
    LAST_EVID="ПРОГОН_УБИТ(болтливый) :: $LAST_EVID"
    bad "193 img_ver: образ налил в stdout больше буфера трубы -- прогон умер кодом $rc"; return
  fi
  if [[ "$out" != *"ВЕРСИЯ=[2.1.999]"* ]]; then
    LAST_EVID="ГОВОРЯЩИЙ_НЕ_ПРОЧТЁН :: $LAST_EVID"
    bad "193 img_ver: исправный образ не прочитан -- прибор нем сам по себе"; return
  fi
  ok "193 img_ver: отказ и болтливость образа не уносят прогон, версия читается"
}

scenario_178() {   # обязательные инструменты: отсутствующий tsc НАЗВАН дверью
  # Замер 10.09 на usbox, откуда взялся сценарий: `tsc` нет в неинтерактивном
  # PATH, дверь инструментов его не требовала, и прогон умирал через полторы
  # тысячи строк на разборе вклеиваемого кода -- строкой «якорь/строка
  # пропали», то есть НЕ ТОЙ причиной: якорь был на месте.
  #
  # Проверка имён (tools/emit-check.js) зовётся БЕЗУСЛОВНО и объявляет
  # отсутствующий компилятор отказом, а не пропуском. Значит `tsc` обязателен
  # ровно как `node`, и дверь обязана называть его ЗДЕСЬ.
  local d carved out rc
  d="$C/s178"; rm -rf "$d"; mkdir -p "$d"
  carved=$(tools_door_carve "$d")
  if [[ "$carved" != "4" ]]; then
    LAST_EVID="ЯКОРЬ_ПОТЕРЯН вырезано=$carved из 4"
    bad "178 дверь инструментов: не вырезана из конвейера -- прибор не мерит"; return
  fi
  out=$(tools_door_run "$d" notsc Linux нет_codesign tsc); rc=$?
  LAST_EVID="rc=$rc заглушено:[${DOOR_STUBBED:-}] [$(printf '%s' "$out" | tr '\n' '|')]"
  if (( rc == 9 )); then
    bad "178 дверь инструментов: вырезанные куски не подгрузились -- прибор не мерит"; return
  fi
  if (( rc != 6 )); then
    LAST_EVID="TSC_НЕ_ОБЯЗАТЕЛЕН :: $LAST_EVID"
    bad "178 дверь инструментов: без tsc дверь прошла (rc=$rc), а разбор имён зовётся безусловно"; return
  fi
  if [[ "$out" != *"tsc"* ]]; then
    LAST_EVID="TSC_НЕ_НАЗВАН :: $LAST_EVID"
    bad "178 дверь инструментов: отказ есть, но tsc в нём не назван"; return
  fi
  ok "178 обязательные инструменты: отсутствующий tsc назван дверью по имени"
}

# --- обёртка окружения форка (#101, решение юзера) ----------------------------
# Предмет: кит САМ подставляет форку `NODE_USE_ENV_PROXY=1`, когда в окружении
# задан прокси, ОБЪЯВЛЯЕТ подстановку отдельной строкой лога и умеет от неё
# отказаться по ручке. Обещаний юзеру три -- подставить, объявить, дать отказ, --
# и у каждого свой сценарий: слитая проверка зеленела бы, потеряв любое из них.
#
# Смотрится ЖИВАЯ вырезка функции из конвейера, а не пересказ правила в стенде:
# вторая копия правила расходится с оригиналом молча (урок волны 45).
#
# Сеть не нужна и не трогается: функция только СОБИРАЕТ массив запуска, ничего
# им не исполняя. Драйвер печатает получившуюся команду -- по ней и судим.
PROXY_FUNCS=(__tw_node_proxy_wrap)

proxy_prepare() {   # имя каталога сценария
  PROXY_D="$C/$1"; rm -rf "$PROXY_D"; mkdir -p "$PROXY_D"
  PROXY_CARVED=0
  local name
  for name in "${PROXY_FUNCS[@]}"; do
    awk -v h="${name}() {" 'index($0, h) == 1 {on=1} on {print} on && $0 == "}" {exit}' \
      "$K/claude-patch-all.real" > "$PROXY_D/$name.sh"
    [[ -s "$PROXY_D/$name.sh" ]] && PROXY_CARVED=$((PROXY_CARVED+1))
  done
  cat > "$PROXY_D/drv.sh" <<'PRXDRV'
set -euo pipefail
source "$1"
TWEAKCC=(node /dev/null)
__tw_node_proxy_wrap
printf 'КОМАНДА: %s\n' "${TWEAKCC[*]}"
PRXDRV
}

proxy_carved_or_bad() {   # номер сценария
  (( PROXY_CARVED == ${#PROXY_FUNCS[@]} )) && return 0
  LAST_EVID="ФРАГМЕНТ_НЕ_ВЫРЕЗАН вырезано=$PROXY_CARVED из ${#PROXY_FUNCS[@]}"
  bad "$1 обёртка прокси: фрагмент не вырезан -- прибор смотрит не туда"
  return 1
}

proxy_call() {   # [ПЕРЕМЕННАЯ=значение ...]
  # Окружение СТИРАЕТСЯ и задаётся заново. Иначе ветка «прокси нет» мерила бы
  # окружение хозяина: на usbox прокси задан по-настоящему, и там отрицательный
  # контроль был бы зелёным по совпадению. Прибор наследует состояние
  # вызывающего -- это уже стоило двух дефектов (#100 и его родня).
  PROXY_OUT=$(env -u https_proxy -u HTTPS_PROXY -u http_proxy -u HTTP_PROXY \
                  -u all_proxy -u ALL_PROXY -u NODE_USE_ENV_PROXY \
                  -u CATALYST_TWEAKCC_NO_ENV_PROXY "$@" \
              bash "$PROXY_D/drv.sh" "$PROXY_D/__tw_node_proxy_wrap.sh" 2>&1 9>&-)
  PROXY_RC=$?
  LAST_EVID="rc=$PROXY_RC :: $(printf '%s' "$PROXY_OUT" | tr '\n' '|')"
}

proxy_wrapped() {   # 0 -- в собранной команде есть обёртка окружения
  [[ "$PROXY_OUT" == *"КОМАНДА: env NODE_USE_ENV_PROXY=1 node"* ]]
}

scenario_179() {   # прокси задан -- ручка ПОДСТАВЛЕНА в команду запуска
  proxy_prepare s179; proxy_carved_or_bad 179 || return
  proxy_call https_proxy=http://127.0.0.1:3128
  if ! proxy_wrapped; then
    LAST_EVID="ОБЁРТКА_НЕ_ПОСТАВЛЕНА :: $LAST_EVID"
    bad "179 обёртка прокси: https_proxy задан, а ручка форку не подставлена"; return
  fi
  ok "179 обёртка прокси: при заданном прокси ручка подставлена в команду запуска"
}

scenario_180() {   # подстановка ОБЪЯВЛЕНА, и объявление НАЗЫВАЕТ выключатель
  # Половина решения юзера -- именно объявление: молчаливая правка окружения
  # чужого процесса делает разбор прогона по логу несходящимся. Объявление без
  # имени выключателя тоже неполно: знать о подстановке и не мочь её снять --
  # то же самое, что не знать.
  proxy_prepare s180; proxy_carved_or_bad 180 || return
  proxy_call https_proxy=http://127.0.0.1:3128
  if [[ "$PROXY_OUT" != *"ПОДСТАВЛЕН"* ]]; then
    LAST_EVID="ПОДСТАНОВКА_НЕ_ОБЪЯВЛЕНА :: $LAST_EVID"
    bad "180 обёртка прокси: подставили молча -- в логе нет строки о подстановке"; return
  fi
  if [[ "$PROXY_OUT" != *"CATALYST_TWEAKCC_NO_ENV_PROXY"* ]]; then
    LAST_EVID="ВЫКЛЮЧАТЕЛЬ_НЕ_НАЗВАН :: $LAST_EVID"
    bad "180 обёртка прокси: подстановка объявлена, но выключатель не назван"; return
  fi
  ok "180 обёртка прокси: подстановка объявлена и выключатель назван по имени"
}

scenario_181() {   # выключатель ОТКАЗЫВАЕТ подстановку и говорит, чем это грозит
  proxy_prepare s181; proxy_carved_or_bad 181 || return
  proxy_call https_proxy=http://127.0.0.1:3128 CATALYST_TWEAKCC_NO_ENV_PROXY=1
  if proxy_wrapped; then
    LAST_EVID="ВЫКЛЮЧАТЕЛЬ_НЕ_РАБОТАЕТ :: $LAST_EVID"
    bad "181 обёртка прокси: выключатель поднят, а ручка всё равно подставлена"; return
  fi
  if [[ "$PROXY_OUT" != *"ОТКЛЮЧЕНА"* ]]; then
    LAST_EVID="ОТКАЗ_НЕ_ОБЪЯВЛЕН :: $LAST_EVID"
    bad "181 обёртка прокси: отказались молча -- в логе нет строки об отключении"; return
  fi
  ok "181 обёртка прокси: выключатель снимает подстановку и объявляет отказ"
}

scenario_182() {   # ручку задал ОПЕРАТОР -- кит поверх неё не пишет
  # Значение берётся `0`, то есть явный ЗАПРЕТ: подстановка `1` поверх него
  # была бы не помощью, а тихой отменой решения оператора. Поэтому проверяется
  # не «значение сохранилось», а «обёртки нет».
  proxy_prepare s182; proxy_carved_or_bad 182 || return
  proxy_call https_proxy=http://127.0.0.1:3128 NODE_USE_ENV_PROXY=0
  if proxy_wrapped; then
    LAST_EVID="ОПЕРАТОР_ПЕРЕЗАПИСАН :: $LAST_EVID"
    bad "182 обёртка прокси: оператор задал ручку сам, а кит подставил свою"; return
  fi
  if [[ "$PROXY_OUT" != *"ОПЕРАТОРОМ"* ]]; then
    LAST_EVID="ОПЕРАТОР_НЕ_НАЗВАН :: $LAST_EVID"
    bad "182 обёртка прокси: ручку оператора уважили, но в логе это не названо"; return
  fi
  ok "182 обёртка прокси: ручка оператора уважена, включая явный запрет"
}

scenario_183() {   # прокси в окружении НЕТ -- ни обёртки, ни строки в логе
  # Отрицательный контроль. Без него мутация, включающая подстановку ВСЕГДА,
  # оставалась бы незамеченной: остальные сценарии задают прокси и потому
  # зеленели бы и на всегда-подставляющей ветке.
  proxy_prepare s183; proxy_carved_or_bad 183 || return
  proxy_call
  if proxy_wrapped; then
    LAST_EVID="ПОДСТАВИЛИ_БЕЗ_ПРОКСИ :: $LAST_EVID"
    bad "183 обёртка прокси: прокси в окружении нет, а ручка подставлена"; return
  fi
  if [[ "$PROXY_OUT" == *"Прокси node:"* ]]; then
    LAST_EVID="ЛИШНЯЯ_СТРОКА :: $LAST_EVID"
    bad "183 обёртка прокси: прокси нет, а лог всё равно о нём говорит"; return
  fi
  ok "183 обёртка прокси: без прокси ни обёртки, ни лишней строки в логе"
}

scenario_184() {   # САЙТ ВЫЗОВА: конвейер действительно зовёт обёртку
  # Сценарии 179-183 смотрят ФУНКЦИЮ. Функция может быть безупречной и просто
  # не зваться -- тогда кит молча перестаёт подставлять ручку, а стенд остаётся
  # зелёным. Поэтому здесь исполняется НАСТОЯЩИЙ верхнеуровневый кусок
  # конвейера, вырезанный по якорю: сборка массива и вызов обёртки следом.
  #
  # `ensure_tweakcc` подменяется заглушкой намеренно: её предмет -- сеть и кэш
  # распаковщика, к этому зубу отношения не имеющие. Предмет здесь ровно один --
  # ЗВАЛИ ли обёртку после того, как массив собран.
  local d out rc
  d="$C/s184"; rm -rf "$d"; mkdir -p "$d"
  awk -v h='__tw_node_proxy_wrap() {' 'index($0, h) == 1 {on=1} on {print} on && $0 == "}" {exit}' \
    "$K/claude-patch-all.real" > "$d/func.sh"
  # Кусок кончается ПУСТОЙ строкой -- ею он отделён от следующей стадии.
  awk '/^ensure_tweakcc$/{on=1} on{if ($0 == "") exit; print}' \
    "$K/claude-patch-all.real" > "$d/site.sh"
  if [[ ! -s "$d/func.sh" || ! -s "$d/site.sh" ]]; then
    LAST_EVID="ЯКОРЬ_ПОТЕРЯН func=$(wc -c <"$d/func.sh") site=$(wc -c <"$d/site.sh")"
    bad "184 сайт вызова обёртки: куски не вырезаны -- прибор смотрит не туда"; return
  fi
  cat > "$d/drv.sh" <<'SITEDRV'
set -euo pipefail
source "$1"
# Заглушка распаковщика: массив собран, сеть и кэш не трогаются.
ensure_tweakcc() { TWEAKCC=(node /dev/null); }
source "$2"
printf 'КОМАНДА: %s\n' "${TWEAKCC[*]}"
SITEDRV
  out=$(env -u https_proxy -u HTTPS_PROXY -u http_proxy -u HTTP_PROXY \
            -u all_proxy -u ALL_PROXY -u NODE_USE_ENV_PROXY \
            -u CATALYST_TWEAKCC_NO_ENV_PROXY https_proxy=http://127.0.0.1:3128 \
        bash "$d/drv.sh" "$d/func.sh" "$d/site.sh" 2>&1 9>&-); rc=$?
  LAST_EVID="rc=$rc :: $(printf '%s' "$out" | tr '\n' '|')"
  if [[ "$out" != *"КОМАНДА: env NODE_USE_ENV_PROXY=1 node"* ]]; then
    LAST_EVID="ОБЁРТКА_НЕ_ЗВАЛАСЬ :: $LAST_EVID"
    bad "184 сайт вызова обёртки: массив собран, а обёртку конвейер не позвал"; return
  fi
  ok "184 сайт вызова обёртки: конвейер зовёт обёртку сразу после сборки массива"
}

scenario_153() {   # ветка «вышел без отрисовки» ДОСТИЖИМА
  gate_prepare s153
  gate_carved_or_bad 153 || return
  gate_call a ul 5
  LAST_EVID="rc=$GATE_RC :: $(printf '%s' "$GATE_OUT" | tr '\n' '|')"
  if [[ "$GATE_OUT" != *"exited 1 without drawing anything"* ]]; then
    LAST_EVID="ВЕТКА_БЕЗ_ОТРИСОВКИ_НЕДОСТУПНА :: $LAST_EVID"
    bad "153 вердикт: мгновенная смерть ребёнка не названа своей строкой"; return
  fi
  if (( GATE_RC == 0 )); then
    LAST_EVID="ОТКАЗ_НЕ_ОТКАЗ :: $LAST_EVID"
    bad "153 вердикт: стадия объявила успех на умершем без отрисовки ребёнке"; return
  fi
  ok "153 вердикт: вышел кодом 1 без отрисовки -- своей строкой"
}

scenario_154() {   # ветка «отрисовал и умер» ДОСТИЖИМА
  # Смерть наступает ПОСЛЕ первой отрисовки, поэтому её ловит цикл добора --
  # вторая площадка `wait`, у которой своя мутация.
  gate_prepare s154
  gate_carved_or_bad 154 || return
  gate_call b ul 12
  LAST_EVID="rc=$GATE_RC :: $(printf '%s' "$GATE_OUT" | tr '\n' '|')"
  if [[ "$GATE_OUT" != *"drew its message and then exited 1"* ]]; then
    LAST_EVID="ВЕТКА_ОТРИСОВАЛ_И_УМЕР_НЕДОСТУПНА :: $LAST_EVID"
    bad "154 вердикт: смерть после отрисовки не названа своей строкой"; return
  fi
  if (( GATE_RC == 0 )); then
    LAST_EVID="ОТКАЗ_НЕ_ОТКАЗ :: $LAST_EVID"
    bad "154 вердикт: стадия объявила успех на умершем после отрисовки ребёнке"; return
  fi
  ok "154 вердикт: отрисовал и умер кодом 1 -- своей строкой"
}

scenario_155() {   # ветка «не дошёл до отрисовки» ДОСТИЖИМА и не подменена
  gate_prepare s155
  gate_carved_or_bad 155 || return
  gate_call c ul 3
  LAST_EVID="rc=$GATE_RC :: $(printf '%s' "$GATE_OUT" | tr '\n' '|')"
  if [[ "$GATE_OUT" != *"never reached a render within 3s"* ]]; then
    LAST_EVID="ВЕТКА_ТАЙМАУТА_ПОДМЕНЕНА :: $LAST_EVID"
    bad "155 вердикт: молчащий живой ребёнок не назван таймаутом бюджета"; return
  fi
  if (( GATE_RC == 0 )); then
    LAST_EVID="ОТКАЗ_НЕ_ОТКАЗ :: $LAST_EVID"
    bad "155 вердикт: стадия объявила успех, не дождавшись отрисовки"; return
  fi
  ok "155 вердикт: живой, но молчащий ребёнок -- таймаут своей строкой"
}

scenario_156() {   # ветка успеха: вердикт назван и временный дом СНЯТ
  gate_prepare s156
  gate_carved_or_bad 156 || return
  gate_call d ul 12
  LAST_EVID="rc=$GATE_RC дом=$([[ -d "$GATE_H" ]] && echo есть || echo снят) :: $(printf '%s' "$GATE_OUT" | tr '\n' '|')"
  if (( GATE_RC != 0 )) || [[ "$GATE_OUT" != *"came up in a throwaway home"* ]]; then
    LAST_EVID="ВЕРДИКТ_НЕ_УСПЕХ :: $LAST_EVID"
    bad "156 вердикт: живой отрисовавший ребёнок не признан успехом"; return
  fi
  if [[ -d "$GATE_H" ]]; then
    LAST_EVID="ДОМ_НЕ_СНЯТ :: $LAST_EVID"
    bad "156 вердикт: успех оставил временный дом гейта"; return
  fi
  ok "156 вердикт: отрисовал и жив -- успех, дом гейта снят"
}

scenario_157() {   # красный блок проверок отвечает СВОИМ кодом
  # Две половины, и вторая -- ФОРМА, прочитанная из копии кита. Замер (linux,
  # bash 5.2.26): при ненулевом питоне обрыв по `set -e` отдаёт ТОТ ЖЕ код, что
  # и честный хвост, -- различить их снаружи нечем. Отличается ГАРАНТИЯ:
  # отметка `__DONE` не ставится, и часовой оборванного прогона (он и написан
  # для оболочки, которая теряет код) начинает решать судьбу красного блока
  # кодом, который сам же и не контролирует. Поэтому поведение здесь -- ПОЛОЖИ-
  # ТЕЛЬНЫЙ КОНТРОЛЬ (код блока доехал, строки обрыва нет), а зуб держит форма.
  local out rc form
  printf 'не образ\n' > "$C/s157.img"
  out=$(bash "$K/tools/checks-on-image.sh" --script "$K/claude-patch-all.real" \
          "$C/s157.img" "$K/tweakcc-patch.js" 2>&1 9>&-); rc=$?
  form=$(grep -cF 'python3 "$BLOCK" "$IMG" "$PATCH_SRC" || __rc_block=$?' \
           "$K/tools/checks-on-image.sh")
  LAST_EVID="rc=$rc форма=$form :: $(printf '%s' "$out" | tail -3 | tr '\n' '|')"
  if (( rc != 1 )); then
    LAST_EVID="КОД_НЕ_КОД_БЛОКА :: $LAST_EVID"
    bad "157 checks-on-image: красный блок ответил не своим кодом"; return
  fi
  if [[ "$out" == *"прогон оборвался, не дойдя до конца"* ]]; then
    LAST_EVID="ОБЪЯВЛЕН_ОБРЫВ :: $LAST_EVID"
    bad "157 checks-on-image: красный блок назван обрывом прогона"; return
  fi
  if [[ "$form" != "1" ]]; then
    LAST_EVID="ФОРМА_КОДА_БЛОКА_СНЯТА :: $LAST_EVID"
    bad "157 checks-on-image: код блока снимается формой, обрывающей стадию"; return
  fi
  ok "157 checks-on-image: красный блок отвечает своим кодом, хвост стадии достижим"
}

# --- волна 40c: платформа как ЯВНАЯ ось (#80) --------------------------------
# Один вывод платформы обслуживал ЧЕТЫРЕ вопроса (какой пакет качать, можно ли
# подписать, можно ли запустить, относится ли пин), и на машине, где хозяин и
# цель расходятся, три из них отвечались про не ту сторону. Ниже -- по зубу на
# каждое разведённое сравнение.

# Детектор платформы образа гоняется на СИНТЕТИЧЕСКИХ заголовках: наши корпуса
# несут только Mach-O arm64 и ELF x86-64, а разбор обязан отвечать за все формы,
# которые он берётся называть. Заголовок строится здесь, а не хранится файлом:
# двоичная фикстура в дереве -- это байты, которых никто не перечитывает.
cp_img_probe() {   # путь-образа -> печатает пару либо «ОТКАЗ <код> <причина>»
  CPK="$K" CPI="$1" python3 - <<'PROBE40C'
import os, sys, subprocess
snippet = (
    "import sys;sys.path.insert(0,%r);import claude_patch,pathlib;"
    "print('%%s-%%s' %% claude_patch.image_os_arch(pathlib.Path(sys.argv[1])))"
    % os.environ['CPK'])
r = subprocess.run([sys.executable, '-c', snippet, os.environ['CPI']],
                   capture_output=True, text=True)
if r.returncode == 0:
    sys.stdout.write(r.stdout.strip() + '\n')
else:
    sys.stdout.write('ОТКАЗ %d %s\n' % (r.returncode, r.stderr.strip().replace('\n', ' ')))
PROBE40C
}

cp_mkhead() {   # путь, форма
  CPP="$1" CPF="$2" python3 - <<'HEAD40C'
import os, struct
form, path = os.environ['CPF'], os.environ['CPP']
if form == 'macho-arm64':  b = b"\xcf\xfa\xed\xfe" + struct.pack('<I', 0x0100000C)
elif form == 'macho-x64':  b = b"\xcf\xfa\xed\xfe" + struct.pack('<I', 0x01000007)
elif form == 'elf-x64':    b = b"\x7fELF\x02\x01\x01" + b"\0" * 11 + struct.pack('<H', 0x3E)
elif form == 'elf-arm64':  b = b"\x7fELF\x02\x01\x01" + b"\0" * 11 + struct.pack('<H', 0xB7)
elif form.startswith('pe-'):
    machine = 0x8664 if form == 'pe-x64' else 0xAA64
    head = bytearray(b"MZ" + b"\0" * 0x3E)
    head[0x3C:0x40] = struct.pack('<I', 0x40)
    b = bytes(head) + b"PE\0\0" + struct.pack('<H', machine)
elif form == 'fat-magic':     b = b"\xca\xfe\xba\xbe"
elif form == 'fat-cigam':     b = b"\xbe\xba\xfe\xca"
elif form == 'fat-magic64':   b = b"\xca\xfe\xba\xbf"
elif form == 'fat-cigam64':   b = b"\xbf\xba\xfe\xca"
elif form == 'мусор':         b = b"\x01\x02\x03\x04garbage"
else:                         raise SystemExit('неизвестная форма %s' % form)
open(path, 'wb').write(b + b"\0" * 256)
HEAD40C
}

scenario_158() {   # Т1: пара ЦЕЛИ читается из ОБРАЗА, и детектор не слеп
  local d form got want bad_forms="" answer
  d="$C/s158"; rm -rf "$d"; mkdir -p "$d"
  for form in macho-arm64:darwin-arm64 macho-x64:darwin-x64 \
              elf-x64:linux-x64 elf-arm64:linux-arm64 \
              pe-x64:win32-x64 pe-arm64:win32-arm64; do
    want="${form#*:}"; form="${form%%:*}"
    cp_mkhead "$d/$form.img" "$form"
    got=$(cp_img_probe "$d/$form.img")
    [[ "$got" == "$want" ]] || bad_forms="$bad_forms ${form}(ждали ${want}, было «${got}»)"
  done
  # Положительный контроль: детектор, который принимает ВСЁ, доказывал бы лишь
  # то, что он что-то печатает.
  cp_mkhead "$d/garbage.img" 'мусор'
  answer=$(cp_img_probe "$d/garbage.img")
  LAST_EVID="формы:${bad_forms:- все сошлись} мусор=[$answer]"
  if [[ -n "$bad_forms" ]]; then
    LAST_EVID="ПАРА_НЕ_ТА :: $LAST_EVID"
    bad "158 детектор платформы: пара не та --$bad_forms"; return
  fi
  if [[ "$answer" != "ОТКАЗ 1 "* ]]; then
    LAST_EVID="ДЕТЕКТОР_СЛЕП :: $LAST_EVID"
    bad "158 детектор платформы: мусорный заголовок принят, а обязан отказать"; return
  fi
  ok "158 детектор платформы: шесть форм дают свою пару, мусор отвергнут"
}

scenario_159() {   # Т2: универсальный образ -- ОТКАЗ с причиной, а не догадка
  # Все ЧЕТЫРЕ формы: FAT_MAGIC и FAT_MAGIC_64 лежат big-endian, FAT_CIGAM и
  # FAT_CIGAM_64 -- их переставленные близнецы. Разбор, знающий часть из них,
  # называет остальные «не образом» -- верный отказ по неверной причине.
  local d form answer bad_forms=""
  d="$C/s159"; rm -rf "$d"; mkdir -p "$d"
  for form in fat-magic fat-cigam fat-magic64 fat-cigam64; do
    cp_mkhead "$d/$form.img" "$form"
    answer=$(cp_img_probe "$d/$form.img")
    [[ "$answer" == "ОТКАЗ 1 "*"universal (fat)"* ]] \
      || bad_forms="$bad_forms ${form}([${answer}])"
  done
  LAST_EVID="${bad_forms:-все четыре формы отвергнуты своей причиной}"
  if [[ -n "$bad_forms" ]]; then
    LAST_EVID="FAT_ПРИЧИНА_НЕ_НАЗВАНА :: $LAST_EVID"
    bad "159 fat-образ: причина не названа --$bad_forms"; return
  fi
  ok "159 fat-образ: все четыре формы -- отказ кода 1 с названной причиной"
}

scenario_160() {   # Т3: musl невидим детектору, но не сравнению имён пакетов
  local out
  out=$(CPK="$K" python3 - <<'MATCH40C'
import os, sys
sys.path.insert(0, os.environ['CPK'])
import claude_patch as c
p = '@anthropic-ai/claude-code-'
print('musl=%s чужая=%s своя=%s' % (
    c.platform_matches(p + 'linux-x64-musl', ('linux', 'x64')),
    c.platform_matches(p + 'darwin-arm64', ('linux', 'x64')),
    c.platform_matches(p + 'linux-x64', ('linux', 'x64'))))
MATCH40C
)
  LAST_EVID="$out"
  if [[ "$out" != *"musl=True"* ]]; then
    LAST_EVID="MUSL_НЕ_СОШЁЛСЯ :: $LAST_EVID"
    bad "160 platform_matches: musl-пакет не сошёлся со своей парой"; return
  fi
  if [[ "$out" != *"чужая=False"* || "$out" != *"своя=True"* ]]; then
    LAST_EVID="ЧУЖАЯ_ПАРА_СОШЛАСЬ :: $LAST_EVID"
    bad "160 platform_matches: сравнение не различает платформы"; return
  fi
  ok "160 platform_matches: -musl отброшен, чужая пара не сошлась"
}

scenario_161() {   # Т5: отказ по ПИНУ сохраняется -- он верен
  # Регрессия: разведение предметов не должно снять дверь, которая права.
  # Пин привязан к ПОЛНОМУ имени пакета, и darwin-пин к linux-образу не
  # относится, кто бы про него ни спрашивал.
  local out rc
  { echo "# platform: @anthropic-ai/claude-code-darwin-arm64"
    echo "900 0.0.900 -"; } > "$C/s161.txt"
  out=$(python3 "$K/tools/corpus-list.py" "$C/s161.txt" \
          @anthropic-ai/claude-code-linux-x64 2>&1 9>&-); rc=$?
  LAST_EVID="rc=$rc :: $out"
  if (( rc != 1 )); then
    LAST_EVID="ПИН_ДВЕРЬ_СНЯТА :: $LAST_EVID"
    bad "161 чужая цель: код возврата $rc, ждали 1"; return
  fi
  if [[ "$out" != *"список набран для платформы"* \
     || "$out" != *"darwin-arm64"* || "$out" != *"linux-x64"* ]]; then
    LAST_EVID="ПРИЧИНА_НЕ_НАЗВАНА :: $LAST_EVID"
    bad "161 чужая цель: отказ не назвал обе платформы: $out"; return
  fi
  ok "161 чужая цель: отказ по пину сохранён и называет обе платформы"
}

scenario_162() {   # Т6: своя цель, названная ЯВНО, проходит -- снятое ограничение
  # До волны список darwin-корпуса на linux-хозяине отвергался ВСЕГДА, даже
  # когда спрашивали именно про darwin: сравнение брало хозяина, а спрашивали
  # про цель. Здесь цель названа явно и совпадает с объявлением списка.
  local out rc
  { echo "# platform: @anthropic-ai/claude-code-darwin-arm64"
    echo "900 0.0.900 -"; } > "$C/s162.txt"
  out=$(python3 "$K/tools/corpus-list.py" "$C/s162.txt" \
          @anthropic-ai/claude-code-darwin-arm64 2>&1 9>&-); rc=$?
  LAST_EVID="rc=$rc :: $(printf '%s' "$out" | tr '\n' '|')"
  if (( rc != 0 )) || [[ "$out" != *"0.0.900"* ]]; then
    LAST_EVID="СВОЯ_ЦЕЛЬ_ОТВЕРГНУТА :: $LAST_EVID"
    bad "162 своя цель: разбор не прошёл (rc=$rc)"; return
  fi
  ok "162 чужая платформа читается, когда про неё и спрашивают"
}

# Дверь обязательных инструментов вырезается ИЗ КОНВЕЙЕРА по якорям и гоняется
# на подставном `uname`: обе её ветки обязаны быть достижимы с ОДНОЙ машины,
# иначе зуб доказывал бы лишь свойство хозяина, на котором запущен стенд.
tools_door_carve() {   # каталог -> печатает число вырезанных кусков
  local dir="$1" n=0 name
  for name in __host_os_arch __host_needs_codesign; do
    awk -v h="${name}() {" 'index($0, h) == 1 {on=1} on {print} on && $0 == "}" {exit}' \
      "$K/claude-patch-all.real" > "$dir/$name.sh"
    [[ -s "$dir/$name.sh" ]] && n=$((n+1))
  done
  # __host_os -- ОДНОСТРОЧНОЕ определение: закрывающей строки `}` у него нет,
  # и общий цикл выше вырезал бы пустоту.
  awk 'index($0, "__host_os()") == 1 {print; exit}' \
    "$K/claude-patch-all.real" > "$dir/__host_os.sh"
  [[ -s "$dir/__host_os.sh" ]] && n=$((n+1))
  # Сам БЛОК двери -- не пересказ, а те же строки конвейера: копия правила в
  # стенде разошлась бы с ним молча. Блок кончается ВТОРЫМ `fi` с начала строки.
  awk '/^MISSING=\(\)$/{on=1} on{print; if ($0 == "fi") {c++; if (c == 2) exit}}' \
    "$K/claude-patch-all.real" > "$dir/door.sh"
  [[ -s "$dir/door.sh" ]] && n=$((n+1))
  printf '%s\n' "$n"
}

tools_door_run() {   # каталог карвинга, имя прогона, ОС хозяина, «нет codesign»?
  # Куски берутся из каталога КАРВИНГА, а прогонное хозяйство кладётся в свой
  # подкаталог. Прежняя редакция искала куски внутри прогонного каталога, все
  # четыре `source` молча не находили файла, и дверь проходила БЕЗ механизма --
  # то есть зуб зеленел, ничего не измерив (поймано первым же прогоном на
  # linux). Поэтому `source` теперь обязан удаться: неудача -- код 9, отдельный
  # от любого ответа двери.
  local carve="$1" dir="$1/$2" host="$3" nocs="${4:-}"
  mkdir -p "$dir/stub"
  { printf '#!/usr/bin/env bash\n'
    printf 'case "${1:-}" in\n'
    printf '  -s) printf "%%s\\n" "$FAKE_UNAME_S" ;;\n'
    printf '  -m) printf "x86_64\\n" ;;\n'
    printf '  *)  printf "%%s\\n" "$FAKE_UNAME_S" ;;\n'
    printf 'esac\n'
  } > "$dir/stub/uname"
  chmod +x "$dir/stub/uname"
  # Подставной `codesign` кладётся ОТДЕЛЬНЫМ каталогом: положительный контроль
  # снимает именно его, оставляя всё прочее на месте.
  mkdir -p "$dir/cs"
  printf '#!/usr/bin/env bash\nexit 0\n' > "$dir/cs/codesign"
  chmod +x "$dir/cs/codesign"
  # PATH СТРОИТСЯ, а не наследуется. Прежняя редакция дописывала настоящий
  # $PATH, и на darwin-хозяине положительный контроль «без codesign» находил
  # СИСТЕМНЫЙ /usr/bin/codesign: дверь честно проходила, сценарий краснел, и
  # мерил он не дверь, а машину, на которой запущен. Измерено 10.09 на маке:
  # с унаследованным PATH контроль даёт rc=0 ДВЕРЬ_ПРОЙДЕНА, с построенным --
  # rc=6 с именем codesign. Корень тот же, что у #100: прибор наследует
  # состояние вызывающего.
  #
  # Перечень берётся ИЗ ВЫРЕЗАННОГО БЛОКА, а не пишется здесь руками: вторая
  # копия списка разошлась бы с конвейером молча, и «все инструменты на месте»
  # означало бы «на месте те, что помнил автор стенда».
  mkdir -p "$dir/bin"
  local __t __p __omit="${5:-}"
  DOOR_STUBBED=""
  for __t in $(awk -F'[()]' '/^REQUIRED_TOOLS=\(/{print $2}' "$carve/door.sh") bash; do
    # codesign кладётся ТОЛЬКО отдельным каталогом ниже -- иначе снять его
    # контролем было бы нечем.
    if [[ "$__t" == codesign ]]; then continue; fi
    # Названный пятым аргументом инструмент СНИМАЕТСЯ: так положительный
    # контроль проверяет, что дверь называет именно его, а не «что-нибудь».
    if [[ -n "$__omit" && "$__t" == "$__omit" ]]; then continue; fi
    if __p=$(type -P "$__t"); then
      ln -sf "$__p" "$dir/bin/$__t"
    elif [[ "$__t" == bash ]]; then
      # bash здесь ИСПОЛНЯЕТСЯ -- под ним идёт драйвер, заглушкой не подменить.
      echo "НЕТ_BASH_НА_ХОЗЯИНЕ" >&2; return 9
    else
      # Отсутствующий на хозяине инструмент ЗАГЛУШАЕТСЯ, а не пропускается.
      # Дверь спрашивает только `command -v`, ничего не исполняя, а предмет
      # сценария -- ось codesign, не оснащённость машины. Пропуск делал бы
      # сценарий красным там, где инструмента просто нет: замерено 10.09,
      # `tsc` отсутствует в неинтерактивном PATH usbox. Что заглушено --
      # объявляется в следе, а не молчит.
      printf '#!/usr/bin/env bash\nexit 0\n' > "$dir/bin/$__t"
      chmod +x "$dir/bin/$__t"
      DOOR_STUBBED="$DOOR_STUBBED $__t"
    fi
  done
  local path="$dir/stub:$dir/bin"
  [[ -n "$nocs" ]] || path="$dir/cs:$path"
  { printf 'set -u\n'
    printf 'source %q || exit 9\n' "$carve/__host_os_arch.sh"
    printf 'source %q || exit 9\n' "$carve/__host_os.sh"
    printf 'source %q || exit 9\n' "$carve/__host_needs_codesign.sh"
    printf 'declare -F __host_needs_codesign >/dev/null || exit 9\n'
    printf 'source %q\n' "$carve/door.sh"
    printf 'echo ДВЕРЬ_ПРОЙДЕНА\n'
  } > "$dir/drv.sh"
  FAKE_UNAME_S="$host" PATH="$path" bash "$dir/drv.sh" 2>&1 9>&-
}

scenario_163() {   # Т7: codesign требуется ТОГДА И ТОЛЬКО ТОГДА, когда хозяин darwin
  local d carved out_lin rc_lin out_dar rc_dar out_ctl rc_ctl
  d="$C/s163"; rm -rf "$d"; mkdir -p "$d"
  carved=$(tools_door_carve "$d")
  if [[ "$carved" != "4" ]]; then
    LAST_EVID="ЯКОРЬ_ПОТЕРЯН вырезано=$carved из 4"
    bad "163 дверь инструментов: не вырезана из конвейера -- прибор не мерит"; return
  fi
  out_lin=$(tools_door_run "$d" lin Linux нет_codesign); rc_lin=$?
  out_dar=$(tools_door_run "$d" dar Darwin); rc_dar=$?
  out_ctl=$(tools_door_run "$d" ctl Darwin нет_codesign); rc_ctl=$?
  if (( rc_lin == 9 || rc_dar == 9 || rc_ctl == 9 )); then
    LAST_EVID="ФРАГМЕНТ_НЕ_ПОДГРУЖЕН rc=$rc_lin/$rc_dar/$rc_ctl"
    bad "163 дверь инструментов: вырезанные куски не подгрузились -- прибор не мерит"; return
  fi
  LAST_EVID="linux rc=$rc_lin [$(printf '%s' "$out_lin" | tr '\n' '|')] darwin rc=$rc_dar ctl rc=$rc_ctl [$(printf '%s' "$out_ctl" | tr '\n' '|')]"
  if (( rc_lin != 0 )) || [[ "$out_lin" != *"ДВЕРЬ_ПРОЙДЕНА"* ]]; then
    LAST_EVID="ДВЕРЬ_CODESIGN_НЕ_ТА :: $LAST_EVID"
    bad "163 дверь инструментов: на linux-хозяине БЕЗ codesign не прошла"; return
  fi
  if (( rc_dar != 0 )) || [[ "$out_dar" != *"ДВЕРЬ_ПРОЙДЕНА"* ]]; then
    LAST_EVID="ДВЕРЬ_CODESIGN_НЕ_ТА :: $LAST_EVID"
    bad "163 дверь инструментов: на darwin-хозяине С codesign не прошла"; return
  fi
  # Положительный контроль: без него зуб доказывал бы лишь то, что дверь
  # выключена всегда.
  if (( rc_ctl != 6 )) || [[ "$out_ctl" != *"codesign"* ]]; then
    LAST_EVID="ДВЕРЬ_ВЫКЛЮЧЕНА_ВСЕГДА :: $LAST_EVID"
    bad "163 дверь инструментов: darwin-хозяин без codesign прошёл (rc=$rc_ctl)"; return
  fi
  ok "163 дверь инструментов: codesign нужен ровно на darwin-хозяине"
}

scenario_164() {   # Т8: гейт ПРОПУСКАЕТСЯ на чужой паре и НЕ пропускается на своей
  local out_skip rc_skip launch_skip
  gate_prepare s164
  gate_carved_or_bad 164 || return
  gate_call e ul 5 "win32-arm64"; out_skip="$GATE_OUT"; rc_skip=$GATE_RC
  launch_skip=$(gate_launch_line)
  LAST_EVID="чужая rc=$rc_skip запуск=[$launch_skip] [$(printf '%s' "$out_skip" | tr '\n' '|')]"
  if (( rc_skip != 0 )) || [[ "$out_skip" != *"Гейт интерфейса ПРОПУЩЕН"* ]]; then
    LAST_EVID="ПРОПУСК_НЕ_ОБЪЯВЛЕН :: $LAST_EVID"
    bad "164 гейт: чужая пара не объявлена пропуском"; return
  fi
  if [[ "$out_skip" != *"win32-arm64"* ]]; then
    LAST_EVID="ПРОПУСК_НЕ_НАЗВАЛ_СТОРОНЫ :: $LAST_EVID"
    bad "164 гейт: пропуск не назвал обе стороны"; return
  fi
  if [[ -n "$launch_skip" ]]; then
    LAST_EVID="ПРОПУСК_ВСЁ_РАВНО_ЗАПУСТИЛ :: $LAST_EVID"
    bad "164 гейт: путь пропуска всё-таки позвал script"; return
  fi
  # Положительный контроль: без него пропуск незаметно стал бы умолчанием на
  # любой машине.
  gate_call e ul 5
  LAST_EVID="$LAST_EVID ;; своя rc=$GATE_RC [$(printf '%s' "$GATE_OUT" | tr '\n' '|')]"
  if [[ "$GATE_OUT" == *"Гейт интерфейса ПРОПУЩЕН"* ]] \
     || (( GATE_RC != 0 )) || [[ "$GATE_OUT" != *"came up in a throwaway home"* ]]; then
    LAST_EVID="ПРОПУСК_СТАЛ_УМОЛЧАНИЕМ :: $LAST_EVID"
    bad "164 гейт: своя пара тоже пропущена -- гейт не меряет ничего"; return
  fi
  ok "164 гейт интерфейса: чужая пара -- объявленный пропуск, своя -- исполнение"
}

# Решение подписанта вырезается из конвейера теми же якорями и гоняется на
# подставленных парах: копия условия в стенде разошлась бы с конвейером молча.
sign_gate_run() {   # каталог, пара образа, пара хозяина -> вывод, код в rc
  local dir="$1" img="$2" host="$3"
  mkdir -p "$dir"
  awk '/^__BIN_OS_ARCH=/{on=1} on{print; if ($0 == "fi") exit}' \
    "$K/claude-patch-all.real" > "$dir/signblock.sh"
  [[ -s "$dir/signblock.sh" ]] || { printf 'ЯКОРЬ_ПОТЕРЯН\n'; return 9; }
  { printf 'set -u\n'
    printf 'BIN=/dev/null\n'
    printf '__image_os_arch() { printf "%%s\\n" "%s"; }\n' "$img"
    printf '__host_os_arch() { printf "%%s\\n" "%s"; }\n' "$host"
    printf 'sign_macos_binary() { printf "ПОДПИСАНТ ЗВАН\\n"; }\n'
    printf 'source %q\n' "$dir/signblock.sh"
  } > "$dir/drv.sh"
  bash "$dir/drv.sh" 2>&1 9>&-
}

scenario_165() {   # Т9: подписант зовётся по ПАРЕ, а не по одному хозяину
  local d out_for rc_for out_own rc_own
  d="$C/s165"; rm -rf "$d"; mkdir -p "$d"
  out_for=$(sign_gate_run "$d/for" darwin-arm64 linux-x64); rc_for=$?
  out_own=$(sign_gate_run "$d/own" darwin-arm64 darwin-arm64); rc_own=$?
  LAST_EVID="чужой rc=$rc_for [$(printf '%s' "$out_for" | tr '\n' '|')] свой rc=$rc_own [$(printf '%s' "$out_own" | tr '\n' '|')]"
  if [[ "$out_for" == *"ЯКОРЬ_ПОТЕРЯН"* || "$out_own" == *"ЯКОРЬ_ПОТЕРЯН"* ]]; then
    bad "165 подписант: решение не вырезано из конвейера -- прибор не мерит"; return
  fi
  if [[ "$out_for" == *"ПОДПИСАНТ ЗВАН"* ]]; then
    LAST_EVID="ПОДПИСАНТ_ЗВАН_НА_ЧУЖОМ :: $LAST_EVID"
    bad "165 подписант: позван на образе чужой ОС"; return
  fi
  if [[ "$out_for" != *"Подпись ПРОПУЩЕНА"* \
     || "$out_for" != *"darwin-arm64"* || "$out_for" != *"linux-x64"* ]]; then
    LAST_EVID="ПРОПУСК_НЕ_ОБЪЯВЛЕН :: $LAST_EVID"
    bad "165 подписант: пропуск не объявлен своей строкой"; return
  fi
  # Положительный контроль: иначе зуб доказывал бы, что подписант выключен всегда.
  if [[ "$out_own" != *"ПОДПИСАНТ ЗВАН"* ]]; then
    LAST_EVID="ПОДПИСАНТ_НЕ_ЗВАН_НА_СВОЁМ :: $LAST_EVID"
    bad "165 подписант: не позван на образе своей ОС"; return
  fi
  ok "165 подписант: зовётся ровно на паре darwin/darwin, иначе объявленный пропуск"
}

scenario_166() {   # Т10: путь пропуска НЕ мерит форму `script`
  # Подставной script не принимает НИ ОДНОЙ формы. На чужой цели стадия обязана
  # объявить пропуск и дойти до конца: прибор, который прогону не нужен, не
  # вправе его убить.
  local out_skip rc_skip
  gate_prepare s166
  gate_carved_or_bad 166 || return
  gate_call e none 5 "win32-arm64"; out_skip="$GATE_OUT"; rc_skip=$GATE_RC
  LAST_EVID="чужая rc=$rc_skip [$(printf '%s' "$out_skip" | tr '\n' '|')]"
  if (( rc_skip != 0 )) || [[ "$out_skip" != *"Гейт интерфейса ПРОПУЩЕН"* ]]; then
    LAST_EVID="ФОРМА_МЕРЕНА_НА_ПРОПУСКЕ :: $LAST_EVID"
    bad "166 замер формы: путь пропуска не дошёл до конца (rc=$rc_skip)"; return
  fi
  if [[ "$out_skip" == *"script form"* || "$out_skip" == *"НЕ ИЗМЕРЕН"* ]]; then
    LAST_EVID="ФОРМА_МЕРЕНА_НА_ПРОПУСКЕ :: $LAST_EVID"
    bad "166 замер формы: пропуск всё-таки мерил форму"; return
  fi
  # Положительный контроль: иначе зуб доказывал бы, что замер выключен всегда.
  gate_call e none 5
  LAST_EVID="$LAST_EVID ;; своя rc=$GATE_RC [$(printf '%s' "$GATE_OUT" | tr '\n' '|')]"
  if (( GATE_RC != 2 )) || [[ "$GATE_OUT" != *"не принял НИ ОДНОЙ известной формы"* ]]; then
    LAST_EVID="ЗАМЕР_ВЫКЛЮЧЕН_ВСЕГДА :: $LAST_EVID"
    bad "166 замер формы: на своей паре замер не сработал (rc=$GATE_RC)"; return
  fi
  ok "166 замер формы: не исполняется на пропуске, исполняется на своей паре"
}

scenario_167() {   # Т12: чужой образ не занимает имя установки и не даёт .orig
  # Сеть не нужна и не трогается: загрузка подменяется, меряется РЕШЕНИЕ о
  # месте. Дом версий уводится в свой каталог через XDG_DATA_HOME.
  local out home
  home="$C/s167"; rm -rf "$home"; mkdir -p "$home"
  out=$(CPK="$K" CPH="$home" python3 - <<'DLONLY40C' 2>&1
import os, sys
from pathlib import Path
os.environ['XDG_DATA_HOME'] = os.environ['CPH']
sys.path.insert(0, os.environ['CPK'])
import claude_patch as c

def fake_download(version, dest, pkg=None):
    Path(dest).parent.mkdir(parents=True, exist_ok=True)
    Path(dest).write_bytes(b'\x7fELF' + b'\0' * 64)
    print('КАЧАЛИ %s -> %s' % (pkg or c.npm_platform_pkg(), dest))

c.download_binary = fake_download
host = c.npm_platform_pkg()
foreign = ('@anthropic-ai/claude-code-win32-x64'
           if '-win32-' not in host else '@anthropic-ai/claude-code-linux-x64')
vdir = c.versions_dir()

c.main(['--download-only', '0.0.900', '--platform', foreign])
print('ЧУЖОЙ_ИМЯ_УСТАНОВКИ=%s' % (vdir / '0.0.900').exists())
print('ЧУЖОЙ_ORIG=%s' % (vdir / '0.0.900.orig').exists())

c.main(['--download-only', '0.0.901', '--platform', host])
print('СВОЙ_ИМЯ_УСТАНОВКИ=%s' % (vdir / '0.0.901').exists())
print('СВОЙ_ORIG=%s' % (vdir / '0.0.901.orig').exists())
DLONLY40C
)
  LAST_EVID="$(printf '%s' "$out" | tr '\n' '|')"
  if [[ "$out" != *"ЧУЖОЙ_ИМЯ_УСТАНОВКИ=False"* || "$out" != *"ЧУЖОЙ_ORIG=False"* ]]; then
    LAST_EVID="ЧУЖОЙ_ЗАНЯЛ_ИМЯ_УСТАНОВКИ :: $LAST_EVID"
    bad "167 чужая платформа: образ занял имя установки или стал .orig"; return
  fi
  # Положительный контроль: иначе зуб доказывал бы, что установка сломана всегда.
  if [[ "$out" != *"СВОЙ_ИМЯ_УСТАНОВКИ=True"* || "$out" != *"СВОЙ_ORIG=True"* ]]; then
    LAST_EVID="СВОЙ_НЕ_УСТАНОВИЛСЯ :: $LAST_EVID"
    bad "167 своя платформа: обычный маршрут установки не отработал"; return
  fi
  ok "167 чужой образ уходит в staging, своя платформа ставится как прежде"
}

# --- дверь конфликтов синхронизации накладок (волна t106) --------------------
# Пол легших накладок односторонен ПО УСТРОЙСТВУ: он ловит ПАДЕНИЕ числа, а
# ниже нуля падать некуда. На доме, где ни одна накладка не несёт правки
# человека (замер задачи #95: ни одна из накладок дома), «легло промтов» равно
# нулю на любой версии, и нулевой пол зуба не имеет. Зуб перенесён на число,
# которое при регрессе различителя РАСТЁТ: конфликты синхронизации. Их печатает
# распаковщик, когда накладка разошлась с текущим определением апстрима и он
# не смог решить за пользователя; до пина 650a03f такие накладки молча
# вписывались в образ старым текстом, и измерить их было нечем.
#
# Дверь живёт в КОНВЕЙЕРЕ и меряется ВЫРЕЗАННЫМИ фрагментами настоящего
# конвейера -- тем же приёмом, что дверь обвала (#101): сценарий проверяет ТОТ
# ЖЕ код, а не его пересказ в стенде. Сеть не трогается: строка конфликтов
# пишется в фикстуру руками, различитель обвала -- те же иглы, что у соседней
# двери, без своего обращения к адресу снимка.
CONF_FUNCS=(__tw_prompt_conflicts __tw_prompt_outage __tw_prompt_dl_error __ver_from_bytes __tw_check_prompt_conflicts)

conf_prepare() {   # имя каталога сценария
  CONF_D="$C/$1"; rm -rf "$CONF_D"; mkdir -p "$CONF_D/frag"
  CONF_CARVED=$(w48_carve "$CONF_D/frag" "${CONF_FUNCS[@]}")
  # Фикстуры вывода форка. Блок синхронизации («Skipped/Updated/WARNING»)
  # печатается ДО якоря результатов, и дверь читает его по всему выводу --
  # как и живой конвейер, которому TWEAKCC_OUT достаётся целиком.
  printf 'Applying saved customizations to Claude Code...\nSkipped 672 up-to-date file(s)\nUpdated 33 system prompt file(s):\n  agent-prompt-explore.md  (2.1.235 → 2.1.235)\nPatches applied (run with --show-unchanged to show all patches):\n  System Prompts:\n    ✓ Custom Kind: my overlay\n' > "$CONF_D/out-clean.txt"
  printf 'Applying saved customizations to Claude Code...\nSkipped 670 up-to-date file(s)\nUpdated 33 system prompt file(s):\nWARNING: Conflicts detected for 3 system prompt file(s)\nPatches applied (run with --show-unchanged to show all patches):\n  System Prompts:\n    ✓ Custom Kind: my overlay\n' > "$CONF_D/out-conf3.txt"
  printf 'Applying saved customizations to Claude Code...\nSkipped 671 up-to-date file(s)\nUpdated 33 system prompt file(s):\nWARNING: Conflicts detected for 2 system prompt file(s)\nPatches applied (run with --show-unchanged to show all patches):\n  System Prompts:\n    ✓ Custom Kind: my overlay\n' > "$CONF_D/out-conf2.txt"
  # Обвал слоя: та же пара игл, что у двери обвала, ПЛЮС строка конфликтов --
  # так проверяется, что под обвалом дверь не сравнивает даже ненулевое.
  printf 'Applying patches...\nSystem prompts not available for version 2.1.265\nError downloading system prompts: fetch failed\nWARNING: Conflicts detected for 5 system prompt file(s)\nDone\n' > "$CONF_D/out-outage.txt"
  # Образ-игрушка с отметкой версии: дверь, как соседки, читает версию из байтов.
  printf 'мусор\n// Version: 2.1.265\nещё мусор\n' > "$CONF_D/img"
  cat > "$CONF_D/drv.sh" <<'CONFDRV'
set -euo pipefail
source "$1"; source "$2"; source "$3"; source "$4"; source "$5"
__tw_check_prompt_conflicts "$6" "$7"
CONFDRV
}

conf_carved_or_bad() {   # номер сценария
  (( CONF_CARVED == ${#CONF_FUNCS[@]} )) && return 0
  LAST_EVID="ФРАГМЕНТЫ_НЕ_ВЫРЕЗАНЫ вырезано=$CONF_CARVED из ${#CONF_FUNCS[@]}"
  bad "$1 дверь конфликтов: фрагменты не вырезаны -- прибор смотрит не туда"
  return 1
}

conf_decl() {   # объявленное число -- написать объявление с одной строкой на 2.1.265
  printf '2.1.265\t%s\tзамер стенда: фикстура двери конфликтов\n' "$1" > "$CONF_D/decl.txt"
}

conf_call() {   # фикстура (clean|conf3|conf2|outage), объявление: путь или «-» (файла нет)
  local fix="$1" decl="$2"
  [[ "$decl" != "-" ]] || decl="$CONF_D/объявления-нет.txt"
  CONF_OUT=$(env TWEAKCC_HOME="$CONF_D/home" \
                  TWEAKCC_EXPECTED_PROMPT_CONFLICTS="$decl" \
              bash "$CONF_D/drv.sh" \
                "$CONF_D/frag/__tw_prompt_conflicts.sh" \
                "$CONF_D/frag/__tw_prompt_outage.sh" \
                "$CONF_D/frag/__tw_prompt_dl_error.sh" \
                "$CONF_D/frag/__ver_from_bytes.sh" \
                "$CONF_D/frag/__tw_check_prompt_conflicts.sh" \
                "$CONF_D/out-$fix.txt" "$CONF_D/img" 2>&1 9>&-)
  CONF_RC=$?
}

conf_evid() { LAST_EVID="rc=$CONF_RC :: $(printf '%s' "$CONF_OUT" | tr '\n' '|')"; }

scenario_195() {   # конфликтов больше объявленного -- красное с названным смыслом
  conf_prepare s195; conf_carved_or_bad 195 || return
  conf_decl 1
  conf_call conf3 "$CONF_D/decl.txt"; conf_evid
  # Порядок «причина раньше кода» -- констрейнт, объяснён в сценарии 172: у
  # этой двери один код отказа на все ветки, и различает их ТОЛЬКО текст.
  if [[ "$CONF_OUT" != *"конфликтных накладок tweakcc на 2.1.265 больше объявленного"* ]]; then
    LAST_EVID="ПРЕВЫШЕНИЕ_НЕ_НАЗВАНО :: $LAST_EVID"
    bad "195 дверь конфликтов: превышение не названо версией"; return
  fi
  if [[ "$CONF_OUT" != *"конфликтных 3, объявлено 1"* ]]; then
    LAST_EVID="ЧИСЛА_НЕ_НАЗВАНЫ :: $LAST_EVID"
    bad "195 дверь конфликтов: измеренное и объявленное не названы числами"; return
  fi
  if [[ "$CONF_OUT" != *"$CONF_D/decl.txt"* ]]; then
    LAST_EVID="ПУТЬ_ОБЪЯВЛЕНИЯ_НЕ_НАЗВАН :: $LAST_EVID"
    bad "195 дверь конфликтов: путь файла объявления не назван"; return
  fi
  # СМЫСЛ обязателен: дверь, отказывающая числом без причины, отправляет
  # человека править объявление там, где чинить надо накладку. Прежняя немота
  # названа поимённо -- до пина 650a03f эти же накладки вписывались молча.
  if [[ "$CONF_OUT" != *"разошедшаяся с текущим определением"* || "$CONF_OUT" != *"650a03f"* ]]; then
    LAST_EVID="СМЫСЛ_НЕ_НАЗВАН :: $LAST_EVID"
    bad "195 дверь конфликтов: смысл конфликта и прежнюю немоту не названы"; return
  fi
  if (( CONF_RC != 1 )); then
    LAST_EVID="КОД_НЕ_ОТКАЗ(ждали 1) :: $LAST_EVID"
    bad "195 дверь конфликтов: код $CONF_RC, а превышение -- отказ"; return
  fi
  ok "195 конфликтов больше объявленного -- отказ, назвавший версию, числа, путь и смысл"
}

scenario_196() {   # конфликтов РОВНО объявлено -- зелёное со свидетелем
  conf_prepare s196; conf_carved_or_bad 196 || return
  conf_decl 2
  conf_call conf2 "$CONF_D/decl.txt"; conf_evid
  # Свидетель безусловен той же причиной, что у соседних дверей: дверь,
  # молчащая на здоровом прогоне, побайтово неотличима от снятой.
  if [[ "$CONF_OUT" != *"NOTE: конфликты накладок tweakcc на 2.1.265: конфликтных 2, объявлено 2"* ]]; then
    LAST_EVID="СВИДЕТЕЛЬ_НЕ_НАПЕЧАТАН :: $LAST_EVID"
    bad "196 дверь конфликтов: сходство не названо свидетелем с числами"; return
  fi
  if (( CONF_RC != 0 )); then
    LAST_EVID="КОД_НЕ_ЗЕЛЁНЫЙ :: $LAST_EVID"
    bad "196 дверь конфликтов: код $CONF_RC, а равенство -- не отказ"; return
  fi
  ok "196 конфликтов ровно объявлено -- зелёное, свидетель напечатан"
}

scenario_197() {   # конфликтов МЕНЬШЕ объявлено -- NOTE улучшения, не отказ
  conf_prepare s197; conf_carved_or_bad 197 || return
  conf_decl 3
  conf_call conf2 "$CONF_D/decl.txt"; conf_evid
  # Уменьшение -- улучшение, а не отказ: объявление пережило свою причину с
  # «хорошей» стороны, и отказ здесь красил бы версию, на которой ничего не
  # сломано. Но и улучшение ОБЪЯВЛЯЕТСЯ -- молчащее сходство неотличимо от
  # несравнивавшего.
  if [[ "$CONF_OUT" != *"меньше объявленного"* || "$CONF_OUT" != *"улучшение, не отказ"* ]]; then
    LAST_EVID="УЛУЧШЕНИЕ_НЕ_ОБЪЯВЛЕНО :: $LAST_EVID"
    bad "197 дверь конфликтов: уменьшение не названо улучшением"; return
  fi
  if (( CONF_RC != 0 )); then
    LAST_EVID="КОД_НЕ_ЗЕЛЁНЫЙ :: $LAST_EVID"
    bad "197 дверь конфликтов: код $CONF_RC, а уменьшение -- не отказ"; return
  fi
  ok "197 конфликтов меньше объявленного -- NOTE улучшения, зелёное"
}

scenario_198() {   # объявления нет, конфликтов 0 -- умолчание ноль, зелёное
  conf_prepare s198; conf_carved_or_bad 198 || return
  conf_call clean -; conf_evid
  # Отличие от двери пола: там отсутствие файла с ЖИВЫМ слоем -- отказ (пол
  # обязан быть написан), здесь умолчание честно, потому что зуб двери --
  # ПРЕВЫШЕНИЕ, и нулевое умолчание его не гасит.
  if [[ "$CONF_OUT" != *"умолчание ноль, сходится"* ]]; then
    LAST_EVID="УМОЛЧАНИЕ_НЕ_СХОДИТСЯ :: $LAST_EVID"
    bad "198 дверь конфликтов: отсутствие объявления при нуле конфликтов не сходится вслух"; return
  fi
  if (( CONF_RC != 0 )); then
    LAST_EVID="КОД_НЕ_ЗЕЛЁНЫЙ :: $LAST_EVID"
    bad "198 дверь конфликтов: код $CONF_RC, а умолчание ноль -- не отказ"; return
  fi
  ok "198 объявления нет и конфликтов 0 -- умолчание ноль, зелёное"
}

scenario_199() {   # объявления нет, конфликтов > 0 -- умолчание превышено, красное
  conf_prepare s199; conf_carved_or_bad 199 || return
  conf_call conf3 -; conf_evid
  if [[ "$CONF_OUT" != *"умолчание ноль превышено"* ]]; then
    LAST_EVID="УМОЛЧАНИЕ_ПРОБИТО :: $LAST_EVID"
    bad "199 дверь конфликтов: превышение умолчания не названо"; return
  fi
  if (( CONF_RC != 1 )); then
    LAST_EVID="КОД_НЕ_ОТКАЗ(ждали 1) :: $LAST_EVID"
    bad "199 дверь конфликтов: код $CONF_RC, а превышение умолчания -- отказ"; return
  fi
  ok "199 объявления нет и конфликтов 3 -- умолчание ноль превышено, красное"
}

scenario_200() {   # слой обвалился -- «нечего мерить», сравнения нет даже при конфликтах
  conf_prepare s200; conf_carved_or_bad 200 || return
  conf_decl 0
  conf_call outage "$CONF_D/decl.txt"; conf_evid
  # Ноль конфликтов при ОТСУТСТВУЮЩЕМ слое не значит ничего: синхронизация не
  # бежала, и мерить нечем. Признак обвала -- ТОТ ЖЕ, что у двери обвала выше
  # (пара игл недоступности), второй копии правила здесь нет. В живом
  # конвейере дверь обвала отказывает РАНЬШЕ и до этой двери прогон не доходит;
  # проверяется, что и сама дверь не сравнивает под обвалом -- вызов её из
  # другого места не должен рождать ложный ноль.
  if [[ "$CONF_OUT" != *"нечего мерить"* ]]; then
    LAST_EVID="НЕЧЕГО_МЕРИТЬ_НЕ_НАЗВАНО :: $LAST_EVID"
    bad "200 дверь конфликтов: обвал не назван «нечего мерить»"; return
  fi
  if [[ "$CONF_OUT" == *"FATAL"* ]]; then
    LAST_EVID="СРАВНИЛ_ПОД_ОБВАЛОМ :: $LAST_EVID"
    bad "200 дверь конфликтов: под обвалом дверь сравнила конфликты"; return
  fi
  if (( CONF_RC != 0 )); then
    LAST_EVID="КОД_НЕ_ЗЕЛЁНЫЙ :: $LAST_EVID"
    bad "200 дверь конфликтов: код $CONF_RC, а обвал слоя -- не отказ этой двери"; return
  fi
  ok "200 слой обвалился -- «нечего мерить», сравнения нет"
}

scenario_201() {   # САЙТЫ ВЫЗОВА дверей слоя tweakcc: каждая позвана конвейером
  # Сценарии 195-200 гоняют САМИ двери на вырезанных фрагментах, а ценз 192
  # считает сайты ДОМОВ, не дверей. Дверь без сайта вызова -- мёртвый код:
  # замер волны t106 -- удаление сайта вызова двери конфликтов оставляло
  # зелёной всю батарею (сценарии и мутации), то есть правка соседнего этапа
  # могла унести дверь молча. Счёт -- по САЙТАМ ВЫЗОВА: игла «имя + пробел +
  # кавычка» отсекает объявление (`имя() {`) и упоминания в комментариях
  # (комментарий у двери уровня кончается точкой с запятой, не кавычкой).
  # Состав измерен по конвейеру, а не переписан из брифа: в ценз входят ВСЕ
  # двери слоя -- шесть верхнеуровневых звонков стадии и дверь обвала,
  # вложенная в дверь уровня (её вызывает не стадия, а сама дверь уровня);
  # половинный ценз оставил бы соседкам ту же дыру.
  local src anchor_n rows_n miss_n level_n off_n conf_n outage_n
  src="$K/claude-patch-all.real"
  anchor_n=$(grep -c -F '__tw_check_anchor "' "$src" || true)
  rows_n=$(grep -c -F '__tw_check_result_rows "' "$src" || true)
  miss_n=$(grep -c -F '__tw_reconcile_misses "' "$src" || true)
  level_n=$(grep -c -F '__tw_check_applied_level "' "$src" || true)
  off_n=$(grep -c -F '__tw_check_off_set "' "$src" || true)
  conf_n=$(grep -c -F '__tw_check_prompt_conflicts "' "$src" || true)
  outage_n=$(grep -c -F '__tw_prompt_outage_door "' "$src" || true)
  LAST_EVID="сайтов якоря=$anchor_n строк=$rows_n сверки=$miss_n уровня=$level_n выключенных=$off_n конфликтов=$conf_n обвала=$outage_n"
  if (( anchor_n != 1 )); then
    LAST_EVID="САЙТ_ЯКОРЯ_ПРОПАЛ :: $LAST_EVID"
    bad "201 сайты вызова дверей tweakcc: дверь якоря вызвана $anchor_n раз, а сайт один"; return
  fi
  if (( rows_n != 1 )); then
    LAST_EVID="САЙТ_СТРОК_ПРОПАЛ :: $LAST_EVID"
    bad "201 сайты вызова дверей tweakcc: дверь читаемости вызвана $rows_n раз, а сайт один"; return
  fi
  if (( miss_n != 1 )); then
    LAST_EVID="САЙТ_СВЕРКИ_ПРОПАЛ :: $LAST_EVID"
    bad "201 сайты вызова дверей tweakcc: сверка непроходов вызвана $miss_n раз, а сайт один"; return
  fi
  if (( level_n != 1 )); then
    LAST_EVID="САЙТ_УРОВНЯ_ПРОПАЛ :: $LAST_EVID"
    bad "201 сайты вызова дверей tweakcc: дверь уровня вызвана $level_n раз, а сайт один"; return
  fi
  if (( off_n != 1 )); then
    LAST_EVID="САЙТ_ВЫКЛЮЧЕННЫХ_ПРОПАЛ :: $LAST_EVID"
    bad "201 сайты вызова дверей tweakcc: дверь выключенных вызвана $off_n раз, а сайт один"; return
  fi
  if (( conf_n != 1 )); then
    LAST_EVID="САЙТ_КОНФЛИКТОВ_ПРОПАЛ :: $LAST_EVID"
    bad "201 сайты вызова дверей tweakcc: дверь конфликтов вызвана $conf_n раз, а сайт один"; return
  fi
  if (( outage_n != 1 )); then
    LAST_EVID="САЙТ_ОБВАЛА_ПРОПАЛ :: $LAST_EVID"
    bad "201 сайты вызова дверей tweakcc: дверь обвала вызвана $outage_n раз, а сайт один"; return
  fi
  ok "201 сайты вызова дверей tweakcc: все двери слоя вызваны конвейером"
}

scenario_202() {   # снятое глушение: на нечитаемом выводе замер называет ошибку
  # Правило кита «2>/dev/null в ЗАМЕРЕ запрещён» обеспечено волной t106
  # (доводка) на трёх чтениях вывода tweakcc: погашенная ошибка чтения
  # выходила пустой строкой или нулём, и двери читали «измеренный ноль» на
  # сломанном приборе. Зуб утверждает ровно то, что поменялось: на
  # ОТСУТСТВУЮЩЕМ выводе собственные слова инструмента видны на stderr.
  # Значения не сверяются: пустой stdout у grep при ошибке -- свойство grep,
  # а ноль awk ниже по трубе -- форма трубы, не прибора; единственный
  # носитель причины здесь -- stderr.
  # Третий предмет -- ПЕРЕЧЕНЬ не-найденных накладок в двери уровня. Через
  # саму дверь он недостижим на отсутствующем выводе: перечень стоит под
  # условием «счёт видел промахи», а счёт читает ТОТ ЖЕ файл и молчит нулём
  # -- поэтому зуб ведёт САЙТ (трубу перечня), вырезанную якорем по её
  # грепу-голове, как сценарий 184 вырезает верхнеуровневый кусок конвейера.
  local d carved out rc
  d="$C/s202"; rm -rf "$d"; mkdir -p "$d/frag"
  carved=$(w48_carve "$d/frag" __tw_prompt_notfound __tw_prompt_conflicts)
  if (( carved != 2 )); then
    LAST_EVID="ФРАГМЕНТЫ_НЕ_ВЫРЕЗАНЫ вырезано=$carved из 2"
    bad "202 stderr замеров: фрагменты не вырезаны -- прибор смотрит не туда"; return
  fi
  awk '/LC_ALL=C grep -a '\''Could not find system prompt'\'' "\$__out"/{on=1} on{print} on && /done >&2 \|\| true/{exit}' \
    "$K/claude-patch-all.real" > "$d/frag/listing.sh"
  if [[ ! -s "$d/frag/listing.sh" ]]; then
    LAST_EVID="ТРУБА_ПЕРЕЧНЯ_НЕ_ВЫРЕЗАНА"
    bad "202 stderr замеров: труба перечня не вырезана -- прибор смотрит не туда"; return
  fi
  cat > "$d/drv.sh" <<'MUTEDRV'
set -euo pipefail
source "$1"; source "$2"
# Вывода НЕТ: замер обязан НАЗВАТЬ это ошибкой на stderr, а не ответить нулём.
nf="$(__tw_prompt_notfound "$3" 2>"$4")" || true
cf="$(__tw_prompt_conflicts "$3" 2>"$5")" || true
printf 'не-найденные=[%s] конфликты=[%s]\n' "$nf" "$cf"
# Сайт перечня -- та же честность: источник тот же, читатель -- человек.
# Пояс у грепа не нужен и обязан не понадобиться: проверяется прогоном.
__out="$3"
source "$6" 2>"$7"
MUTEDRV
  out=$(bash "$d/drv.sh" "$d/frag/__tw_prompt_notfound.sh" \
                         "$d/frag/__tw_prompt_conflicts.sh" \
                         "$d/вывода-нет.txt" "$d/nf.err" "$d/cf.err" \
                         "$d/frag/listing.sh" "$d/listing.err" \
        2>"$d/drv.err"); rc=$?
  LAST_EVID="rc=$rc :: $(printf '%s' "$out" | tr '\n' '|') :: nf_err=$(wc -c <"$d/nf.err") cf_err=$(wc -c <"$d/cf.err") listing_err=$(wc -c <"$d/listing.err")"
  if (( rc != 0 )); then
    LAST_EVID="ВЕТКА_ПЕЧАТИ_УПАЛА :: $LAST_EVID"
    bad "202 stderr замеров: прогон сайта перечня упал без пояса -- пояс необходим"; return
  fi
  if [[ ! -s "$d/nf.err" ]]; then
    LAST_EVID="СТДЕРР_НЕНАЙДЕННЫХ_ПОГАШЕН :: $LAST_EVID"
    bad "202 stderr замеров: счёт не-найденных погасил свою ошибку чтения"; return
  fi
  if [[ ! -s "$d/cf.err" ]]; then
    LAST_EVID="СТДЕРР_КОНФЛИКТОВ_ПОГАШЕН :: $LAST_EVID"
    bad "202 stderr замеров: счёт конфликтов погасил свою ошибку чтения"; return
  fi
  if [[ ! -s "$d/listing.err" ]]; then
    LAST_EVID="СТДЕРР_ПЕРЕЧНЯ_ПОГАШЕН :: $LAST_EVID"
    bad "202 stderr замеров: перечень не-найденных погасил свою ошибку чтения"; return
  fi
  ok "202 stderr замеров: на отсутствующем выводе ошибка названа, а не погашена"
}

scenario_203() {   # ПАРА литералов пина распаковщика: умолчание и сверка -- ОДИН SHA
  # Сверка «тот ли это форк» сравнивает переменную со СВОИМ литералом SHA, а
  # умолчание той же величины кладёт тот же SHA несколькими строками выше.
  # Подъём ОДНОГО места пары -- бамп пина, забывший второе, -- расходил их
  # молча: конвейер обязан печатать «Unpacker source OVERRIDDEN», но код
  # остаётся нулевым, и замер 10.09 (t107, копия кита: 4209 поднят, 4214
  # оставлен старым) показал, что вся батарея проходила ЗЕЛЁНОЙ -- свидетель
  # читал только человек. Зуб требует РАВЕНСТВА пары: расходятся -- отказ,
  # называющий оба значения.
  local src def_site cmp_site def_sha cmp_sha
  src="$K/claude-patch-all.real"
  def_site=$(grep -c -F 'CATALYST_TWEAKCC_SHA="${CATALYST_TWEAKCC_SHA:-' "$src" || true)
  cmp_site=$(grep -c -F '"$CATALYST_TWEAKCC_SHA" == "' "$src" || true)
  def_sha=$(sed -n 's/^CATALYST_TWEAKCC_SHA="${CATALYST_TWEAKCC_SHA:-\([0-9a-f]\{40\}\)}"$/\1/p' "$src")
  cmp_sha=$(sed -n 's/^ *&& "$CATALYST_TWEAKCC_SHA" == "\([0-9a-f]\{40\}\)" \]\] \\$/\1/p' "$src")
  LAST_EVID="умолчание=[${def_sha:-НЕ_РАЗОБРАН}] сверка=[${cmp_sha:-НЕ_РАЗОБРАН}] сайтов умолчания=$def_site сверки=$cmp_site"
  if (( def_site != 1 )); then
    LAST_EVID="САЙТ_УМОЛЧАНИЯ_НЕ_ОДИН :: $LAST_EVID"
    bad "203 пара пина распаковщика: строк умолчания CATALYST_TWEAKCC_SHA -- $def_site, а сайт один"; return
  fi
  if (( cmp_site != 1 )); then
    LAST_EVID="САЙТ_СВЕРКИ_НЕ_ОДИН :: $LAST_EVID"
    bad "203 пара пина распаковщика: строк сверки «тот ли форк» -- $cmp_site, а сайт один"; return
  fi
  if [[ -z "$def_sha" ]]; then
    LAST_EVID="ФОРМА_УМОЛЧАНИЯ_НЕ_РАЗОБРАНА :: $LAST_EVID"
    bad "203 пара пина распаковщика: SHA умолчания не вырезан -- форма строки уехала"; return
  fi
  if [[ -z "$cmp_sha" ]]; then
    LAST_EVID="ФОРМА_СВЕРКИ_НЕ_РАЗОБРАНА :: $LAST_EVID"
    bad "203 пара пина распаковщика: SHA сверки не вырезан -- форма строки уехала"; return
  fi
  if [[ "$def_sha" != "$cmp_sha" ]]; then
    LAST_EVID="ПАРА_ПИНА_РАЗОШЛАСЬ :: $LAST_EVID"
    bad "203 пара пина распаковщика: умолчание и сверка держат РАЗНЫЕ SHA -- каждый прогон объявит собственный пин подменённым"; return
  fi
  ok "203 пара пина распаковщика: умолчание и сверка держат один SHA ($def_sha)"
}

# --- волна 109/110: страж случая (u) и связка кодов зонда с ветвями свипа ----
#
# Два стража случая (u) выходили ОДНИМ кодом, и оболочка зонда на отказ
# ВТОРОГО печатала диагноз первого («якорь уехал») -- контроль случая (u)
# не измерял вовсе, а чинить отправляли не тот механизм (замер волны 109).
# В связке -- таблица кодов зонда объявляет ВОСЕМЬ кодов, а свип разбирал
# только пять, и коды 4 и 7 уезжали в общую ветвь «не сошёлся» с выходом 1:
# лечение «чинить таблицу зонда»/«чинить вырезку зонда» читалось оператору
# как красный прогон кита, хотя измерения не было вовсе (замер волны 110).

scenario_204() {   # зонд объявил несошедшееся число (код 4): «не измерено», не красный
  # Код 4 -- расхождение ОБЪЯВЛЕННОГО числа с фактическим: правилась таблица
  # сценариев или мутаций зонда без переноса счётчика. Чинить надо таблицу
  # зонда, повтор прогона не поможет -- это класс «не измерено» (выход 2), а
  # не «случай разошёлся» (выход 1); тот же раскол, что у сценария 63.
  local out rc
  out=$(STUB_PROBE_RC=4 run_sweep "$K" "$C/corpus" "$C/versions.txt" 900); rc=$?
  LAST_EVID="rc=$rc :: $out"
  if (( rc != 2 )); then
    LAST_EVID="КЛАСС_НЕ_ТОТ rc=$rc :: $out"
    bad "204 таблица зонда: код возврата $rc, ждали 2"; return
  fi
  if [[ "$out" != *"объявленное число разошлось с фактическим"* ]]; then
    LAST_EVID="ПРИЧИНА_НЕ_НАЗВАНА :: $out"
    bad "204 таблица зонда: причина не названа: $(printf '%s' "$out" | head -2 | tr '\n' ' ')"; return
  fi
  if [[ "$out" == *"SWEEP DONE"* ]]; then
    bad "204 таблица зонда: версии всё равно померены"; return
  fi
  ok "204 несошедшееся число у зонда -- свой класс, а не красный прогон"
}

scenario_205() {   # оснастка зонда усечена (код 7): «не измерено», не красный
  # Код 7 у build-path-probe (docnum:other -- это код возврата, а не счёт) --
  # жертва сценария звала дом, которого в вырезке
  # нет: ответы сценариев НИЧЕГО не мерили, чинить надо ВЫРЕЗКУ зонда, повтор
  # не поможет. Прежде уезжал в общую ветвь «не сошёлся» с выходом 1 --
  # чужое действие для обеих причин.
  local out rc
  out=$(STUB_PROBE_RC=7 run_sweep "$K" "$C/corpus" "$C/versions.txt" 900); rc=$?
  LAST_EVID="rc=$rc :: $out"
  if (( rc != 2 )); then
    LAST_EVID="КЛАСС_НЕ_ТОТ rc=$rc :: $out"
    bad "205 вырезка зонда: код возврата $rc, ждали 2"; return
  fi
  if [[ "$out" != *"оснастка зонда усечена"* ]]; then
    LAST_EVID="ПРИЧИНА_НЕ_НАЗВАНА :: $out"
    bad "205 вырезка зонда: причина не названа: $(printf '%s' "$out" | head -2 | tr '\n' ' ')"; return
  fi
  if [[ "$out" == *"SWEEP DONE"* ]]; then
    bad "205 вырезка зонда: версии всё равно померены"; return
  fi
  ok "205 усечённая вырезка зонда -- свой класс, а не красный прогон"
}

scenario_206() {   # СВЯЗКА таблицы кодов зонда с ветвями свипа: обе стороны
  # Таблицу кодов объявляет шапка зонда, потребитель -- предполёт свипа.
  # Связка ничем не цензовалась: сценарии пинят по ОДНОМУ коду каждый, и
  # новый код уезжал в общую ветвь молча -- ровно так уехали коды 4 и 7.
  # Ценз читает ОБА первоисточника: таблицу -- из копии НАСТОЯЩЕГО зонда в
  # снимке кита (.real.sh: по имени .sh карвер кладёт ЗАГЛУШКУ, и ценз
  # по .sh был бы поддельным зубом), ветви -- из копии свипа. Расхождение
  # в любую сторону -- красное с названной причиной: объявленный код без
  # ветви и ветвь на коде, которого таблица не объявляла.
  local verdict
  if [[ ! -f "$K/tools/build-path-probe.real.sh" ]]; then
    LAST_EVID="НЕТ_КОПИИ_ЗОНДА :: $K/tools/build-path-probe.real.sh"
    bad "206 связка кодов: в снимке кита нет настоящего зонда"; return
  fi
  verdict=$(python3 - "$K/tools/build-path-probe.real.sh" "$K/tools/sweep.sh" <<'PY206'
import io
import re
import sys

probe, sweep = (io.open(p, encoding='utf-8').read() for p in sys.argv[1:3])
# Таблица кодов -- шапка зонда от строки «Exit codes» до «Death by signal»:
# каждая строка вида «#   N  текст» объявляет код N. Продолжения описаний
# идут с БОЛЬШИМ отступом и цифр после трёх пробелов не несут.
tab = re.search(r'^# Exit codes\b.*?(?=^# Death by signal)', probe, re.M | re.S)
if not tab:
    print('НЕТ_ТАБЛИЦЫ_КОДОВ шапка зонда не объявляет таблицу кодов')
    raise SystemExit
declared = re.findall(r'^#   ([0-9]+)  ', tab.group(0), re.M)
# Ветви -- блок разбора кода зонда в свипе; метки вида «    N)».
case = re.search(r'^  case \$__prc in$(.*?)^  esac$', sweep, re.M | re.S)
if not case:
    print('НЕТ_БЛОКА_ВЕТВЕЙ у свипа нет разбора кода зонда')
    raise SystemExit
branches = re.findall(r'^    ([0-9]+)\)', case.group(1), re.M)
no_branch = [c for c in declared if c not in branches]
no_code = [b for b in branches if b not in declared]
if no_branch:
    print('КОД_БЕЗ_ВЕТВИ:%s код объявлен таблицей зонда, а ветви в свипе нет'
          % ','.join(no_branch))
elif no_code:
    print('ВЕТВЬ_БЕЗ_КОДА:%s у ветви нет кода в таблице зонда'
          % ','.join(no_code))
elif not declared:
    print('ПУСТАЯ_ТАБЛИЦА таблица кодов пуста -- ценз слеп')
else:
    print('СХОДИТСЯ:%s' % ','.join(declared))
PY206
)
  LAST_EVID="$verdict"
  case "$verdict" in
    СХОДИТСЯ:*)
      ok "206 каждый код таблицы зонда имеет названную ветвь свипа (${verdict#СХОДИТСЯ:})" ;;
    *)
      bad "206 связка таблицы кодов зонда с ветвями свипа разошлась: $verdict" ;;
  esac
}

scenario_207() {   # ФОРМА стража случая (u): сверка «до/после», а не зашитый литерал
  # Страж соседей случая (u) считал ОСТАВШИЕМСЯ сайты стадии и сверял их
  # число с зашитой единицей; когда законных сайтов в claude_patch.py стало
  # три (замер волны 109), законная подмена оставляла два, страж отказывал,
  # а диагноз называл причину ПЕРВОГО стража («якорь уехал»). Настоящее
  # намерение -- «подмена задела свой сайт и ни одного чужого» -- держится
  # РАЗНИЦЕЙ: сайтов после подмены ровно на единицу меньше, чем до. Пин по
  # ФОРМЕ, идиомой сценария 203: сверка «до/после» присутствует, сверки
  # соседей с литералом -- нет. Жертва -- копия НАСТОЯЩЕГО зонда (.real.sh):
  # по имени .sh в снимке кита лежит заглушка.
  local src old_form diff_form
  src="$K/tools/build-path-probe.real.sh"
  if [[ ! -f "$src" ]]; then
    LAST_EVID="НЕТ_КОПИИ_ЗОНДА :: $src"
    bad "207 форма стража (u): в снимке кита нет настоящего зонда"; return
  fi
  # Игла старой формы -- хвост соседской сверки с литералом; сверку СВОЕГО
  # якоря первый страж держит другой строкой, и хвост уникален старой форме.
  old_form=$(grep -c -F '.staging.{os.getpid()}")'"'"') != 1' "$src" || true)
  diff_form=$(grep -c -F 'if after_sites != before_sites - 1:' "$src" || true)
  LAST_EVID="соседский_литерал=$old_form сверка_до_после=$diff_form"
  if (( old_form != 0 )); then
    LAST_EVID="СВЕРКА_СОСЕДЕЙ_ВЕРНУЛАСЬ :: $LAST_EVID"
    bad "207 форма стража (u): вернулась сверка соседей с зашитым литералом -- счёт снова ломается о новые законные сайты"; return
  fi
  if (( diff_form != 1 )); then
    LAST_EVID="СВЕРКА_ДО_ПОСЛЕ_НЕТ :: $LAST_EVID"
    bad "207 форма стража (u): сверки «до/после» нет (строк $diff_form, а нужна одна) -- страж перестал доказывать «задет ровно свой сайт»"; return
  fi
  ok "207 страж случая (u) сверяет сайты «до/после», а не соседей с литералом"
}

